-- EatWhat full MySQL 8.0 database initialization script.
-- Generated: 2026-07-29 00:57:27 +08:00
-- Dataset: 6,665 cleaned system dishes.
--
-- IMPORTANT:
-- 1. This script drops and recreates the food table. Back up an existing database first.
-- 2. To use another schema name, regenerate with -DatabaseName your_schema.
-- 3. Execute this file with MySQL 8.0 / Workbench using UTF-8.

SET NAMES utf8mb4;
SET time_zone = '+08:00';
SET SQL_SAFE_UPDATES = 0;


-- ============================================
-- 吃什么小程序 - 数据库建表 SQL
-- 数据库名：food
-- 表名：food
-- 生成时间：2026-04-29
-- ============================================

-- 创建数据库
CREATE DATABASE IF NOT EXISTS `food`
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_general_ci;

USE `food`;

-- 删除旧表（如需保留数据请先备份）
DROP TABLE IF EXISTS food;

-- 创建菜品表
CREATE TABLE food (
  id                        INT AUTO_INCREMENT PRIMARY KEY,
  name                      VARCHAR(255)    NOT NULL,
  type                      VARCHAR(50)     NOT NULL,
  cl                        TEXT,
  fl                        TEXT,
  step                      TEXT,
  tags                      VARCHAR(500)    DEFAULT ''      COMMENT '标签，逗号分隔',
  image                     VARCHAR(500)    DEFAULT ''      COMMENT '菜品图片URL',
  difficulty                VARCHAR(20)     DEFAULT ''      COMMENT '难度：简单/普通/困难',
  cook_time                 VARCHAR(50)     DEFAULT ''      COMMENT '烹饪时间',
  ingredients_amounts       TEXT                     COMMENT '食材与用量',
  steps                     TEXT                     COMMENT '详细步骤',
  step_images               TEXT                     COMMENT '步骤图片URL，JSON数组',
  tips                      TEXT                     COMMENT '小贴士',
  methods                   VARCHAR(200)    DEFAULT ''      COMMENT '烹饪方法',
  kcal                      INT             DEFAULT 0      COMMENT '热量（千卡）',
  cuisine_code              VARCHAR(32)     DEFAULT NULL   COMMENT '稳定菜系编码',
  tag_codes                 VARCHAR(500)    DEFAULT ''     COMMENT '稳定标签编码，逗号分隔',
  cook_minutes              INT             DEFAULT NULL   COMMENT '标准化烹饪分钟数',
  metadata_version          INT             NOT NULL DEFAULT 1 COMMENT '推荐元数据版本',
  is_custom                 TINYINT(1)      DEFAULT 0      COMMENT '是否为用户自定义菜品',
  user_id                   BIGINT          DEFAULT NULL   COMMENT '自定义菜品所属用户ID',
  create_time               DATETIME        DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_general_ci
  COMMENT='菜品数据表';

-- 创建索引
CREATE INDEX idx_type       ON food(type);
CREATE INDEX idx_difficulty ON food(difficulty);
CREATE INDEX idx_kcal      ON food(kcal);
CREATE INDEX idx_user_id   ON food(user_id);
CREATE INDEX idx_food_cuisine_code ON food(cuisine_code);
CREATE INDEX idx_food_cook_minutes ON food(cook_minutes);

CREATE TABLE IF NOT EXISTS user_preference (
  user_id                   BIGINT PRIMARY KEY,
  preferred_cuisines        JSON NOT NULL,
  preferred_tags            JSON NOT NULL,
  excluded_tags             JSON NOT NULL,
  excluded_ingredients      JSON NOT NULL,
  avoid_recent_days         INT NOT NULL DEFAULT 7,
  max_cook_minutes          INT DEFAULT NULL,
  version                   INT NOT NULL DEFAULT 1,
  updated_at                DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 验证
DESC food;
SELECT COUNT(*) AS total_rows FROM food;


-- EatWhat system dish replacement generated from a cleaned workbook.
-- Source: 食谱数据清洗版.xlsx
-- Rows: 6665

SET NAMES utf8mb4;
SET time_zone = '+08:00';
USE `food`;

START TRANSACTION;
CREATE TEMPORARY TABLE eatwhat_food_import LIKE food;
ALTER TABLE eatwhat_food_import MODIFY COLUMN id INT NOT NULL;




























-- Keep user-created dishes and only replace system dishes.
DELETE FROM food WHERE user_id IS NULL;
SELECT name, type, cl, fl, step, tags, image, difficulty, cook_time, ingredients_amounts, steps, step_images, tips, methods, kcal, is_custom, user_id, create_time FROM eatwhat_food_import;
DROP TEMPORARY TABLE eatwhat_food_import;
COMMIT;

-- Verification queries
SELECT type, COUNT(*) AS count FROM food WHERE user_id IS NULL GROUP BY type ORDER BY type;
SELECT COUNT(*) AS system_dishes FROM food WHERE user_id IS NULL;
SELECT COUNT(*) AS custom_dishes FROM food WHERE user_id IS NOT NULL;


USE `food`;

DROP PROCEDURE IF EXISTS ensure_recommendation_preferences_schema;
DELIMITER //
CREATE PROCEDURE ensure_recommendation_preferences_schema()
BEGIN
    IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='food' AND column_name='cuisine_code') = 0 THEN
        ALTER TABLE food ADD COLUMN cuisine_code VARCHAR(32) NULL;
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='food' AND column_name='tag_codes') = 0 THEN
        ALTER TABLE food ADD COLUMN tag_codes VARCHAR(500) NOT NULL DEFAULT '';
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='food' AND column_name='cook_minutes') = 0 THEN
        ALTER TABLE food ADD COLUMN cook_minutes INT NULL;
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='food' AND column_name='metadata_version') = 0 THEN
        ALTER TABLE food ADD COLUMN metadata_version INT NOT NULL DEFAULT 1;
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='food' AND index_name='idx_food_cuisine_code') = 0 THEN
        CREATE INDEX idx_food_cuisine_code ON food(cuisine_code);
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='food' AND index_name='idx_food_cook_minutes') = 0 THEN
        CREATE INDEX idx_food_cook_minutes ON food(cook_minutes);
    END IF;
END//
DELIMITER ;
CALL ensure_recommendation_preferences_schema();
DROP PROCEDURE ensure_recommendation_preferences_schema;

CREATE TABLE IF NOT EXISTS user_preference (
    user_id BIGINT PRIMARY KEY,
    preferred_cuisines JSON NOT NULL,
    preferred_tags JSON NOT NULL,
    excluded_tags JSON NOT NULL,
    excluded_ingredients JSON NOT NULL,
    avoid_recent_days INT NOT NULL DEFAULT 7,
    max_cook_minutes INT NULL,
    version INT NOT NULL DEFAULT 1,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


USE `food`;

-- utf8mb4_general_ci gives many CJK characters the same comparison weight.
-- BINARY comparisons are required here so canonical tags only match exact text.
UPDATE food
SET cuisine_code = CASE
        WHEN FIND_IN_SET(BINARY '川菜', BINARY tags) > 0 THEN 'SICHUAN'
        WHEN FIND_IN_SET(BINARY '粤菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '广东菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '潮汕菜', BINARY tags) > 0 THEN 'CANTONESE'
        WHEN FIND_IN_SET(BINARY '东北菜', BINARY tags) > 0 THEN 'NORTHEAST'
        WHEN FIND_IN_SET(BINARY '湘菜', BINARY tags) > 0 THEN 'HUNAN'
        WHEN FIND_IN_SET(BINARY '苏菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '淮扬菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '浙菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '上海菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '本帮菜', BINARY tags) > 0 THEN 'JIANGNAN'
        WHEN FIND_IN_SET(BINARY '鲁菜', BINARY tags) > 0 THEN 'SHANDONG'
        WHEN FIND_IN_SET(BINARY '闽菜', BINARY tags) > 0 THEN 'FUJIAN'
        WHEN FIND_IN_SET(BINARY '西北菜', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '新疆菜', BINARY tags) > 0 THEN 'NORTHWEST'
        ELSE NULL
    END,
    cook_minutes = CAST(NULLIF(REGEXP_SUBSTR(cook_time, '[0-9]+'), '') AS UNSIGNED),
    tag_codes = CONCAT_WS(',',
        IF(FIND_IN_SET(BINARY '家常菜', BINARY tags) > 0, 'HOME_STYLE', NULL),
        IF(FIND_IN_SET(BINARY '香辣', BINARY tags) > 0, 'SPICY', NULL),
        IF(FIND_IN_SET(BINARY '麻辣', BINARY tags) > 0, 'NUMB_SPICY', NULL),
        IF(FIND_IN_SET(BINARY '酸辣', BINARY tags) > 0, 'SOUR_SPICY', NULL),
        IF(FIND_IN_SET(BINARY '酸甜', BINARY tags) > 0, 'SWEET_SOUR', NULL),
        IF(FIND_IN_SET(BINARY '番茄味', BINARY tags) > 0, 'TOMATO', NULL),
        IF(FIND_IN_SET(BINARY '清淡', BINARY tags) > 0, 'LIGHT', NULL),
        IF(FIND_IN_SET(BINARY '懒人食谱', BINARY tags) > 0, 'LOW_EFFORT', NULL),
        IF(FIND_IN_SET(BINARY '素食', BINARY tags) > 0
          OR FIND_IN_SET(BINARY '素食主义', BINARY tags) > 0, 'VEGETARIAN', NULL),
        IF(FIND_IN_SET(BINARY '健康食谱', BINARY tags) > 0, 'HEALTHY', NULL),
        IF(FIND_IN_SET(BINARY '午餐', BINARY tags) > 0, 'LUNCH', NULL),
        IF(FIND_IN_SET(BINARY '晚餐', BINARY tags) > 0, 'DINNER', NULL),
        IF(FIND_IN_SET(BINARY '朋友聚餐', BINARY tags) > 0, 'GATHERING', NULL),
        IF(CAST(NULLIF(REGEXP_SUBSTR(cook_time, '[0-9]+'), '') AS UNSIGNED) <= 20, 'QUICK', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('蒸' AS BINARY), CAST('清蒸' AS BINARY)), 'STEAM', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('炒' AS BINARY), CAST('爆炒' AS BINARY), CAST('煸炒' AS BINARY)), 'STIR_FRY', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('烧' AS BINARY), CAST('红烧' AS BINARY), CAST('焖' AS BINARY)), 'BRAISE', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('炖' AS BINARY), CAST('煮' AS BINARY), CAST('煲' AS BINARY)), 'STEW', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('烤' AS BINARY), CAST('烘焙' AS BINARY)), 'BAKE', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('炸' AS BINARY), CAST('煎炸' AS BINARY)), 'FRY', NULL),
        IF(CAST(methods AS BINARY) IN (CAST('拌' AS BINARY), CAST('凉拌' AS BINARY)), 'COLD_MIX', NULL)
    ),
    metadata_version = 1
WHERE user_id IS NULL;



-- Final verification: expected system dish count is 6,665.
SELECT COUNT(*) AS system_dishes FROM `food`.food WHERE user_id IS NULL;
SELECT COUNT(*) AS custom_dishes FROM `food`.food WHERE user_id IS NOT NULL;
SELECT cuisine_code, COUNT(*) AS dish_count
FROM `food`.food
WHERE user_id IS NULL
GROUP BY cuisine_code
ORDER BY cuisine_code;
SELECT
    SUM(tag_codes LIKE '%HOME_STYLE%') AS home_style_dishes,
    SUM(cuisine_code = 'SICHUAN') AS sichuan_dishes,
    SUM(cuisine_code = 'CANTONESE') AS cantonese_dishes
FROM `food`.food
WHERE user_id IS NULL;