INSERT INTO eatwhat_food_import (id, name, type, cl, fl, step, tags, image, difficulty, cook_time, ingredients_amounts, steps, step_images, tips, methods, kcal, is_custom, user_id, create_time) VALUES
(10170, '青椒肉丝', 'meat', '五香粉:6克#猪里脊:345克#青椒:205克#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#肉丝:345克', '2名成年人总量+15%冗余', '1. 将青椒和番茄切成图中所示备用~\\(≧▽≦)/~###2. 锅子倒上油之后放入里脊肉丝(油是凉的就倒肉肉),翻炒过程中放入少量五香粉和适量酱油,翻炒变色后放入事先切好的番茄翻炒出味儿,然后倒入青椒,加入一丁点水(千万别小手一抖放多了就变菜汤成主力了)。###3. 待快出锅时放入少量糖(出鲜味儿,而且我麻麻南方人,传授我做菜技巧时就这么放哈哈)适量盐,翻匀后关火。###4. 然后就可以开吃啦~', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/a/3/yuan_fa79f73016d773174d0b2faa03e3c6c3.jpg', '普通', '20分钟', '五香粉|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###肉丝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将青椒和番茄切成图中所示备用~\\(≧▽≦)/~###2. 锅子倒上油之后放入里脊肉丝(油是凉的就倒肉肉),翻炒过程中放入少量五香粉和适量酱油,翻炒变色后放入事先切好的番茄翻炒出味儿,然后倒入青椒,加入一丁点水(千万别小手一抖放多了就变菜汤成主力了)。###3. 待快出锅时放入少量糖(出鲜味儿,而且我麻麻南方人,传授我做菜技巧时就这么放哈哈)适量盐,翻匀后关火。###4. 然后就可以开吃啦~', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(10171, '丝瓜炒鸡蛋', 'meat', '丝瓜:460克#鸡蛋:5个#食用油:45毫升#食盐:7克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 丝瓜切成滚刀块(也可切片)备用。###2. 鸡蛋搅拌好,加入适量盐调味,###3. 锅热加少量橄榄油,放入蛋液,快炒盛出。###4. 重新放油,油热,加葱蒜辣椒爆香。###5. 倒入丝瓜翻炒,致丝瓜由白转入半透明。加盐调味。###6. 加入之前炒好的鸡蛋一起翻炒,临出锅加少量鸡精或味精。美味!', '禽类,蛋类,热菜,下饭菜,午餐,单身食谱,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/7/3/c/yuan_73659adee1a9c5f7c377877180bd73ec.jpg', '困难', '20分钟', '丝瓜|460|克|主料|去皮切块|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 丝瓜切成滚刀块(也可切片)备用。###2. 鸡蛋搅拌好,加入适量盐调味,###3. 锅热加少量橄榄油,放入蛋液,快炒盛出。###4. 重新放油,油热,加葱蒜辣椒爆香。###5. 倒入丝瓜翻炒,致丝瓜由白转入半透明。加盐调味。###6. 加入之前炒好的鸡蛋一起翻炒,临出锅加少量鸡精或味精。美味!', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(10264, '彩烩肉粒', 'meat', '牛肉:400克#红椒:170克#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克#花椒:6克#肉粒:345克', '2名成年人总量+15%冗余', '1. 牛肉,彩椒,香菇切1cm左右的粒,紫甘蓝修剪待用;###2. 牛肉粒抓浆(水淀粉)###3. 热锅下油放辣椒花椒葱姜蒜煸炒出香味,下牛肉粒,煸炒变色###4. 放入彩椒及香菇,继续煸炒###5. 放入绍酒、酱油、蚝油等调色调味,也可放入糖提鲜,若口轻可不再放盐###6. 最后放入松子,大火收汁儿即可出锅', '肉类,水产,热菜,单身食谱,下饭菜,家常菜,秋冬进补', 'https://cp1.douguo.net/upload/caiku/0/7/a/yuan_072892aa7480b82b0edc85be572589aa.jpg', '普通', '20分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###肉粒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 牛肉,彩椒,香菇切1cm左右的粒,紫甘蓝修剪待用;###2. 牛肉粒抓浆(水淀粉)###3. 热锅下油放辣椒花椒葱姜蒜煸炒出香味,下牛肉粒,煸炒变色###4. 放入彩椒及香菇,继续煸炒###5. 放入绍酒、酱油、蚝油等调色调味,也可放入糖提鲜,若口轻可不再放盐###6. 最后放入松子,大火收汁儿即可出锅', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(10270, '土豆烧老鸭', 'meat', '土豆:460克#食用油:45毫升#生抽:35毫升#香醋:30毫升#姜:25克#老鸭:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 原材###2. 炒鸭###3. 炒干后放醋,酒炒一下。###4. 醋酒炒后清冼###5. 放姜,油,爆香###6. 加入蚝油,生抽,炒一下###7. 放五匙茶匙卤汁###8. 入水。加八角###9. 放入电饭煲烧约半小时。###10. 土豆放油炒###11. 炒成这样OK###12. 加入土豆###13. 烧到干水。中途开盖小翻二下###14. 成品出炉', '肉类,禽类,水产,热菜,晚餐,午餐,下饭菜,家常菜,电饭煲', 'https://cp1.douguo.net/upload/caiku/2/e/a/yuan_2ea6d0fc9d504f275a6754b946d6d04a.jpg', '简单', '15分钟', '土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###老鸭|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 原材###2. 炒鸭###3. 炒干后放醋,酒炒一下。###4. 醋酒炒后清冼###5. 放姜,油,爆香###6. 加入蚝油,生抽,炒一下###7. 放五匙茶匙卤汁###8. 入水。加八角###9. 放入电饭煲烧约半小时。###10. 土豆放油炒###11. 炒成这样OK###12. 加入土豆###13. 烧到干水。中途开盖小翻二下###14. 成品出炉', '[]', '来源步骤数: 14', '炒', 0, 0, NULL, NULL),
(1043, '花肉烩扁豆土豆', 'meat', '五花肉:345克#土豆:460克#食盐:7克#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#花肉:345克#扁豆:345克#食用油:45毫升', '2名成年人总量+15%冗余', '1. 五花肉切片,扁豆洗净掰小段,土豆切条,葱姜蒜切碎备用。###2. 先将五花肉煸一下。###3. 放入葱姜蒜炝锅。###4. 放入土豆炒呀炒。###5. 再放入扁豆炒呀炒。###6. 加入料酒。###7. 再来点老抽翻炒上色。###8. 最后加入盐和适量的清水,小咕嘟一会。###9. 待食材全部软烂,汤汁也收尽就可以出锅了。', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/5/a/3/yuan_5a74c99c14c6cb56a115f6788139e2e3.jpg', '简单', '15分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###扁豆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全', '1. 五花肉切片,扁豆洗净掰小段,土豆切条,葱姜蒜切碎备用。###2. 先将五花肉煸一下。###3. 放入葱姜蒜炝锅。###4. 放入土豆炒呀炒。###5. 再放入扁豆炒呀炒。###6. 加入料酒。###7. 再来点老抽翻炒上色。###8. 最后加入盐和适量的清水,小咕嘟一会。###9. 待食材全部软烂,汤汁也收尽就可以出锅了。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(10949, '果味黑胡椒孜然烤鸡', 'meat', '梨:460克#孜然:9克#黑胡椒:6克#果味:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 清洗干净后,清水浸泡十二小时,泡出血水###2. 调味料###3. 准备好的梨子###4. Mix 调味料,再把准备好的梨子磨成糊状###5. 用牙签在表面扎几个孔,更容易入味,放入冰箱冷藏24小时###6. 烤箱预热五分钟,上下200度烤至三十分钟就可以出炉啦', '肉类,禽类,热菜,孜然,晚餐,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/1/1/1/yuan_11f8e91daa0c5ad34768c71cc58c2a21.jpeg', '困难', '60分钟', '梨|460|克|主料|去皮去核切块|2名成年人总量+15%冗余|步骤###孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###果味|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 清洗干净后,清水浸泡十二小时,泡出血水###2. 调味料###3. 准备好的梨子###4. Mix 调味料,再把准备好的梨子磨成糊状###5. 用牙签在表面扎几个孔,更容易入味,放入冰箱冷藏24小时###6. 烤箱预热五分钟,上下200度烤至三十分钟就可以出炉啦', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(11020, '步做出冰糖炖猪脚', 'meat', '白糖:55克#步做出:345克#猪脚:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 猪脚###2. 把撇沫后的猪脚放高压锅内,放我上面说的各种佐料(除鸡精和蜂蜜,最后收汤时加)盖上锅盖,大火炖十分钟后转小火二十五分钟即可。###3. 出高压锅后放炒锅稍微收汤,这样做出甜度适合,糯而不腻,可口美味,唇齿留香。###4. 出锅###5. 非常棒###6. 成品,简单、省事、而且口感极其美味香甜可口。', '肉类,禽类,热菜,午餐,朋友聚餐,家常菜,懒人食谱,高压锅', 'https://cp1.douguo.net/upload/caiku/9/6/1/yuan_96aad1dbf9dad8e971df80453d1b8121.jpg', '普通', '25分钟', '白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名###步做出|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###猪脚|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 猪脚###2. 把撇沫后的猪脚放高压锅内,放我上面说的各种佐料(除鸡精和蜂蜜,最后收汤时加)盖上锅盖,大火炖十分钟后转小火二十五分钟即可。###3. 出高压锅后放炒锅稍微收汤,这样做出甜度适合,糯而不腻,可口美味,唇齿留香。###4. 出锅###5. 非常棒###6. 成品,简单、省事、而且口感极其美味香甜可口。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(11057, '豆豉排骨', 'meat', '排骨:575克#红椒:170克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#葱:35克#豆豉:345克', '2名成年人总量+15%冗余', '1. 肋排洗净,控干水。炒锅内倒少许油,倒入豆豉煸香后,捞出豆豉。###2. 排骨内放葱姜片,酱油,料酒,淀粉,豆豉油,少量盐,拌匀腌制30分钟以上。###3. 将姜片葱片夹出,排骨均匀摆盘。之前煸香的豆豉也均匀倒在排骨上。###4. 蒸锅水开后,放入排骨蒸。30分钟后出锅,撒上碎红椒粒上桌!', '肉类,热菜,单身食谱,下酒菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/1/3/yuan_4155b9f6c7705f02486a748c6dc49d83.jpg', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###豆豉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 肋排洗净,控干水。炒锅内倒少许油,倒入豆豉煸香后,捞出豆豉。###2. 排骨内放葱姜片,酱油,料酒,淀粉,豆豉油,少量盐,拌匀腌制30分钟以上。###3. 将姜片葱片夹出,排骨均匀摆盘。之前煸香的豆豉也均匀倒在排骨上。###4. 蒸锅水开后,放入排骨蒸。30分钟后出锅,撒上碎红椒粒上桌!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(11081, '烤箱零食', 'meat', '排骨:575克#羊肉:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#箱零食:345克', '2名成年人总量+15%冗余', '1. 将排骨洗干净,倒点料酒,加点食用盐,辣油酱###2. 加点酱油,尽量让所有的佐料均匀的涂在排骨上###3. 放上切好的姜片和辣椒###4. 放进烤箱烤制20分钟左右,温度是200度###5. 美味的小排骨和烤的羊肉串相比,这个味道也很好', '肉类,热菜,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/f/a/1/yuan_fa68694de398310dd773b14d7c619011.jpeg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|步骤###羊肉|460|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###箱零食|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将排骨洗干净,倒点料酒,加点食用盐,辣油酱###2. 加点酱油,尽量让所有的佐料均匀的涂在排骨上###3. 放上切好的姜片和辣椒###4. 放进烤箱烤制20分钟左右,温度是200度###5. 美味的小排骨和烤的羊肉串相比,这个味道也很好', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(11193, '烤箱版腊肉', 'meat', '椒盐:9克#五花肉:345克#食用油:45毫升#食盐:7克#花椒:6克#箱版腊肉:345克', '2名成年人总量+15%冗余', '1. 五花肉去血水洗净吸干水份放烧酒抹匀###2. 用小火把盐和花椒炒香,盐的颜色略黄即可###3. 花椒盐均匀的抹在肉上后包紧放冰箱冷藏一天左右###4. 腌好的肉放烤箱架上,底下有个烤盘接油###5. 同时烤盘里扔些桂叶,八角,草果之类的香料,200华氏(95摄氏)烤12小时左右###6. 出炉了!', '肉类,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/9/3/3/yuan_931bb91bfa362877da8db4b2beb75a63.jpg', '困难', '60分钟', '椒盐|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###箱版腊肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 五花肉去血水洗净吸干水份放烧酒抹匀###2. 用小火把盐和花椒炒香,盐的颜色略黄即可###3. 花椒盐均匀的抹在肉上后包紧放冰箱冷藏一天左右###4. 腌好的肉放烤箱架上,底下有个烤盘接油###5. 同时烤盘里扔些桂叶,八角,草果之类的香料,200华氏(95摄氏)烤12小时左右###6. 出炉了!', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(11194, '简易萝卜炖牛腩', 'meat', '牛肉:400克#萝卜:460克#食盐:7克#简易:345克', '2名成年人总量+15%冗余', '1. 牛腩切成2*2cm大小。入锅中,加水,煮至水开后两分钟。冷水冲去血沫,血水。###2. 去血水的牛腩稍沥干水放入高压锅,加入所有调料,加水稍没过牛腩。待高压锅上汽后计时,大火煮10分钟。关火,待高压锅自然冷却泄气。###3. 白萝卜滚刀切约2*2cm大,加入牛腩中。试咸淡,淡了就加盐。盖高压锅盖子,上汽后马上关火。待高压锅自然冷却泄气。装盘,开吃。', '肉类,热菜,午餐,家常菜,懒人食谱,高压锅', 'https://cp1.douguo.net/upload/caiku/f/c/2/yuan_fc4648a68133a840269c7d437c81f6f2.jpg', '困难', '20分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###简易|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 牛腩切成2*2cm大小。入锅中,加水,煮至水开后两分钟。冷水冲去血沫,血水。###2. 去血水的牛腩稍沥干水放入高压锅,加入所有调料,加水稍没过牛腩。待高压锅上汽后计时,大火煮10分钟。关火,待高压锅自然冷却泄气。###3. 白萝卜滚刀切约2*2cm大,加入牛腩中。试咸淡,淡了就加盐。盖高压锅盖子,上汽后马上关火。待高压锅自然冷却泄气。装盘,开吃。', '[]', '来源步骤数: 3', '炖', 0, 0, NULL, NULL),
(1121, '春笋', 'meat', '枸杞:25克#猪肉:345克#青椒:205克#红椒:170克#竹笋:460克#食用油:45毫升#食盐:7克#淀粉:30克#葱:35克', '2名成年人总量+15%冗余', '1. 干锅加热,向锅内倒入少量葱油待油烧热后将肉丝倒入锅中摊开翻炒即可###2. 待肉丝炒熟后放入青椒丝和红椒丝,稍微翻炒一下即可放入春笋,然后开大火翻炒###3. 待春笋炒熟后,放入泡好的枸杞和汤汁###4. 放入少许盐和鸡精继续翻炒,最后加入少许水淀粉,稍微翻炒一下即可关火###5. 将准备好的黄菊花将花瓣取下,并清洗干净###6. 将洗净的黄菊花瓣放入锅中,用锅内余温翻炒两下即可装盘', '禽类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/f/a/yuan_8fd9e0832289e42b0ea8b2336249c64a.jpg', '普通', '20分钟', '枸杞|25|克|辅料|洗净备用|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 干锅加热,向锅内倒入少量葱油待油烧热后将肉丝倒入锅中摊开翻炒即可###2. 待肉丝炒熟后放入青椒丝和红椒丝,稍微翻炒一下即可放入春笋,然后开大火翻炒###3. 待春笋炒熟后,放入泡好的枸杞和汤汁###4. 放入少许盐和鸡精继续翻炒,最后加入少许水淀粉,稍微翻炒一下即可关火###5. 将准备好的黄菊花将花瓣取下,并清洗干净###6. 将洗净的黄菊花瓣放入锅中,用锅内余温翻炒两下即可装盘', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(11239, '香芹豆干炒牛肉', 'meat', '玉米:460克#黑胡椒:6克#牛肉:400克#豆干:345克#芹菜:400克#食用油:45毫升#生抽:35毫升#料酒:30毫升#淀粉:30克#香芹:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好材料哦~~牛肉我用微波炉解冻的~颜色欠佳吖###2. 牛肉改刀切条~豆干切条~小红美人椒一根,斜着切成条~###3. 芹菜去叶切小段~~我不知道怎么处理叶子...于是放进去一起了。最好是只要梗哦!!我买的是香芹...芹菜分两种哈~###4. 好啦我们开始腌肉~~~放入两勺料酒,三勺豆果酱油~两勺黑胡椒粉~然后拌一下~再加入玉米淀粉哦!!可以一点点添加搅拌~看肉裹上淀粉变黏糊就行啦~', '肉类,热菜,晚餐,下饭菜,午餐,单身食谱,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/6/8/d/yuan_6800a55e26419342d6470560b0783f9d.jpg', '普通', '20分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###豆干|345|克|主料|切片或切条|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###香芹|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好材料哦~~牛肉我用微波炉解冻的~颜色欠佳吖###2. 牛肉改刀切条~豆干切条~小红美人椒一根,斜着切成条~###3. 芹菜去叶切小段~~我不知道怎么处理叶子...于是放进去一起了。最好是只要梗哦!!我买的是香芹...芹菜分两种哈~###4. 好啦我们开始腌肉~~~放入两勺料酒,三勺豆果酱油~两勺黑胡椒粉~然后拌一下~再加入玉米淀粉哦!!可以一点点添加搅拌~看肉裹上淀粉变黏糊就行啦~', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(11317, '红烧肉上海口味', 'meat', '五花肉:345克#白糖:55克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#肉上海口味:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将五花肉切块,再用水抄一下,在锅中放入八角、桂皮、姜片去腥,抄好后备用。###2. 油锅中放油,将蒜瓣放入锅中翻炒,再倒入五花肉翻炒,再加入料酒没过五花肉即可。###3. 在锅中加入冰糖、生抽、老抽、味精、,调为小火进行慢慢炖煮,煮锅中收汁即可。', '上海菜,肉类,热菜,朋友聚餐,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/3/c/yuan_3331a7c32ce1c1da415e8d6e3fceff4c.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###肉上海口味|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将五花肉切块,再用水抄一下,在锅中放入八角、桂皮、姜片去腥,抄好后备用。###2. 油锅中放油,将蒜瓣放入锅中翻炒,再倒入五花肉翻炒,再加入料酒没过五花肉即可。###3. 在锅中加入冰糖、生抽、老抽、味精、,调为小火进行慢慢炖煮,煮锅中收汁即可。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(11352, '西红柿牛腩', 'meat', '牛肉:400克#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 准备材料###2. 牛腩洗净,冷水下锅,水开撇去浮沫,捞出牛肉备用###3. 锅中到底油,油热将牛肉倒进锅里翻炒,放入清水,加入葱、姜、香叶、盐大火烧开###4. 放入牛肉粉,加盖焖煮1小时###5. 捞出香叶、葱、姜后,放入西红柿,加入番茄酱与白糖,继续炖煮10分钟即可###6. 我做的西红柿牛腩', '肉类,热菜,晚餐,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/d/4/8/yuan_d474d281ae66520a5636600a2f4ef358.jpg', '困难', '60分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 准备材料###2. 牛腩洗净,冷水下锅,水开撇去浮沫,捞出牛肉备用###3. 锅中到底油,油热将牛肉倒进锅里翻炒,放入清水,加入葱、姜、香叶、盐大火烧开###4. 放入牛肉粉,加盖焖煮1小时###5. 捞出香叶、葱、姜后,放入西红柿,加入番茄酱与白糖,继续炖煮10分钟即可###6. 我做的西红柿牛腩', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(1202, '口香排骨', 'meat', '排骨:575克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#口香:345克', '2名成年人总量+15%冗余', '1. 排骨切小块###2. 洗净,加姜入锅焯水###3. 水煮开后加料酒再次煮开###4. 倒出洗去浮沫,沥干水###5. 二大勺排骨酱、一大勺甜辣酱、料酒、少许鲜酱油###6. 均匀抹在排骨上,放冰箱腌制至少4小时,期间翻转排骨几次###7. 排骨放碗中,入微波炉高火3分钟###8. 微波炉开时,把卷心菜洗净,用盐水泡一会,切成细丝,放在盆底。把排骨翻面,高火3分钟###9. 卷心菜上码好排骨', '肉类,热菜,下饭菜,朋友聚餐,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/f/6/9/yuan_f68d397d201ee740e1a96057bd293929.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###口香|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 排骨切小块###2. 洗净,加姜入锅焯水###3. 水煮开后加料酒再次煮开###4. 倒出洗去浮沫,沥干水###5. 二大勺排骨酱、一大勺甜辣酱、料酒、少许鲜酱油###6. 均匀抹在排骨上,放冰箱腌制至少4小时,期间翻转排骨几次###7. 排骨放碗中,入微波炉高火3分钟###8. 微波炉开时,把卷心菜洗净,用盐水泡一会,切成细丝,放在盆底。把排骨翻面,高火3分钟###9. 卷心菜上码好排骨', '[]', '来源步骤数: 9', '煮', 0, 0, NULL, NULL),
(1258, '喜丸子', 'meat', '猪肉:345克#鸡蛋:5个#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 肉馅加入鸡蛋,葱姜末朝一个方向搅拌,肉馅上劲儿###2. 加入面包糠继续搅拌(如果没有面包糠,也可以用馒头渣儿)###3. 团成丸子去油锅煎至金黄###4. 丸子捞出,锅中剩些底油,###5. 放入准备好的调料,先不放冰糖和香叶###6. 加热水,丸子,酱油,冰糖,香叶,中小火炖至汁液粘稠###7. 出锅,可撒些配菜', '肉类,禽类,蛋类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/5/f/yuan_b5a163875b57fbe4e5d50aa025c8716f.jpg', '困难', '60分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 肉馅加入鸡蛋,葱姜末朝一个方向搅拌,肉馅上劲儿###2. 加入面包糠继续搅拌(如果没有面包糠,也可以用馒头渣儿)###3. 团成丸子去油锅煎至金黄###4. 丸子捞出,锅中剩些底油,###5. 放入准备好的调料,先不放冰糖和香叶###6. 加热水,丸子,酱油,冰糖,香叶,中小火炖至汁液粘稠###7. 出锅,可撒些配菜', '[]', '来源步骤数: 7', '煎', 0, 0, NULL, NULL),
(1279, '色滑虾仁', 'meat', '虾:520克#红椒:170克#黄瓜:400克#萝卜:460克#食用油:45毫升#料酒:30毫升#淀粉:30克#蒜:30克#花椒:6克#色滑:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 虾仁洗净去线后加入料酒,花椒粉,淀粉后,拌均,腌制15分钟。###2. 材料切丁(大小依据个人爱好),蒜###3. 虾仁在油锅里煸炒7成熟时拿起备用,另起油,倒入胡萝卜翻炒,再加入红椒等~这时倒入蚝油翻炒均匀,倒入过油的虾仁,一分钟后加入黄瓜翻炒,所有材料在一起翻炒半分钟后,起锅~^_^', '水产,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/f/c/yuan_ef26ab4a0014df9bfe1b3b83dc428bdc.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###黄瓜|400|克|主料|洗净切片或拍碎|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###色滑|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 虾仁洗净去线后加入料酒,花椒粉,淀粉后,拌均,腌制15分钟。###2. 材料切丁(大小依据个人爱好),蒜###3. 虾仁在油锅里煸炒7成熟时拿起备用,另起油,倒入胡萝卜翻炒,再加入红椒等~这时倒入蚝油翻炒均匀,倒入过油的虾仁,一分钟后加入黄瓜翻炒,所有材料在一起翻炒半分钟后,起锅~^_^', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(12826, '泡椒芹菜牛肉丝', 'meat', '牛肉:400克#芹菜:400克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#泡椒丝:345克', '2名成年人总量+15%冗余', '1. 牛肉切丝后,放少量酱油,淀粉,料酒腌制十分钟,这时可以准备将芹菜切丝,泡椒及姜切丝###2. 锅内油烧至六成热(手放上锅上空感觉有明显热气上升),下姜丝煸炒出香味###3. 下牛肉丝滑炒变色###4. 放入泡椒丝一起炒约一分钟,即可将芹菜放入同炒###5. 炒一分钟后放一勺盐,半勺鸡精即可出锅', '川菜,禽类,肉类,热菜,泡椒,朋友聚餐,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/2/3/e/yuan_233bdf4d80167fa9400d7ecfca35665e.png', '普通', '20分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###泡椒丝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 牛肉切丝后,放少量酱油,淀粉,料酒腌制十分钟,这时可以准备将芹菜切丝,泡椒及姜切丝###2. 锅内油烧至六成热(手放上锅上空感觉有明显热气上升),下姜丝煸炒出香味###3. 下牛肉丝滑炒变色###4. 放入泡椒丝一起炒约一分钟,即可将芹菜放入同炒###5. 炒一分钟后放一勺盐,半勺鸡精即可出锅', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(12870, '孜然烤翅', 'meat', '孜然:9克#鸡翅:575克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升', '2名成年人总量+15%冗余', '1. 翅中洗净沥干水分,两面分别划几刀;###2. 倒上料酒、酱油、盐、胡椒粉拌匀;###3. 最后倒上孜然粉;###4. 拌匀后敷上保鲜膜,放冰箱里腌渍半小时以上;###5. 空气炸锅预热160度,将腌好的鸡翅中放进空气炸锅;###6. 烤10分钟之后,刷上一层橄榄油,翻个面继续烤5-10分钟即可;###7. 香喷喷的孜然烤翅出炉了,开吃!', '禽类,热菜,孜然,私家菜,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/a/f/4/yuan_af6507622f40ef4028adc4001f5e2ef4.jpg', '简单', '15分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤', '1. 翅中洗净沥干水分,两面分别划几刀;###2. 倒上料酒、酱油、盐、胡椒粉拌匀;###3. 最后倒上孜然粉;###4. 拌匀后敷上保鲜膜,放冰箱里腌渍半小时以上;###5. 空气炸锅预热160度,将腌好的鸡翅中放进空气炸锅;###6. 烤10分钟之后,刷上一层橄榄油,翻个面继续烤5-10分钟即可;###7. 香喷喷的孜然烤翅出炉了,开吃!', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(12885, '傣味番茄酸香虾', 'meat', '虾:520克#西红柿:460克#竹笋:460克#萝卜:460克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 青虾开背去皮洗净,横切成两片装,焯水备用###2. 番茄切丁,酸笋切末###3. 甘蓝菜和胡萝卜切丝,加沙拉酱搅拌备用。###4. 热锅放油,炒制番茄丁和酸笋末,加盐和焯虾水调味。最后放入焯好的虾。###5. 饵块切成薄片,放煎锅中煎成单面金黄色,将炒好的虾分装在饵块上,装盘配蔬菜沙拉。', '云南菜,水产,热菜,番茄味,下酒菜,创意菜,家常菜', 'https://cp1.douguo.net/upload/caiku/8/7/f/yuan_876331968505bf80cb4bb25ad2b3367f.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 青虾开背去皮洗净,横切成两片装,焯水备用###2. 番茄切丁,酸笋切末###3. 甘蓝菜和胡萝卜切丝,加沙拉酱搅拌备用。###4. 热锅放油,炒制番茄丁和酸笋末,加盐和焯虾水调味。最后放入焯好的虾。###5. 饵块切成薄片,放煎锅中煎成单面金黄色,将炒好的虾分装在饵块上,装盘配蔬菜沙拉。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(12907, '铸铁锅烤番茄牛肉', 'meat', '玉米:460克#牛肉:400克#西红柿:460克#白糖:55克#生抽:35毫升#老抽:15毫升#姜:25克#干辣椒:15克#铸铁锅:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 牛肉焯水,撇去浮沫捞出放入铸铁锅内,加入生抽、老抽、红葡萄酒炒匀。###2. 放入冰糖、姜片、干辣椒和香料包。###3. 加入整罐番茄酱,番茄酱建议买进口的生番茄酱,味道会比较好。###4. 加入热水,与肉持平。###5. 放入玉米与肉同煮至开锅。###6. 烤箱预热180度,铸铁锅放入中下层,加热2个小时即可。', '肉类,热菜,番茄味,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/0/a/yuan_803112323b722e2ff1e1d146c7f25c7a.png', '简单', '15分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###铸铁锅|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 牛肉焯水,撇去浮沫捞出放入铸铁锅内,加入生抽、老抽、红葡萄酒炒匀。###2. 放入冰糖、姜片、干辣椒和香料包。###3. 加入整罐番茄酱,番茄酱建议买进口的生番茄酱,味道会比较好。###4. 加入热水,与肉持平。###5. 放入玉米与肉同煮至开锅。###6. 烤箱预热180度,铸铁锅放入中下层,加热2个小时即可。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(12936, '肉丁蒸茄子', 'meat', '花生:170克#猪肉:345克#茄子:460克#香菇:230克#食用油:45毫升#食盐:7克#葱:35克#肉丁:345克', '2名成年人总量+15%冗余', '1. 茄子洗净。猪肉切成小丁放到小碗中,加入葱花、花生油、味极鲜、蘑菇精略微搅拌。###2. 肉丁跟茄子一起上锅蒸,大火沸腾后转中火继续蒸15分钟,关火焖2分钟。###3. 一手捏住茄蒂的硬心,一手用筷子夹住茄身,将蒸好的茄子摆入盘内,并用筷子或小刀在茄身上拉几道口子。往肉丁里加适量盐,拌匀,倒入茄子上。', '肉类,热菜,单身食谱,懒人食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/2/5/6/yuan_251e5f1108664df5c5895173412f58b6.jpg', '普通', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###茄子|460|克|主料|切块或切条|2名成年人总量+15%冗余|菜名+步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###肉丁|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 茄子洗净。猪肉切成小丁放到小碗中,加入葱花、花生油、味极鲜、蘑菇精略微搅拌。###2. 肉丁跟茄子一起上锅蒸,大火沸腾后转中火继续蒸15分钟,关火焖2分钟。###3. 一手捏住茄蒂的硬心,一手用筷子夹住茄身,将蒸好的茄子摆入盘内,并用筷子或小刀在茄身上拉几道口子。往肉丁里加适量盐,拌匀,倒入茄子上。', '[]', '来源步骤数: 3', '焖', 0, 0, NULL, NULL),
(13151, '胡萝卜肉皮冻', 'meat', '萝卜:460克#食用油:45毫升#食盐:7克#姜:25克#蒜:30克#肉皮冻:345克', '2名成年人总量+15%冗余', '1. 肉皮把毛去干净 洗净后煮十分钟左右(不能煮太长时间 太软不好去肥油)###2. 用刀把肥油刮干净###3. 用厨房剪把肉皮剪成丁###4. 胡萝卜切丁###5. 把肉皮丁 胡萝卜丁 姜未 蒜未 放进豆浆机 选择营养米糊 剩下的就是等待了###6. 打好成浓浆 可以放少许的盐拌匀 倒进干净的容器 放凉后冷藏###7. 冷藏后已经成型了 吃的时候切块即', '肉类,凉菜,热菜,午餐,家常菜,豆浆机', 'https://cp1.douguo.net/upload/caiku/0/f/9/yuan_0f0af7c782c58acb6b08d4b0200a31b9.jpg', '简单', '15分钟', '萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###肉皮冻|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 肉皮把毛去干净 洗净后煮十分钟左右(不能煮太长时间 太软不好去肥油)###2. 用刀把肥油刮干净###3. 用厨房剪把肉皮剪成丁###4. 胡萝卜切丁###5. 把肉皮丁 胡萝卜丁 姜未 蒜未 放进豆浆机 选择营养米糊 剩下的就是等待了###6. 打好成浓浆 可以放少许的盐拌匀 倒进干净的容器 放凉后冷藏###7. 冷藏后已经成型了 吃的时候切块即', '[]', '来源步骤数: 7', '煮', 0, 0, NULL, NULL),
(13272, '那些年我们一起追过的钵钵鸡', 'meat', '莴笋:460克#鸡翅:575克#鸡肉:520克#鸡蛋:5个#腐竹:230克#竹笋:460克#莲藕:460克#白糖:55克#食盐:7克#花椒:6克', '2名成年人总量+15%冗余', '1. 将腐竹提前用冷水泡发,鹌鹑蛋煮熟剥壳备用,鸭胗、鸡翅尖、鸡爪汆水后捞起沥干水分,鸡爪对切开,鸭胗切片备用。###2. 藕切薄片,腐竹切段,厚百叶切条,莴笋切滚刀块,分次将素菜煮熟后捞起沥干水分备用。###3. 将高汤和卤水汁倒入深锅中大火烧开后,放入所有荤菜转小火煮10分钟。###4. 准备一个大的钵,放入盐、花椒粉、白砂糖,然后将所有荤菜连汤汁倒入大钵中,然后一并放入素菜拌匀。', '川菜,禽类,蛋类,热菜,酸辣,下饭菜,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/2/e/2/yuan_2e64074fabe2ee7616b8aa3333ee5502.jpg', '普通', '25分钟', '莴笋|460|克|主料|去皮切片|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###腐竹|230|克|主料|提前泡发或切丝|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###莲藕|460|克|主料|去皮切片或切丁|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 将腐竹提前用冷水泡发,鹌鹑蛋煮熟剥壳备用,鸭胗、鸡翅尖、鸡爪汆水后捞起沥干水分,鸡爪对切开,鸭胗切片备用。###2. 藕切薄片,腐竹切段,厚百叶切条,莴笋切滚刀块,分次将素菜煮熟后捞起沥干水分备用。###3. 将高汤和卤水汁倒入深锅中大火烧开后,放入所有荤菜转小火煮10分钟。###4. 准备一个大的钵,放入盐、花椒粉、白砂糖,然后将所有荤菜连汤汁倒入大钵中,然后一并放入素菜拌匀。', '[]', '来源步骤数: 4', '煮', 0, 0, NULL, NULL),
(13375, '法国红酒炖牛肉', 'meat', '洋葱:290克#牛肉:400克#土豆:460克#萝卜:460克#食用油:45毫升#食盐:7克#蒜:30克#葱:35克#法国红酒:345克', '2名成年人总量+15%冗余', '1. 先将牛肉切成2厘米的丁,炖上30分钟左右,炖好备用。###2. 胡萝卜、土豆切成丁,辣椒切成块或条。###3. 将大蒜切片###4. 红酒是这道白重要的食材###5. 牛肉用油煎一下盛出来。###6. 将土豆、胡萝卜、洋葱,放入锅中翻炒,加入适量的盐,接着倒入牛肉一起翻炒。###7. 倒入红酒中火炖15分钟,加入鸡精,大火收汁。###8. 嫩滑爽口的法国红酒炖牛肉出炉了。', '禽类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/a/4/yuan_da1cfc917e733993c30f4ac436f28ac4.jpg', '困难', '60分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###法国红酒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 先将牛肉切成2厘米的丁,炖上30分钟左右,炖好备用。###2. 胡萝卜、土豆切成丁,辣椒切成块或条。###3. 将大蒜切片###4. 红酒是这道白重要的食材###5. 牛肉用油煎一下盛出来。###6. 将土豆、胡萝卜、洋葱,放入锅中翻炒,加入适量的盐,接着倒入牛肉一起翻炒。###7. 倒入红酒中火炖15分钟,加入鸡精,大火收汁。###8. 嫩滑爽口的法国红酒炖牛肉出炉了。', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(134, '萝卜烧牛肋排', 'meat', '排骨:575克#萝卜:460克#食用油:45毫升#料酒:30毫升#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 将牛肋排洗净血水,放入电压力锅中倒入料酒和1升左右的水,压20分钟。待压好后,将牛肋排捞出备用,压牛肋排剩下的汤汁留着备用。###2. 白萝卜去皮切滚刀块。###3. 炒锅中放入食用油烧至6成热,放入老姜,柱候酱,牛肋排爆香。###4. 然后倒入压牛肋排的汤汁。放入白萝卜,盖上锅盖,大火烧开后,转中小火烧30分钟至萝卜入味。###5. 就好了!', '肉类,热菜,朋友聚餐,午餐,家常菜,电压力锅,压力锅', 'https://cp1.douguo.net/upload/caiku/f/f/5/yuan_ff9638dae04cbf4f358a4973a9add755.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将牛肋排洗净血水,放入电压力锅中倒入料酒和1升左右的水,压20分钟。待压好后,将牛肋排捞出备用,压牛肋排剩下的汤汁留着备用。###2. 白萝卜去皮切滚刀块。###3. 炒锅中放入食用油烧至6成热,放入老姜,柱候酱,牛肋排爆香。###4. 然后倒入压牛肋排的汤汁。放入白萝卜,盖上锅盖,大火烧开后,转中小火烧30分钟至萝卜入味。###5. 就好了!', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(13499, '陕北小吃鸡蛋泡泡', 'meat', '鸡蛋:5个#面粉:400克#白糖:55克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 三颗鸡蛋加适量盐或白糖打匀,盐或者白糖随各人喜好添加###2. 蛋液中加入适量40度左右温水,随后加入适量面粉,边加边用勺子搅拌,直至面糊可以拉丝###3. 大火,滚油,将一勺一勺的面糊倒入油中,慢慢炸至金黄即可!为什么叫鸡蛋泡泡,就是因为最后成型是泡泡状!如果是凉油将面糊倒进去炸出来的是饼状', '西北菜,蛋类,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/7/6/yuan_3759003dbbe0599a39625f30373ab546.jpg', '简单', '15分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 三颗鸡蛋加适量盐或白糖打匀,盐或者白糖随各人喜好添加###2. 蛋液中加入适量40度左右温水,随后加入适量面粉,边加边用勺子搅拌,直至面糊可以拉丝###3. 大火,滚油,将一勺一勺的面糊倒入油中,慢慢炸至金黄即可!为什么叫鸡蛋泡泡,就是因为最后成型是泡泡状!如果是凉油将面糊倒进去炸出来的是饼状', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(13559, '剁椒蒸鱼片', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#料酒:30毫升#姜:25克#蒜:30克#葱:35克#剁椒:345克', '2名成年人总量+15%冗余', '1. 将草鱼中断从中间切块然后用刀切开但不要切断###2. 用黄酒和盐腌制10分钟左右###3. 码在平盘上,撒上自制剁椒(已经有了蒜末和姜末之类所以没另外放)###4. 烧开水放入蒸6-8分钟左右(根据鱼的大小)取出###5. 将多余汁倒掉,然后淋上蒸鱼豉油###6. 撒香葱末最后浇热油即可', '水产,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/7/3/yuan_07a4bb71ffaa0acb0b3daaccae80c6a3.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###剁椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将草鱼中断从中间切块然后用刀切开但不要切断###2. 用黄酒和盐腌制10分钟左右###3. 码在平盘上,撒上自制剁椒(已经有了蒜末和姜末之类所以没另外放)###4. 烧开水放入蒸6-8分钟左右(根据鱼的大小)取出###5. 将多余汁倒掉,然后淋上蒸鱼豉油###6. 撒香葱末最后浇热油即可', '[]', '来源步骤数: 6', '蒸', 0, 0, NULL, NULL),
(13643, '番茄牛肉', 'meat', '玉米:460克#洋葱:290克#牛肉:400克#土豆:460克#西红柿:460克#萝卜:460克#食用油:45毫升#生抽:35毫升#料酒:30毫升#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 备齐所有材料:洋葱切片 土豆胡萝卜切滚刀块 番茄切块 大葱切葱花 牛肉提前清炖好了 估计大家清炖牛肉都会做所以就没有从头做起了###2. 锅中放入适量玉米油 油热后放入八角炒香###3. 放入葱花炒香###4. 放入洋葱翻炒1分钟###5. 放入番茄翻炒出少量茄汁加入适量熟酱油###6. 烹入料酒放入胡萝卜土豆翻炒2分钟左右###7. 放入适量的番茄酱或者番茄沙司也可以###8. 加入清水', '肉类,热菜,番茄味,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/5/7/yuan_6522ebd00a4060bc67c333d7e1454337.jpg', '困难', '60分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 备齐所有材料:洋葱切片 土豆胡萝卜切滚刀块 番茄切块 大葱切葱花 牛肉提前清炖好了 估计大家清炖牛肉都会做所以就没有从头做起了###2. 锅中放入适量玉米油 油热后放入八角炒香###3. 放入葱花炒香###4. 放入洋葱翻炒1分钟###5. 放入番茄翻炒出少量茄汁加入适量熟酱油###6. 烹入料酒放入胡萝卜土豆翻炒2分钟左右###7. 放入适量的番茄酱或者番茄沙司也可以###8. 加入清水', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(137, '文鱼塔塔', 'meat', '柠檬:170克#黑胡椒:6克#鱼:690克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 备好所有用料###2. 将宜家三文鱼及培根切粒,三文鱼撒上黑胡椒先腌制一会儿,牛油果压成泥。###3. 锅中倒油,倒入培根和三文鱼粒加少许盐炒香。###4. 盛盘装出###5. 将三文鱼培根和牛油果挤入少许柠檬汁相拌,撒上黑胡椒###6. 用慕斯模具装盆,上面撒上坚果蔓越莓粒。搭配自己榨的云南石榴汁,可以抗氧化。', '海鲜,水产,肉类,热菜,午餐,单身食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/5/d/8/yuan_5d267d9bd6f8b2aa0142fabad4afe498.jpeg', '普通', '20分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 备好所有用料###2. 将宜家三文鱼及培根切粒,三文鱼撒上黑胡椒先腌制一会儿,牛油果压成泥。###3. 锅中倒油,倒入培根和三文鱼粒加少许盐炒香。###4. 盛盘装出###5. 将三文鱼培根和牛油果挤入少许柠檬汁相拌,撒上黑胡椒###6. 用慕斯模具装盆,上面撒上坚果蔓越莓粒。搭配自己榨的云南石榴汁,可以抗氧化。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(13709, '花肉炒菜椒', 'meat', '五花肉:345克#青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#葱:35克#花肉:345克', '2名成年人总量+15%冗余', '1. 锅里烧水放点油,,然后先烫下菜椒###2. 烫八分熟就好,,然后用冷水过滤下冷水,,这样菜椒就不会变黄###3. 五花肉跟葱切好备用###4. 锅放油烧开后放五花肉爆炒###5. 五花肉炒熟之后倒入菜椒,,五花肉怎样才算炒熟,,每个人定义不同,喜欢吃没那么油的多炒下就好了###6. 加盐和酱油翻炒几个,,就可以出盘了###7. 成品', '肉类,热菜,晚餐,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/0/4/d/yuan_0446099162326d6b5350841d6290a83d.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 锅里烧水放点油,,然后先烫下菜椒###2. 烫八分熟就好,,然后用冷水过滤下冷水,,这样菜椒就不会变黄###3. 五花肉跟葱切好备用###4. 锅放油烧开后放五花肉爆炒###5. 五花肉炒熟之后倒入菜椒,,五花肉怎样才算炒熟,,每个人定义不同,喜欢吃没那么油的多炒下就好了###6. 加盐和酱油翻炒几个,,就可以出盘了###7. 成品', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(13729, '糖醋带鱼', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 带鱼清洗干净,可以先放料酒和少许盐腌制一会!葱姜蒜切小末或者小段备用,料汁是把上述调料放入碗中!###2. 锅中放油,带鱼煎两面焦黄,中火不要急于翻面,###3. 带鱼煎好之后放葱姜蒜,和料汁!炖一会直至入味!出锅###4. 腊八你好', '海鲜,水产,热菜,酸甜,家常菜', 'https://cp1.douguo.net/upload/caiku/5/1/f/yuan_5157971eb6961b2ac8fe90af7f52d64f.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 带鱼清洗干净,可以先放料酒和少许盐腌制一会!葱姜蒜切小末或者小段备用,料汁是把上述调料放入碗中!###2. 锅中放油,带鱼煎两面焦黄,中火不要急于翻面,###3. 带鱼煎好之后放葱姜蒜,和料汁!炖一会直至入味!出锅###4. 腊八你好', '[]', '来源步骤数: 4', '煎', 0, 0, NULL, NULL),
(13819, '土豆炒肉片', 'meat', '猪肉:345克#土豆:460克#红椒:170克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. 猪肉切片,加料酒,生抽,淀粉,少量老抽拌匀。土豆洗净(不去皮)切3mm厚片,冲洗干净,加盖入微波炉高火叮3分钟。###2. 热油锅入肉片翻炒变色后拨至一边,入姜丝蒜泥红椒炒香,倒入土豆片,炒匀后加少量水,盐,糖,少量老抽焖煮收干汁。###3. 吃了一半可以看到汤汁很诱人。', '川菜,肉类,热菜,单身食谱,懒人食谱,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/4/7/1/yuan_478c4140423ac1baaa2b582c73d37d51.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 猪肉切片,加料酒,生抽,淀粉,少量老抽拌匀。土豆洗净(不去皮)切3mm厚片,冲洗干净,加盖入微波炉高火叮3分钟。###2. 热油锅入肉片翻炒变色后拨至一边,入姜丝蒜泥红椒炒香,倒入土豆片,炒匀后加少量水,盐,糖,少量老抽焖煮收干汁。###3. 吃了一半可以看到汤汁很诱人。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(1384, '糖醋小排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#香醋:30毫升#淀粉:30克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 将排骨剁成小段洗净,在电压力锅(普通压力锅也行)中加入水、葱姜、料酒、盐和排骨,将排骨煮熟捞起待用。###2. 将水、水淀粉、老抽、香油、醋调成碗汁。###3. 另起油锅,放入少量油,加入冰糖小火融化,倒入碗汁烧开,把煮熟的排骨倒入裹匀,再煮片刻即可。', '肉类,热菜,酸甜,朋友聚餐,下饭菜,家常菜,电压力锅,压力锅', 'https://cp1.douguo.net/upload/caiku/a/e/f/yuan_aecbd04d7052bc60fc3bedbede337e2f.jpg', '普通', '45分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 将排骨剁成小段洗净,在电压力锅(普通压力锅也行)中加入水、葱姜、料酒、盐和排骨,将排骨煮熟捞起待用。###2. 将水、水淀粉、老抽、香油、醋调成碗汁。###3. 另起油锅,放入少量油,加入冰糖小火融化,倒入碗汁烧开,把煮熟的排骨倒入裹匀,再煮片刻即可。', '[]', '来源步骤数: 3', '糖醋', 0, 0, NULL, NULL),
(14022, '芹菜香干炒肉片', 'meat', '猪里脊:345克#豆干:345克#香菇:230克#芹菜:400克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#葱:35克#花椒:6克#肉片:345克', '2名成年人总量+15%冗余', '1. 芹菜洗净,斜切成片,嫰芹菜叶不要扔,营养又美味。香干和里脊肉都切片。葱切成葱花。###2. 里脊肉加淀粉抓匀,锅烧热,加油,放入肉片滑开,加生抽炒熟待用。亲们记住,热锅凉油不会扒锅。###3. 锅中油烧热,加二十几粒花椒炸香,捞出,放葱花,煸炒出香味,放芹菜,大火爆炒,翻炒片刻,加入香干,点入香菇水,倒入肉片,加少许盐调味,喜欢香油的可以点少许,出锅即可。###4. 成品~', '肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/a/3/2/yuan_a34b5724681e3462b1af3dfbf445b432.jpg', '普通', '20分钟', '猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###豆干|345|克|主料|切片或切条|2名成年人总量+15%冗余|菜名+步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###肉片|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 芹菜洗净,斜切成片,嫰芹菜叶不要扔,营养又美味。香干和里脊肉都切片。葱切成葱花。###2. 里脊肉加淀粉抓匀,锅烧热,加油,放入肉片滑开,加生抽炒熟待用。亲们记住,热锅凉油不会扒锅。###3. 锅中油烧热,加二十几粒花椒炸香,捞出,放葱花,煸炒出香味,放芹菜,大火爆炒,翻炒片刻,加入香干,点入香菇水,倒入肉片,加少许盐调味,喜欢香油的可以点少许,出锅即可。###4. 成品~', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(1415, '香熏鱼', 'meat', '鱼:690克#食用油:45毫升#香熏:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 草鱼洗净切片(肚内黑色膜一定要洗掉,不然成品会很腥)###2. 将鱼片彻底沥干###3. 将所有调味料一并倒入水(或鸡汤)中煮滚,中火熬至浓稠待用###4. 另起油锅(热锅冷油)将鱼片炸至两面金黄,起锅前调至大火将鱼片中的油分逼出,可确保鱼片酥脆###5. 将鱼片浸泡至酱料中约5分钟后取出,装盆', '水产,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/4/9/yuan_54487010ee14c2bbd2b0c0e404d5bfa9.jpg', '困难', '60分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###香熏|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 草鱼洗净切片(肚内黑色膜一定要洗掉,不然成品会很腥)###2. 将鱼片彻底沥干###3. 将所有调味料一并倒入水(或鸡汤)中煮滚,中火熬至浓稠待用###4. 另起油锅(热锅冷油)将鱼片炸至两面金黄,起锅前调至大火将鱼片中的油分逼出,可确保鱼片酥脆###5. 将鱼片浸泡至酱料中约5分钟后取出,装盆', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(14317, '番茄煎鹌鹑蛋', 'meat', '黑胡椒:6克#椒盐:9克#鸡蛋:5个#西红柿:460克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 备好食材###2. 番茄洗净,带皮切厚片###3. 用汤匙或小刀在番茄片中间挖开###4. 平底锅烧热,放少许食用油###5. 放入番茄中火煎制一会###6. 鹌鹑蛋敲破,放入番茄中心位置###7. 遮上锅盖焗30秒钟左右,让鹌鹑蛋快速凝固###8. 鹌鹑蛋定型后铲起,摆在碟子上,撒些椒盐粉、黑椒粒即可###9. 成品###10. 成品', '禽类,蛋类,热菜,番茄味,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/7/7/9/yuan_7717f47cdf04dc1b1ab403f302136c69.jpg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###椒盐|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 备好食材###2. 番茄洗净,带皮切厚片###3. 用汤匙或小刀在番茄片中间挖开###4. 平底锅烧热,放少许食用油###5. 放入番茄中火煎制一会###6. 鹌鹑蛋敲破,放入番茄中心位置###7. 遮上锅盖焗30秒钟左右,让鹌鹑蛋快速凝固###8. 鹌鹑蛋定型后铲起,摆在碟子上,撒些椒盐粉、黑椒粒即可###9. 成品###10. 成品', '[]', '来源步骤数: 10', '炒', 0, 0, NULL, NULL),
(14390, '辅食之虾仁荷兰豆', 'meat', '虾:520克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 新鲜活虾剥皮取仁,清洗干净,加适量料酒和淀粉腌制几分钟###2. 荷兰豆掐去两头,用水焯一分钟左右###3. 锅里加油至六成热,放入虾仁滑炒,在加入葱姜蒜和适量盐,最后放入荷兰豆翻炒熟即可###4. 在来一张图###5. 看看我家小妞兜兜都还没有穿上就迫不及待的用手抓进嘴里了', '海鲜,水产,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/4/7/yuan_549143c30dcfc0ab244522f5a6310407.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 新鲜活虾剥皮取仁,清洗干净,加适量料酒和淀粉腌制几分钟###2. 荷兰豆掐去两头,用水焯一分钟左右###3. 锅里加油至六成热,放入虾仁滑炒,在加入葱姜蒜和适量盐,最后放入荷兰豆翻炒熟即可###4. 在来一张图###5. 看看我家小妞兜兜都还没有穿上就迫不及待的用手抓进嘴里了', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(14720, '花肉炒芹菜', 'meat', '五花肉:345克#青椒:205克#芹菜:400克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#花肉:345克', '2名成年人总量+15%冗余', '1. 五花肉切片###2. 其它配料也切片,备用###3. 五花肉先煸炒,然后加入蒜,姜...炒五分钟,加入尖椒###4. 五分钟后加入芹菜段,同时加人盐,酱油调味,再炒三分钟加入蠔油大火翻炒三十秒,出锅###5. 时间控制好,芹菜脆口,尖椒也脆中带香。', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/1/1/yuan_e1b8ea0c834b186a58846aad84f6c401.jpeg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 五花肉切片###2. 其它配料也切片,备用###3. 五花肉先煸炒,然后加入蒜,姜...炒五分钟,加入尖椒###4. 五分钟后加入芹菜段,同时加人盐,酱油调味,再炒三分钟加入蠔油大火翻炒三十秒,出锅###5. 时间控制好,芹菜脆口,尖椒也脆中带香。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(1474, '粉蒸排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 这是所需的材料。###2. 排骨洗净控干水,放入葱姜 料酒腌20分钟。###3. 挑出葱姜,放入小勺老抽、一点糖提味。###4. 放两块腐乳、少量腐乳水。###5. 耗油一勺(也可不用)###6. 拌匀后,加一袋蒸肉粉。(超市都有,我用的是五香味)。拌匀后,腌30分钟,充分入味。###7. 上锅蒸,水开后小火40分钟以上。###8. 出锅即可', '肉类,热菜,下酒菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/4/8/yuan_94f7a0ec1836ab47a0ca96828ab25af8.jpg', '困难', '45分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 这是所需的材料。###2. 排骨洗净控干水,放入葱姜 料酒腌20分钟。###3. 挑出葱姜,放入小勺老抽、一点糖提味。###4. 放两块腐乳、少量腐乳水。###5. 耗油一勺(也可不用)###6. 拌匀后,加一袋蒸肉粉。(超市都有,我用的是五香味)。拌匀后,腌30分钟,充分入味。###7. 上锅蒸,水开后小火40分钟以上。###8. 出锅即可', '[]', '来源步骤数: 8', '蒸', 0, 0, NULL, NULL),
(14821, '鸡公煲', 'meat', '洋葱:290克#鸡肉:520克#土豆:460克#红椒:170克#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#豆瓣酱:30克#姜:25克#蒜:30克#葱:35克#鸡公:345克', '2名成年人总量+15%冗余', '1. 把,所以食材都洗好,切好。###2. 鸡肉,先用水煮一下,加一点料酒去腥,去掉血沐,洗干净。###3. 先把,洋葱,青红椒煸炒一下在出锅,留油放蒜头,生姜,葱,再放郫县豆瓣酱炒###4. 炒出香味放入鸡肉和土豆,放入料酒,酱油,糖。继续炒一会。###5. 加入香菇,水,盐,盖锅盖煮。###6. 等煮到快收汁时,把之前炒过的洋葱 ,青红椒放进去,加入鸡精。出锅。', '禽类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/8/d/yuan_189c53dd4c3f0b517200ec1b5801cb2d.jpg', '困难', '60分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###鸡公|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 把,所以食材都洗好,切好。###2. 鸡肉,先用水煮一下,加一点料酒去腥,去掉血沐,洗干净。###3. 先把,洋葱,青红椒煸炒一下在出锅,留油放蒜头,生姜,葱,再放郫县豆瓣酱炒###4. 炒出香味放入鸡肉和土豆,放入料酒,酱油,糖。继续炒一会。###5. 加入香菇,水,盐,盖锅盖煮。###6. 等煮到快收汁时,把之前炒过的洋葱 ,青红椒放进去,加入鸡精。出锅。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(14978, '焖五花', 'meat', '五花肉:345克#芹菜:400克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#五花:345克', '2名成年人总量+15%冗余', '1. 把五花肉切成厚薄均匀后,烧红锅不放油,中火把五花肉的油煎出来。煎到两边呈金黄色。###2. 放姜爆炒后,加入老抽生抽。超至肉上色。###3. 把蒜苗加入,再炒一下。###4. 在砂锅底放少许油铺上芹菜、蒜苗。###5. 把肉放入锅中,加上冰糖。###6. 加入八角、料酒、水没过肉的2分一。盖上锅盖。中火焖20分钟。待收汁后,加盐关火即可。###7. 加上香菜装饰。', '肉类,热菜,下饭菜,一家三口,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/f/4/e/yuan_f42d59542a1aa14be57bfdffc61fe92e.jpg', '困难', '60分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###五花|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 把五花肉切成厚薄均匀后,烧红锅不放油,中火把五花肉的油煎出来。煎到两边呈金黄色。###2. 放姜爆炒后,加入老抽生抽。超至肉上色。###3. 把蒜苗加入,再炒一下。###4. 在砂锅底放少许油铺上芹菜、蒜苗。###5. 把肉放入锅中,加上冰糖。###6. 加入八角、料酒、水没过肉的2分一。盖上锅盖。中火焖20分钟。待收汁后,加盐关火即可。###7. 加上香菜装饰。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(15152, '花肉炒豆干', 'meat', '五花肉:345克#豆干:345克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#花肉:345克', '2名成年人总量+15%冗余', '1. 准备五花肉,豆干,辣椒,姜,蒜。###2. 五花肉,豆干切片,辣椒切丝,姜切片,蒜头拍碎切皮。###3. 先热锅放五花肉,五花肉出油两面焦黃色,放入姜,蒜,辣椒翻炒一分钟,放入豆干放调料盐,鸡粉,酱油,约两分钟后放料酒再翻炒三十秒就可以出锅了。', '豆制品,禽类,肉类,热菜,下饭菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/f/8/b/yuan_f80186135cc3bf82da4393449399609b.jpg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###豆干|345|克|主料|切片或切条|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 准备五花肉,豆干,辣椒,姜,蒜。###2. 五花肉,豆干切片,辣椒切丝,姜切片,蒜头拍碎切皮。###3. 先热锅放五花肉,五花肉出油两面焦黃色,放入姜,蒜,辣椒翻炒一分钟,放入豆干放调料盐,鸡粉,酱油,约两分钟后放料酒再翻炒三十秒就可以出锅了。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(15158, '菜花炒鸡蛋', 'meat', '鸡蛋:5个#菜花:520克#食用油:45毫升#食盐:7克#料酒:30毫升#葱:35克', '2名成年人总量+15%冗余', '1. 有机菜花摘好洗净。水烧开后加一点 食用油 盐,将菜花焯水。因为孩子吃 所以焯的比较软。捞出控水。###2. 鸡蛋中加一点料酒去腥,打散。###3. 热锅倒油,润锅。油温高一些,将打散的鸡蛋倒入,晃一圈。鸡蛋快速膨大,用锅铲略翻几秒钟后关火,盛出。这样鸡蛋炒嫩一点。###4. 锅内余油爆香葱花###5. 倒入菜花翻炒几下,接着倒入鸡蛋,加盐调味,出锅前滴入香油提味。翻炒均匀即可出锅。', '蛋类,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/8/e/yuan_e8bdd465c06c3c9692beea8cbc342bee.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###菜花|520|克|主料|掰小朵洗净|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 有机菜花摘好洗净。水烧开后加一点 食用油 盐,将菜花焯水。因为孩子吃 所以焯的比较软。捞出控水。###2. 鸡蛋中加一点料酒去腥,打散。###3. 热锅倒油,润锅。油温高一些,将打散的鸡蛋倒入,晃一圈。鸡蛋快速膨大,用锅铲略翻几秒钟后关火,盛出。这样鸡蛋炒嫩一点。###4. 锅内余油爆香葱花###5. 倒入菜花翻炒几下,接着倒入鸡蛋,加盐调味,出锅前滴入香油提味。翻炒均匀即可出锅。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(15252, '豆爷香辣麻小', 'meat', '虾:520克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#豆瓣酱:30克#姜:25克#蒜:30克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 用牙刷一只只洗好虾爬爬,用盐水泡10分钟后清水过2遍,滤干备用###2. 准备配料###3. 八角茴香 桂皮 花椒 香叶###4. 锅下2两豆油5成热,先加花椒辣椒爆香然后葱姜蒜郫县豆瓣酱一起爆香,加入香叶、八角茴香、桂皮翻炒。加入虾爬爬翻炒至变色,加一瓶啤酒,白酒少许,加生抽 、老抽、糖转中火加入青椒煮10分钟,再大火收汁起锅###5. 放上香菜大功告成!开吃吧!', '水产,热菜,香辣,晚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/b/f/yuan_eb06f02d99653186aed59bef0ffae62f.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 用牙刷一只只洗好虾爬爬,用盐水泡10分钟后清水过2遍,滤干备用###2. 准备配料###3. 八角茴香 桂皮 花椒 香叶###4. 锅下2两豆油5成热,先加花椒辣椒爆香然后葱姜蒜郫县豆瓣酱一起爆香,加入香叶、八角茴香、桂皮翻炒。加入虾爬爬翻炒至变色,加一瓶啤酒,白酒少许,加生抽 、老抽、糖转中火加入青椒煮10分钟,再大火收汁起锅###5. 放上香菜大功告成!开吃吧!', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(1537, '烤鸟蛋', 'meat', '鸡蛋:5个#食用油:45毫升#食盐:7克#鸟蛋:345克', '2名成年人总量+15%冗余', '1. 模具里用刷子刷一层香油,鹌鹑蛋磕开,打进模具里,海苔片剪成碎条###2. 在鹌鹑蛋上撒适量盐、适量胡椒粉,撒适量海苔(部分撒海苔,另一部分烤好后可以抹上自己喜欢的酱料)###3. 烤箱预热200度,将烤模放入,定时7分钟,中途看到鹌鹑蛋鼓起来时,打开烤箱门,用牙签在每个鹌鹑蛋上戳一下,最后时间到了,拿出即可###4. 胡椒海苔的拿出来就可以吃,还可以挤上适量的抹酱', '蛋类,禽类,热菜,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/3/7/3/yuan_37bcc3d6f2334ab88a9552a36c278a23.jpeg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###鸟蛋|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 模具里用刷子刷一层香油,鹌鹑蛋磕开,打进模具里,海苔片剪成碎条###2. 在鹌鹑蛋上撒适量盐、适量胡椒粉,撒适量海苔(部分撒海苔,另一部分烤好后可以抹上自己喜欢的酱料)###3. 烤箱预热200度,将烤模放入,定时7分钟,中途看到鹌鹑蛋鼓起来时,打开烤箱门,用牙签在每个鹌鹑蛋上戳一下,最后时间到了,拿出即可###4. 胡椒海苔的拿出来就可以吃,还可以挤上适量的抹酱', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(1557, '酸辣牛腩', 'meat', '牛肉:400克#土豆:460克#竹笋:460克#白糖:55克#食用油:45毫升#生抽:35毫升#豆瓣酱:30克#姜:25克#蒜:30克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 牛腩切块,冷水下锅,下一把花椒,焯水后捞出。###2. 热锅下油,下豆瓣酱,蒜瓣,姜片炒出红油。###3. 下牛腩翻炒,肉质收紧后加入一汤匙米酒和一汤匙生抽,稍稍翻炒,再加入酸笋条,竹笋片,泡椒和辣椒,再加入一汤匙白糖稍稍翻炒。###4. 加入土豆块,再加入足量的热水,再次煮开,转小火煮一个小时以上或者移入高压锅煮半个小时。', '肉类,热菜,酸辣,午餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/e/3/5/yuan_e34848d2b75b6643568b1f818be82aa5.jpg', '普通', '25分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 牛腩切块,冷水下锅,下一把花椒,焯水后捞出。###2. 热锅下油,下豆瓣酱,蒜瓣,姜片炒出红油。###3. 下牛腩翻炒,肉质收紧后加入一汤匙米酒和一汤匙生抽,稍稍翻炒,再加入酸笋条,竹笋片,泡椒和辣椒,再加入一汤匙白糖稍稍翻炒。###4. 加入土豆块,再加入足量的热水,再次煮开,转小火煮一个小时以上或者移入高压锅煮半个小时。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(15583, '小鸡炖蘑菇', 'meat', '鸡肉:520克#香菇:230克#食用油:45毫升#生抽:35毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#小鸡:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡切块,过水###2. 蒜葱姜切好###3. 蘑菇切块备用###4. 油锅预热,葱姜蒜下锅炒香###5. 下鸡块炒微黄###6. 放入八角胡椒粉香叶花椒粉倒入白酒###7. 倒入酱油###8. 倒入蚝油###9. 倒入大喜大牛肉粉###10. 倒入开水、没过鸡肉、炖10分钟###11. 下蘑菇块翻炒、在炖5分钟就可以出锅了、蘑菇容易粘锅、注意翻炒', '东北菜,禽类,水产,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/2/1/yuan_c25b84443b138150c358ba3fb790d911.jpg', '困难', '20分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###小鸡|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡切块,过水###2. 蒜葱姜切好###3. 蘑菇切块备用###4. 油锅预热,葱姜蒜下锅炒香###5. 下鸡块炒微黄###6. 放入八角胡椒粉香叶花椒粉倒入白酒###7. 倒入酱油###8. 倒入蚝油###9. 倒入大喜大牛肉粉###10. 倒入开水、没过鸡肉、炖10分钟###11. 下蘑菇块翻炒、在炖5分钟就可以出锅了、蘑菇容易粘锅、注意翻炒', '[]', '来源步骤数: 11', '炒', 0, 0, NULL, NULL),
(15878, '蒸蒸更的南瓜蒸排骨', 'meat', '排骨:575克#南瓜:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#蒜:30克#更的:345克', '2名成年人总量+15%冗余', '1. 准备食材。南瓜切片,稍厚~###2. 排骨洗净斩件,备好蒜蓉、豆豉###3. 将油、盐、酱油、糖、生粉、蒜蓉、豆豉放入排骨里,拌匀,腌30分钟(气温高的夏天最好放冰箱)###4. 将腌好的排骨铺在南瓜上###5. 水开后蒸15分钟。出锅喽~###6. 营养美味~', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/9/e/yuan_c923618426dd7f94a5cfa1928f93085e.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###南瓜|575|克|主料|去瓤切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###更的|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 准备食材。南瓜切片,稍厚~###2. 排骨洗净斩件,备好蒜蓉、豆豉###3. 将油、盐、酱油、糖、生粉、蒜蓉、豆豉放入排骨里,拌匀,腌30分钟(气温高的夏天最好放冰箱)###4. 将腌好的排骨铺在南瓜上###5. 水开后蒸15分钟。出锅喽~###6. 营养美味~', '[]', '来源步骤数: 6', '蒸', 0, 0, NULL, NULL),
(15901, '抱子甘蓝炒火腿肠', 'meat', '火腿:290克#黑胡椒:6克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克#抱子甘蓝:345克', '2名成年人总量+15%冗余', '1. 可爱的芽甘蓝。###2. 部分食材###3. 抱子甘蓝对剥,放热水里加点盐稍煮一下。###4. 葱、蒜、姜切沫,火腿肠切片,水果蕃茄切小块备用。###5. 热锅倒入橄榄油,将姜、蒜沫炒香,再依次放入葱、火腿肠、蕃茄、抱子甘蓝翻炒几下。###6. 加入一勺菁选酱油提鲜。###7. 最后洒一点黑胡椒碎即可。###8. 很简单、很美味哦!', '肉类,热菜,晚餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/3/0/8/yuan_3058bdc5c2224ec2863456e61df3ec88.jpg', '普通', '20分钟', '火腿|290|克|主料|切片|2名成年人总量+15%冗余|菜名+步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###抱子甘蓝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 可爱的芽甘蓝。###2. 部分食材###3. 抱子甘蓝对剥,放热水里加点盐稍煮一下。###4. 葱、蒜、姜切沫,火腿肠切片,水果蕃茄切小块备用。###5. 热锅倒入橄榄油,将姜、蒜沫炒香,再依次放入葱、火腿肠、蕃茄、抱子甘蓝翻炒几下。###6. 加入一勺菁选酱油提鲜。###7. 最后洒一点黑胡椒碎即可。###8. 很简单、很美味哦!', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(15969, '糖醋带鱼', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#香醋:30毫升#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 全家福###2. 鱼去除内脏,洗净切块;均匀拌入调味料腌制约30分钟###3. 空气炸锅180度预热5分钟###4. 完成后将鱼块放入炸篮中,炸篮上刷点油,也给鱼块刷些辣椒油,烤约15-20分钟###5. 中途拿出来翻面###6. 烤好了很香!###7. 最后浇上糖醋汁,再撒点葱花即可', '海鲜,水产,热菜,酸甜,午餐,朋友聚餐,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/d/e/2/yuan_de8aece03b9989474a1d8e98046fd702.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 全家福###2. 鱼去除内脏,洗净切块;均匀拌入调味料腌制约30分钟###3. 空气炸锅180度预热5分钟###4. 完成后将鱼块放入炸篮中,炸篮上刷点油,也给鱼块刷些辣椒油,烤约15-20分钟###5. 中途拿出来翻面###6. 烤好了很香!###7. 最后浇上糖醋汁,再撒点葱花即可', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(16005, '肉炒豆芽', 'meat', '猪肉:345克#食用油:45毫升#食盐:7克#生抽:35毫升#葱:35克#豆芽:345克', '2名成年人总量+15%冗余', '1. 豆芽择去老根,洗净。###2. 瘦肉切丝。###3. 倒入适量菁选酱油,腌制入味。###4. 锅中烧开水,放入黄豆芽,焯去豆腥味。捞出控水。###5. 另起油锅,烧温热。###6. 放入腌好的肉丝,顿时酱香味扑鼻。煸炒变色。###7. 放入豆芽翻炒。###8. 放入小葱、少量盐。(这时也可以再加一些酱油调色)###9. 炒匀即可。', '肉类,热菜,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/e/e/c/yuan_ee751355895be1d92ec2400c48a0d84c.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###豆芽|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 豆芽择去老根,洗净。###2. 瘦肉切丝。###3. 倒入适量菁选酱油,腌制入味。###4. 锅中烧开水,放入黄豆芽,焯去豆腥味。捞出控水。###5. 另起油锅,烧温热。###6. 放入腌好的肉丝,顿时酱香味扑鼻。煸炒变色。###7. 放入豆芽翻炒。###8. 放入小葱、少量盐。(这时也可以再加一些酱油调色)###9. 炒匀即可。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(16060, '种生蚝两种吃法', 'meat', '生蚝:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#蒜:30克', '2名成年人总量+15%冗余', '1. 生蚝全部洗净沥干水分###2. 先做蒜蓉芝士烤生蚝,把一半生蚝加入适量蒜蓉、盐、糖、生抽,烤箱200度烤15分钟###3. 把烤出的水分倒掉铺上芝士,烤箱160度烤5分钟左右###4. 家里没有烤箱的话,就做蒜蓉蒸生蚝也很好吃,蒜蓉、盐、糖、生抽铺到生蚝上,上锅蒸20分钟,喜欢原味的可以什么都不加直接烤熟或蒸熟蘸芥末酱油也很美味', '海鲜,水产,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/5/3/c/yuan_53f477b237dde461f5753967b1df791c.jpg', '普通', '25分钟', '生蚝|575|克|主料|刷洗干净|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 生蚝全部洗净沥干水分###2. 先做蒜蓉芝士烤生蚝,把一半生蚝加入适量蒜蓉、盐、糖、生抽,烤箱200度烤15分钟###3. 把烤出的水分倒掉铺上芝士,烤箱160度烤5分钟左右###4. 家里没有烤箱的话,就做蒜蓉蒸生蚝也很好吃,蒜蓉、盐、糖、生抽铺到生蚝上,上锅蒸20分钟,喜欢原味的可以什么都不加直接烤熟或蒸熟蘸芥末酱油也很美味', '[]', '来源步骤数: 4', '蒸', 0, 0, NULL, NULL),
(1616, '新奥尔良烤翅', 'meat', '鸡翅:575克#土豆:460克#新奥尔良:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 就是这个料~在网上买的 才20多哇 30多 很便宜~ 用这个勺子加了3勺半###2. 一个鸡翅上切3刀更入味###3. 加水??放入鸡翅 ??盖好盖子??放入冰箱腌制最少4个小时 可以过夜###4. 烤箱预热上下火200度 下面最好加一片蔬菜 比如土豆之类的 这样烤翅不会粘在锡箔纸上 而且还能吃点蔬菜~ ??上下火200度 烤10分钟 ??取出来把鸡翅都翻一面 涂上新奥尔', '禽类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/7/4/1/yuan_74171beb7889efa7665e4291cfbfac11.jpg', '普通', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###新奥尔良|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 就是这个料~在网上买的 才20多哇 30多 很便宜~ 用这个勺子加了3勺半###2. 一个鸡翅上切3刀更入味###3. 加水??放入鸡翅 ??盖好盖子??放入冰箱腌制最少4个小时 可以过夜###4. 烤箱预热上下火200度 下面最好加一片蔬菜 比如土豆之类的 这样烤翅不会粘在锡箔纸上 而且还能吃点蔬菜~ ??上下火200度 烤10分钟 ??取出来把鸡翅都翻一面 涂上新奥尔', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(16204, '香辣宫保虾', 'meat', '花生:170克#虾:520克#豆干:345克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#干辣椒:15克#花椒:6克#宫保:345克', '2名成年人总量+15%冗余', '1. 草虾剪去虾须洗净,在虾背上横切一刀,加入盐、料酒和白胡椒粉拌匀,腌制15分钟。###2. 葱白切成段状;姜、蒜都切成片,辣椒剪成辣椒圈,青椒切丁。###3. 烧热锅内油,倒入基围虾炒至虾壳变红,立即盛入碟中。###4. 续添油烧热,用小火炒香干辣椒和辣椒酱,倒入葱白、姜片和蒜片炒至香味溢出,然后加入酱油,盐,倒入草虾,花生米炒匀,最后放入糖,淋上料酒,撒上花椒面即可上碟。', '川菜,海鲜,水产,热菜,香辣,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/4/a/yuan_c429429bf1f2af051f2021dc92a8ebea.jpg', '普通', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###豆干|345|克|主料|切片或切条|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###宫保|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 草虾剪去虾须洗净,在虾背上横切一刀,加入盐、料酒和白胡椒粉拌匀,腌制15分钟。###2. 葱白切成段状;姜、蒜都切成片,辣椒剪成辣椒圈,青椒切丁。###3. 烧热锅内油,倒入基围虾炒至虾壳变红,立即盛入碟中。###4. 续添油烧热,用小火炒香干辣椒和辣椒酱,倒入葱白、姜片和蒜片炒至香味溢出,然后加入酱油,盐,倒入草虾,花生米炒匀,最后放入糖,淋上料酒,撒上花椒面即可上碟。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(16230, '蒜汁龙利鱼细嫩滑口的诱人', 'meat', '黑胡椒:6克#鱼:690克#食用油:45毫升#生抽:35毫升#淀粉:30克#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 蒜切碎末,加入蚝油,生抽,黑胡椒粉,食用油,橄榄油,调汁;###2. 龙利鱼从冰箱取出,解冻,用厨房纸巾吸取表面水分,斜刀切片;###3. 切好的龙利鱼,表面均匀的裹上淀粉;###4. 裹好淀粉后,再均匀的裹上调好的汁,腌制20分钟;###5. 腌制好后,整齐的码放在烤盘上,烤箱预热后,温度220度,时间15分钟,放入烤盘即可。', '水产,热菜,下饭菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/5/1/a/yuan_514d40ea002e708b4818525671c579fa.jpg', '普通', '25分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 蒜切碎末,加入蚝油,生抽,黑胡椒粉,食用油,橄榄油,调汁;###2. 龙利鱼从冰箱取出,解冻,用厨房纸巾吸取表面水分,斜刀切片;###3. 切好的龙利鱼,表面均匀的裹上淀粉;###4. 裹好淀粉后,再均匀的裹上调好的汁,腌制20分钟;###5. 腌制好后,整齐的码放在烤盘上,烤箱预热后,温度220度,时间15分钟,放入烤盘即可。', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(16347, '麻辣香水鱼', 'meat', '鱼:690克#白菜:575克#食用油:45毫升#姜:25克#葱:35克#香水:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将准备好的鱼片、鱼骨等清洗一下,沥干水分,麻辣香水鱼自带粉料包拆开放在鱼片上搅拌均匀,可以适当放两片姜和葱一起腌一会儿,期间洗好小葱和香菜###2. 白菜开水烫一下沥干水分备用###3. 锅内放油,烧热后加入麻辣香水鱼的辣椒调料炒出红油,加入适量开水,大火烧开###4. 将腌好的鱼骨鱼头先行放入锅内,煮开后放入剩下的鱼片###5. 煮至鱼片熟透出锅放在白菜上,放香菜香葱即可', '川菜,水产,热菜,麻辣,朋友聚餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/a/1/7/yuan_a1d59b1ab0558509fb07b3bee8212bc7.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白菜|575|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###香水|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将准备好的鱼片、鱼骨等清洗一下,沥干水分,麻辣香水鱼自带粉料包拆开放在鱼片上搅拌均匀,可以适当放两片姜和葱一起腌一会儿,期间洗好小葱和香菜###2. 白菜开水烫一下沥干水分备用###3. 锅内放油,烧热后加入麻辣香水鱼的辣椒调料炒出红油,加入适量开水,大火烧开###4. 将腌好的鱼骨鱼头先行放入锅内,煮开后放入剩下的鱼片###5. 煮至鱼片熟透出锅放在白菜上,放香菜香葱即可', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(16393, '糖醋鲫鱼', 'meat', '玉米:460克#鱼:690克#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#淀粉:30克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 原料。###2. 鲫鱼洗净,在鱼身两面切几刀,用少许白酒,盐,胡椒粉腌20分钟。###3. 腌好的鱼抹少许玉米淀粉。###4. 热油炸制。###5. 炸至金黄捞出。###6. 用少许水,番茄酱,白糖,生抽,玉米淀粉,盐调汁。###7. 炒锅倒少许油,放入葱末和姜末炸香,倒入碗汁炒至粘稠后浇在炸好的鱼上即可。', '浙菜,水产,热菜,酸甜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/3/d/yuan_535a466bc75ded06c920becbe1fdcf6d.jpg', '普通', '25分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 原料。###2. 鲫鱼洗净,在鱼身两面切几刀,用少许白酒,盐,胡椒粉腌20分钟。###3. 腌好的鱼抹少许玉米淀粉。###4. 热油炸制。###5. 炸至金黄捞出。###6. 用少许水,番茄酱,白糖,生抽,玉米淀粉,盐调汁。###7. 炒锅倒少许油,放入葱末和姜末炸香,倒入碗汁炒至粘稠后浇在炸好的鱼上即可。', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(16405, '鲜卤', 'meat', '猪肉:345克#虾:520克#鸡蛋:5个#豆干:345克#腐竹:230克#木耳:35克#菜花:520克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#淀粉:30克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 虾仁去沙线,调底口(盐白胡椒料酒粉面上浆)###2. 猪肉切片上浆调味(盐白胡椒料酒)###3. 香干切小片,面巾切小块,腐竹,花菜,木耳改切小块,鸡蛋加料酒打散炒出备用。###4. 锅底放油7成热下肉片虾仁姜葱炝出香味放香干面巾腐竹花菜木耳料酒老抽水大火烧开放盐糖味精香油淋水淀粉后放炒好鸡蛋出锅即可。###5. 三鲜卤', '禽类,水产,蛋类,肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/b/7/yuan_9b8d84b8622fc1032f8c292ec286ff77.jpg', '普通', '25分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###豆干|345|克|主料|切片或切条|2名成年人总量+15%冗余|步骤###腐竹|230|克|主料|提前泡发或切丝|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###菜花|520|克|主料|掰小朵洗净|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 虾仁去沙线,调底口(盐白胡椒料酒粉面上浆)###2. 猪肉切片上浆调味(盐白胡椒料酒)###3. 香干切小片,面巾切小块,腐竹,花菜,木耳改切小块,鸡蛋加料酒打散炒出备用。###4. 锅底放油7成热下肉片虾仁姜葱炝出香味放香干面巾腐竹花菜木耳料酒老抽水大火烧开放盐糖味精香油淋水淀粉后放炒好鸡蛋出锅即可。###5. 三鲜卤', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(16415, '鲜炒虾仁', 'meat', '虾:520克#食用油:45毫升#食盐:7克#淀粉:30克', '2名成年人总量+15%冗余', '1. 鲜虾去壳、去虾线,裹上生粉,这样炒出来的虾有一种水晶质感,又能保持虾的鲜美###2. 锅烧热下油,先炒虾仁,虾仁变色后差不多就可以起锅,不要炒太久会变老###3. 单独炒三鲜,加入适量的盐巴,待三鲜快炒熟时把炒好的虾仁加进去一起翻炒###4. 炒好的虾仁,色泽和味道都不错,看着很有食欲', '水产,热菜,下饭菜,午餐,孕妇食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/0/c/6/yuan_0c7bcde4f5f987b00bc2b7f8e2906166.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 鲜虾去壳、去虾线,裹上生粉,这样炒出来的虾有一种水晶质感,又能保持虾的鲜美###2. 锅烧热下油,先炒虾仁,虾仁变色后差不多就可以起锅,不要炒太久会变老###3. 单独炒三鲜,加入适量的盐巴,待三鲜快炒熟时把炒好的虾仁加进去一起翻炒###4. 炒好的虾仁,色泽和味道都不错,看着很有食欲', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(16467, '文豆腐鱼头', 'meat', '鱼:690克#豆腐:460克#红椒:170克#牛奶:575毫升#食用油:45毫升#食盐:7克#姜:25克', '2名成年人总量+15%冗余', '1. 1,先将买来的三文鱼头洗净,将红椒跟老姜切丝备好,热锅冷油将三文鱼头煎黄###2. 2,放冷水熬高汤,大火先将水煮开,再转小火慢慢熬,注意海鱼都有锅边泡泡,记得拿勺子舀出来。###3. 3,把三文鱼头煮熟后,把准备好的纯牛奶倒入,放置豆腐,豆腐熟了加少许盐,保持海鱼原有的鲜味,起锅的时候撒上香菜即可。', '水产,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/d/4/yuan_1d6372444aa72f1932308c67fc5a8934.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###牛奶|575|毫升|主料|直接使用|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 1,先将买来的三文鱼头洗净,将红椒跟老姜切丝备好,热锅冷油将三文鱼头煎黄###2. 2,放冷水熬高汤,大火先将水煮开,再转小火慢慢熬,注意海鱼都有锅边泡泡,记得拿勺子舀出来。###3. 3,把三文鱼头煮熟后,把准备好的纯牛奶倒入,放置豆腐,豆腐熟了加少许盐,保持海鱼原有的鲜味,起锅的时候撒上香菜即可。', '[]', '来源步骤数: 3', '煎', 0, 0, NULL, NULL),
(1648, '香菇烘蛋', 'meat', '鸡蛋:5个#香菇:230克#食用油:45毫升#食盐:7克#烘蛋:345克', '2名成年人总量+15%冗余', '1. 原材料:鸡蛋3个,新鲜香菇4朵洗净沥干。###2. 鸡蛋打散成蛋液,香菇切碎末。###3. 将香菇碎倒入蛋液搅拌均匀,根据个人口味加入适量盐。###4. 起锅热油,倒入蛋液中小火烘煎,过程需要有点耐心,等蛋液凝固一面定形再翻面,可用两只木铲辅助,保持形状,煎至两面金黄即可。###5. 烘完蛋的锅都是香香的,用锅里的残油炒了个饭,老公吃完还找我添,呵呵。', '蛋类,禽类,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/7/0/5/yuan_70984f35d687ec8784369446d4696b55.jpg', '简单', '15分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###烘蛋|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 原材料:鸡蛋3个,新鲜香菇4朵洗净沥干。###2. 鸡蛋打散成蛋液,香菇切碎末。###3. 将香菇碎倒入蛋液搅拌均匀,根据个人口味加入适量盐。###4. 起锅热油,倒入蛋液中小火烘煎,过程需要有点耐心,等蛋液凝固一面定形再翻面,可用两只木铲辅助,保持形状,煎至两面金黄即可。###5. 烘完蛋的锅都是香香的,用锅里的残油炒了个饭,老公吃完还找我添,呵呵。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(16496, '老太太的烤鸡根', 'meat', '洋葱:290克#鸡蛋:5个#淀粉:30克#姜:25克#葱:35克#老太太的:345克#鸡根:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好各种调料,混合,成酱。###2. 把洗净,吸干水分的鸡根放入大的容器,加入调制好的酱,加入生姜,洋葱,鸡蛋清,生粉,烤肉粉可以再适量加入,搅拌均匀,腌制一晚上,冷藏。###3. 烤箱预热,250度,中层,25分钟,期间翻面,再次刷上剩下来的烤酱,上色,喜欢颜色深点,焦点的可以再考10分钟。PS:中间步骤忘拍了,省略,文字描述。###4. 成品图。', '禽类,蛋类,肉类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/5/c/yuan_85dec1bc3a402c90221f17abd8838cbc.jpg', '普通', '25分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###老太太的|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###鸡根|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好各种调料,混合,成酱。###2. 把洗净,吸干水分的鸡根放入大的容器,加入调制好的酱,加入生姜,洋葱,鸡蛋清,生粉,烤肉粉可以再适量加入,搅拌均匀,腌制一晚上,冷藏。###3. 烤箱预热,250度,中层,25分钟,期间翻面,再次刷上剩下来的烤酱,上色,喜欢颜色深点,焦点的可以再考10分钟。PS:中间步骤忘拍了,省略,文字描述。###4. 成品图。', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(1654, '蜜汁黑椒猪肉脯', 'meat', '芝麻:35克#玉米:460克#黑胡椒:6克#猪肉:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 将除了蜂蜜和芝麻的所有东西倒入猪肉馅中,搅拌,成猪肉糜。###2. 腌制30分钟以上。###3. 烤箱预热,烤盘包上锡纸,在锡纸上涂抹一层玉米油,肉会比较好拿下来。###4. 把腌制好的肉糜放置于锡纸上,用擀面杖压均匀,压薄,大概3毫米左右。###5. 在肉上涂抹蜂蜜,撒上少许白芝麻。烤箱170°C中层烤15分钟,拿出,翻面,涂抹蜂蜜,撒芝麻,在放入烤箱170°C,15分钟。', '肉类,零食,热菜,黑椒,下酒菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/0/d/1/yuan_0d3e600efce836a8f81c85ad2e92b081.jpg', '简单', '15分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将除了蜂蜜和芝麻的所有东西倒入猪肉馅中,搅拌,成猪肉糜。###2. 腌制30分钟以上。###3. 烤箱预热,烤盘包上锡纸,在锡纸上涂抹一层玉米油,肉会比较好拿下来。###4. 把腌制好的肉糜放置于锡纸上,用擀面杖压均匀,压薄,大概3毫米左右。###5. 在肉上涂抹蜂蜜,撒上少许白芝麻。烤箱170°C中层烤15分钟,拿出,翻面,涂抹蜂蜜,撒芝麻,在放入烤箱170°C,15分钟。', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(16546, '超红烧爆鲫鱼', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#超红:345克', '2名成年人总量+15%冗余', '1. 鲫鱼洗净去鳞 鱼身划数刀###2. 少许油入锅,小火 ,下姜片 蒜头 , 爆香 ,###3. 把鲫鱼放锅里 两面煎,有点变黄后(如图,###4. 放入盐,料酒,少许水,继续煎一两分钟###5. 之后 下酱油 醋 味精 葱段 就可以起锅啦,,,###6. 一盘香喷喷 健康 美味的 爆鲫鱼就做好啦!', '水产,热菜,晚餐,午餐,朋友聚餐,幼儿食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/1/f/9/yuan_1f8bcb4230c0f92c9d6a18c384da3e59.jpg', '困难', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###超红|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鲫鱼洗净去鳞 鱼身划数刀###2. 少许油入锅,小火 ,下姜片 蒜头 , 爆香 ,###3. 把鲫鱼放锅里 两面煎,有点变黄后(如图,###4. 放入盐,料酒,少许水,继续煎一两分钟###5. 之后 下酱油 醋 味精 葱段 就可以起锅啦,,,###6. 一盘香喷喷 健康 美味的 爆鲫鱼就做好啦!', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(16627, '红烧排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 排骨冷水下过放入葱姜 一起煮啊煮,煮大概半小时。###2. 锅烧热,下入糖,炒到棕黄色,倒入煮好的排骨。就会发现排骨上色啦!好神奇!###3. 倒入料酒,生抽老抽,翻炒。加水没过排骨,加入桂皮与八角。炖煮三十分钟。味道不够了加酱油~', '肉类,热菜,下酒菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/f/6/yuan_dfca12c6ffb3daf0df510224ca8bc4b6.jpg', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 排骨冷水下过放入葱姜 一起煮啊煮,煮大概半小时。###2. 锅烧热,下入糖,炒到棕黄色,倒入煮好的排骨。就会发现排骨上色啦!好神奇!###3. 倒入料酒,生抽老抽,翻炒。加水没过排骨,加入桂皮与八角。炖煮三十分钟。味道不够了加酱油~', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(16647, '蜜汁鸡翅', 'meat', '鸡翅:575克#白糖:55克#食用油:45毫升#生抽:35毫升#蜜汁:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 买鸡中翅回来,划痕,准备一个碗,加生抽,糖,白酒,自己偿味道,合适就把鸡中翅放进碗里面,用保鲜袋装着放冰箱里面,我是前天晚上腌制,第二天做。###2. 热油,开小火,放鸡中翅,用筷子不停的翻边,然后煎至两面金黄###3. 成品,看,很简单很简单', '禽类,热菜,朋友聚餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/7/e/0/yuan_7efeeff4bdc72904ca17c545dfed25c0.jpg', '普通', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蜜汁|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 买鸡中翅回来,划痕,准备一个碗,加生抽,糖,白酒,自己偿味道,合适就把鸡中翅放进碗里面,用保鲜袋装着放冰箱里面,我是前天晚上腌制,第二天做。###2. 热油,开小火,放鸡中翅,用筷子不停的翻边,然后煎至两面金黄###3. 成品,看,很简单很简单', '[]', '来源步骤数: 3', '煎', 0, 0, NULL, NULL),
(16679, '传统海鳗', 'meat', '洋葱:290克#鱼:690克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#海鳗:345克', '2名成年人总量+15%冗余', '1. 先将浸好的鳗干码在盘中,将洋葱圈,拍碎的大蒜头,大葱段,红辣椒,姜片放于鳗鱼上,均匀撒上1勺老抽,3勺料酒,半勺菜油,一点点鸡精(无需再放盐),再加2勺清水###2. 把盘子放在电饭煲蒸架上蒸吧,饭熟了,鳗鱼也熟了噢(舟山的一个蜀黍告诉我的,一试果然如此!)###3. 饭好了,鱼也蒸好了呦~撒上葱花即可^W^', '禽类,水产,热菜,鲜,午餐,家常菜,电饭煲', 'https://cp1.douguo.net/upload/caiku/7/3/e/yuan_732a7f29ab3551d6a2d92fbcca9febce.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###海鳗|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 先将浸好的鳗干码在盘中,将洋葱圈,拍碎的大蒜头,大葱段,红辣椒,姜片放于鳗鱼上,均匀撒上1勺老抽,3勺料酒,半勺菜油,一点点鸡精(无需再放盐),再加2勺清水###2. 把盘子放在电饭煲蒸架上蒸吧,饭熟了,鳗鱼也熟了噢(舟山的一个蜀黍告诉我的,一试果然如此!)###3. 饭好了,鱼也蒸好了呦~撒上葱花即可^W^', '[]', '来源步骤数: 3', '煲', 0, 0, NULL, NULL),
(16719, '蔬菜烤鱼', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#蔬菜:345克', '2名成年人总量+15%冗余', '1. 鱼洗干净,切花刀。###2. 调汁:碗内放料酒,蚝油,盐,橄榄油,酱油,调成料汁。###3. 将调好的料汁抹到鱼身上,装保鲜袋腌渍1小时。###4. 烤盘底部抹油,放葱姜蒜适量,放入腌好的鱼,烤箱预热200度30分钟。###5. 烤好后,放入喜欢的蔬菜,撒适量盐。###6. 另起一锅,爆香葱姜蒜,辣椒,加一碗水,烧开后倒入烤盘内。###7. 再入烤箱220度20分钟', '川菜,水产,热菜,下饭菜,午餐,家常菜,懒人食谱,烤箱', 'https://cp1.douguo.net/upload/caiku/5/1/c/yuan_51748e8c410b1490fac53b0f9edb491c.jpeg', '困难', '60分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###蔬菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鱼洗干净,切花刀。###2. 调汁:碗内放料酒,蚝油,盐,橄榄油,酱油,调成料汁。###3. 将调好的料汁抹到鱼身上,装保鲜袋腌渍1小时。###4. 烤盘底部抹油,放葱姜蒜适量,放入腌好的鱼,烤箱预热200度30分钟。###5. 烤好后,放入喜欢的蔬菜,撒适量盐。###6. 另起一锅,爆香葱姜蒜,辣椒,加一碗水,烧开后倒入烤盘内。###7. 再入烤箱220度20分钟', '[]', '来源步骤数: 7', '烤', 0, 0, NULL, NULL),
(16721, '泡椒凤爪', 'meat', '鸡肉:520克#鱼:690克#芹菜:400克#萝卜:460克#食用油:45毫升#料酒:30毫升#香醋:30毫升#姜:25克#葱:35克#泡椒:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好食材###2. 冷锅冷水中加入洗净的鸡爪 白醋 葱 姜 料酒 大火煮沸后转中小火煮10分钟左右###3. 鸡爪煮好后开大火放入胡萝卜和芹菜 芹菜变色后捞出###4. 用净水冲洗到没有油花###5. 放入泡椒 香糟卤 鱼露 放冰箱冷藏二到三小时就可以啃了 味道好极了###6. 成品', '禽类,水产,热菜,泡椒,下酒菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/1/8/yuan_81683d5ee7ad54522feb42b38b4010c8.jpg', '普通', '25分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###泡椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好食材###2. 冷锅冷水中加入洗净的鸡爪 白醋 葱 姜 料酒 大火煮沸后转中小火煮10分钟左右###3. 鸡爪煮好后开大火放入胡萝卜和芹菜 芹菜变色后捞出###4. 用净水冲洗到没有油花###5. 放入泡椒 香糟卤 鱼露 放冰箱冷藏二到三小时就可以啃了 味道好极了###6. 成品', '[]', '来源步骤数: 6', '煮', 0, 0, NULL, NULL),
(16747, '可乐鸡翅无比', 'meat', '鸡翅:575克#食用油:45毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 2勺油,爆香葱和姜,放鸡翅煎至金黄(鸡翅最好正反面划3刀,易熟)###2. 加可乐,略低于鸡翅(喜欢吃甜的盆友可乐可多加)。大火至可乐滚后降小火,盖锅5~10分钟后,用筷子插进鸡翅里看是否软了,软了代表熟了!大火收汁!###3. 大功告成!太好吃了!', '禽类,热菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/4/a/8/yuan_4a26f121c1e1a8488a3076029e8a09e8.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 2勺油,爆香葱和姜,放鸡翅煎至金黄(鸡翅最好正反面划3刀,易熟)###2. 加可乐,略低于鸡翅(喜欢吃甜的盆友可乐可多加)。大火至可乐滚后降小火,盖锅5~10分钟后,用筷子插进鸡翅里看是否软了,软了代表熟了!大火收汁!###3. 大功告成!太好吃了!', '[]', '来源步骤数: 3', '煎', 0, 0, NULL, NULL),
(16782, '可乐鸡翅', 'meat', '柠檬:170克#鸡翅:575克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#可乐:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡翅洗干净 老姜切片备好###2. 在鸡翅有一粒粒小疙瘩的一面用牙签戳几个小洞洞 入味 另外一面用刀划两下 放入适量的老姜料酒和酱油 再滴入几滴柠檬汁 使鸡翅肉质更嫩 腌制20~30min左右###3. 半小时之后 锅中水煮开将鸡翅过水焯一下###4. 锅烧热 倒入一点点油 放入老姜 鸡翅将鸡翅两面煎一下###5. 倒入可乐 老抽 喜欢 甜辣的 再放点辣椒###6. 我放的是百事可乐 感', '禽类,肉类,热菜,甜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/f/c/8/yuan_fc8a2591e98742011408ab48f8af1108.jpg', '普通', '25分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###可乐|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡翅洗干净 老姜切片备好###2. 在鸡翅有一粒粒小疙瘩的一面用牙签戳几个小洞洞 入味 另外一面用刀划两下 放入适量的老姜料酒和酱油 再滴入几滴柠檬汁 使鸡翅肉质更嫩 腌制20~30min左右###3. 半小时之后 锅中水煮开将鸡翅过水焯一下###4. 锅烧热 倒入一点点油 放入老姜 鸡翅将鸡翅两面煎一下###5. 倒入可乐 老抽 喜欢 甜辣的 再放点辣椒###6. 我放的是百事可乐 感', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(16801, '番茄炒鸡蛋', 'meat', '鸡蛋:5个#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 番茄洗净,去除蒂,切块备用###2. 将4个鸡蛋打碎,搅拌成蛋液备用###3. 锅中加入少量油,将蛋液倒入,炒成炒蛋###4. 再放入油,放入4个大蒜,放入番茄,再加适量的水,然后,依次将炒熟的鸡蛋,盖锅,之后2勺半盐和1勺半的糖也要放进去^_^###5. 拌炒均匀,正宗番茄炒鸡蛋即可正式“出锅”!味道和高级餐厅做出来的相媲美^_^おいしぃ!', '禽类,蛋类,热菜,番茄味,下饭菜,单身食谱,幼儿食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/8/6/e/yuan_8637edb142d5c9d0121c41ec058c579e.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 番茄洗净,去除蒂,切块备用###2. 将4个鸡蛋打碎,搅拌成蛋液备用###3. 锅中加入少量油,将蛋液倒入,炒成炒蛋###4. 再放入油,放入4个大蒜,放入番茄,再加适量的水,然后,依次将炒熟的鸡蛋,盖锅,之后2勺半盐和1勺半的糖也要放进去^_^###5. 拌炒均匀,正宗番茄炒鸡蛋即可正式“出锅”!味道和高级餐厅做出来的相媲美^_^おいしぃ!', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(16819, '酱香烤鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 翅中洗净,用刀在正反两面都划个两刀,然后把葱和姜都切成末。。。###2. 把所有材料都放到鸡翅中,拌匀,至少要3个小时以上。。。###3. 时间差不多时,把烤盘垫上锡纸接油,放到烤箱最下层,同时烤箱200°C预热,上下火哦。然后把鸡翅再稍稍拌几下捞出摆放在网架上。。。###4. 把放有鸡翅的网架送入预热好的烤箱中,上下火继续再烤20分钟。。。###5. 出炉。。。由于两面都划了口子,就不用中途', '禽类,热菜,酱香,午餐,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/b/1/yuan_8b179d2be0114ab65ddc0dcf42140a81.jpg', '普通', '25分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 翅中洗净,用刀在正反两面都划个两刀,然后把葱和姜都切成末。。。###2. 把所有材料都放到鸡翅中,拌匀,至少要3个小时以上。。。###3. 时间差不多时,把烤盘垫上锡纸接油,放到烤箱最下层,同时烤箱200°C预热,上下火哦。然后把鸡翅再稍稍拌几下捞出摆放在网架上。。。###4. 把放有鸡翅的网架送入预热好的烤箱中,上下火继续再烤20分钟。。。###5. 出炉。。。由于两面都划了口子,就不用中途', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(16956, '西芹炒北极虾', 'meat', '虾:520克#芹菜:400克#食用油:45毫升#北极:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 加拿大野生北极虾,取出,浸泡,轻轻清洗;###2. 捞出,洌干水;###3. 西芹,洗干净;###4. 西芹去嫩的(中间的)切小段,待用;###5. 青辣椒切好###6. 热锅,倒油,爆炒西芹;###7. 热锅,热油,爆炒北极虾;###8. 放辣椒,然后再放刚刚炒好的西芹,###9. 美味西芹炒北极虾出锅了。', '水产,热菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/2/3/yuan_324fb2142fa9d6c94ad6539b398d03b3.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###北极|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 加拿大野生北极虾,取出,浸泡,轻轻清洗;###2. 捞出,洌干水;###3. 西芹,洗干净;###4. 西芹去嫩的(中间的)切小段,待用;###5. 青辣椒切好###6. 热锅,倒油,爆炒西芹;###7. 热锅,热油,爆炒北极虾;###8. 放辣椒,然后再放刚刚炒好的西芹,###9. 美味西芹炒北极虾出锅了。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(16969, '香烤鸡', 'meat', '鸡腿:575克#鸡肉:520克#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 全鸡切去鸡爪和屁股,鸡头的话随意,我是给切了。准备个大盆腌制全鸡,盆里放入所有辅料,切好的姜片,葱段放入鸡身体里腌制30分钟。###2. 取出烤叉,穿入鸡身固定,以便烤箱旋转时会掉下来。叉好的全鸡刷一遍蜂蜜,入烤箱,180度烤30分钟。###3. 翅膀和鸡腿骨部分可以加锡箔纸防烤焦,喜欢烤焦味道的就省略了。###4. 完成了,趁热吃哦!', '禽类,热菜,下酒菜,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/2/b/yuan_82df8eda3ecbf05c787f541794210efb.jpg', '普通', '25分钟', '鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 全鸡切去鸡爪和屁股,鸡头的话随意,我是给切了。准备个大盆腌制全鸡,盆里放入所有辅料,切好的姜片,葱段放入鸡身体里腌制30分钟。###2. 取出烤叉,穿入鸡身固定,以便烤箱旋转时会掉下来。叉好的全鸡刷一遍蜂蜜,入烤箱,180度烤30分钟。###3. 翅膀和鸡腿骨部分可以加锡箔纸防烤焦,喜欢烤焦味道的就省略了。###4. 完成了,趁热吃哦!', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(16980, '蒜香鸡翼', 'meat', '白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#淀粉:30克#姜:25克#蒜:30克#香鸡翼:345克', '2名成年人总量+15%冗余', '1. 鸡翼洗干净,后背切两刀,沥干水待用。姜切丝,蒜切碎。###2. 鸡翼沥干后,加入姜丝蒜粒,生抽,老抽,盐,砂糖适量,搅拌均匀。###3. 搅拌后,确保鸡翼都上色。腌制半小时以上。###4. 腌制好后,烧油锅,鸡翼慢火煎至金黄。腌制鸡翼的汁别浪费,加入淀粉,水调成汁,加入煎好的鸡翼上。小火焗3分钟。大火收汁!###5. 搞掂', '肉类,禽类,热菜,蒜香,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/b/6/yuan_8b960dd2741701595b03623c5343f9d6.jpg', '简单', '15分钟', '白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###香鸡翼|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡翼洗干净,后背切两刀,沥干水待用。姜切丝,蒜切碎。###2. 鸡翼沥干后,加入姜丝蒜粒,生抽,老抽,盐,砂糖适量,搅拌均匀。###3. 搅拌后,确保鸡翼都上色。腌制半小时以上。###4. 腌制好后,烧油锅,鸡翼慢火煎至金黄。腌制鸡翼的汁别浪费,加入淀粉,水调成汁,加入煎好的鸡翼上。小火焗3分钟。大火收汁!###5. 搞掂', '[]', '来源步骤数: 5', '煎', 0, 0, NULL, NULL),
(17015, '香菇蒸鳕鱼', 'meat', '鱼:690克#香菇:230克#食用油:45毫升#食盐:7克#料酒:30毫升#葱:35克', '2名成年人总量+15%冗余', '1. 清洗:把鳕鱼用流水洗净,用厨房纸巾吸干水分后摆入盘中。###2. 切配:香菇洗净去蒂后,切成薄片;小红辣椒和香葱洗净后分别切碎。###3. 预热:取出蒸箱中的无孔蒸盘,水箱加满水,再关门、通电、开机,选择“蒸鱼”模式,设置100°C,定时6分钟,按确认键,蒸箱开始预热。###4. 调味:将蒸鱼豉油、料酒、盐放入小碗搅拌均匀,做成调味汁;将香菇片摆在鳕鱼上,均匀浇上调味汁。###5. 蒸制:将盘', '海鲜,水产,热菜,鲜,下饭菜,午餐,一家三口,家常菜,蒸箱', 'https://cp1.douguo.net/upload/caiku/c/7/3/yuan_c71849517d10aaecf1f4890218c91443.jpg', '困难', '60分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 清洗:把鳕鱼用流水洗净,用厨房纸巾吸干水分后摆入盘中。###2. 切配:香菇洗净去蒂后,切成薄片;小红辣椒和香葱洗净后分别切碎。###3. 预热:取出蒸箱中的无孔蒸盘,水箱加满水,再关门、通电、开机,选择“蒸鱼”模式,设置100°C,定时6分钟,按确认键,蒸箱开始预热。###4. 调味:将蒸鱼豉油、料酒、盐放入小碗搅拌均匀,做成调味汁;将香菇片摆在鳕鱼上,均匀浇上调味汁。###5. 蒸制:将盘', '[]', '来源步骤数: 5', '焖', 0, 0, NULL, NULL),
(17116, '杯鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#生抽:35毫升#料酒:30毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡翅表面划两刀,加入料酒腌制半小时###2. 洗净,擦干###3. 锅内下麻油(约2勺),烧热后下鸡翅煎至两面变色。###4. 加入九层塔、红烧酱油翻炒至鸡翅收干酱油###5. 加入rio或米酒,烧开后文火煮10分钟。###6. 撒入一把罗勒,继续焖5分钟。###7. 大火收汁,即可。', '禽类,热菜,下酒菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/b/e/yuan_2b26b0a4848c8b784bfaa1463a36d12e.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡翅表面划两刀,加入料酒腌制半小时###2. 洗净,擦干###3. 锅内下麻油(约2勺),烧热后下鸡翅煎至两面变色。###4. 加入九层塔、红烧酱油翻炒至鸡翅收干酱油###5. 加入rio或米酒,烧开后文火煮10分钟。###6. 撒入一把罗勒,继续焖5分钟。###7. 大火收汁,即可。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(17136, '丝家常小炒', 'meat', '猪肉:345克#木耳:35克#萝卜:460克#豆角:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. 肉切丝,豆角,胡萝卜全部切细丝###2. 炒锅烧热后倒油,热锅冷油倒入肉丝煸炒加点生抽 糖炒至肉丝变白后盛出准用###3. 再将炒锅烧热倒油,油温高后先放姜未爆锅放入豆角,胡萝卜炒至断生,放入肉丝,加点泡发木耳翻炒,然后加点盐再炒二三分钟,起锅前加上耗油,蒜泥,鸡精少许翻炒几下好啦。', '肉类,禽类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/e/5/yuan_6e425b7cdcb7493e888b607971b13795.jpg', '简单', '15分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 肉切丝,豆角,胡萝卜全部切细丝###2. 炒锅烧热后倒油,热锅冷油倒入肉丝煸炒加点生抽 糖炒至肉丝变白后盛出准用###3. 再将炒锅烧热倒油,油温高后先放姜未爆锅放入豆角,胡萝卜炒至断生,放入肉丝,加点泡发木耳翻炒,然后加点盐再炒二三分钟,起锅前加上耗油,蒜泥,鸡精少许翻炒几下好啦。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17178, '丝瓜炒肉', 'meat', '丝瓜:460克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 肥瘦相间的肉。###2. 切稍粗的丝。###3. 丝瓜去皮,洗净。###4. 切小块。###5. 先把白肉放入锅中,炒出油,再进红肉,炒好放入葱姜蒜酱油,倒入丝瓜翻炒。###6. 加入酱油咸盐。###7. 继续翻炒,可加一点点水,量自己控制。闷1分钟,加入味精鸡精出锅。###8. 加到荷叶饼里,美味有没有啊。', '禽类,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/7/7/e/yuan_771af1c9003e24be93637c50e44b06ce.jpg', '简单', '15分钟', '丝瓜|460|克|主料|去皮切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 肥瘦相间的肉。###2. 切稍粗的丝。###3. 丝瓜去皮,洗净。###4. 切小块。###5. 先把白肉放入锅中,炒出油,再进红肉,炒好放入葱姜蒜酱油,倒入丝瓜翻炒。###6. 加入酱油咸盐。###7. 继续翻炒,可加一点点水,量自己控制。闷1分钟,加入味精鸡精出锅。###8. 加到荷叶饼里,美味有没有啊。', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(17221, '炒鸡蛋的最吃法', 'meat', '黑胡椒:6克#鸡蛋:5个#牛奶:575毫升#食用油:45毫升#食盐:7克#的最吃法:345克', '2名成年人总量+15%冗余', '1. 鸡蛋打入碗中,加入牛奶,充分打散,让足够多的空气融进蛋液中。###2. 蛋液中加入盐,搅拌均匀。###3. 锅烧热,倒少许油,加热10秒种后关火。###4. 倒入蛋液,稍凝固后,将凝固部分推开,让剩余蛋液接触锅底,使其凝固。###5. 待蛋液全部凝固后打散成块状,撒黑胡椒粉后即可装盘。', '蛋类,禽类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/5/9/yuan_d5a890ce9e23d3ac39f264cda25f3109.jpg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###牛奶|575|毫升|主料|直接使用|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###的最吃法|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡蛋打入碗中,加入牛奶,充分打散,让足够多的空气融进蛋液中。###2. 蛋液中加入盐,搅拌均匀。###3. 锅烧热,倒少许油,加热10秒种后关火。###4. 倒入蛋液,稍凝固后,将凝固部分推开,让剩余蛋液接触锅底,使其凝固。###5. 待蛋液全部凝固后打散成块状,撒黑胡椒粉后即可装盘。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(17222, '家常胡萝卜炒肉片', 'meat', '猪肉:345克#萝卜:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. 肉,胡萝卜切片,姜蒜切好备用###2. 腌肉,在肉片中放两勺生粉,两勺料酒,生抽适量,再放入4克家乐鸡粉搅拌均匀,腌15分钟###3. 热锅放油,将腌好的肉炒至微熟放入胡萝卜继续翻炒,炒的过程中稍有些干我还放了点水,炒至胡萝卜熟加入适量的盐装盘。', '禽类,肉类,热菜,下饭菜,午餐,朋友聚餐,老年食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/8/f/8/yuan_8f6e1d4e44ed52d40f1b3f2a61ccdf88.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 肉,胡萝卜切片,姜蒜切好备用###2. 腌肉,在肉片中放两勺生粉,两勺料酒,生抽适量,再放入4克家乐鸡粉搅拌均匀,腌15分钟###3. 热锅放油,将腌好的肉炒至微熟放入胡萝卜继续翻炒,炒的过程中稍有些干我还放了点水,炒至胡萝卜熟加入适量的盐装盘。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17262, '简易美式早餐附煎蛋蓉不老秘方', 'meat', '鸡蛋:5个#简易美式早餐附:345克#蛋蓉不老秘方:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 先上全图。鲜磨黑豆浆、韩国辣椒酱拌面、烫蒸菜、自家种小蕃茄、还有今天介绍的『主角』。###2. 准备好材料备用。蛋浆加入鸡粉拌匀。炒蛋蓉不老的秘方就是拌蛋前加入少量凉开水。炒的时候用中火,分两次倒蛋浆,快手炒。炒时蛋蓉会渗出少量水,这无疑中保护了蛋蓉。###3. 3分钟是煮完全餐哦,不单单是只是鸡蛋肠。好啦,美美上桌咯!', '蛋类,禽类,热菜,早餐食谱,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/6/d/a/yuan_6d1da9c7ed302e34a2afccd390f0e5ba.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###简易美式早餐附|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###蛋蓉不老秘方|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 先上全图。鲜磨黑豆浆、韩国辣椒酱拌面、烫蒸菜、自家种小蕃茄、还有今天介绍的『主角』。###2. 准备好材料备用。蛋浆加入鸡粉拌匀。炒蛋蓉不老的秘方就是拌蛋前加入少量凉开水。炒的时候用中火,分两次倒蛋浆,快手炒。炒时蛋蓉会渗出少量水,这无疑中保护了蛋蓉。###3. 3分钟是煮完全餐哦,不单单是只是鸡蛋肠。好啦,美美上桌咯!', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17312, '肉末酱烧茄子', 'meat', '猪肉:345克#茄子:460克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#淀粉:30克#豆瓣酱:30克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 肉末加少许盐,淀粉,水搅拌至上劲,茄子洗净去蒂切滚刀,姜蒜切片,葱切花。###2. 热锅凉油,下肉末炒至变白。###3. 下姜蒜炒香。###4. 下豆瓣酱煸出红油,加适量老抽,白糖炒匀。###5. 下茄子翻炒均匀,加适量水(水不要加太多,因为茄子要出水,而且很容易熟),盖盖大火烧开,焖煮至茄子变软(软硬度看个人哈)。###6. 勾芡(比较稀的水淀粉淋入锅中,大火收汁)撒葱花,拌匀出锅。', '肉类,热菜,下饭菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/2/c/yuan_02ed1a777e35ecea8096cd1e6b93ee3c.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###茄子|460|克|主料|切块或切条|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 肉末加少许盐,淀粉,水搅拌至上劲,茄子洗净去蒂切滚刀,姜蒜切片,葱切花。###2. 热锅凉油,下肉末炒至变白。###3. 下姜蒜炒香。###4. 下豆瓣酱煸出红油,加适量老抽,白糖炒匀。###5. 下茄子翻炒均匀,加适量水(水不要加太多,因为茄子要出水,而且很容易熟),盖盖大火烧开,焖煮至茄子变软(软硬度看个人哈)。###6. 勾芡(比较稀的水淀粉淋入锅中,大火收汁)撒葱花,拌匀出锅。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(174, '蒸带鱼', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 带鱼洗净,切段儿后放入料酒 花椒 葱 姜 盐 腌制1小时以上###2. 平底锅或者电饼铛上倒入适量油 ,油热后将带鱼煎成两面金黄盛出备用###3. 调料汁:酱油+料酒+白糖+蚝油+醋 备用###4. 炸金黄的带鱼放入盘中后倒入调料汁撒上红糖###5. 再放上葱姜蒜###6. 热水烧开后上锅蒸30-40分钟(进味儿)也可以蒸10分钟左右', '浙菜,海鲜,水产,热菜,午餐,朋友聚餐,家常菜,电饼铛', 'https://cp1.douguo.net/upload/caiku/4/8/9/yuan_48bd49d7bb9ae858dc519cfb05fb2289.jpg', '普通', '25分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 带鱼洗净,切段儿后放入料酒 花椒 葱 姜 盐 腌制1小时以上###2. 平底锅或者电饼铛上倒入适量油 ,油热后将带鱼煎成两面金黄盛出备用###3. 调料汁:酱油+料酒+白糖+蚝油+醋 备用###4. 炸金黄的带鱼放入盘中后倒入调料汁撒上红糖###5. 再放上葱姜蒜###6. 热水烧开后上锅蒸30-40分钟(进味儿)也可以蒸10分钟左右', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(17404, '可乐鸡翅', 'meat', '鸡翅:575克#鸡肉:520克#食用油:45毫升#老抽:15毫升#可乐:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将鸡翅用清水洗干净,若不嫌麻烦可在鸡翅正反两面各划两道方便入味,当然我以前没划也相当好吃###2. 锅内放少量油,下鸡翅翻炒,直到两面变成白黄色,倒入4汤勺老抽,加入一听可乐,搅拌均匀###3. 盖上锅盖转中小火闷十五到二十分钟,最后用筷子可以轻而易举穿透鸡肉就可以。开盖,大火收汁,汤汁浓稠,留自己喜欢的量就好', '禽类,肉类,热菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/5/c/yuan_059ec06135416178f533aa113d7ca26c.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###可乐|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将鸡翅用清水洗干净,若不嫌麻烦可在鸡翅正反两面各划两道方便入味,当然我以前没划也相当好吃###2. 锅内放少量油,下鸡翅翻炒,直到两面变成白黄色,倒入4汤勺老抽,加入一听可乐,搅拌均匀###3. 盖上锅盖转中小火闷十五到二十分钟,最后用筷子可以轻而易举穿透鸡肉就可以。开盖,大火收汁,汤汁浓稠,留自己喜欢的量就好', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17457, '不腻红烧肉', 'meat', '五花肉:345克#白糖:55克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克#不腻红:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将五花肉切块洗净,放入高压锅,放生姜,葱段,黄酒。烧开后压10几分钟。肉会比较烂。###2. 热油锅,将生姜辣椒放油里爆一下,倒入五花肉翻炒至略带金色,然后倒入适量生抽,老抽少许,翻炒上色。再倒入压肉时的汤汁,盖过肉就好,加入适量冰糖,放入葵香,香叶。大火闷煮。###3. 大火煮开后用小火闷。期间不定时翻炒一下,当心烧干。当酱汁翻滚成泡时可以开大火收汁然后出锅。', '肉类,热菜,下饭菜,朋友聚餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/6/0/a/yuan_60299d9c979bea995eac845ac9226f1a.jpg', '简单', '15分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###不腻红|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将五花肉切块洗净,放入高压锅,放生姜,葱段,黄酒。烧开后压10几分钟。肉会比较烂。###2. 热油锅,将生姜辣椒放油里爆一下,倒入五花肉翻炒至略带金色,然后倒入适量生抽,老抽少许,翻炒上色。再倒入压肉时的汤汁,盖过肉就好,加入适量冰糖,放入葵香,香叶。大火闷煮。###3. 大火煮开后用小火闷。期间不定时翻炒一下,当心烧干。当酱汁翻滚成泡时可以开大火收汁然后出锅。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17463, '花肉卷金针菇', 'meat', '五花肉:345克#金针菇:290克#食用油:45毫升#生抽:35毫升#花肉:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 五花肉自己切的,有些厚了。我用海鲜酱油和白酒腌了10分钟左右,去去肉腥味。###2. 金针菇洗净###3. 用五花肉卷住适量的金针菇,再用牙签固定好。###4. 放在不粘锅里小火慢慢煎,不需要放油。###5. 一面煎好再翻另一面###6. 两面都煎好,加些海鲜酱油和少量水,小火慢慢炖,收汤即可。经过这道工序,五花肉滋味都进入了,肉还不会太硬。###7. 因为加了白酒,味道很独特那。', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/c/2/e/yuan_c24b3ee2fa8840c4488eb1368e579efe.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###金针菇|290|克|配菜|去根洗净|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 五花肉自己切的,有些厚了。我用海鲜酱油和白酒腌了10分钟左右,去去肉腥味。###2. 金针菇洗净###3. 用五花肉卷住适量的金针菇,再用牙签固定好。###4. 放在不粘锅里小火慢慢煎,不需要放油。###5. 一面煎好再翻另一面###6. 两面都煎好,加些海鲜酱油和少量水,小火慢慢炖,收汤即可。经过这道工序,五花肉滋味都进入了,肉还不会太硬。###7. 因为加了白酒,味道很独特那。', '[]', '来源步骤数: 7', '煎', 0, 0, NULL, NULL),
(1748, '糖醋排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#香醋:30毫升', '2名成年人总量+15%冗余', '1. 排骨斩小块,蕃茄切小块###2. 锅烧热,下排骨煸炒出油,选有点肥肉的腩排,炒到肉有点变黄,喷点料酒继续翻炒,接着下李锦记特级头抽和蚝油翻炒均匀,盖上盖子转最小火焖,隔一分钟开盖翻炒几下防止煳锅###3. 开盖三四次之后,会发现排骨已经焖得入味透亮了,这时候下蕃茄块,一点盐继续翻炒到蕃茄变软有汤汁,这时候就可以下白糖和香醋调出你喜欢的酸甜口味,一般是两勺糖一勺醋,加入的蕃茄也会有酸味的', '水产,肉类,热菜,酸甜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/1/7/yuan_61d51963560ed6c4e71aa9921eeddcf7.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤', '1. 排骨斩小块,蕃茄切小块###2. 锅烧热,下排骨煸炒出油,选有点肥肉的腩排,炒到肉有点变黄,喷点料酒继续翻炒,接着下李锦记特级头抽和蚝油翻炒均匀,盖上盖子转最小火焖,隔一分钟开盖翻炒几下防止煳锅###3. 开盖三四次之后,会发现排骨已经焖得入味透亮了,这时候下蕃茄块,一点盐继续翻炒到蕃茄变软有汤汁,这时候就可以下白糖和香醋调出你喜欢的酸甜口味,一般是两勺糖一勺醋,加入的蕃茄也会有酸味的', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(17582, '清蒸鲈鱼', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 把鲈鱼头部切,鱼鳍和尾巴都剪掉弃之不用,从背部下刀切厚片,鱼肚不切断,装盘摆好花型###2. 葱丝姜丝,花椒,八角,辣椒,生抽,酱油,鸡精,盐搅拌均匀###3. 料汁浇在鱼身上腌制30分钟左右###4. 上锅大火烧开转中火蒸制15分钟再关火焖2~3分钟就可以出锅享用(我忍不住吃了一口', '湘菜,水产,禽类,热菜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/2/f/yuan_626773b36de84f8a41fee339121a4caf.jpg', '困难', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 把鲈鱼头部切,鱼鳍和尾巴都剪掉弃之不用,从背部下刀切厚片,鱼肚不切断,装盘摆好花型###2. 葱丝姜丝,花椒,八角,辣椒,生抽,酱油,鸡精,盐搅拌均匀###3. 料汁浇在鱼身上腌制30分钟左右###4. 上锅大火烧开转中火蒸制15分钟再关火焖2~3分钟就可以出锅享用(我忍不住吃了一口', '[]', '来源步骤数: 4', '焖', 0, 0, NULL, NULL),
(17588, '不减可乐鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#食盐:7克#料酒:30毫升#姜:25克#不减可乐:345克', '2名成年人总量+15%冗余', '1. 鸡翅用姜,一点盐,料酒腌制2-3个小时。###2. 腌制好的鸡翅,放到不粘锅里,不放油煎至两年金黄。(想吃嫩点的就少煎下,想吃香点就煎黄点。)###3. 可乐到入锅里,淹过鸡翅。###4. 熬呀熬,直到汤汁刚刚收到挂在鸡翅上,关火,开吃!', '禽类,热菜,下酒菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/2/8/yuan_521d16b8e5e6cb93b15df00abdf1b558.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###不减可乐|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡翅用姜,一点盐,料酒腌制2-3个小时。###2. 腌制好的鸡翅,放到不粘锅里,不放油煎至两年金黄。(想吃嫩点的就少煎下,想吃香点就煎黄点。)###3. 可乐到入锅里,淹过鸡翅。###4. 熬呀熬,直到汤汁刚刚收到挂在鸡翅上,关火,开吃!', '[]', '来源步骤数: 4', '煎', 0, 0, NULL, NULL),
(17730, '我们都是食肉兽步骤简单味道赞的叉烧来喽', 'meat', '五香粉:6克#猪里脊:345克#白糖:55克#生抽:35毫升#蒜:30克#来喽:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 猪里脊肉两条洗净备用###2. 把生抽、蒜蓉、麦芽糖、南乳、五香粉、酒混合均匀放入保鲜袋里,把肉放进去就开始给肉做按摩###3. 肉经过一夜的腌制已经充分入味了,这是腌制好的样子###4. 烤箱180度烤制15分钟取出,刷一层蜂蜜,再继续烤20分钟###5. 好啦,出炉###6. 待凉 一点切片,特别的美味', '粤菜,肉类,热菜,午餐,家常菜,懒人食谱,烤箱', 'https://cp1.douguo.net/upload/caiku/e/3/b/yuan_e30be798db743554fede0fe70e9e7d3b.jpg', '普通', '25分钟', '五香粉|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###来喽|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 猪里脊肉两条洗净备用###2. 把生抽、蒜蓉、麦芽糖、南乳、五香粉、酒混合均匀放入保鲜袋里,把肉放进去就开始给肉做按摩###3. 肉经过一夜的腌制已经充分入味了,这是腌制好的样子###4. 烤箱180度烤制15分钟取出,刷一层蜂蜜,再继续烤20分钟###5. 好啦,出炉###6. 待凉 一点切片,特别的美味', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(17807, '糖醋秋刀鱼', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#蒜:30克#秋刀:345克', '2名成年人总量+15%冗余', '1. 将鱼洗净去内脏切成小块###2. 放入适量料酒和盐腌渍10分钟。###3. 将一汤勺料酒、二汤勺酱油、三汤勺白糖、四汤勺醋、还有5汤勺水混合调成糖醋汁。###4. 热锅放油放入鱼###5. 将鱼块煎至两面金黄后出锅。###6. 锅内留少许油下入姜片蒜粒炒香###7. 再放入鱼块、糖醋汁大火快速收汁即可出锅', '东北菜,海鲜,水产,热菜,酸甜,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/2/3/5/yuan_23365c30edda8331525203755f8586e5.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###秋刀|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将鱼洗净去内脏切成小块###2. 放入适量料酒和盐腌渍10分钟。###3. 将一汤勺料酒、二汤勺酱油、三汤勺白糖、四汤勺醋、还有5汤勺水混合调成糖醋汁。###4. 热锅放油放入鱼###5. 将鱼块煎至两面金黄后出锅。###6. 锅内留少许油下入姜片蒜粒炒香###7. 再放入鱼块、糖醋汁大火快速收汁即可出锅', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(17992, '彩缤纷的香肠炒青豆', 'meat', '玉米:460克#香肠:290克#红椒:170克#食用油:45毫升#食盐:7克#彩缤纷的:345克#青豆:345克', '2名成年人总量+15%冗余', '1. 准备好所需的食材###2. 锅中烧水,待水烧至快开时,将清洗过后的青豆、玉米粒下入锅中,然后滴几滴食用油、加少许盐,筷子搅动一下###3. 将煮好的青豆、玉米粒从锅中捞出,立即过下冷水备用###4. 将香肠切成小丁、洗过后的彩椒随意切小块###5. 锅中倒入适量油,将过青豆和玉米粒放入其中,中火翻炒几下后加盐###6. 待盐与青豆、玉米粒混合后,加入切好的香肠和彩椒,翻炒30秒左右出锅', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/a/7/yuan_8aec46b59cb63e953e4b7c907563f327.jpg', '困难', '20分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###香肠|290|克|主料|切片|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###彩缤纷的|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###青豆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 准备好所需的食材###2. 锅中烧水,待水烧至快开时,将清洗过后的青豆、玉米粒下入锅中,然后滴几滴食用油、加少许盐,筷子搅动一下###3. 将煮好的青豆、玉米粒从锅中捞出,立即过下冷水备用###4. 将香肠切成小丁、洗过后的彩椒随意切小块###5. 锅中倒入适量油,将过青豆和玉米粒放入其中,中火翻炒几下后加盐###6. 待盐与青豆、玉米粒混合后,加入切好的香肠和彩椒,翻炒30秒左右出锅', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(18043, '爆炒鸡胗', 'meat', '食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#鸡胗:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡胗反复清洗干净###2. 切片,抓少许料酒备用###3. 辣椒,蒜苗切丁,姜切片。###4. 锅里放油,爆香姜片,油可比平时炒菜稍多些。###5. 放入鸡胗大火爆炒,变色马上盛出。动作要快!###6. 重新起锅少量底油炒熟蒜苗辣椒。###7. 锅里倒回鸡胗###8. 迅速加调料,蚝油老抽和生抽。###9. 翻炒均匀马上出锅。###10. 成品', '禽类,水产,热菜,晚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/8/d/yuan_580e1837e09b5f25c10ffb9ab79eb8cd.jpg', '困难', '20分钟', '食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###鸡胗|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡胗反复清洗干净###2. 切片,抓少许料酒备用###3. 辣椒,蒜苗切丁,姜切片。###4. 锅里放油,爆香姜片,油可比平时炒菜稍多些。###5. 放入鸡胗大火爆炒,变色马上盛出。动作要快!###6. 重新起锅少量底油炒熟蒜苗辣椒。###7. 锅里倒回鸡胗###8. 迅速加调料,蚝油老抽和生抽。###9. 翻炒均匀马上出锅。###10. 成品', '[]', '来源步骤数: 10', '炒', 0, 0, NULL, NULL),
(18197, '肉沫豆角', 'meat', '猪肉:345克#豆角:460克#小米:290克#白糖:55克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#淀粉:30克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 1勺料酒 1勺糖 1勺淀粉 1勺生抽 抓匀 先把肉碎腌制10分钟###2. 豆角切成丁###3. 葱 蒜 小米椒 切成丁###4. 锅底放适量植物油 油低温的时候就把肉沫放进去煸炒 加少许老抽调色###5. 然后乘出备用###6. 锅底放少量植物油 把切好的葱、蒜、小米椒 放入锅中 炒出香味###7. 把豆角放入锅里翻炒 边炒边加入 少量的清水,一定要一点一点的放 一定要少量多次加入,', '肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/f/a/yuan_bffdf82751c46768d124dd6ff0329daa.png', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|菜名+步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 1勺料酒 1勺糖 1勺淀粉 1勺生抽 抓匀 先把肉碎腌制10分钟###2. 豆角切成丁###3. 葱 蒜 小米椒 切成丁###4. 锅底放适量植物油 油低温的时候就把肉沫放进去煸炒 加少许老抽调色###5. 然后乘出备用###6. 锅底放少量植物油 把切好的葱、蒜、小米椒 放入锅中 炒出香味###7. 把豆角放入锅里翻炒 边炒边加入 少量的清水,一定要一点一点的放 一定要少量多次加入,', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(18405, '粽叶飘香香五花肉', 'meat', '五花肉:345克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克#粽叶飘香香:345克', '2名成年人总量+15%冗余', '1. 先将调味料洗净备用###2. 五花肉洗净后放入盐、葱、姜、适量黄酒腌制1小时###3. 将腌制过的肉用粽叶包好###4. 肉用棉绳扎紧###5. 将大料放入油锅爆香,然后放入冰糖老抽等调料,放入适量清水###6. 将砂锅底部铺上粽叶###7. 将包好的五花肉放入之前做好的汤料中,汤刚好盖过粽叶即可,文火炖制2小时左右', '东北菜,肉类,热菜,一家三口,午餐,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/7/8/d/yuan_78cfc954b7c2b3e7cf8fdf53de0ec77d.jpeg', '困难', '60分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###粽叶飘香香|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 先将调味料洗净备用###2. 五花肉洗净后放入盐、葱、姜、适量黄酒腌制1小时###3. 将腌制过的肉用粽叶包好###4. 肉用棉绳扎紧###5. 将大料放入油锅爆香,然后放入冰糖老抽等调料,放入适量清水###6. 将砂锅底部铺上粽叶###7. 将包好的五花肉放入之前做好的汤料中,汤刚好盖过粽叶即可,文火炖制2小时左右', '[]', '来源步骤数: 7', '炖', 0, 0, NULL, NULL),
(18442, '木耳烧墨鱼', 'meat', '鱼:690克#木耳:35克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 木耳泡发洗净备用。###2. 将墨鱼洗净,去皮去内脏,把裙边留下(看起来完整一点,比较好看)###3. 葱切段,姜切片备用。锅里加油,入葱根部和姜片炝锅。###4. 放入墨鱼至色发白,###5. 加入料酒、清水与食材平。###6. 加入生抽、老抽###7. 加入泡发黑木耳,再加一勺糖调味,可以适当加一点点盐。烧开后转小火焖煮。###8. 20分钟左右汤汁收浓关火,洒上绿葱丝装饰。', '海鲜,水产,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/6/0/e/yuan_60d3f3ff306edf22895706bc8956bfbe.jpg', '困难', '60分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 木耳泡发洗净备用。###2. 将墨鱼洗净,去皮去内脏,把裙边留下(看起来完整一点,比较好看)###3. 葱切段,姜切片备用。锅里加油,入葱根部和姜片炝锅。###4. 放入墨鱼至色发白,###5. 加入料酒、清水与食材平。###6. 加入生抽、老抽###7. 加入泡发黑木耳,再加一勺糖调味,可以适当加一点点盐。烧开后转小火焖煮。###8. 20分钟左右汤汁收浓关火,洒上绿葱丝装饰。', '[]', '来源步骤数: 8', '焖', 0, 0, NULL, NULL),
(18498, '黑椒柠檬鳕鱼', 'meat', '柠檬:170克#黑胡椒:6克#鱼:690克#淀粉:30克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 鳕鱼解冻###2. 可以放微波炉,叮一分钟###3. 淀粉一勺###4. 柠檬汁少于,加点蜂蜜...看个人口味添加哦......做酱料###5. 鳕鱼稍微煎一下,收一下水,然后切点午餐肉,拼盘,加点白水撩青菜,然后上面抹黑椒酱###6. 鳕鱼,午餐肉放烤箱稍微烤一下,然后浇上柠檬酱!完', '水产,肉类,热菜,黑椒,下酒菜,儿童,孕妇食谱,家常菜,微波炉,烤箱', 'https://cp1.douguo.net/upload/caiku/c/b/5/yuan_cbe65db076059191bd9f9cf29f62dc85.jpg', '普通', '20分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|菜名+步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鳕鱼解冻###2. 可以放微波炉,叮一分钟###3. 淀粉一勺###4. 柠檬汁少于,加点蜂蜜...看个人口味添加哦......做酱料###5. 鳕鱼稍微煎一下,收一下水,然后切点午餐肉,拼盘,加点白水撩青菜,然后上面抹黑椒酱###6. 鳕鱼,午餐肉放烤箱稍微烤一下,然后浇上柠檬酱!完', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(18518, '香卤蛋', 'meat', '鸡蛋:5个#白糖:55克#食盐:7克#老抽:15毫升', '2名成年人总量+15%冗余', '1. 讲鸡蛋放白水里煮沸,小火烧5分钟捞出,放冷水里浸一会,然后把壳剥掉,在上面划两道,容易入味###2. 将桂皮八角辣椒放入锅中,放入适量的盐和糖,加上适量的水,开始点火###3. 在小碗里倒入半碗老抽,将准备好的鸡蛋放在老抽里滚过去,这样比较有味,然后放入锅里###4. 先用大火烧,煮沸后开小火慢炖以便卤汁入味,大约20分钟后可以出锅,香喷喷的卤蛋ok啦(注意水量,千万别烧干了)', '东北菜,蛋类,禽类,热菜,家常菜', 'https://cp1.douguo.net/upload/caiku/d/7/f/yuan_d7546ee421f48db6480d255e09240cbf.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤', '1. 讲鸡蛋放白水里煮沸,小火烧5分钟捞出,放冷水里浸一会,然后把壳剥掉,在上面划两道,容易入味###2. 将桂皮八角辣椒放入锅中,放入适量的盐和糖,加上适量的水,开始点火###3. 在小碗里倒入半碗老抽,将准备好的鸡蛋放在老抽里滚过去,这样比较有味,然后放入锅里###4. 先用大火烧,煮沸后开小火慢炖以便卤汁入味,大约20分钟后可以出锅,香喷喷的卤蛋ok啦(注意水量,千万别烧干了)', '[]', '来源步骤数: 4', '炖', 0, 0, NULL, NULL),
(18547, '油焖大虾', 'meat', '虾:520克#西红柿:460克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 鲜虾洗净,开背去虾线,放少量盐腌15分钟左右入味###2. 葱切段,蒜切片或者中间切一刀,姜切片备用。###3. 热油锅下葱姜蒜爆炒出香味###4. 放入鲜虾翻炒到变色,加入少量生抽、盐、鸡精,最后加入番茄沙司,烧微加一点水,翻炒均匀出锅即可。###5. duang?成品,是不是很有食欲呢', '鄂菜,海鲜,禽类,水产,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/9/2/yuan_29d8377c3815d9affde78e6885d71a22.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鲜虾洗净,开背去虾线,放少量盐腌15分钟左右入味###2. 葱切段,蒜切片或者中间切一刀,姜切片备用。###3. 热油锅下葱姜蒜爆炒出香味###4. 放入鲜虾翻炒到变色,加入少量生抽、盐、鸡精,最后加入番茄沙司,烧微加一点水,翻炒均匀出锅即可。###5. duang?成品,是不是很有食欲呢', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(18586, '川火爆麻辣小龙虾', 'meat', '洋葱:290克#虾:520克#竹笋:460克#食用油:45毫升#料酒:30毫升#豆瓣酱:30克#姜:25克#蒜:30克#葱:35克#花椒:6克#川火爆:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 差不多就以上佐料###2. 放油,先把虾油锅穿下一步变色,捞起。然后炒葱姜蒜花椒闻到香味,就可以倒下豆瓣酱一起炒。###3. 倒入小龙虾,加点料酒,然后倒入其他辅料(洋葱,青笋),也可不加辅料。起锅时,撒上一把海椒面。###4. 麻辣鲜香的四川火爆小龙虾出炉!口水...', '水产,热菜,麻辣,下酒菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/2/7/yuan_52299feb0b1cdd37bace07b137da2527.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###川火爆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 差不多就以上佐料###2. 放油,先把虾油锅穿下一步变色,捞起。然后炒葱姜蒜花椒闻到香味,就可以倒下豆瓣酱一起炒。###3. 倒入小龙虾,加点料酒,然后倒入其他辅料(洋葱,青笋),也可不加辅料。起锅时,撒上一把海椒面。###4. 麻辣鲜香的四川火爆小龙虾出炉!口水...', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(18642, '羊蝎子', 'meat', '洋葱:290克#羊肉:460克#食用油:45毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 将羊蝎子、羊排剁成4cm的小块放入冷水中浸泡两个小时,将其中的血水浸泡出来。 洋葱切丝、葱切段、姜切片,大蒜去皮拍散备用。###2. 锅中加入冷水,将浸泡好的羊蝎子、羊排倒入锅中放入葱段、姜片、花椒和一个大料,倒入适量料酒, 大火烧开,撇去浮沫捞出羊蝎子、羊排备用。###3. 另起锅倒入少许油,油温4成热时放入洋葱丝和香菜小火煸炒出香味,炒出葱、香菜油捞出备用。在少到些油,油温5成热时下', '肉类,热菜,朋友聚餐,下酒菜,私家菜,秋冬进补,家常菜', 'https://cp1.douguo.net/upload/caiku/d/6/6/yuan_d62ef1746ee3589cea6d520ed78772a6.jpg', '困难', '60分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###羊肉|460|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将羊蝎子、羊排剁成4cm的小块放入冷水中浸泡两个小时,将其中的血水浸泡出来。 洋葱切丝、葱切段、姜切片,大蒜去皮拍散备用。###2. 锅中加入冷水,将浸泡好的羊蝎子、羊排倒入锅中放入葱段、姜片、花椒和一个大料,倒入适量料酒, 大火烧开,撇去浮沫捞出羊蝎子、羊排备用。###3. 另起锅倒入少许油,油温4成热时放入洋葱丝和香菜小火煸炒出香味,炒出葱、香菜油捞出备用。在少到些油,油温5成热时下', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(1876, '彩百叶卷', 'meat', '火腿:290克#虾:520克#腐竹:230克#食用油:45毫升#食盐:7克#淀粉:30克#姜:25克#彩百叶:345克', '2名成年人总量+15%冗余', '1. 各种材料切丝,温水泡虾皮###2. 豆皮和香菜入开水汆一下###3. 虾皮和姜香菜一起切碎###4. 所有的料包入百叶内###5. 用香菜捆住###6. 放上火腿丝入锅大火蒸###7. 蒸熟后把盘子里的水入锅加水淀粉勾成玻璃芡,加少许盐白胡椒香油,淋入###8. 成品', '水产,肉类,热菜,朋友聚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/9/5/yuan_4908aea87d828df2f459075165c7c9a5.jpg', '普通', '25分钟', '火腿|290|克|主料|切片|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###腐竹|230|克|主料|提前泡发或切丝|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###彩百叶|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 各种材料切丝,温水泡虾皮###2. 豆皮和香菜入开水汆一下###3. 虾皮和姜香菜一起切碎###4. 所有的料包入百叶内###5. 用香菜捆住###6. 放上火腿丝入锅大火蒸###7. 蒸熟后把盘子里的水入锅加水淀粉勾成玻璃芡,加少许盐白胡椒香油,淋入###8. 成品', '[]', '来源步骤数: 8', '蒸', 0, 0, NULL, NULL),
(188, '外婆乡小榨菜籽油', 'meat', '鸡蛋:5个#食用油:45毫升#食盐:7克#料酒:30毫升#葱:35克#外婆乡小榨:345克', '2名成年人总量+15%冗余', '1. 备好食材:菜籽油、鸡蛋和杭椒###2. 鸡蛋打入碗中###3. 杭椒洗净切小段###4. 将杭椒段、料酒、盐、葱花和白胡椒粉放入鸡蛋碗中###5. 将其打散备用###6. 锅中倒入适量菜籽油###7. 中火将油烧热,倒入蛋液先不要翻动,待底面煎好后,再翻面煎###8. 煎熟之后可用锅铲将其划成小块即可出锅###9. 盛出后趁热吃吧!###10. 成品', '禽类,蛋类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/3/5/yuan_03bac66d22af6f41bb905f02a72abcf5.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###外婆乡小榨|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 备好食材:菜籽油、鸡蛋和杭椒###2. 鸡蛋打入碗中###3. 杭椒洗净切小段###4. 将杭椒段、料酒、盐、葱花和白胡椒粉放入鸡蛋碗中###5. 将其打散备用###6. 锅中倒入适量菜籽油###7. 中火将油烧热,倒入蛋液先不要翻动,待底面煎好后,再翻面煎###8. 煎熟之后可用锅铲将其划成小块即可出锅###9. 盛出后趁热吃吧!###10. 成品', '[]', '来源步骤数: 10', '煎', 0, 0, NULL, NULL),
(18806, '西葫芦炒肉菁选酱油二', 'meat', '西葫芦:460克#猪肉:345克#食用油:45毫升#食盐:7克#生抽:35毫升#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 豆果菁选酱油,还有密封罐包装保护,标签很精致可爱哦。###2. 备好食材。###3. 瘦肉切片,淋入少许菁选酱油,盐抓匀,腌制一会,西葫芦洗净切片。###4. 热锅凉油,下肉片滑炒变色,盛出备用。###5. 加少许油,爆香蒜末,葱白。###6. 倒入西葫芦片,大火快炒至软身,加入适量盐。###7. 淋入适量菁选酱油炒匀。###8. 倒入炒好的肉片,淋入少许清水略煮。###9. 炒匀出锅。', '东北菜,肉类,热菜,家常味,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/8/c/b/yuan_8c73e5d75afde5c57c1b19e10dad7d8b.jpg', '普通', '20分钟', '西葫芦|460|克|主料|洗净切片|2名成年人总量+15%冗余|菜名+步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 豆果菁选酱油,还有密封罐包装保护,标签很精致可爱哦。###2. 备好食材。###3. 瘦肉切片,淋入少许菁选酱油,盐抓匀,腌制一会,西葫芦洗净切片。###4. 热锅凉油,下肉片滑炒变色,盛出备用。###5. 加少许油,爆香蒜末,葱白。###6. 倒入西葫芦片,大火快炒至软身,加入适量盐。###7. 淋入适量菁选酱油炒匀。###8. 倒入炒好的肉片,淋入少许清水略煮。###9. 炒匀出锅。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(18811, '麻辣卤鸡爪', 'meat', '鸡肉:520克#鸡蛋:5个#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 将锅内倒适量的油烧热,放入所以的香料,葱姜蒜,炒香,放入鸡爪翻炒一下###2. 将鸡爪连同各种材料一起倒入电饭煲,加入没过鸡爪的水,放适量的酱油,盐,按下煲汤健煮着就行了,煮到喜欢的熟烂程度就可以了###3. 还可以将煮好的鸡蛋剥皮后放进锅里一起煮', '禽类,蛋类,热菜,麻辣,下酒菜,家常菜,电饭煲', 'https://cp1.douguo.net/upload/caiku/4/f/e/yuan_4f8b9ec0a51eb87a7d9f870f6983106e.jpg', '简单', '15分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 将锅内倒适量的油烧热,放入所以的香料,葱姜蒜,炒香,放入鸡爪翻炒一下###2. 将鸡爪连同各种材料一起倒入电饭煲,加入没过鸡爪的水,放适量的酱油,盐,按下煲汤健煮着就行了,煮到喜欢的熟烂程度就可以了###3. 还可以将煮好的鸡蛋剥皮后放进锅里一起煮', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(18851, '土豆烧鸡', 'meat', '洋葱:290克#鸡肉:520克#土豆:460克#青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#豆瓣酱:30克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 鸡块加豆瓣酱,生抽以及少许淀粉和好腌十多分钟。###2. 土豆切块,和鸡块差不多大。###3. 其他配料也切好。青椒也是家里自己种的绿色蔬菜。###4. 锅里放油放豆瓣酱,炒一会儿放姜片和洋葱炒香。###5. 下鸡块和土豆炒两分钟。###6. 加青椒炒一会儿,加水没过材料盖上锅盖小火闷二十分钟。###7. 最后加点大葱以及盐和鸡精,起锅。', '川菜,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/2/d/yuan_d26abbdde58af4355d539c4d261ab3ed.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鸡块加豆瓣酱,生抽以及少许淀粉和好腌十多分钟。###2. 土豆切块,和鸡块差不多大。###3. 其他配料也切好。青椒也是家里自己种的绿色蔬菜。###4. 锅里放油放豆瓣酱,炒一会儿放姜片和洋葱炒香。###5. 下鸡块和土豆炒两分钟。###6. 加青椒炒一会儿,加水没过材料盖上锅盖小火闷二十分钟。###7. 最后加点大葱以及盐和鸡精,起锅。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(18869, '水煮肉片', 'meat', '猪肉:345克#食用油:45毫升#料酒:30毫升#淀粉:30克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 将猪肉切片尽量切薄一点,放入适量料酒和淀粉抓匀,放置20分钟###2. 将炒锅内放油,油热后放入豆芽和菜心,炒至断生即可,盛入大碗中。###3. 再炒锅内放入骨汤,如没有可放清水,放入料包煮开,将腌好的肉片放入煮一两分钟即可###4. 肉片煮熟后起锅倒入放菜的碗中,将辣椒面和蒜末撒在肉片表面,将炒锅内加油烧热后浇到辣椒面上。加上适量葱花和香菜即可食用。', '川菜,肉类,热菜,下酒菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/4/9/yuan_44294f136e04e84ba9e493b4050777f9.jpg', '简单', '15分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将猪肉切片尽量切薄一点,放入适量料酒和淀粉抓匀,放置20分钟###2. 将炒锅内放油,油热后放入豆芽和菜心,炒至断生即可,盛入大碗中。###3. 再炒锅内放入骨汤,如没有可放清水,放入料包煮开,将腌好的肉片放入煮一两分钟即可###4. 肉片煮熟后起锅倒入放菜的碗中,将辣椒面和蒜末撒在肉片表面,将炒锅内加油烧热后浇到辣椒面上。加上适量葱花和香菜即可食用。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(19131, '酸萝卜炒肉丝最佳', 'meat', '猪肉:345克#青椒:205克#萝卜:460克#白糖:55克#食盐:7克#料酒:30毫升#姜:25克#蒜:30克#葱:35克#最佳:345克#食用油:45毫升', '2名成年人总量+15%冗余', '1. 都准备好了,肉切丝,肥瘦都有,小尖椒切细小状,###2. 先炒肉,添加些盐,入姜蒜有些香味出来后,倒入酸萝卜片,一边翻炒一边加料酒,少许白糖,###3. 最后加鸡精,葱花,几分钟就搞定啦,有时候美味不一定要很繁琐的程序才能成就的,', '禽类,肉类,热菜,午餐,下饭菜,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/6/0/1/yuan_609badde9607fd6e327d92d5ec660e31.jpg', '普通', '25分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###最佳|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全', '1. 都准备好了,肉切丝,肥瘦都有,小尖椒切细小状,###2. 先炒肉,添加些盐,入姜蒜有些香味出来后,倒入酸萝卜片,一边翻炒一边加料酒,少许白糖,###3. 最后加鸡精,葱花,几分钟就搞定啦,有时候美味不一定要很繁琐的程序才能成就的,', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(19210, '酸菜炖排骨', 'meat', '五花肉:345克#排骨:575克#豆腐:460克#食盐:7克#料酒:30毫升#姜:25克#酸菜:345克', '2名成年人总量+15%冗余', '1. 酸菜洗净,片成几层薄片,再切成丝备用,取1/2酸菜丝码在砂锅里;###2. 排骨用开水焯一下、去除血水和表面的脏东西,码在酸菜丝上;###3. 再把剩下的1/2酸菜码在排骨上,铺上切好块的冻豆腐;###4. 最后码上五花肉,沙锅加足清水;###5. 加姜片高火煮沸,煮沸后加入料酒和盐;转文火,继续煲1个小时,煮到排骨酥烂;###6. 最后加入香菜、胡椒粉调味就可以了。', '东北菜,肉类,热菜,下饭菜,朋友聚餐,午餐,幼儿食谱,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/8/b/e/yuan_8bc10728caca28f7cfbe21b1e0d52a4e.jpg', '困难', '60分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###酸菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 酸菜洗净,片成几层薄片,再切成丝备用,取1/2酸菜丝码在砂锅里;###2. 排骨用开水焯一下、去除血水和表面的脏东西,码在酸菜丝上;###3. 再把剩下的1/2酸菜码在排骨上,铺上切好块的冻豆腐;###4. 最后码上五花肉,沙锅加足清水;###5. 加姜片高火煮沸,煮沸后加入料酒和盐;转文火,继续煲1个小时,煮到排骨酥烂;###6. 最后加入香菜、胡椒粉调味就可以了。', '[]', '来源步骤数: 6', '炖', 0, 0, NULL, NULL),
(19229, '蜜酱牛肉', 'meat', '黑胡椒:6克#牛肉:400克#菜花:520克#食用油:45毫升#生抽:35毫升#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 牛肉''加八角肉桂''香叶白酒少许''酱油少许加水没过肉即可''入高压锅''煮透。###2. 制作酱汁''酱油''加蜂蜜''加黑胡椒''蒜汁''依个人口味增减!###3. 牛肉出高压锅后''连同汤汁一起入锅煮''加辣椒一个###4. 汤汁变少后加干黄酱###5. 西兰花焯水###6. 肉汤汁快收尽时加入西兰花###7. 摆盘即可', '肉类,热菜,午餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/b/1/8/yuan_b105d4fbe0cbd5c83fd8d40bf669de58.jpg', '困难', '60分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###菜花|520|克|主料|掰小朵洗净|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 牛肉''加八角肉桂''香叶白酒少许''酱油少许加水没过肉即可''入高压锅''煮透。###2. 制作酱汁''酱油''加蜂蜜''加黑胡椒''蒜汁''依个人口味增减!###3. 牛肉出高压锅后''连同汤汁一起入锅煮''加辣椒一个###4. 汤汁变少后加干黄酱###5. 西兰花焯水###6. 肉汤汁快收尽时加入西兰花###7. 摆盘即可', '[]', '来源步骤数: 7', '煮', 0, 0, NULL, NULL),
(19264, '搞定蒸鱼图解', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#料酒:30毫升#姜:25克#葱:35克#搞定:345克#图解:345克', '2名成年人总量+15%冗余', '1. 鲈鱼处理干净,上埚前10分钟,加盐,料酒,胡椒稍腌。鱼一定要新鲜,我家这条现杀的,买回来还在动。###2. 蒸锅大火烧开,盘子下垫姜葱去腥,更有利于水汽循环。###3. 上鱼蒸8到10分钟。注意别蒸过火候。###4. 同时调酱汁,我用的是李锦记鼔油,香油,椒粉,湖南黄色剁椒。黄的色泽柔和,更好看。酱汁另蒸热,不会破坏鱼的鲜°C和口感更柔和。###5. 鱼出锅,换盘,倒去汁水调料,蒸鱼的水有腥味', '粤菜,水产,热菜,家常菜', 'https://cp1.douguo.net/upload/caiku/1/e/0/yuan_1efef6b4377e89f5583fb2b85e5e9ab0.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###搞定|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###图解|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鲈鱼处理干净,上埚前10分钟,加盐,料酒,胡椒稍腌。鱼一定要新鲜,我家这条现杀的,买回来还在动。###2. 蒸锅大火烧开,盘子下垫姜葱去腥,更有利于水汽循环。###3. 上鱼蒸8到10分钟。注意别蒸过火候。###4. 同时调酱汁,我用的是李锦记鼔油,香油,椒粉,湖南黄色剁椒。黄的色泽柔和,更好看。酱汁另蒸热,不会破坏鱼的鲜°C和口感更柔和。###5. 鱼出锅,换盘,倒去汁水调料,蒸鱼的水有腥味', '[]', '来源步骤数: 5', '蒸', 0, 0, NULL, NULL),
(19409, '甜辣烤里脊肉', 'meat', '花生:170克#洋葱:290克#猪里脊:345克#萝卜:460克#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#葱:35克#甜辣:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将所有材料准备好。胡萝卜切块,洋葱切碎。里脊肉切成大块,洗净擦干表面。###2. 把胡萝卜、洋葱、姜、米酒、辣椒粉、生抽、细砂糖、花生油全部放入食品料理机,搅打成细腻的腌汁。###3. 将腌汁和里脊肉混合在一起。###4. 让里脊肉浸泡在腌汁里,盖上保鲜膜,腌制12-24个小时。###5. 腌好的里脊肉,摆放在烤盘上。预热烤箱到上下火200°C。###6. 将腌肉剩下的腌汁倒入奶锅里,中火加热', '肉类,热菜,甜辣,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/7/b/7/yuan_7b119277822984c02f7dc5acc3cd4447.jpg', '普通', '25分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###甜辣|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将所有材料准备好。胡萝卜切块,洋葱切碎。里脊肉切成大块,洗净擦干表面。###2. 把胡萝卜、洋葱、姜、米酒、辣椒粉、生抽、细砂糖、花生油全部放入食品料理机,搅打成细腻的腌汁。###3. 将腌汁和里脊肉混合在一起。###4. 让里脊肉浸泡在腌汁里,盖上保鲜膜,腌制12-24个小时。###5. 腌好的里脊肉,摆放在烤盘上。预热烤箱到上下火200°C。###6. 将腌肉剩下的腌汁倒入奶锅里,中火加热', '[]', '来源步骤数: 6', '煮', 0, 0, NULL, NULL),
(19431, '湖南小炒肉', 'meat', '五花肉:345克#猪肉:345克#鱼:690克#食用油:45毫升#食盐:7克#蒜:30克#湖南小:345克', '2名成年人总量+15%冗余', '1. 辣椒洗净,用快刀削成片状,肉切薄片待用###2. 干锅不上油,下辣椒中火干煸,煸到辣椒疲软,乘出待用###3. 坐锅起油,下蒜子爆香###4. 下五花肉翻炒,煸出油质###5. 下瘦肉翻炒至变色###6. 下煸好的辣椒,翻炒2分钟,下盐、味素调味,翻炒2分钟,撒蒸鱼豉油,翻匀出锅即可', '湘菜,肉类,水产,热菜,朋友聚餐,下饭菜,下酒菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/8/a/yuan_e890fd54464a89ade2421e290ad559ca.jpg', '困难', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###湖南小|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 辣椒洗净,用快刀削成片状,肉切薄片待用###2. 干锅不上油,下辣椒中火干煸,煸到辣椒疲软,乘出待用###3. 坐锅起油,下蒜子爆香###4. 下五花肉翻炒,煸出油质###5. 下瘦肉翻炒至变色###6. 下煸好的辣椒,翻炒2分钟,下盐、味素调味,翻炒2分钟,撒蒸鱼豉油,翻匀出锅即可', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(19453, '肉酱', 'meat', '芝麻:35克#猪肉:345克#白糖:55克#食用油:45毫升#豆瓣酱:30克#葱:35克#干辣椒:15克#食盐:7克', '2名成年人总量+15%冗余', '1. 猪肉切的碎碎的 肥瘦相间口感不错 我这个有点瘦了###2. 放入辣椒粉 胡椒粉 少许白酒###3. 搅拌并腌制五分钟即可###4. 把酱料放入调味碗中 郫县豆瓣酱是金黄酱的二分之一 放入辣椒粉 辣椒段儿 搅拌好###5. 将葱花下锅 有葱香溢出 将猪肉碎下锅翻炒后放入辣椒油 迅速将酱倒入锅中翻炒 最后放芝麻###6. 放入白糖 黑芝麻 继续翻炒 根据自己口味增减调料', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/8/a/b/yuan_8a33214a2aa5fb09cccf17696b25c34b.jpg', '简单', '15分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 猪肉切的碎碎的 肥瘦相间口感不错 我这个有点瘦了###2. 放入辣椒粉 胡椒粉 少许白酒###3. 搅拌并腌制五分钟即可###4. 把酱料放入调味碗中 郫县豆瓣酱是金黄酱的二分之一 放入辣椒粉 辣椒段儿 搅拌好###5. 将葱花下锅 有葱香溢出 将猪肉碎下锅翻炒后放入辣椒油 迅速将酱倒入锅中翻炒 最后放芝麻###6. 放入白糖 黑芝麻 继续翻炒 根据自己口味增减调料', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(19481, '花肉炖豆角', 'meat', '五花肉:345克#豆角:460克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克#花肉:345克', '2名成年人总量+15%冗余', '1. 油豆角掐去两头洗干净备用###2. 五花肉切好备用###3. 葱姜切丝好,蒜切末备用###4. 锅里热油,放入五花肉煸炒,然后在放入葱姜和两粒八角。###5. 倒入豆角继续炒###6. 一直炒到豆角颜色成深绿色,加入盐 、酱油###7. 加入适量的水,大火烧开转小火慢炖到汤汁浓缩###8. 出锅前加点蒜末###9. 成品', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/f/d/8/yuan_fd15bd9f84946ec07c505dc528c6d018.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 油豆角掐去两头洗干净备用###2. 五花肉切好备用###3. 葱姜切丝好,蒜切末备用###4. 锅里热油,放入五花肉煸炒,然后在放入葱姜和两粒八角。###5. 倒入豆角继续炒###6. 一直炒到豆角颜色成深绿色,加入盐 、酱油###7. 加入适量的水,大火烧开转小火慢炖到汤汁浓缩###8. 出锅前加点蒜末###9. 成品', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(195, '红烧鸡块', 'meat', '鸡肉:520克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. 鸡肉切小块,加盐和姜片腌制10分钟。###2. 锅下油烧热,放姜蒜爆香。###3. 加入鸡块翻炒到肉色变白,转中小火慢慢把鸡皮的油脂煎出来,再加糖翻炒到糖融化,让鸡肉裹上焦糖上色。这个步骤有点像红烧肉里的炒糖色。###4. 鸡肉煎炸到变黄变香酥,加入米酒和酱油翻炒几下。###5. 加水,大火煮开,转小火焖煮。###6. 水快收干后,开大火快速收锅,汁烧干就能上色。', '川菜,禽类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/b/7/yuan_5b45dc847e69ae7f2e3c38661ca9cb37.jpg', '简单', '15分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 鸡肉切小块,加盐和姜片腌制10分钟。###2. 锅下油烧热,放姜蒜爆香。###3. 加入鸡块翻炒到肉色变白,转中小火慢慢把鸡皮的油脂煎出来,再加糖翻炒到糖融化,让鸡肉裹上焦糖上色。这个步骤有点像红烧肉里的炒糖色。###4. 鸡肉煎炸到变黄变香酥,加入米酒和酱油翻炒几下。###5. 加水,大火煮开,转小火焖煮。###6. 水快收干后,开大火快速收锅,汁烧干就能上色。', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(19502, '土豆炖牛肉', 'meat', '洋葱:290克#黑胡椒:6克#牛肉:400克#土豆:460克#萝卜:460克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 胡萝卜土豆滚刀切块儿,洋葱切丝,顺带切点儿爆锅的姜片和蒜。###2. 还有牛腩切方块儿~###3. 热锅冷油用姜片、蒜爆锅,放入牛肉快速翻炒,入料酒保持肉质,待牛肉变色后放入洋葱翻炒~###4. 洋葱炒软后加入胡萝卜、土豆,翻炒均匀后加入适量砂糖和酱油(生抽); 加入开水煮开后小火慢炖40分钟,出锅前记得加一点点黑胡椒哦~###5. 完成咯~', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/6/a/5/yuan_6a1dc631692be47be2d2827a80ca5e25.jpg', '普通', '25分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 胡萝卜土豆滚刀切块儿,洋葱切丝,顺带切点儿爆锅的姜片和蒜。###2. 还有牛腩切方块儿~###3. 热锅冷油用姜片、蒜爆锅,放入牛肉快速翻炒,入料酒保持肉质,待牛肉变色后放入洋葱翻炒~###4. 洋葱炒软后加入胡萝卜、土豆,翻炒均匀后加入适量砂糖和酱油(生抽); 加入开水煮开后小火慢炖40分钟,出锅前记得加一点点黑胡椒哦~###5. 完成咯~', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(19632, '焖猪肉', 'meat', '猪肉:345克#食用油:45毫升#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 焯过水的猪肉,先用豉油腌半小时###2. 锅里先放油,再放葱和蒜炒香###3. 放入猪肉和豉油翻炒###4. 把猪肉炒香###5. 加入水,大火烧开,转小火焖###6. 焖至快收汁,加入大喜大牛肉粉拌匀再焖十分钟。###7. 焖熟关火即可###8. 装好上桌', '肉类,豆制品,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/d/c/2/yuan_dcbf9334ad068c3b879b001afd5f3e72.jpg', '普通', '25分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 焯过水的猪肉,先用豉油腌半小时###2. 锅里先放油,再放葱和蒜炒香###3. 放入猪肉和豉油翻炒###4. 把猪肉炒香###5. 加入水,大火烧开,转小火焖###6. 焖至快收汁,加入大喜大牛肉粉拌匀再焖十分钟。###7. 焖熟关火即可###8. 装好上桌', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(19747, '西芹腰果虾仁', 'meat', '虾:520克#芹菜:400克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#腰果:345克', '2名成年人总量+15%冗余', '1. 鲜虾洗净去壳去虾线###2. 加少许盐,料酒、半个蛋清、水淀粉,拌匀腌制十多分钟###3. 芹菜切小段,姜蒜切末切丝###4. 炒锅热油,下姜蒜爆香###5. 放入芹菜煸炒片刻###6. 然后加入腌好的虾仁,爆炒至变色,加一点盐调味,喜欢的话还可加一点糖提鲜###7. 最后加入腰果翻炒均匀即可出锅###8. 成品', '水产,热菜,下饭菜,下酒菜,创意菜,家常菜', 'https://cp1.douguo.net/upload/caiku/a/4/7/yuan_a40d8162aa63c90834dfd54a9a8312a7.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###腰果|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鲜虾洗净去壳去虾线###2. 加少许盐,料酒、半个蛋清、水淀粉,拌匀腌制十多分钟###3. 芹菜切小段,姜蒜切末切丝###4. 炒锅热油,下姜蒜爆香###5. 放入芹菜煸炒片刻###6. 然后加入腌好的虾仁,爆炒至变色,加一点盐调味,喜欢的话还可加一点糖提鲜###7. 最后加入腰果翻炒均匀即可出锅###8. 成品', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(19748, '香酥烤鱼柳', 'meat', '黑胡椒:6克#鱼:690克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 龙利鱼解冻后,加入盐和黑胡椒粉腌制10分钟左右;###2. 蒜切末,加入到面包糠中,再倒入橄榄油,用筷子拌至面包糠到湿润的状态;###3. 腌好的龙利鱼切细条,表面裹上拌好的面包糠;###4. 烤盘铺油纸,鱼柳整齐的码放在烤盘上;###5. 烤箱温度200度,时间20分钟,预热后放入烤盘即可。', '川菜,水产,零食,热菜,香酥,午餐,一家三口,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/7/2/8/yuan_72782fc4005bde611e2bd5e599f92e88.jpg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 龙利鱼解冻后,加入盐和黑胡椒粉腌制10分钟左右;###2. 蒜切末,加入到面包糠中,再倒入橄榄油,用筷子拌至面包糠到湿润的状态;###3. 腌好的龙利鱼切细条,表面裹上拌好的面包糠;###4. 烤盘铺油纸,鱼柳整齐的码放在烤盘上;###5. 烤箱温度200度,时间20分钟,预热后放入烤盘即可。', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(19761, '水煮虾', 'meat', '虾:520克#食用油:45毫升#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 将准备好的明虾用清水稍作清洗,准备使用。###2. 在锅内加入冷水,并把准备好的明虾放入锅中。###3. 把切好的生姜丝直接撒至锅内。###4. 并倒入适量料酒。###5. 然后开火盖锅盖,中火煮3~4分钟即熟。###6. 出锅装盘。可直接食用或剥壳后沾取适量醋混合酱油进行调味。###7. 小龙虾镇楼!', '海鲜,水产,热菜,一家三口,下饭菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/0/3/8/yuan_0329085ece2feaf18eb424f9de326ef8.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将准备好的明虾用清水稍作清洗,准备使用。###2. 在锅内加入冷水,并把准备好的明虾放入锅中。###3. 把切好的生姜丝直接撒至锅内。###4. 并倒入适量料酒。###5. 然后开火盖锅盖,中火煮3~4分钟即熟。###6. 出锅装盘。可直接食用或剥壳后沾取适量醋混合酱油进行调味。###7. 小龙虾镇楼!', '[]', '来源步骤数: 7', '煮', 0, 0, NULL, NULL),
(19780, '酱香烤排', 'meat', '花生:170克#芝麻:35克#排骨:575克#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 老抽加昭通酱###2. 加芝麻酱和花生酱!###3. 排骨洗净,加小粉!###4. 再加蒜末和姜末!###5. 酱料碗加料酒搅匀!###6. 酱料倒入排骨,拌匀!###7. 研制4个小时!###8. 放上辣椒和辣椒面,放入烤箱180度20分钟!用锡纸包好!###9. 拿出来反面,再烤25分钟。取出倒出多余的汤汁,拿掉盖在上面的锡纸,刷蜂蜜,再入烤箱250度,烤10分钟!###10. 摆盘!', '肉类,热菜,酱香,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/1/a/4/yuan_1a03ce1e0625b6efc0aa68a1a9989074.jpg', '简单', '15分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 老抽加昭通酱###2. 加芝麻酱和花生酱!###3. 排骨洗净,加小粉!###4. 再加蒜末和姜末!###5. 酱料碗加料酒搅匀!###6. 酱料倒入排骨,拌匀!###7. 研制4个小时!###8. 放上辣椒和辣椒面,放入烤箱180度20分钟!用锡纸包好!###9. 拿出来反面,再烤25分钟。取出倒出多余的汤汁,拿掉盖在上面的锡纸,刷蜂蜜,再入烤箱250度,烤10分钟!###10. 摆盘!', '[]', '来源步骤数: 10', '烤', 0, 0, NULL, NULL),
(1984, '牛肉金针菇蒸萝卜', 'meat', '牛肉:400克#金针菇:290克#萝卜:460克#食用油:45毫升#食盐:7克#生抽:35毫升#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 牛肉洗净切片###2. 倒入橄露橄榄油###3. 倒入酱油###4. 加盐拌匀###5. 胡萝卜切成粗条,摆在碗底###6. 金针菇洗净备用,切蒜蓉###7. 将牛肉和金针菇、蒜蓉拌匀###8. 拌匀后均匀地放在胡萝卜上###9. 入蒸锅蒸10分钟至熟透###10. 取出撒上葱花即成。', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/f/7/yuan_1fccd595945a17ab48a3ae7be1b38697.jpg', '简单', '15分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###金针菇|290|克|配菜|去根洗净|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 牛肉洗净切片###2. 倒入橄露橄榄油###3. 倒入酱油###4. 加盐拌匀###5. 胡萝卜切成粗条,摆在碗底###6. 金针菇洗净备用,切蒜蓉###7. 将牛肉和金针菇、蒜蓉拌匀###8. 拌匀后均匀地放在胡萝卜上###9. 入蒸锅蒸10分钟至熟透###10. 取出撒上葱花即成。', '[]', '来源步骤数: 10', '蒸', 0, 0, NULL, NULL),
(1989, '南瓜炒肉', 'meat', '猪肉:345克#南瓜:575克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 南瓜去皮去籽,切成片,不要太薄,海米用水洗净,微泡一下捞出###2. 猪肉切片,切好葱丝和姜末待用###3. 热锅凉油,把猪肉下锅翻炒,###4. 待猪肉变白后,放入姜末,葱丝,花椒粉,翻炒,加少许酱油###5. 放入南瓜,同时添入少许水,盐,继续炒几下###6. 放入泡好的海米,再加适量的水,烧五分钟###7. 等南瓜熟后,大火收汁,放入一匙家乐鸡粉,稍稍拌匀就可以起锅了', '禽类,肉类,热菜,甜辣,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/d/1/yuan_3d5c3e0c957ad48a82d41b5030969791.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###南瓜|575|克|主料|去瓤切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 南瓜去皮去籽,切成片,不要太薄,海米用水洗净,微泡一下捞出###2. 猪肉切片,切好葱丝和姜末待用###3. 热锅凉油,把猪肉下锅翻炒,###4. 待猪肉变白后,放入姜末,葱丝,花椒粉,翻炒,加少许酱油###5. 放入南瓜,同时添入少许水,盐,继续炒几下###6. 放入泡好的海米,再加适量的水,烧五分钟###7. 等南瓜熟后,大火收汁,放入一匙家乐鸡粉,稍稍拌匀就可以起锅了', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(19950, '东北酸菜炖多宝鱼', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#姜:25克#葱:35克#花椒:6克#东北酸菜:345克#多宝:345克', '2名成年人总量+15%冗余', '1. 鱼洗净,切段,用盐、姜丝、白胡椒粉、盐,葱段腌制。使鱼有了咸淡味了###2. 酸菜洗净切丝,需要偏几层,这样的酸菜丝才能是细细的###3. 姜也切丝。###4. 锅里放半羹匙新鲜猪油,再放点植物油###5. 青花椒和红干椒准备好,油热就放里面炸香###6. 之后是炒软酸菜###7. 添汤后把酸菜炖10分钟,下鱼段,再炖8分钟到十分钟。这期间别翻腾菜喽###8. 鲜辣的酸菜炖鱼出锅了!', '东北菜,水产,肉类,热菜,下饭菜,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/6/9/2/yuan_69435fcd0bb90b3e85936652434e8b52.jpg', '普通', '25分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###东北酸菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###多宝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鱼洗净,切段,用盐、姜丝、白胡椒粉、盐,葱段腌制。使鱼有了咸淡味了###2. 酸菜洗净切丝,需要偏几层,这样的酸菜丝才能是细细的###3. 姜也切丝。###4. 锅里放半羹匙新鲜猪油,再放点植物油###5. 青花椒和红干椒准备好,油热就放里面炸香###6. 之后是炒软酸菜###7. 添汤后把酸菜炖10分钟,下鱼段,再炖8分钟到十分钟。这期间别翻腾菜喽###8. 鲜辣的酸菜炖鱼出锅了!', '[]', '来源步骤数: 8', '炸', 0, 0, NULL, NULL),
(19984, '酱猪蹄', 'meat', '猪蹄:690克#白糖:55克#食盐:7克#生抽:35毫升#老抽:15毫升#姜:25克#蒜:30克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 猪蹄洗净一劈两半放高压锅里备用###2. 准备个料包,花椒3g、八角一个、桂皮一小片###3. 葱切段,蒜切块、姜切片###4. 锅里放入生抽老抽白酒白糖鸡精盐,然后放入切好的葱姜蒜,把料包也放入###5. 加入开水,水差不多和猪蹄一般齐就可以了,然后盖上高压锅盖,开大火,待高压锅开始"呲呲"后转中火30分钟左右即可。###6. 出锅!我就盛出来两块,盘子有限啊', '肉类,禽类,热菜,朋友聚餐,午餐,一家三口,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/8/4/4/yuan_840a3d6769e52b500b87a6e4436131b4.jpg', '普通', '20分钟', '猪蹄|690|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 猪蹄洗净一劈两半放高压锅里备用###2. 准备个料包,花椒3g、八角一个、桂皮一小片###3. 葱切段,蒜切块、姜切片###4. 锅里放入生抽老抽白酒白糖鸡精盐,然后放入切好的葱姜蒜,把料包也放入###5. 加入开水,水差不多和猪蹄一般齐就可以了,然后盖上高压锅盖,开大火,待高压锅开始"呲呲"后转中火30分钟左右即可。###6. 出锅!我就盛出来两块,盘子有限啊', '[]', '来源步骤数: 6', '酱制', 0, 0, NULL, NULL),
(20001, '椒小鸡丝儿白领快手菜', 'meat', '鸡肉:520克#青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 鸡胸肉切丝,放一点料酒,胡椒粉,盐,淀粉,腌制10分钟。为了颜色好看没有放蚝油酱油。###2. 各种椒切丝儿,因为爱吃辣所以加了一个杭椒。不吃辣的可以把尖椒换成青椒。###3. 鸡肉滚水焯过,变白后就可以捞出控水###4. 锅内放油,葱姜蒜爆香后捞出,还是为了好看。###5. 辣椒丝倒进锅里翻炒。###6. 椒丝炒到断生后放入鸡肉继续炒,放少许盐和胡椒粉。###7. 撒点鸡精就可以出锅了~', '禽类,水产,肉类,热菜,下饭菜,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/6/0/4/yuan_60be3cfdecb49e9d36b80df8294b4704.jpg', '简单', '15分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鸡胸肉切丝,放一点料酒,胡椒粉,盐,淀粉,腌制10分钟。为了颜色好看没有放蚝油酱油。###2. 各种椒切丝儿,因为爱吃辣所以加了一个杭椒。不吃辣的可以把尖椒换成青椒。###3. 鸡肉滚水焯过,变白后就可以捞出控水###4. 锅内放油,葱姜蒜爆香后捞出,还是为了好看。###5. 辣椒丝倒进锅里翻炒。###6. 椒丝炒到断生后放入鸡肉继续炒,放少许盐和胡椒粉。###7. 撒点鸡精就可以出锅了~', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(2015, '豆炖排骨', 'meat', '排骨:575克#土豆:460克#木耳:35克#豆角:460克#大米:345克#食用油:45毫升#老抽:15毫升#姜:25克#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 炒锅热油,中火放姜片、蒜片爆香后加入焯好的排骨翻炒出肉香味,加入适量老抽上色煸炒片刻,倒入没过排骨的开水炖30分钟###2. 趁着炖排骨的时间准备其它材料:土豆洗净去皮切成块状,豆角洗净切段,木耳粉条洗净泡发###3. 待排骨炖软后依次加入扁豆角、土豆、木耳,再炖15分钟至蔬菜熟软###4. 最后加入粉条再炖到软烂,上至老人下到孩童都能咬得动,来份米饭开动喽', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/0/e/yuan_e0e33126c023584a917c7f899a6cc42e.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|步骤###大米|345|克|主料|淘洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 炒锅热油,中火放姜片、蒜片爆香后加入焯好的排骨翻炒出肉香味,加入适量老抽上色煸炒片刻,倒入没过排骨的开水炖30分钟###2. 趁着炖排骨的时间准备其它材料:土豆洗净去皮切成块状,豆角洗净切段,木耳粉条洗净泡发###3. 待排骨炖软后依次加入扁豆角、土豆、木耳,再炖15分钟至蔬菜熟软###4. 最后加入粉条再炖到软烂,上至老人下到孩童都能咬得动,来份米饭开动喽', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(20177, '糖醋虾', 'meat', '虾:520克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#香醋:30毫升#姜:25克#蒜:30克#花椒:6克', '2名成年人总量+15%冗余', '1. 虾,用剪刀剪掉胡子和头上那个刀,免得吃的时候扎到嘴巴。我每次都把它的眼珠子剪掉了。处理好了洗干净,沥干水###2. 准备好的花椒,辣椒,蒜,姜,去除腥味###3. 油烧热,爆香花椒,辣椒,蒜,姜###4. 倒入虾,翻炒###5. 虾有点变色了,放入盐,糖,醋,生抽,老抽,鸡精,继续翻炒1分钟多点,就是调料都化开,虾上色就好了。###6. 成品咯', '水产,禽类,热菜,酸甜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/0/6/yuan_5015d666b928b0e0c3e73e90c66a42b6.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 虾,用剪刀剪掉胡子和头上那个刀,免得吃的时候扎到嘴巴。我每次都把它的眼珠子剪掉了。处理好了洗干净,沥干水###2. 准备好的花椒,辣椒,蒜,姜,去除腥味###3. 油烧热,爆香花椒,辣椒,蒜,姜###4. 倒入虾,翻炒###5. 虾有点变色了,放入盐,糖,醋,生抽,老抽,鸡精,继续翻炒1分钟多点,就是调料都化开,虾上色就好了。###6. 成品咯', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(20192, '红烧黄花鱼', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#黄花:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 黄花鱼去黑膜洗净,姜、蒜切丝。###2. 热锅冷油,鱼下锅煎。###3. 煎鱼的时候调酱汁:水,生抽/味极鲜,料酒。###4. 鱼煎得差不多了(随意感受一下,反正煎不熟加酱汁也会煮熟)推到锅的一边,用剩下的油爆香姜和蒜。###5. 姜蒜和鱼混合,倒入酱汁...盖锅盖煮,期间给鱼翻个面。###6. 筷子戳鱼身最厚的部分,看看熟没。###7. 加糖,收汁,起锅。', '海鲜,水产,热菜,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/1/b/3/yuan_1b38e69201794196b273b6f9f7842e63.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###黄花|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 黄花鱼去黑膜洗净,姜、蒜切丝。###2. 热锅冷油,鱼下锅煎。###3. 煎鱼的时候调酱汁:水,生抽/味极鲜,料酒。###4. 鱼煎得差不多了(随意感受一下,反正煎不熟加酱汁也会煮熟)推到锅的一边,用剩下的油爆香姜和蒜。###5. 姜蒜和鱼混合,倒入酱汁...盖锅盖煮,期间给鱼翻个面。###6. 筷子戳鱼身最厚的部分,看看熟没。###7. 加糖,收汁,起锅。', '[]', '来源步骤数: 7', '煎', 0, 0, NULL, NULL),
(20283, '菜黑胡椒炒肉', 'meat', '洋葱:290克#黑胡椒:6克#牛肉:400克#青椒:205克#红椒:170克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#葱:35克', '2名成年人总量+15%冗余', '1. 青椒,红椒,洋葱改刀切成小块备用。###2. 牛肉洗净切片,放少许料酒,淀粉,黑胡椒,白糖腌制一会。###3. 调黑胡椒汁,放入黑胡椒,水淀粉,盐,鸡精,料酒。锅里放油,下牛肉,把红椒和洋葱放进去,青椒最后放!###4. 材料快熟时倒入黑胡椒汁,大火收汁即可!', '肉类,禽类,热菜,下饭菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/5/5/yuan_0573c64743d2f6908dce5a56d4410355.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 青椒,红椒,洋葱改刀切成小块备用。###2. 牛肉洗净切片,放少许料酒,淀粉,黑胡椒,白糖腌制一会。###3. 调黑胡椒汁,放入黑胡椒,水淀粉,盐,鸡精,料酒。锅里放油,下牛肉,把红椒和洋葱放进去,青椒最后放!###4. 材料快熟时倒入黑胡椒汁,大火收汁即可!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(20320, '好炖', 'meat', '猪肉:345克#鱼:690克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升', '2名成年人总量+15%冗余', '1. 直接上成品图吧!因为真的很简单!###2. 白萝卜去皮,切块,下冷水中煮开,调小火煮熟。###3. 换一锅新的水,把白萝卜、肉片、鱼丸等任何你想吃的好东西丢到锅里,加2大勺日本酱油和2克糖。根据自己口味加少许盐(不爱吃咸的人就可以不加盐啦)大火烧开。小火煮20分钟。好啦!享受美味吧!', '水产,肉类,小吃,热菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/9/1/3/yuan_912c472a32b890368375da5af6c65243.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤', '1. 直接上成品图吧!因为真的很简单!###2. 白萝卜去皮,切块,下冷水中煮开,调小火煮熟。###3. 换一锅新的水,把白萝卜、肉片、鱼丸等任何你想吃的好东西丢到锅里,加2大勺日本酱油和2克糖。根据自己口味加少许盐(不爱吃咸的人就可以不加盐啦)大火烧开。小火煮20分钟。好啦!享受美味吧!', '[]', '来源步骤数: 3', '炖', 0, 0, NULL, NULL),
(20339, '糖醋排骨', 'meat', '芝麻:35克#排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#香醋:30毫升#淀粉:30克', '2名成年人总量+15%冗余', '1. 大喜大的产品外形靓丽 内在丰富 很不错的产品###2. 排骨小段加入少许大喜大粉 白糖 盐 老陈醋腌制半小时到一小时倒掉水###3. 加入淀粉抓匀,炸时抖掉多余粉###4. 炸好后再复炸一次###5. 倒掉油下少许水,加入少许盐,半匙老陈醋,少许白糖,大喜大粉,煮开少许水淀粉勾兑。浓时下排骨翻一下###6. 装盘后,洒上一点白芝麻装饰并增香', '肉类,热菜,酸甜,晚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/0/e/yuan_80aa8f12e38c523082e3b36357d48e5e.jpg', '困难', '20分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 大喜大的产品外形靓丽 内在丰富 很不错的产品###2. 排骨小段加入少许大喜大粉 白糖 盐 老陈醋腌制半小时到一小时倒掉水###3. 加入淀粉抓匀,炸时抖掉多余粉###4. 炸好后再复炸一次###5. 倒掉油下少许水,加入少许盐,半匙老陈醋,少许白糖,大喜大粉,煮开少许水淀粉勾兑。浓时下排骨翻一下###6. 装盘后,洒上一点白芝麻装饰并增香', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(20411, '蜜汁烤鸭腿', 'meat', '排骨:575克#鸭肉:575克#白糖:55克#食用油:45毫升#生抽:35毫升#蜜汁:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸭腿洗净,小刀尖在两面戳一些洞眼,以便入味。###2. 将菁选酱油、排骨酱和糖拌成酱料。###3. 鸭腿两面均匀抹上酱料,放冰箱冷藏室腌制一晚。###4. 取出后在脚踝处包上锡纸。烤箱220度预热。###5. 鸭腿放在铺了锡纸的烤盘上,蜂蜜加水调成蜂蜜水,刷在鸭腿两面,烤箱中层200度先烤20分钟,取出再刷一遍蜂蜜水,稍微晾一下,再放入烤箱烤20分钟,即可取出切块食用。', '禽类,肉类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/d/4/d/yuan_d46c933ded492ed55b381f333f1c02dd.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|步骤###鸭肉|575|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蜜汁|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸭腿洗净,小刀尖在两面戳一些洞眼,以便入味。###2. 将菁选酱油、排骨酱和糖拌成酱料。###3. 鸭腿两面均匀抹上酱料,放冰箱冷藏室腌制一晚。###4. 取出后在脚踝处包上锡纸。烤箱220度预热。###5. 鸭腿放在铺了锡纸的烤盘上,蜂蜜加水调成蜂蜜水,刷在鸭腿两面,烤箱中层200度先烤20分钟,取出再刷一遍蜂蜜水,稍微晾一下,再放入烤箱烤20分钟,即可取出切块食用。', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(20445, '蒜香骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#老抽:15毫升#蒜:30克#干辣椒:15克#香骨:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 猪肋排改刀成12厘米的长段,用清水漂去血水;###2. 用调料腌制2小时(海鲜酱,沙茶酱,老抽,生抽,蚝油,味精,白糖)以上;###3. 油烧到二成热,把排骨放入锅中,油温由低至高慢慢炸制,至肋排成熟、外皮结壳取出沥干油;###4. 再在锅中放入蒜茸、干辣椒炒出香味,再放入肋排稍炒,加上调料,装盆即可。', '肉类,水产,热菜,蒜香,朋友聚餐,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/5/3/a/yuan_53a7ae77a03ef5da98ed78caec83182a.png', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###香骨|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 猪肋排改刀成12厘米的长段,用清水漂去血水;###2. 用调料腌制2小时(海鲜酱,沙茶酱,老抽,生抽,蚝油,味精,白糖)以上;###3. 油烧到二成热,把排骨放入锅中,油温由低至高慢慢炸制,至肋排成熟、外皮结壳取出沥干油;###4. 再在锅中放入蒜茸、干辣椒炒出香味,再放入肋排稍炒,加上调料,装盆即可。', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(20450, '西红柿炒蛋', 'meat', '鸡蛋:5个#西红柿:460克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡蛋打散打匀,放入少许食盐(取盐的小勺底上一点即可)。西红柿切块,提前剥皮也可。###2. 热锅热油,放入打好的鸡蛋,炒成型(凝固),用铲子捣开变成小块,盛入盘中。###3. 再次加入少量清油入锅,待油热加入西红柿块,翻炒至出汁。###4. 加入炒好的鸡蛋,翻炒拌匀(如果喜欢多汁则加入少许水)。放盐,炒匀,出锅!', '禽类,蛋类,热菜,酸甜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/6/6/e/yuan_66a9b3bde2a6a0b33e8909bbb41cc9ae.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 鸡蛋打散打匀,放入少许食盐(取盐的小勺底上一点即可)。西红柿切块,提前剥皮也可。###2. 热锅热油,放入打好的鸡蛋,炒成型(凝固),用铲子捣开变成小块,盛入盘中。###3. 再次加入少量清油入锅,待油热加入西红柿块,翻炒至出汁。###4. 加入炒好的鸡蛋,翻炒拌匀(如果喜欢多汁则加入少许水)。放盐,炒匀,出锅!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(20544, '酥炸鸡腿肉', 'meat', '鸡腿:575克#鸡肉:520克#鸡蛋:5个#面粉:400克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 将鸡腿洗净剔除骨头和鸡皮,切块(比拇指略粗),放入葱姜蒜碎,适量一品鲜酱油和料酒调成的酱汁,冷藏腌制3小时。###2. 将腌制好的鸡腿肉,依次裹上面粉、鸡蛋液、面包糠。###3. 空气炸锅180度预热3分钟,炸篮底部刷适量油,将鸡肉块摆放入炸篮,记得肉块间留适量空隙,便于受热均匀。180度炸制10分钟既可。###4. 开吃吧,香稣可口的健康美食。', '禽类,蛋类,肉类,热菜,午餐,朋友聚餐,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/f/f/1/yuan_ff6c55368e89f7723d4220e4472268d1.jpg', '简单', '15分钟', '鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|菜名+步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将鸡腿洗净剔除骨头和鸡皮,切块(比拇指略粗),放入葱姜蒜碎,适量一品鲜酱油和料酒调成的酱汁,冷藏腌制3小时。###2. 将腌制好的鸡腿肉,依次裹上面粉、鸡蛋液、面包糠。###3. 空气炸锅180度预热3分钟,炸篮底部刷适量油,将鸡肉块摆放入炸篮,记得肉块间留适量空隙,便于受热均匀。180度炸制10分钟既可。###4. 开吃吧,香稣可口的健康美食。', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(20607, '蛤蜊', 'meat', '蛤蜊:690克#食用油:45毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 备好食材,蛤蜊用清水泡,滴两滴香油让它吐渣渣,一两个小时后把蛤蜊洗净###2. 开火,放油,姜蒜,然后放小块火锅底料,稍加翻炒,让它融化,然后加蛤蜊,翻炒,滴点料酒,盖上锅盖让蛤蜊煮开开口,千万不要加水噢,继续翻炒至全开口为止###3. 出锅~加点小葱更漂亮!很好吃噢!', '水产,热菜,下饭菜,私家菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/6/9/yuan_368832d2493f27da8e6297bf278a85f9.jpg', '普通', '20分钟', '蛤蜊|690|克|主料|吐沙并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 备好食材,蛤蜊用清水泡,滴两滴香油让它吐渣渣,一两个小时后把蛤蜊洗净###2. 开火,放油,姜蒜,然后放小块火锅底料,稍加翻炒,让它融化,然后加蛤蜊,翻炒,滴点料酒,盖上锅盖让蛤蜊煮开开口,千万不要加水噢,继续翻炒至全开口为止###3. 出锅~加点小葱更漂亮!很好吃噢!', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(20679, '麻辣牛肉干', 'meat', '芝麻:35克#孜然:9克#牛肉:400克#白糖:55克#食用油:45毫升#食盐:7克#花椒:6克', '2名成年人总量+15%冗余', '1. 市场买的卤牛肉切条,(用卤牛肉不用加盐,不用煮),热锅加油,油热后关火。待油温稍冷点加入牛肉条翻炒###2. 稍微翻炒后起锅,锅里剩少许油,加入冰糖,慢慢炒,待冰糖溶化后加入各种香料翻炒。###3. 香料翻炒后,再次倒入牛肉。然后花椒面,辣椒面,孜然,白芝麻翻炒匀净,就ok啦~', '肉类,零食,热菜,麻辣,家常菜', 'https://cp1.douguo.net/upload/caiku/a/a/7/yuan_aaf6ce9c16da92d42476f9f9ec9bfa27.jpeg', '普通', '20分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 市场买的卤牛肉切条,(用卤牛肉不用加盐,不用煮),热锅加油,油热后关火。待油温稍冷点加入牛肉条翻炒###2. 稍微翻炒后起锅,锅里剩少许油,加入冰糖,慢慢炒,待冰糖溶化后加入各种香料翻炒。###3. 香料翻炒后,再次倒入牛肉。然后花椒面,辣椒面,孜然,白芝麻翻炒匀净,就ok啦~', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(20683, '香鲅鱼', 'meat', '五香粉:6克#鱼:690克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克#花椒:6克#香鲅:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鲅鱼切块儿,加姜片,料酒,生抽,五香粉腌制半小时###2. 下油锅,炸到表皮发紧,鱼肉发黄,捞出,沥油###3. 锅内留少许油,花椒葱末姜末炝锅###4. 把炸好的鱼再次下锅,倒生抽,料酒,放白糖,五香粉###5. 小火焖10分钟左右,大火收汤,装盘儿,撒香菜', '海鲜,水产,肉类,热菜,五香,下饭菜,下酒菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/recipe/2/e/a/yuan_2ef248c04979d6b3a7b283ec3dc32cca.jpg', '困难', '20分钟', '五香粉|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###香鲅|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鲅鱼切块儿,加姜片,料酒,生抽,五香粉腌制半小时###2. 下油锅,炸到表皮发紧,鱼肉发黄,捞出,沥油###3. 锅内留少许油,花椒葱末姜末炝锅###4. 把炸好的鱼再次下锅,倒生抽,料酒,放白糖,五香粉###5. 小火焖10分钟左右,大火收汤,装盘儿,撒香菜', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(20889, '蟹味菇', 'meat', '花生:170克#猪里脊:345克#蟹:690克#食用油:45毫升#食盐:7克#生抽:35毫升#葱:35克#味菇:345克', '2名成年人总量+15%冗余', '1. 蟹味菇洗净沥干###2. 花生油七成热爆香葱花###3. 加入里脊肉煸炒###4. 炒至里脊肉变白###5. 烹入酱油继续煸炒###6. 放入之前洗好的蟹味菇###7. 放入适量的盐,继续煸炒,此时蟹味菇会出汤,刚好用这个汤将蟹味菇炖5分钟左右,然后放适量的鸡精,起锅装盘即可', '禽类,水产,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/1/9/yuan_81f66665ff2a54f9ce05d7663942fcb9.jpg', '普通', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###蟹|690|克|主料|刷洗干净|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###味菇|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 蟹味菇洗净沥干###2. 花生油七成热爆香葱花###3. 加入里脊肉煸炒###4. 炒至里脊肉变白###5. 烹入酱油继续煸炒###6. 放入之前洗好的蟹味菇###7. 放入适量的盐,继续煸炒,此时蟹味菇会出汤,刚好用这个汤将蟹味菇炖5分钟左右,然后放适量的鸡精,起锅装盘即可', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(21034, '橄榄菜豆角肉末', 'meat', '猪肉:345克#豆角:460克#食用油:45毫升#食盐:7克#蒜:30克#橄榄菜:345克', '2名成年人总量+15%冗余', '1. 豆角洗干净切粒###2. 准备肉末,橄榄菜。###3. 下油、蒜蓉把肉末炒到变白色,下豆角继续翻炒,等豆角快熟了下橄榄菜翻炒均匀,下一点点盐,因为橄榄菜有咸味的所以不需要下太多盐。###4. 豆角全熟就可以出锅了,建议豆角不要炒得过熟,有点脆脆的比较好吃。', '川菜,肉类,热菜,咸,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/a/1/9/yuan_a10ca7e7ee32c3a86540d042f2159179.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###橄榄菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 豆角洗干净切粒###2. 准备肉末,橄榄菜。###3. 下油、蒜蓉把肉末炒到变白色,下豆角继续翻炒,等豆角快熟了下橄榄菜翻炒均匀,下一点点盐,因为橄榄菜有咸味的所以不需要下太多盐。###4. 豆角全熟就可以出锅了,建议豆角不要炒得过熟,有点脆脆的比较好吃。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(21114, '可乐鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#可乐:345克', '2名成年人总量+15%冗余', '1. 将鸡翅放到水中焯一下,捞出备用###2. 八角放入油锅中爆香,放入鸡翅两面煎炸至金黄色,###3. 倒入料酒、生抽、可乐适量,盖上锅盖开至中大火闷煮(可加入适量盐和鸡精,根据个人口味而定,我自己比较喜欢加盐和鸡精),###4. 等汤汁烧至浓稠,便可盛起食用啦。', '禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/5/8/yuan_9560bae9a63f6dccc50b4ae69125fcb8.jpeg', '困难', '60分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###可乐|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将鸡翅放到水中焯一下,捞出备用###2. 八角放入油锅中爆香,放入鸡翅两面煎炸至金黄色,###3. 倒入料酒、生抽、可乐适量,盖上锅盖开至中大火闷煮(可加入适量盐和鸡精,根据个人口味而定,我自己比较喜欢加盐和鸡精),###4. 等汤汁烧至浓稠,便可盛起食用啦。', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(21158, '牛肉干', 'meat', '孜然:9克#牛肉:400克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#花椒:6克', '2名成年人总量+15%冗余', '1. 将牛肉切大块,在锅中煮开,撇去血沫。###2. 煮5分钟后取出,顺着纹理切成长条。切成的牛肉条再在锅里煮5分钟。###3. 锅里放油,将花椒、香叶、桂皮爆香,然后加入牛肉、酱油、辣椒粉、孜然粉、白糖、盐,翻炒2分钟。###4. 将炒好的牛肉干放入烤箱,150度,25分钟。中间可来回翻两次。', '肉类,零食,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/a/b/7/yuan_abc0aa31dbcf785dbd1d53361ad40907.jpg', '普通', '25分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 将牛肉切大块,在锅中煮开,撇去血沫。###2. 煮5分钟后取出,顺着纹理切成长条。切成的牛肉条再在锅里煮5分钟。###3. 锅里放油,将花椒、香叶、桂皮爆香,然后加入牛肉、酱油、辣椒粉、孜然粉、白糖、盐,翻炒2分钟。###4. 将炒好的牛肉干放入烤箱,150度,25分钟。中间可来回翻两次。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(2131, '烤鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 买回的鸡翅泡在凉水中15分钟左右,把血泡出来###2. 姜和蒜在一起捣成泥(我弄的蒜多了,最后蒜香味比较浓),葱切丝。###3. 把泡鸡翅的水分挤干,用尖刀在两面扎眼儿,两面抹上盐,和葱姜蒜拌匀,倒入一小勺酱油,揉一揉每一个鸡翅,使入味。###4. 封口放到冰箱里24小时,中间可以翻动一下,再揉一揉。(这是腌了24小时以后的图片,貌似没有太大变化...)###5. 腌好的鸡翅直接摆到烤架上,20', '禽类,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/0/5/1/yuan_0527c2c3485de1617060aabf9b0adf61.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 买回的鸡翅泡在凉水中15分钟左右,把血泡出来###2. 姜和蒜在一起捣成泥(我弄的蒜多了,最后蒜香味比较浓),葱切丝。###3. 把泡鸡翅的水分挤干,用尖刀在两面扎眼儿,两面抹上盐,和葱姜蒜拌匀,倒入一小勺酱油,揉一揉每一个鸡翅,使入味。###4. 封口放到冰箱里24小时,中间可以翻动一下,再揉一揉。(这是腌了24小时以后的图片,貌似没有太大变化...)###5. 腌好的鸡翅直接摆到烤架上,20', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(21339, '苦瓜炒蛋', 'meat', '苦瓜:400克#鸡蛋:5个#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克', '2名成年人总量+15%冗余', '1. 苦瓜去籽切片备用。###2. 鸡蛋加水淀粉和盐搅打均匀。###3. 锅里放油,可稍多一点,倒入蛋液。###4. 迅速划散,凝固立即盛出。###5. 锅里留少量底油,放入苦瓜煸炒。###6. 变色加一点点盐,炒匀###7. 重新倒入炒好的蛋。###8. 调入生抽,拌匀立即出锅。###9. 成品。', '禽类,蛋类,热菜,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/4/e/5/yuan_4e517ca5edf65d1417085d981d4eded5.jpg', '普通', '20分钟', '苦瓜|400|克|主料|去瓤切片|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 苦瓜去籽切片备用。###2. 鸡蛋加水淀粉和盐搅打均匀。###3. 锅里放油,可稍多一点,倒入蛋液。###4. 迅速划散,凝固立即盛出。###5. 锅里留少量底油,放入苦瓜煸炒。###6. 变色加一点点盐,炒匀###7. 重新倒入炒好的蛋。###8. 调入生抽,拌匀立即出锅。###9. 成品。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(21389, '柠檬泡椒凤爪', 'meat', '柠檬:170克#鸡肉:520克#白糖:55克#食盐:7克#生抽:35毫升#姜:25克#葱:35克#泡椒:345克', '2名成年人总量+15%冗余', '1. 鸡爪洗净剪掉指甲,切开###2. 锅中放冷水放鸡爪八角酒葱姜,煮开后大概10分钟捞起来放入准备好的冰水中。###3. 柠檬切好后和泡椒一起放进糟卤中,倒入一点生抽和糖盐。###4. 最后将鸡爪倒入调好的糟卤中,浸泡一夜,哇撒......你懂的哈哈!', '川菜,禽类,热菜,泡椒,下酒菜,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/d/1/9/yuan_d1f701ae826bcd4443e58ce8d5bb25a9.jpeg', '简单', '15分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|菜名+步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###泡椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡爪洗净剪掉指甲,切开###2. 锅中放冷水放鸡爪八角酒葱姜,煮开后大概10分钟捞起来放入准备好的冰水中。###3. 柠檬切好后和泡椒一起放进糟卤中,倒入一点生抽和糖盐。###4. 最后将鸡爪倒入调好的糟卤中,浸泡一夜,哇撒......你懂的哈哈!', '[]', '来源步骤数: 4', '煮', 0, 0, NULL, NULL),
(21613, '烤羊排', 'meat', '羊肉:460克#土豆:460克#料酒:30毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 洗净 切出密密的缝隙 不断底###2. 加入各种调料###3. 卷起来 装入大碗中 倒入两勺料酒 用小刀到处戳洞 让它更好入味 然后腌制六小时以上 我放冰箱腌制24小时###4. 铺入锡纸 包住四周 进烤箱220度 一小时 中间可以半小时把包裹的锡纸敞开 有利于收汁###5. 香飘四溢###6. 上次 我还加入了土豆片 也不错', '肉类,热菜,午餐,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/5/3/f/yuan_530c2669c1cf48173e56d7c2891617df.jpg', '普通', '25分钟', '羊肉|460|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 洗净 切出密密的缝隙 不断底###2. 加入各种调料###3. 卷起来 装入大碗中 倒入两勺料酒 用小刀到处戳洞 让它更好入味 然后腌制六小时以上 我放冰箱腌制24小时###4. 铺入锡纸 包住四周 进烤箱220度 一小时 中间可以半小时把包裹的锡纸敞开 有利于收汁###5. 香飘四溢###6. 上次 我还加入了土豆片 也不错', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(21684, '爵仕快波炉之豆豉蒸腊肉', 'meat', '食用油:45毫升#食盐:7克#爵仕快波炉之豆豉:345克#腊肉:345克', '2名成年人总量+15%冗余', '1. 先来张全身照,外形时尚美观。###2. 第一次使用时用手机下载小智APP,长按微波炉重量键,屏幕出现FI:FI后,用小智找到并绑定微波炉,链接家里的WiFi就可以了。只要不拔电源,无论你身在何处,都可以用手机操控微波炉啦。###3. 腊肉提前冷水浸泡六小时去盐。###4. 锅里热开水,将浸泡过的腊肉放入,进行第一次焯水。取出,用刀刮掉腊肉表面上的油脂。再放入滚水,第二次焯水取出。', '肉类,热菜,午餐,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/f/9/8/yuan_f97f02c803343cc0b1799a1a29e99d68.jpg', '简单', '15分钟', '食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###爵仕快波炉之豆豉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###腊肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 先来张全身照,外形时尚美观。###2. 第一次使用时用手机下载小智APP,长按微波炉重量键,屏幕出现FI:FI后,用小智找到并绑定微波炉,链接家里的WiFi就可以了。只要不拔电源,无论你身在何处,都可以用手机操控微波炉啦。###3. 腊肉提前冷水浸泡六小时去盐。###4. 锅里热开水,将浸泡过的腊肉放入,进行第一次焯水。取出,用刀刮掉腊肉表面上的油脂。再放入滚水,第二次焯水取出。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(21802, '啤酒虾球', 'meat', '鱼:690克#虾:520克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#香醋:30毫升#姜:25克#蒜:30克#干辣椒:15克#花椒:6克', '2名成年人总量+15%冗余', '1. 小龙虾洗净,掐头去尾,抽虾线###2. 生姜切片备用,大蒜头剥皮###3. 锅内加入橄榄油,烧至4,5成热,倒入姜蒜,花椒,干辣椒煸炒出香味,倒入处理干净的虾球炒制。###4. 虾球炒红,倒入老抽,鱼露,红醋继续翻炒。###5. 加入啤酒。根据个人口味加入胡椒,白糖。闷烧至虾球完全吸收啤酒后加入食盐,鸡精调味。即可出锅。', '水产,禽类,热菜,朋友聚餐,单身食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/d/5/6/yuan_d57bad177bad625844a8d407d6e76276.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 小龙虾洗净,掐头去尾,抽虾线###2. 生姜切片备用,大蒜头剥皮###3. 锅内加入橄榄油,烧至4,5成热,倒入姜蒜,花椒,干辣椒煸炒出香味,倒入处理干净的虾球炒制。###4. 虾球炒红,倒入老抽,鱼露,红醋继续翻炒。###5. 加入啤酒。根据个人口味加入胡椒,白糖。闷烧至虾球完全吸收啤酒后加入食盐,鸡精调味。即可出锅。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(22040, '叉烧五花肉', 'meat', '五花肉:345克#猪肉:345克#食用油:45毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 这是我买回来猪肉的分量###2. 把猪肉切好,姜末蒜末撒到上面###3. 加2勺叉烧酱,搅拌均匀。腌2个小时,至少也要一个小时,不然不够入味的###4. 2小时之后就可以下锅煮了。油热锅,蒜末葱末下锅,把肉倒下去翻炒几下,倒水下去煮10分钟左右。等汁收得差不多就可以熄火了!喜欢葱的可以在上面撒点葱花', '粤菜,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/a/e/0/yuan_aeab1c79dfea46f158f2dd0f9af23a50.jpg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|菜名###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 这是我买回来猪肉的分量###2. 把猪肉切好,姜末蒜末撒到上面###3. 加2勺叉烧酱,搅拌均匀。腌2个小时,至少也要一个小时,不然不够入味的###4. 2小时之后就可以下锅煮了。油热锅,蒜末葱末下锅,把肉倒下去翻炒几下,倒水下去煮10分钟左右。等汁收得差不多就可以熄火了!喜欢葱的可以在上面撒点葱花', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(22053, '香烤孜然猪蹄', 'meat', '猪蹄:690克#孜然:9克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 猪蹄在凉水中煮开几分钟后捞出洗净###2. 猪蹄放锅中,放葱姜、料酒去腥###3. 放八角、桂皮###4. 放萬字纯酿造酱油和老抽###5. 放冰糖,再放足够的开水大火煮开后改小火###6. 等猪蹄酥烂时放盐,再煮10分钟###7. 取出吸干水分###8. 空气炸锅180度预热5分钟后,放入猪蹄烤10分钟###9. 刷蜂蜜和煮猪蹄的卤汁调成的汁水,再烤5分钟左右###10. 取出撒上孜然', '肉类,热菜,孜然,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/3/0/2/yuan_3040fa57077dd8980454ae7d80ed1442.jpg', '困难', '60分钟', '猪蹄|690|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 猪蹄在凉水中煮开几分钟后捞出洗净###2. 猪蹄放锅中,放葱姜、料酒去腥###3. 放八角、桂皮###4. 放萬字纯酿造酱油和老抽###5. 放冰糖,再放足够的开水大火煮开后改小火###6. 等猪蹄酥烂时放盐,再煮10分钟###7. 取出吸干水分###8. 空气炸锅180度预热5分钟后,放入猪蹄烤10分钟###9. 刷蜂蜜和煮猪蹄的卤汁调成的汁水,再烤5分钟左右###10. 取出撒上孜然', '[]', '来源步骤数: 10', '炸', 0, 0, NULL, NULL),
(2206, '鲜小炒', 'meat', '火腿:290克#豆腐:460克#香菇:230克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#鲜小:345克', '2名成年人总量+15%冗余', '1. 香菇斜片成片,火腿切片,海带切方片,冻豆腐凉水解冻切半厘米厚的长方片,准备好。###2. 热锅下凉油少许,油热后将香菇片和火腿煎一下取出###3. 加少许油,油刚热下葱姜蒜爆香锅,依次下海带、冻豆腐片、香菇火腿,加少许水,加一勺盐,依个人口味加醋和酱油,翻炒均匀,出锅', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/9/3/a/yuan_93fdbe82d5520899345c4ac8ecb7773a.jpg', '简单', '15分钟', '火腿|290|克|主料|切片|2名成年人总量+15%冗余|步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###鲜小|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 香菇斜片成片,火腿切片,海带切方片,冻豆腐凉水解冻切半厘米厚的长方片,准备好。###2. 热锅下凉油少许,油热后将香菇片和火腿煎一下取出###3. 加少许油,油刚热下葱姜蒜爆香锅,依次下海带、冻豆腐片、香菇火腿,加少许水,加一勺盐,依个人口味加醋和酱油,翻炒均匀,出锅', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(2207, '红烧牛肉', 'meat', '牛肉:400克#白糖:55克#食用油:45毫升#料酒:30毫升#豆瓣酱:30克#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 先把牛肉的血水洗净###2. 烧一锅开水放姜把牛肉淖过心,加少量料酒去味###3. 将淖好的牛肉放入砂锅备用,另起炒锅炒作料。放菜油适量,加牛油小火炒制,加入香料,豆瓣酱,白糖炒制###4. 将炒好的作料放入砂锅牛肉中加水炖煮###5. 炖至沸腾关小火慢炖三小时以上', '肉类,热菜,下饭菜,午餐,朋友聚餐,家常菜,懒人食谱,砂锅', 'https://cp1.douguo.net/upload/caiku/b/4/4/yuan_b43909c1c8312d4f681fe4c60c9f0b84.jpg', '简单', '15分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 先把牛肉的血水洗净###2. 烧一锅开水放姜把牛肉淖过心,加少量料酒去味###3. 将淖好的牛肉放入砂锅备用,另起炒锅炒作料。放菜油适量,加牛油小火炒制,加入香料,豆瓣酱,白糖炒制###4. 将炒好的作料放入砂锅牛肉中加水炖煮###5. 炖至沸腾关小火慢炖三小时以上', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(22073, '肉末蛋卷', 'meat', '猪肉:345克#鸡蛋:5个#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 准备好食材,我用的是夹心肉,让摊主给绞好的,鸡蛋选择的是土鸡蛋。###2. 肉馅中加盐,白胡椒粉,料酒,生粉,葱末与姜末。###3. 将肉馅顺着一个方向搅拌均匀。###4. 鸡蛋打散后加入少许盐和大约十克水搅打均匀,放小许水能前鸡蛋皮剪出来更嫩。###5. 不沾锅烧热,放入几滴油,然后转小火,把鸡蛋液放锅内摊成蛋皮,摊蛋皮的决窍是抓住锅柄让锅子晃动一圈,让蛋液分布均匀成一个圆形。', '肉类,蛋类,禽类,热菜,朋友聚餐,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/c/3/a/yuan_c3169089f781121e8de8b81c84471f3a.jpeg', '困难', '60分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 准备好食材,我用的是夹心肉,让摊主给绞好的,鸡蛋选择的是土鸡蛋。###2. 肉馅中加盐,白胡椒粉,料酒,生粉,葱末与姜末。###3. 将肉馅顺着一个方向搅拌均匀。###4. 鸡蛋打散后加入少许盐和大约十克水搅打均匀,放小许水能前鸡蛋皮剪出来更嫩。###5. 不沾锅烧热,放入几滴油,然后转小火,把鸡蛋液放锅内摊成蛋皮,摊蛋皮的决窍是抓住锅柄让锅子晃动一圈,让蛋液分布均匀成一个圆形。', '[]', '来源步骤数: 5', '煎', 0, 0, NULL, NULL),
(2208, '泡椒炒牛箭', 'meat', '牛肉:400克#白糖:55克#食用油:45毫升#食盐:7克#淀粉:30克#姜:25克#泡椒:345克#牛箭:345克', '2名成年人总量+15%冗余', '1. 备好料。(姜片,泡椒,牛肉)###2. 把牛肉用(盐,胡椒粉,味精,糖,生粉,搅拌匀,在放少量生粉,味道重轻按个人口味)。腌好牛肉在放到锅里用油炸一下,油温高点炸10~20秒,捞起来。###3. 把姜片跟泡椒用油爆炒在放炸好的牛肉,炒炒,放点生粉水,即可。', '川菜,肉类,热菜,泡椒,下饭菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/7/7/yuan_17ad395970a6a27a70e1245c81620687.jpg', '简单', '15分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###泡椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###牛箭|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 备好料。(姜片,泡椒,牛肉)###2. 把牛肉用(盐,胡椒粉,味精,糖,生粉,搅拌匀,在放少量生粉,味道重轻按个人口味)。腌好牛肉在放到锅里用油炸一下,油温高点炸10~20秒,捞起来。###3. 把姜片跟泡椒用油爆炒在放炸好的牛肉,炒炒,放点生粉水,即可。', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(22099, '剁椒鱼头', 'meat', '鱼:690克#食用油:45毫升#食盐:7克#姜:25克#蒜:30克#葱:35克#剁椒:345克', '2名成年人总量+15%冗余', '1. 鱼头清洗干净用盐涂抹表面腌制十分钟左右###2. 将胡椒粉.鸡精抹均匀全头###3. 油烧热将剁椒放入煽炒片刻###4. 将剁椒均匀铺在鱼头上###5. 蒸锅水开放入鱼头加豉香鱼油蒸10分钟,开汽蒸8分钟关火焖2分钟###6. 端出鱼头后将香葱碎、蒜蓉、姜末撒在表面###7. 炒锅油烧热均匀浇于调料上面烫熟###8. 剁椒鱼头完成', '湘菜,海鲜,水产,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/d/c/yuan_cda1b33ff1a20b1d3b790a9b20d0bfcc.jpg', '困难', '60分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###剁椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鱼头清洗干净用盐涂抹表面腌制十分钟左右###2. 将胡椒粉.鸡精抹均匀全头###3. 油烧热将剁椒放入煽炒片刻###4. 将剁椒均匀铺在鱼头上###5. 蒸锅水开放入鱼头加豉香鱼油蒸10分钟,开汽蒸8分钟关火焖2分钟###6. 端出鱼头后将香葱碎、蒜蓉、姜末撒在表面###7. 炒锅油烧热均匀浇于调料上面烫熟###8. 剁椒鱼头完成', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(22144, '麻辣小龙虾', 'meat', '虾:520克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#豆瓣酱:30克#姜:25克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 先啰嗦一下,之前试了很多方子,觉得味道都差一点,直到加了红99,味道一下就对了。###2. 把小龙虾用刷子洗干净备用、红辣椒切段###3. 将油烧热,姜片、葱段、花椒、八角、香叶、红###4. 豆瓣酱等全部下锅炒出香味。###5. 倒入小龙虾,翻炒3分钟,加啤酒。###6. 转中火炖20分钟后,加入糖、鸡精、生抽、青椒圈,味道如果觉得淡加少许盐,再翻炒至收汁即可出锅', '海鲜,禽类,水产,热菜,麻辣,下酒菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/8/0/yuan_c8d45bb29ca1cadd7a62146a765aee10.jpg', '困难', '60分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 先啰嗦一下,之前试了很多方子,觉得味道都差一点,直到加了红99,味道一下就对了。###2. 把小龙虾用刷子洗干净备用、红辣椒切段###3. 将油烧热,姜片、葱段、花椒、八角、香叶、红###4. 豆瓣酱等全部下锅炒出香味。###5. 倒入小龙虾,翻炒3分钟,加啤酒。###6. 转中火炖20分钟后,加入糖、鸡精、生抽、青椒圈,味道如果觉得淡加少许盐,再翻炒至收汁即可出锅', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(22248, '蟹煲鸡', 'meat', '鸡翅:575克#蟹:690克#腐竹:230克#食用油:45毫升#生抽:35毫升#料酒:30毫升#淀粉:30克#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 新鮮 雞翅中 雞腿 洗淨,翅中菜刀劃口,雞腿 剁碎,用生抽 料酒 醃漬30分鐘備用。###2. 準備食材,老薑 大蒜 切片,腐竹 溫水泡軟,備用。###3. 花蟹清除蟹腮並洗淨,剁成小塊,沾上生粉,鍋內入油小火油炸至蟹殼呈紅色,撈起備用 (順序見圖) 。###4. 用炸花蟹的餘油,放入 老薑 蒜片 煸香,加入 步驟1 翻炒至雞肉呈金黃色後,連同餘油一同倒入砂鍋內 (順序見圖) 。', '海鲜,禽类,水产,肉类,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/5/8/yuan_b5a6868ed8a6bf5cdc0440e2e46eae48.jpg', '困难', '60分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###蟹|690|克|主料|刷洗干净|2名成年人总量+15%冗余|菜名+步骤###腐竹|230|克|主料|提前泡发或切丝|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 新鮮 雞翅中 雞腿 洗淨,翅中菜刀劃口,雞腿 剁碎,用生抽 料酒 醃漬30分鐘備用。###2. 準備食材,老薑 大蒜 切片,腐竹 溫水泡軟,備用。###3. 花蟹清除蟹腮並洗淨,剁成小塊,沾上生粉,鍋內入油小火油炸至蟹殼呈紅色,撈起備用 (順序見圖) 。###4. 用炸花蟹的餘油,放入 老薑 蒜片 煸香,加入 步驟1 翻炒至雞肉呈金黃色後,連同餘油一同倒入砂鍋內 (順序見圖) 。', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(2229, '孜然金丝鱼哟', 'meat', '芝麻:35克#孜然:9克#鱼:690克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 菜市场转卖冰鲜的地方就有得卖哟~而且本身已经腌制好了,是甜咸味道的,拿回家,冲洗之后,浸泡20分钟,然后沥干备用###2. 热油,小火,炸到金黄就可以了。鱼要沥干,否则~会砰油出来哟###3. 炸好之后,撒上孜然,和白芝麻~喷香的金丝鱼就完成了。有大排档烧烤的风味哟~是不是超简单哩', '海鲜,水产,热菜,孜然,朋友聚餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/b/1/c/yuan_b17603e5ea6ba0a2ff32e01d49c0c96c.jpg', '简单', '15分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 菜市场转卖冰鲜的地方就有得卖哟~而且本身已经腌制好了,是甜咸味道的,拿回家,冲洗之后,浸泡20分钟,然后沥干备用###2. 热油,小火,炸到金黄就可以了。鱼要沥干,否则~会砰油出来哟###3. 炸好之后,撒上孜然,和白芝麻~喷香的金丝鱼就完成了。有大排档烧烤的风味哟~是不是超简单哩', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(22315, '蒜香宫爆虾丁', 'meat', '虾:520克#土豆:460克#西红柿:460克#黄瓜:400克#萝卜:460克#面粉:400克#白糖:55克#食用油:45毫升#食盐:7克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 黄瓜、胡萝卜,土豆切两厘米小方块,鲜虾去虾线剥壳,小香葱切段,姜蒜切片。###2. 剥好的虾仁,撒上一点干面粉搅拌均匀。###3. 放入油,少许,撒上几颗麻椒,放入虾丁炸一下,捞出;放入黄瓜胡萝卜土豆丁,翻炒片刻,加入姜蒜,翻炒几下,放入葱段倒入虾丁,随后加入蚝油、番茄酱翻炒。###4. 根据菜量放入盐、白糖、鸡精,装盘即可。###5. 小提示:如果油放多了,可以面粉加水沟个芡汁,增加黏稠度的同时使菜品更加入味。', '川菜,水产,禽类,凉菜,热菜,蒜香,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/a/a/1/yuan_aad32f4b7a1e1d71ae6dd254007404d1.jpeg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###黄瓜|400|克|主料|洗净切片或拍碎|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 黄瓜、胡萝卜,土豆切两厘米小方块,鲜虾去虾线剥壳,小香葱切段,姜蒜切片。###2. 剥好的虾仁,撒上一点干面粉搅拌均匀。###3. 放入油,少许,撒上几颗麻椒,放入虾丁炸一下,捞出;放入黄瓜胡萝卜土豆丁,翻炒片刻,加入姜蒜,翻炒几下,放入葱段倒入虾丁,随后加入蚝油、番茄酱翻炒。###4. 根据菜量放入盐、白糖、鸡精,装盘即可。###5. 小提示:如果油放多了,可以面粉加水沟个芡汁,增加黏稠度的同时使菜品更加入味。', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(22377, '不用一滴油的蒜香排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 先准备好排骨,姜蒜切碎沫,葱切碎备用。###2. 把排骨放入锅里,加水刚好盖过排骨,用中小火煮。###3. 当水煮干汁,排骨本身的油会跑出来,用小火煎到两面焦黄。###4. 当排骨煎到焦黄时,加调料酱油,鸡粉,白糖,料酒翻炒一分钟,出锅时撒上葱花就可以了。', '肉类,禽类,热菜,蒜香,家常菜', 'https://cp1.douguo.net/upload/caiku/c/e/5/yuan_ce6a3b76a33847b07e4d0793c6c17075.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 先准备好排骨,姜蒜切碎沫,葱切碎备用。###2. 把排骨放入锅里,加水刚好盖过排骨,用中小火煮。###3. 当水煮干汁,排骨本身的油会跑出来,用小火煎到两面焦黄。###4. 当排骨煎到焦黄时,加调料酱油,鸡粉,白糖,料酒翻炒一分钟,出锅时撒上葱花就可以了。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(22464, '糖醋鸡蛋', 'meat', '鸡蛋:5个#白糖:55克#食用油:45毫升#香醋:30毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 将锅烧热注入少量油直至油被烧的略微热 快去打开鸡蛋 一面煎熟###2. 将糖和醋以个人喜好调好###3. 倒入煎好的鸡蛋上切记 要离鸡蛋近点倒否则容易迸溅###4. 糖醋可以杀菌 所以锅的味道可以熏一下屋子 慎用###5. 完成', '蛋类,禽类,热菜,酸甜,家常菜', 'https://cp1.douguo.net/upload/caiku/e/e/6/yuan_ee1df9463119f9417146c3bc43ca2906.jpeg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将锅烧热注入少量油直至油被烧的略微热 快去打开鸡蛋 一面煎熟###2. 将糖和醋以个人喜好调好###3. 倒入煎好的鸡蛋上切记 要离鸡蛋近点倒否则容易迸溅###4. 糖醋可以杀菌 所以锅的味道可以熏一下屋子 慎用###5. 完成', '[]', '来源步骤数: 5', '煎', 0, 0, NULL, NULL),
(22487, '荷叶糯米蒸鸡', 'meat', '鸡肉:520克#香菇:230克#糯米:345克#食盐:7克#老抽:15毫升#姜:25克#荷叶:345克', '2名成年人总量+15%冗余', '1. 1、腌鸡肉。鸡肉入盆,入老抽、姜、盐,腌制1~2小时。腌制的时候把蘑菇切成片。###2. 2、蒸鸡肉。蒸锅加水放盘,盘子上放两片荷叶。叶子上放鸡肉,混入糯米、蘑菇,包好第一层后倒置,再包一层。大火转中火蒸30分钟,转小火10分钟。###3. 出锅装盘。就是这么简单美味。开吃吧~', '禽类,肉类,热菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/d/e/7/yuan_de165ddf03a613906a2380c3c29963a7.jpg', '普通', '25分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###糯米|345|克|主料|提前浸泡|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###荷叶|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 1、腌鸡肉。鸡肉入盆,入老抽、姜、盐,腌制1~2小时。腌制的时候把蘑菇切成片。###2. 2、蒸鸡肉。蒸锅加水放盘,盘子上放两片荷叶。叶子上放鸡肉,混入糯米、蘑菇,包好第一层后倒置,再包一层。大火转中火蒸30分钟,转小火10分钟。###3. 出锅装盘。就是这么简单美味。开吃吧~', '[]', '来源步骤数: 3', '蒸', 0, 0, NULL, NULL),
(22554, '酸豆角炒肉末', 'meat', '猪肉:345克#豆角:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#蒜:30克', '2名成年人总量+15%冗余', '1. 这是自己淹的酸豆角###2. 先将酸豆角切成丁###3. 再把肉剁成末###4. 锅烧热加点油,放两块蒜头。(喜欢辣的朋友可以加点辣椒,因为家人都不吃辣所以没加,个人是觉的加点辣椒味道更好)###5. 下肉末翻炒###6. 待肉炒变色后下豆角翻炒,炒差不多了加点生抽,一点点就好,加点糖,切记不要加盐,因为豆角本身是咸的。###7. 差不多了加点鸡精,起锅###8. 成品图', '禽类,肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/b/f/yuan_db180388ec372feeaac0e22bd82f361f.jpg', '普通', '25分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 这是自己淹的酸豆角###2. 先将酸豆角切成丁###3. 再把肉剁成末###4. 锅烧热加点油,放两块蒜头。(喜欢辣的朋友可以加点辣椒,因为家人都不吃辣所以没加,个人是觉的加点辣椒味道更好)###5. 下肉末翻炒###6. 待肉炒变色后下豆角翻炒,炒差不多了加点生抽,一点点就好,加点糖,切记不要加盐,因为豆角本身是咸的。###7. 差不多了加点鸡精,起锅###8. 成品图', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(22562, '快手彩椒山药炒肉片', 'meat', '香肠:290克#猪肉:345克#红椒:170克#山药:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#淀粉:30克#快手:345克', '2名成年人总量+15%冗余', '1. 山药去皮切片泡在白醋水里备用(炒之前沥水后再冲一下水,去掉酸味),彩椒切小块,家里有肉片可以加生抽、料酒和水淀粉先浆一下,我没有就用了自己灌的香肠蒸熟切片代替了。###2. 热锅内加入少许植物油,加入彩椒先煸一下,然后加入肉片(香肠)和生抽(菁选酱油)翻炒一下。###3. 加入山药片,翻炒一下,加入少许盐,再翻炒几下后就可以出锅了。', '肉类,热菜,晚餐,下饭菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/4/7/1/yuan_47636bfb296ea42325d1a2967181b951.jpg', '普通', '20分钟', '香肠|290|克|主料|切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###山药|460|克|主料|去皮切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###快手|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 山药去皮切片泡在白醋水里备用(炒之前沥水后再冲一下水,去掉酸味),彩椒切小块,家里有肉片可以加生抽、料酒和水淀粉先浆一下,我没有就用了自己灌的香肠蒸熟切片代替了。###2. 热锅内加入少许植物油,加入彩椒先煸一下,然后加入肉片(香肠)和生抽(菁选酱油)翻炒一下。###3. 加入山药片,翻炒一下,加入少许盐,再翻炒几下后就可以出锅了。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(22610, '香菇酿肉', 'meat', '玉米:460克#香菇:230克#食用油:45毫升#生抽:35毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 新鲜香菇洗净,去蒂,背后开花(我也就是胡乱切了几刀)###2. 肉糜拌上玉米粒,香菇蒂,用香油生抽入味搅拌###3. 将肉糜双手交替摔打成和香菇大小差不多的圆形饼状###4. 在烤盘锡纸和香菇顶部都抹上薄薄一层油,入烤箱200°C,20分钟即可###5. 拿出烤箱装盘,其实再浇上点酱汁或用青菜围边样子更好', '肉类,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/d/5/6/yuan_d5321a88c2fb56c49b43d28b73e47516.jpg', '普通', '25分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 新鲜香菇洗净,去蒂,背后开花(我也就是胡乱切了几刀)###2. 肉糜拌上玉米粒,香菇蒂,用香油生抽入味搅拌###3. 将肉糜双手交替摔打成和香菇大小差不多的圆形饼状###4. 在烤盘锡纸和香菇顶部都抹上薄薄一层油,入烤箱200°C,20分钟即可###5. 拿出烤箱装盘,其实再浇上点酱汁或用青菜围边样子更好', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(22809, '酸辣猪皮', 'meat', '青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#蒜:30克#猪皮:345克', '2名成年人总量+15%冗余', '1. 猪皮洗干净切条,热锅热油放入煎炒出油,然后放入料酒去腥,把料酒炒干后再煎炒出油。###2. 然后放入泡椒辣椒粉大蒜和酸菜,如果有青椒什么的就更好了,接着炒出香味后加水盖锅盖煮五六分钟。###3. 起锅前放入酱油鸡精就ok了。(泡椒和酸菜有盐份所以不要再加盐了。)', '禽类,肉类,热菜,酸辣,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/c/9/0/yuan_c9269f541eadb0ba37a52e94a1b6bbc0.jpg', '普通', '20分钟', '青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###猪皮|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 猪皮洗干净切条,热锅热油放入煎炒出油,然后放入料酒去腥,把料酒炒干后再煎炒出油。###2. 然后放入泡椒辣椒粉大蒜和酸菜,如果有青椒什么的就更好了,接着炒出香味后加水盖锅盖煮五六分钟。###3. 起锅前放入酱油鸡精就ok了。(泡椒和酸菜有盐份所以不要再加盐了。)', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(23122, '蚝油翅中', 'meat', '鸡翅:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升', '2名成年人总量+15%冗余', '1. 用刀在翅中表皮划口子加入生抽、盐、白酒拌均匀腌制十五分钟入味###2. 热油炸制三遍至焦黄色###3. 锅起底油加入白糖熬溶化 、保持小火防糖色熬老###4. 翅中放入后煸炒均匀后加入 蚝油###5. 加入清水大火开锅转小火煨十五分钟左右###6. 汤汁接近收干转大火煸炒###7. 盛盘中撒上米椒碎', '禽类,水产,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/9/8/yuan_1947a5a7869690edf89679d8557d4658.jpg', '困难', '60分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤', '1. 用刀在翅中表皮划口子加入生抽、盐、白酒拌均匀腌制十五分钟入味###2. 热油炸制三遍至焦黄色###3. 锅起底油加入白糖熬溶化 、保持小火防糖色熬老###4. 翅中放入后煸炒均匀后加入 蚝油###5. 加入清水大火开锅转小火煨十五分钟左右###6. 汤汁接近收干转大火煸炒###7. 盛盘中撒上米椒碎', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(23169, '炖梭鱼', 'meat', '黑胡椒:6克#鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#姜:25克#蒜:30克#花椒:6克', '2名成年人总量+15%冗余', '1. 鲜梭鱼洗干净去头,切三段,身上切口,抹盐,盐10分钟以上。###2. 油热,下擦干水分的鱼段,大火两面煎黄。###3. 倒出锅内的油,下蒜瓣、姜、大料、醋酱油###4. 之后放糖、红干椒、水。之后是花椒面、黑胡椒面、味精。大火烧开,小火炖15分钟。###5. 看看,绝对不输任何一家大厨做的炖鱼!味美的程度就是:好吃到哭!', '东北菜,海鲜,水产,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/f/c/yuan_2f98a27757edc4ee99b9ee26d7be04ac.jpg', '普通', '25分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 鲜梭鱼洗干净去头,切三段,身上切口,抹盐,盐10分钟以上。###2. 油热,下擦干水分的鱼段,大火两面煎黄。###3. 倒出锅内的油,下蒜瓣、姜、大料、醋酱油###4. 之后放糖、红干椒、水。之后是花椒面、黑胡椒面、味精。大火烧开,小火炖15分钟。###5. 看看,绝对不输任何一家大厨做的炖鱼!味美的程度就是:好吃到哭!', '[]', '来源步骤数: 5', '煎', 0, 0, NULL, NULL),
(2321, '鸡翅煲', 'meat', '洋葱:290克#鸡翅:575克#土豆:460克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 鸡翅凉水泡净,冲去血水...然后放入洋葱,生抽,耗油,胡椒粉,料酒,适量的食盐,腌制一小时...###2. 萝卜,土豆切段备用...洋葱另准备两个切开...###3. 再来两颗洋葱,这个熟了之后味道非常好...###4. 秘制汤料,生抽一勺,老抽两勺,耗油两勺,白糖一勺,盐适量...###5. 放入底油,加入生姜,蒜片,飘香后放入鸡翅煎炸...###6. 腌制的鸡翅,洋葱同时入锅,翻动鸡翅至两面金黄...###7. 然后放', '禽类,热菜,下饭菜,下酒菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/2/e/yuan_e223e5df1fa5b1ddea0a0caf4c98989e.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鸡翅凉水泡净,冲去血水...然后放入洋葱,生抽,耗油,胡椒粉,料酒,适量的食盐,腌制一小时...###2. 萝卜,土豆切段备用...洋葱另准备两个切开...###3. 再来两颗洋葱,这个熟了之后味道非常好...###4. 秘制汤料,生抽一勺,老抽两勺,耗油两勺,白糖一勺,盐适量...###5. 放入底油,加入生姜,蒜片,飘香后放入鸡翅煎炸...###6. 腌制的鸡翅,洋葱同时入锅,翻动鸡翅至两面金黄...###7. 然后放', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(23350, '丝炒五花肉', 'meat', '洋葱:290克#五花肉:345克#猪肉:345克#青椒:205克#萝卜:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#葱:35克', '2名成年人总量+15%冗余', '1. 主料;###2. 洋葱切丝; 胡萝卜去皮切丝;###3. 青椒切丝; 五花肉切薄片;###4. 把锅稍加热,放入肉片煸炒出油,然后捞出沥油;###5. 锅中留底油,炒香洋葱丝;###6. 加入青椒丝和胡萝卜丝炒几下;###7. 倒入肉片煸炒,调入料酒、酱油、盐和鸡精炒匀即可。', '禽类,肉类,热菜,下饭菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/5/b/yuan_25f2a3b86bb4d70f614bb82f4df60eab.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 主料;###2. 洋葱切丝; 胡萝卜去皮切丝;###3. 青椒切丝; 五花肉切薄片;###4. 把锅稍加热,放入肉片煸炒出油,然后捞出沥油;###5. 锅中留底油,炒香洋葱丝;###6. 加入青椒丝和胡萝卜丝炒几下;###7. 倒入肉片煸炒,调入料酒、酱油、盐和鸡精炒匀即可。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(23414, '糖醋排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 小排洗净###2. 锅中坐水,水开后,排骨下锅,一开之后捞出###3. 调汁,调汁比例为,料酒,酱油,糖,醋水1:2:3:4:5,可用个勺子量取,具体比例1是几勺根据排骨的数量。我的是两勺料酒,四勺酱油,六勺糖。。。。。###4. 锅中放油,葱姜片,之后放入排骨煸炒###5. 倒入调好的汁儿!加入适量的盐!如果汁儿不够可加入热水!###6. 小火炖至汁儿粘稠,翻炒片刻,出锅', '肉类,热菜,酸甜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/8/7/yuan_98115b682c72b904eda4103840b758c7.jpg', '困难', '60分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 小排洗净###2. 锅中坐水,水开后,排骨下锅,一开之后捞出###3. 调汁,调汁比例为,料酒,酱油,糖,醋水1:2:3:4:5,可用个勺子量取,具体比例1是几勺根据排骨的数量。我的是两勺料酒,四勺酱油,六勺糖。。。。。###4. 锅中放油,葱姜片,之后放入排骨煸炒###5. 倒入调好的汁儿!加入适量的盐!如果汁儿不够可加入热水!###6. 小火炖至汁儿粘稠,翻炒片刻,出锅', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(23514, '水煮肉', 'meat', '猪里脊:345克#白菜:575克#食用油:45毫升#生抽:35毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 娃娃菜洗净以后开水汆烫,葱姜蒜切末###2. 捞出沥干后均匀铺到一个较深的盘子里###3. 里脊肉切成肉片###4. 加入两勺淀粉充分混匀挂浆###5. 水开后下入肉片,水再次开的时候捞出###6. 沥干后均匀码在娃娃菜上###7. 在肉上放适量辣椒粉、花椒粉、葱姜蒜末,浇适量生抽###8. 比平时炒菜多一点油,烧到快冒烟###9. 热油泼到葱姜蒜末上,迅速盖上锅盖闷一闷,然后完工', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/b/5/yuan_5b61072f670f553de86f639541345665.jpg', '困难', '20分钟', '猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###白菜|575|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 娃娃菜洗净以后开水汆烫,葱姜蒜切末###2. 捞出沥干后均匀铺到一个较深的盘子里###3. 里脊肉切成肉片###4. 加入两勺淀粉充分混匀挂浆###5. 水开后下入肉片,水再次开的时候捞出###6. 沥干后均匀码在娃娃菜上###7. 在肉上放适量辣椒粉、花椒粉、葱姜蒜末,浇适量生抽###8. 比平时炒菜多一点油,烧到快冒烟###9. 热油泼到葱姜蒜末上,迅速盖上锅盖闷一闷,然后完工', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(23564, '胡椒蒸鱼腩', 'meat', '黑胡椒:6克#鱼:690克#食用油:45毫升#食盐:7克#姜:25克#葱:35克#胡椒:345克', '2名成年人总量+15%冗余', '1. 将鱼腩洗净抹盐腌制10分钟后过水冲洗滤干摆入盘内,放入姜片待蒸###2. 在鱼儿上平均撒入胡椒粉###3. 锅内上气后放入鱼儿中火蒸7-8即可###4. 时间到取出倒掉汁水###5. 淋入雀巢美极鲜味汁与葱花###6. 热锅热油内加入研磨黑胡椒碎炒香,然后滚油淋入鱼腩中即可开吃###7. 成品图###8. 成品图###9. 近照###10. 非常鲜嫩野味', '水产,热菜,鲜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/c/f/yuan_fc5be0617b5be83408bd932c8638fc8f.jpeg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###胡椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将鱼腩洗净抹盐腌制10分钟后过水冲洗滤干摆入盘内,放入姜片待蒸###2. 在鱼儿上平均撒入胡椒粉###3. 锅内上气后放入鱼儿中火蒸7-8即可###4. 时间到取出倒掉汁水###5. 淋入雀巢美极鲜味汁与葱花###6. 热锅热油内加入研磨黑胡椒碎炒香,然后滚油淋入鱼腩中即可开吃###7. 成品图###8. 成品图###9. 近照###10. 非常鲜嫩野味', '[]', '来源步骤数: 10', '炒', 0, 0, NULL, NULL),
(23639, '香炸鸡翅', 'meat', '五香粉:6克#鸡翅:575克#鸡蛋:5个#食用油:45毫升#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 说说做炖肉骨头类菜遇到的问题(写的太多,怎么显示不出来啊)就是温热汆水、温热清洗的过程。看看这么多油和末子,是不是都应该汆水了呢。鸡翅洗净,凉水下锅,温火汆烫5分钟。之后温水洗净。控干。接着是入味的煨制。###2. 用五香粉、酱油、葱段、姜片、料酒,喂上二十分钟以上。###3. 之后,淀粉、鸡蛋,抓一起###4. 之后是锅放油,油热,下鸡翅中,中火炸制,观察上色情况,改变火的大小。', '禽类,蛋类,肉类,热菜,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/2/0/d/yuan_20f588274b2186a220403fb11435b81d.jpg', '普通', '25分钟', '五香粉|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 说说做炖肉骨头类菜遇到的问题(写的太多,怎么显示不出来啊)就是温热汆水、温热清洗的过程。看看这么多油和末子,是不是都应该汆水了呢。鸡翅洗净,凉水下锅,温火汆烫5分钟。之后温水洗净。控干。接着是入味的煨制。###2. 用五香粉、酱油、葱段、姜片、料酒,喂上二十分钟以上。###3. 之后,淀粉、鸡蛋,抓一起###4. 之后是锅放油,油热,下鸡翅中,中火炸制,观察上色情况,改变火的大小。', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(23720, '蒜香烤鸡翅', 'meat', '孜然:9克#鸡翅:575克#西红柿:460克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 鸡翅洗净,放入葱姜蒜###2. 半勺盐,口重的还可以多一点###3. 耗油一勺###4. 生抽,老抽,番茄酱各一勺###5. 蜂蜜来2勺###6. 胡椒粉来一点###7. 孜然粉来一点,(不喜欢可不放)###8. 烤盘放上锡纸刷上油,放入鸡翅,开烤啦!上下火180度30分钟,中途拿出翻面刷上蜂蜜###9. 出锅啦,撒上孜然粉,吃辣椒就来点辣椒粉,ok', '禽类,热菜,蒜香,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/b/2/yuan_8baaa2d36d639686f16866111acfc232.jpg', '普通', '20分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鸡翅洗净,放入葱姜蒜###2. 半勺盐,口重的还可以多一点###3. 耗油一勺###4. 生抽,老抽,番茄酱各一勺###5. 蜂蜜来2勺###6. 胡椒粉来一点###7. 孜然粉来一点,(不喜欢可不放)###8. 烤盘放上锡纸刷上油,放入鸡翅,开烤啦!上下火180度30分钟,中途拿出翻面刷上蜂蜜###9. 出锅啦,撒上孜然粉,吃辣椒就来点辣椒粉,ok', '[]', '来源步骤数: 9', '烤', 0, 0, NULL, NULL),
(23749, '糖醋排骨', 'meat', '孜然:9克#排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#淀粉:30克#蒜:30克', '2名成年人总量+15%冗余', '1. 排骨用盐巴,味精,孜然粉腌好待用###2. 排骨裹好淀粉下油锅炸,这时候可以开始做调料,把糖醋蒜末少量味精和酱油调在一起###3. 调好的酱汁,味道根据自己喜欢是多醋还是多糖###4. 将炸好的排骨倒入酱汁内就完成了', '肉类,热菜,酸甜,晚餐,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/6/a/8/yuan_6a13f6e7f6e3a37019a38c06d987e878.jpg', '普通', '20分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 排骨用盐巴,味精,孜然粉腌好待用###2. 排骨裹好淀粉下油锅炸,这时候可以开始做调料,把糖醋蒜末少量味精和酱油调在一起###3. 调好的酱汁,味道根据自己喜欢是多醋还是多糖###4. 将炸好的排骨倒入酱汁内就完成了', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(23821, '盐焗鸡爪', 'meat', '鸡肉:520克#食盐:7克#生抽:35毫升#姜:25克', '2名成年人总量+15%冗余', '1. 鸡爪洗干净,剪去指甲。将姜切片,辣椒切段。###2. 鸡爪,辣椒,姜片放入锅中,加水煮开后转中火煮一分钟后捞起。###3. 撒入盐焗粉,少量生抽(调色),盐抹匀。###4. 抹匀后冷藏四小时。###5. 四小时后取出。将烤制的容器底部撒盐,铺上鸡爪后再撒一层盐。###6. 200度预热烤十分钟即可。(我烤了20分钟,太软了)', '粤菜,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/d/c/yuan_5d185ce0ebbd9a1de9ef6490e35f804c.jpg', '普通', '25分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 鸡爪洗干净,剪去指甲。将姜切片,辣椒切段。###2. 鸡爪,辣椒,姜片放入锅中,加水煮开后转中火煮一分钟后捞起。###3. 撒入盐焗粉,少量生抽(调色),盐抹匀。###4. 抹匀后冷藏四小时。###5. 四小时后取出。将烤制的容器底部撒盐,铺上鸡爪后再撒一层盐。###6. 200度预热烤十分钟即可。(我烤了20分钟,太软了)', '[]', '来源步骤数: 6', '煮', 0, 0, NULL, NULL),
(23934, '肉酿尖椒', 'meat', '猪肉:345克#青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#姜:25克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 肉末加油、酱油、淀粉、盐、葱姜末拌匀。腌15分钟以上。###2. 尖椒洗净,去芯,切断,充分晾干。###3. 将肉塞进尖椒段内,不用太紧,两头的肉稍微捏紧一点。保证肉质嫩,两头不散出来。###4. 锅内煸香花椒油,将尖椒段放入,小火慢煸。需要耐心、小火。###5. 待尖椒起褶子并且蔫软后,下入少量豆豉,酱油、料酒。加小半碗水,盖锅闷熟。耗汤后出锅。', '肉类,热菜,朋友聚餐,创意菜,家常菜', 'https://cp1.douguo.net/upload/caiku/e/2/5/yuan_e2023424a33afb93dc26b66377ecea35.jpg', '困难', '45分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 肉末加油、酱油、淀粉、盐、葱姜末拌匀。腌15分钟以上。###2. 尖椒洗净,去芯,切断,充分晾干。###3. 将肉塞进尖椒段内,不用太紧,两头的肉稍微捏紧一点。保证肉质嫩,两头不散出来。###4. 锅内煸香花椒油,将尖椒段放入,小火慢煸。需要耐心、小火。###5. 待尖椒起褶子并且蔫软后,下入少量豆豉,酱油、料酒。加小半碗水,盖锅闷熟。耗汤后出锅。', '[]', '来源步骤数: 5', '酱制', 0, 0, NULL, NULL),
(24044, '日式烤秋刀鱼', 'meat', '柠檬:170克#鱼:690克#食用油:45毫升#食盐:7克#日式:345克#秋刀:345克', '2名成年人总量+15%冗余', '1. 鱼洗净后用厨房纸巾吸干表面水份。###2. 用刀在鱼身上划几刀。划不是轻轻的,是重重的哦,背上的切刀要深入骨,腹上不要切到。###3. 在鱼身上均匀地撒上细盐,感觉用手更好操作一点哦。###4. 把茴香塞一支到鱼肚子里,鱼身下和身上也铺一点。然后用刷子刷上一点清油。###5. 鱼入预热好的烤箱,开始烤吧,200度15分钟后,取出翻个身,继续烤完。###6. 烤好后摆盘挤上柠檬汁就行了。', '海鲜,水产,热菜,二人世界,下酒菜,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/1/2/6/yuan_12b7149efc1bc2bd72ad287a866038c6.jpg', '普通', '20分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###日式|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###秋刀|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鱼洗净后用厨房纸巾吸干表面水份。###2. 用刀在鱼身上划几刀。划不是轻轻的,是重重的哦,背上的切刀要深入骨,腹上不要切到。###3. 在鱼身上均匀地撒上细盐,感觉用手更好操作一点哦。###4. 把茴香塞一支到鱼肚子里,鱼身下和身上也铺一点。然后用刷子刷上一点清油。###5. 鱼入预热好的烤箱,开始烤吧,200度15分钟后,取出翻个身,继续烤完。###6. 烤好后摆盘挤上柠檬汁就行了。', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(24063, '番茄炒蛋简单的', 'meat', '鸡蛋:5个#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#蒜:30克#蛋简单的:345克', '2名成年人总量+15%冗余', '1. 鸡蛋打散加入半量勺的盐拌匀备用###2. 热锅,放入适量的油,把鸡蛋下锅,待煎结底部便可以翻面,期间翻炒几次,带蛋煎至金黄便可用铲子铲成小块,出锅待用###3. 就着刚才的锅,热锅,加油进去,放入蒜末爆香,倒入番茄进去翻炒,等到番茄差不多变软就可以加入半碗水再翻炒加入一勺盐,一瓷勺白糖翻炒两分钟左右就可以把刚才的鸡蛋放入再翻炒均匀就可以出锅啦###4. 热腾腾的开胃菜出锅啦', '蛋类,禽类,热菜,番茄味,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/7/1/a/yuan_71865e93ff5905b493118247ae64b86a.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###蛋简单的|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡蛋打散加入半量勺的盐拌匀备用###2. 热锅,放入适量的油,把鸡蛋下锅,待煎结底部便可以翻面,期间翻炒几次,带蛋煎至金黄便可用铲子铲成小块,出锅待用###3. 就着刚才的锅,热锅,加油进去,放入蒜末爆香,倒入番茄进去翻炒,等到番茄差不多变软就可以加入半碗水再翻炒加入一勺盐,一瓷勺白糖翻炒两分钟左右就可以把刚才的鸡蛋放入再翻炒均匀就可以出锅啦###4. 热腾腾的开胃菜出锅啦', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(24117, '蒸鱼', 'meat', '洋葱:290克#鱼:690克#红椒:170克#食用油:45毫升#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 将葱、姜,红椒、洋葱切条###2. 酱油淹没辅料,倒一点点醋调味,加少许料酒是为了去腥味。###3. 杀鱼,洗鱼备用###4. 辅料夹一部分放入鱼肚子里,更入味###5. 烧水放盘子里蒸15-20分钟,家里的盘子没有鱼大,所以选择用薄低盆蒸鱼。###6. 15分钟后,将辅料倒入盘子里,再蒸5-10分钟左右便可出国。###7. 出锅!香甜鲜超美味!', '水产,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/2/a/yuan_e2b5c3f55431f2c193f0ae4bf719b80a.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将葱、姜,红椒、洋葱切条###2. 酱油淹没辅料,倒一点点醋调味,加少许料酒是为了去腥味。###3. 杀鱼,洗鱼备用###4. 辅料夹一部分放入鱼肚子里,更入味###5. 烧水放盘子里蒸15-20分钟,家里的盘子没有鱼大,所以选择用薄低盆蒸鱼。###6. 15分钟后,将辅料倒入盘子里,再蒸5-10分钟左右便可出国。###7. 出锅!香甜鲜超美味!', '[]', '来源步骤数: 7', '蒸', 0, 0, NULL, NULL),
(24150, '辣子鸡丁', 'meat', '鸡肉:520克#青椒:205克#木耳:35克#芹菜:400克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#花椒:6克#辣子:345克', '2名成年人总量+15%冗余', '1. 青尖椒 红辣椒 姜 大蒜 花椒 配成料###2. 鸡肉切丁 用盐多点 料酒 酱油腌制半小时 把鸡肉里多余水分脱尽 或者说用热水焯下鸡肉是最有效的去腥的方法###3. 切芹菜 泡木耳 东西备齐 开始了~(>_<)###4. 我昨晚实验得知 鸡肉里有血腥气 一定要把鸡肉多余水分脱尽 辣子鸡丁有的是过油锅炸两遍的 我昨晚是炒的 先把鸡肉水分炒出来 差不多了起锅', '川菜,禽类,肉类,热菜,朋友聚餐,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/b/8/f/yuan_b813163e95261ab779c6424a98d574df.jpg', '简单', '15分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###辣子|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 青尖椒 红辣椒 姜 大蒜 花椒 配成料###2. 鸡肉切丁 用盐多点 料酒 酱油腌制半小时 把鸡肉里多余水分脱尽 或者说用热水焯下鸡肉是最有效的去腥的方法###3. 切芹菜 泡木耳 东西备齐 开始了~(>_<)###4. 我昨晚实验得知 鸡肉里有血腥气 一定要把鸡肉多余水分脱尽 辣子鸡丁有的是过油锅炸两遍的 我昨晚是炒的 先把鸡肉水分炒出来 差不多了起锅', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(24161, '烤肉排', 'meat', '洋葱:290克#黑胡椒:6克#猪肉:345克#鸡蛋:5个#面粉:400克#食用油:45毫升#食盐:7克#料酒:30毫升#蒜:30克#葱:35克#肉排:345克', '2名成年人总量+15%冗余', '1. 洋葱切成碎末###2. 大蒜捣成蓉###3. 把黄油熔化后,和1.2倒入肉馅###4. 打散的鸡蛋,面粉,料酒,顺同一个方向用力搅拌至上劲。###5. 再加入洋葱碎末,蒜蓉,黑胡椒粉,盐,辣椒粉,搅拌均匀。###6. 取适量拌好的肉馅,用手拍成厚约1cm的圆形肉饼,放进烤盘拍好。###7. 肉饼都拍好后,放进预热好200度的烤箱,烤12分钟的时候取出来翻面,再继续烤8分钟即可。', '禽类,蛋类,肉类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/b/3/b/yuan_b3f083bd7fe526ef44f1cd61e7669f4b.jpg', '普通', '25分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###肉排|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 洋葱切成碎末###2. 大蒜捣成蓉###3. 把黄油熔化后,和1.2倒入肉馅###4. 打散的鸡蛋,面粉,料酒,顺同一个方向用力搅拌至上劲。###5. 再加入洋葱碎末,蒜蓉,黑胡椒粉,盐,辣椒粉,搅拌均匀。###6. 取适量拌好的肉馅,用手拍成厚约1cm的圆形肉饼,放进烤盘拍好。###7. 肉饼都拍好后,放进预热好200度的烤箱,烤12分钟的时候取出来翻面,再继续烤8分钟即可。', '[]', '来源步骤数: 7', '烤', 0, 0, NULL, NULL),
(24206, '腐乳汁葱香小排', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 小排砍成段,葱姜切段,把小排放入开水锅中焯水5分钟,捞出冲去血沫;###2. 放入电压力锅中,加料酒生抽,糖和一半的葱姜,加压15分钟;###3. 炒锅放少许油烧五成热,放入剩余的葱姜煸香,放入排骨,腐乳汁,烧5分钟收汁入味,调入适量的盐(也可不加)鸡粉。', '湘菜,禽类,肉类,热菜,葱香,家常菜,电压力锅,压力锅', 'https://cp1.douguo.net/upload/recipe/e/d/a/yuan_ed3d2c21991e3bef5e069713af9fa6ca.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|菜名+步骤', '1. 小排砍成段,葱姜切段,把小排放入开水锅中焯水5分钟,捞出冲去血沫;###2. 放入电压力锅中,加料酒生抽,糖和一半的葱姜,加压15分钟;###3. 炒锅放少许油烧五成热,放入剩余的葱姜煸香,放入排骨,腐乳汁,烧5分钟收汁入味,调入适量的盐(也可不加)鸡粉。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(2421, '水煮鱼', 'meat', '绿豆:230克#五花肉:345克#鱼:690克#豆腐:460克#食用油:45毫升#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 先处理鱼~把鱼收拾干净后~先把两面的鱼肉剔下~片成大片~鱼头鱼骨剁成快~###2. 绿豆芽~油菜洗干净~豆腐皮切片~五花肉切厚片~葱一部分切大段~一部分切葱花~姜祛皮切大片~蒜直接拍一下###3. 先把豆芽~油菜~豆腐皮~用沸水焯熟~控干水后~放在盆里~鱼肉用蛋请淀粉上浆~下沸水中滑熟~控干水后也放在装菜的盆里~在起锅~加一点油~下入鱼头鱼骨~一点葱段~一点姜片~料酒~在加入水~水要多一点', '川菜,水产,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/9/3/8/yuan_9385a8a011f289b69bf108bf1677db58.jpg', '普通', '45分钟', '绿豆|230|克|主料|提前浸泡|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 先处理鱼~把鱼收拾干净后~先把两面的鱼肉剔下~片成大片~鱼头鱼骨剁成快~###2. 绿豆芽~油菜洗干净~豆腐皮切片~五花肉切厚片~葱一部分切大段~一部分切葱花~姜祛皮切大片~蒜直接拍一下###3. 先把豆芽~油菜~豆腐皮~用沸水焯熟~控干水后~放在盆里~鱼肉用蛋请淀粉上浆~下沸水中滑熟~控干水后也放在装菜的盆里~在起锅~加一点油~下入鱼头鱼骨~一点葱段~一点姜片~料酒~在加入水~水要多一点', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(24252, '子姜鸡胸肉', 'meat', '鸡肉:520克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#豆瓣酱:30克#姜:25克', '2名成年人总量+15%冗余', '1. 鸡胸肉、嫩姜切丁,条椒切圈,泡椒剁碎,待用###2. 切好的鸡胸肉放盆里,放入淀粉和料酒拌匀腌制一会###3. 锅中菜籽油熟透后凉至6成热下腌制好的鸡胸肉丁,快速翻炒均匀放入豆瓣酱,炒香后放泡椒、嫩姜,继续炒香后放鸡精调味(尝尝味道,应该不用加盐,不够味再加适量盐)放条椒圈翻炒均匀后,起锅', '肉类,禽类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/f/8/yuan_5fa0c40170f43641299cf6a48ac56648.jpeg', '普通', '20分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|菜名+步骤', '1. 鸡胸肉、嫩姜切丁,条椒切圈,泡椒剁碎,待用###2. 切好的鸡胸肉放盆里,放入淀粉和料酒拌匀腌制一会###3. 锅中菜籽油熟透后凉至6成热下腌制好的鸡胸肉丁,快速翻炒均匀放入豆瓣酱,炒香后放泡椒、嫩姜,继续炒香后放鸡精调味(尝尝味道,应该不用加盐,不够味再加适量盐)放条椒圈翻炒均匀后,起锅', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(24290, '肉塞油豆腐', 'meat', '豆腐:460克#竹笋:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#肉塞:345克', '2名成年人总量+15%冗余', '1. 亲戚家自己做的油豆腐###2. 冬笋尖焯水###3. 把冬笋切碎###4. 超市买的现成肉糜###5. 加入料酒###6. 加点薄盐生抽、盐、砂糖###7. 加点甜面酱、香油###8. 加点鸡汁,搅拌均匀###9. 加入冬笋碎###10. 搅拌均匀###11. 锅里加适量水,放入牛肉粉调味料###12. 把油豆腐放入锅里煮熟###13. 最后尝尝味道后看是否需要加盐', '禽类,肉类,热菜,朋友聚餐,私家菜,家常菜', 'https://cp1.douguo.net/upload/caiku/b/c/d/yuan_bc42f8e6054fee769d16b9c0515a61ed.jpg', '普通', '20分钟', '豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###肉塞|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 亲戚家自己做的油豆腐###2. 冬笋尖焯水###3. 把冬笋切碎###4. 超市买的现成肉糜###5. 加入料酒###6. 加点薄盐生抽、盐、砂糖###7. 加点甜面酱、香油###8. 加点鸡汁,搅拌均匀###9. 加入冬笋碎###10. 搅拌均匀###11. 锅里加适量水,放入牛肉粉调味料###12. 把油豆腐放入锅里煮熟###13. 最后尝尝味道后看是否需要加盐', '[]', '来源步骤数: 13', '煮', 0, 0, NULL, NULL),
(2438, '炖酥肉', 'meat', '鸡蛋:5个#食用油:45毫升#生抽:35毫升#淀粉:30克#酥肉:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 把肉切成厚3mm,宽5mm,长3-4cm的条,这样炸起来比较漂亮,肉里打上一颗鸡蛋,放上干淀粉,搅拌,一直搅拌到那种,面糊往下流,但是慢慢流的状态,如果把握不好淀粉的量,干了,可以放一点水###2. 搅拌好后,除了酱油外,放入其它的调味料,放置十五分钟###3. 放入油锅开始炸,中火,因为是炖的,炸一遍就好,炸制东西,一定要有耐心 金黄色就可捞出,一定要一条一条的放###4. 换另一锅,倒一点点底', '东北菜,肉类,禽类,蛋类,热菜,酱香,午餐,一家三口,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/1/e/b/yuan_1e04290dd0ceeac663e4704293849d4b.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###酥肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 把肉切成厚3mm,宽5mm,长3-4cm的条,这样炸起来比较漂亮,肉里打上一颗鸡蛋,放上干淀粉,搅拌,一直搅拌到那种,面糊往下流,但是慢慢流的状态,如果把握不好淀粉的量,干了,可以放一点水###2. 搅拌好后,除了酱油外,放入其它的调味料,放置十五分钟###3. 放入油锅开始炸,中火,因为是炖的,炸一遍就好,炸制东西,一定要有耐心 金黄色就可捞出,一定要一条一条的放###4. 换另一锅,倒一点点底', '[]', '来源步骤数: 4', '炸', 0, 0, NULL, NULL),
(24456, '番茄炒蛋偏甜', 'meat', '鸡蛋:5个#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#蛋偏甜:345克', '2名成年人总量+15%冗余', '1. 西红柿挑选熟透的、红透的。滚刀切块###2. 三个鸡蛋打散###3. 锅中加油,大火炒鸡蛋###4. 微焦黄后盛出###5. 锅中留底油,放入番茄###6. 加盐、白糖。这时早早放入盐和糖可以使西红柿更容易出汁###7. 翻炒约两分钟,至西红柿出汁。这一点很重要,要西红柿本身的番茄汁味道才浓郁###8. 加少许白水,继续煮1分钟###9. 加鸡蛋,大火煮2分钟,收汁。###10. 盛出即可', '禽类,蛋类,热菜,番茄味,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/5/3/yuan_b5d7a5e087d3a1d5960f2b3fbf7d2b33.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蛋偏甜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 西红柿挑选熟透的、红透的。滚刀切块###2. 三个鸡蛋打散###3. 锅中加油,大火炒鸡蛋###4. 微焦黄后盛出###5. 锅中留底油,放入番茄###6. 加盐、白糖。这时早早放入盐和糖可以使西红柿更容易出汁###7. 翻炒约两分钟,至西红柿出汁。这一点很重要,要西红柿本身的番茄汁味道才浓郁###8. 加少许白水,继续煮1分钟###9. 加鸡蛋,大火煮2分钟,收汁。###10. 盛出即可', '[]', '来源步骤数: 10', '炒', 0, 0, NULL, NULL),
(24574, '步到位卤水拼盘', 'meat', '猪肝:345克#鸭肉:575克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#步到位:345克#水拼盘:345克', '2名成年人总量+15%冗余', '1. 备齐材料放入锅里:八角、桂皮、姜、葱、蒜、香叶、胡椒粒、酱油、卤水(试试味道如太咸加入适量水)###2. 鸭翅鸭肾洗净备用###3. 全部至于锅中大火煮开,熬五分钟,然后转小火熬35分钟###4. 三十五分钟后关火再焖二十分钟,然后切片装盘###5. 最后浇上卤汁!###6. 配上白醋加葱白末撒少许盐,蘸着吃去肉的油腻!###7. 卤水猪肝猪舌###8. 蘸梅汁和卤水汁', '禽类,肉类,凉菜,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/1/2/yuan_316e75c31b29353077091f5f0c72ef62.jpg', '困难', '60分钟', '猪肝|345|克|主料|浸泡洗净切片|2名成年人总量+15%冗余|步骤###鸭肉|575|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###步到位|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###水拼盘|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 备齐材料放入锅里:八角、桂皮、姜、葱、蒜、香叶、胡椒粒、酱油、卤水(试试味道如太咸加入适量水)###2. 鸭翅鸭肾洗净备用###3. 全部至于锅中大火煮开,熬五分钟,然后转小火熬35分钟###4. 三十五分钟后关火再焖二十分钟,然后切片装盘###5. 最后浇上卤汁!###6. 配上白醋加葱白末撒少许盐,蘸着吃去肉的油腻!###7. 卤水猪肝猪舌###8. 蘸梅汁和卤水汁', '[]', '来源步骤数: 8', '焖', 0, 0, NULL, NULL),
(24662, '爆鱼', 'meat', '柠檬:170克#鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#姜:25克', '2名成年人总量+15%冗余', '1. 青鱼洗净取中段切成厚条。###2. 放入老抽、六月鲜、盐、料酒、白酒、生姜、辣椒!有柠檬还可以滴上少许柠檬汁,去腥效果更显著!所有调料放好后腌制两到三小时。###3. 腌制好后把鱼晾干,要两小时左右!一定要晾干?不然接下来的油炸就有的你受了!!###4. 炸好后的鱼块!###5. 将腌制鱼的调料加水放大料放糖煮开!再放入鱼块!烧至无水分###6. 完成!!', '水产,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/7/b/f/yuan_7be128705111f96f1881762e4acbe51f.jpg', '简单', '15分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 青鱼洗净取中段切成厚条。###2. 放入老抽、六月鲜、盐、料酒、白酒、生姜、辣椒!有柠檬还可以滴上少许柠檬汁,去腥效果更显著!所有调料放好后腌制两到三小时。###3. 腌制好后把鱼晾干,要两小时左右!一定要晾干?不然接下来的油炸就有的你受了!!###4. 炸好后的鱼块!###5. 将腌制鱼的调料加水放大料放糖煮开!再放入鱼块!烧至无水分###6. 完成!!', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(24669, '花肉炒甜椒', 'meat', '花生:170克#五花肉:345克#猪肉:345克#青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#姜:25克#花肉:345克#甜椒:345克', '2名成年人总量+15%冗余', '1. 姜丝、盐、料酒放入切好的肉片中拌匀,腌制10分钟。###2. 锅里放入花生油,油温升高后,放入青椒翻炒,滴几点料酒还有水,翻炒两分钟起锅装入盘中待用。###3. 锅里放油,油热后放入五花进行翻炒,等到五花肉变色,炒干肉里的水分。生抽、老抽进行翻炒,上色。###4. 待五花肉两面上色,倒入青椒翻炒,再放入少量盐入味就可以出锅。', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/a/e/yuan_3a48461e2797c5193b8bd972f559c0de.jpg', '普通', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###甜椒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 姜丝、盐、料酒放入切好的肉片中拌匀,腌制10分钟。###2. 锅里放入花生油,油温升高后,放入青椒翻炒,滴几点料酒还有水,翻炒两分钟起锅装入盘中待用。###3. 锅里放油,油热后放入五花进行翻炒,等到五花肉变色,炒干肉里的水分。生抽、老抽进行翻炒,上色。###4. 待五花肉两面上色,倒入青椒翻炒,再放入少量盐入味就可以出锅。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(24701, '烤孜然鸡翅', 'meat', '孜然:9克#鸡翅:575克#鸡蛋:5个#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡蛋洗干净,淋干水分。###2. 在鸡翅的背部划两刀。###3. 把所有辅料放入鸡翅中。###4. 戴上一次性手套,抓均匀,这样更入味。###5. 盖保鲜膜入冰箱冷藏腌制30分钟以上。###6. 空气炸锅预热5分钟。###7. 将鸡翅放入,,烤15分钟即可。###8. 烤好了,香哦。###9. 成品。', '禽类,蛋类,热菜,孜然,午餐,朋友聚餐,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/c/3/0/yuan_c355ab5be3222836a395626251f3e240.jpg', '普通', '25分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡蛋洗干净,淋干水分。###2. 在鸡翅的背部划两刀。###3. 把所有辅料放入鸡翅中。###4. 戴上一次性手套,抓均匀,这样更入味。###5. 盖保鲜膜入冰箱冷藏腌制30分钟以上。###6. 空气炸锅预热5分钟。###7. 将鸡翅放入,,烤15分钟即可。###8. 烤好了,香哦。###9. 成品。', '[]', '来源步骤数: 9', '炸', 0, 0, NULL, NULL),
(24754, '香牛肉丁', 'meat', '牛肉:400克#青椒:205克#红椒:170克#萝卜:460克#莲藕:460克#食用油:45毫升#生抽:35毫升#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 公公不知道已经用把牛肉用冷水浸了两小时然后又焯水了,实际上可以不用焯水###2. 然后藕丁萝卜丁红椒青椒大蒜都切好热锅放入爆炒###3. 再倒入已经熟了的牛肉继续炒,炒了一会后记得加点酱油一两片尖椒压味再加点水这样有汤汁,如果牛肉没焯过水就要先丢下去爆炒哟。###4. 最后装盘好香香。很简单的家常菜就这样成功。', '肉类,热菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/1/5/1/yuan_15b9cf197cb71798be914ceb24986761.jpg', '普通', '20分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###莲藕|460|克|主料|去皮切片或切丁|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 公公不知道已经用把牛肉用冷水浸了两小时然后又焯水了,实际上可以不用焯水###2. 然后藕丁萝卜丁红椒青椒大蒜都切好热锅放入爆炒###3. 再倒入已经熟了的牛肉继续炒,炒了一会后记得加点酱油一两片尖椒压味再加点水这样有汤汁,如果牛肉没焯过水就要先丢下去爆炒哟。###4. 最后装盘好香香。很简单的家常菜就这样成功。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(24767, '红烧肉乱炖', 'meat', '五花肉:345克#土豆:460克#豆角:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#蒜:30克#葱:35克#花椒:6克#肉乱:345克', '2名成年人总量+15%冗余', '1. 五花肉切小块,焯水去沫,倒入料酒,盐,花椒粉,菁选酱油,腌20分钟。###2. 土豆切块,芸豆掰成小段###3. 五花肉放入葱段,老抽,盐,冰糖,大料,花椒,倒入水没过肉,高压锅焖30分钟。###4. 锅内烧热油,放蒜爆香,放入土豆和芸豆煸炒至有香味,倒入两大勺肉汤,放入五花肉。炒至土豆软烂。', '东北菜,肉类,热菜,午餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/e/d/1/yuan_ed827b012636521555154b16a9765551.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###肉乱|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 五花肉切小块,焯水去沫,倒入料酒,盐,花椒粉,菁选酱油,腌20分钟。###2. 土豆切块,芸豆掰成小段###3. 五花肉放入葱段,老抽,盐,冰糖,大料,花椒,倒入水没过肉,高压锅焖30分钟。###4. 锅内烧热油,放蒜爆香,放入土豆和芸豆煸炒至有香味,倒入两大勺肉汤,放入五花肉。炒至土豆软烂。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(24847, '炖鸡爪', 'meat', '莴笋:460克#鸡肉:520克#竹笋:460克#萝卜:460克#食盐:7克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 烧一锅热水###2. 将鸡爪洗净,放入热水锅里,灼去血水,捞起。###3. 在炖锅里加入能淹没所有食材两倍的水,放入鸡爪,拍一小块姜放入,大火炖至水烧开,开小火慢炖。###4. 等鸡爪熟了,还没炖软的时候,加入切块的胡萝卜,中火炖15分钟后,加入切块的莴笋头,中火炖15分钟,加入切块的莴笋尖。###5. 小火慢炖,直至鸡爪,绿萝卜,莴笋都炖软时,加入少许盐,加入葱花,即可关火起锅。', '禽类,热菜,午餐,朋友聚餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/7/5/7/yuan_755b8e8e27d33438829923c64a73fcd7.jpg', '普通', '25分钟', '莴笋|460|克|主料|去皮切片|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 烧一锅热水###2. 将鸡爪洗净,放入热水锅里,灼去血水,捞起。###3. 在炖锅里加入能淹没所有食材两倍的水,放入鸡爪,拍一小块姜放入,大火炖至水烧开,开小火慢炖。###4. 等鸡爪熟了,还没炖软的时候,加入切块的胡萝卜,中火炖15分钟后,加入切块的莴笋头,中火炖15分钟,加入切块的莴笋尖。###5. 小火慢炖,直至鸡爪,绿萝卜,莴笋都炖软时,加入少许盐,加入葱花,即可关火起锅。', '[]', '来源步骤数: 5', '炖', 0, 0, NULL, NULL),
(2486, '香辣虾', 'meat', '洋葱:290克#虾:520克#土豆:460克#芹菜:400克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#葱:35克#干辣椒:15克#花椒:6克', '2名成年人总量+15%冗余', '1. 成品哦###2. 把土豆切成条(不要太细),锅内倒油,油温八成,把土豆条放去锅内炸至金黄捞出###3. 油锅烧热,放两勺白糖,融化以后放红干辣椒,花椒,炒出香味###4. 放入大虾,翻炒,虾略变红色倒去料酒,蚝油少许。###5. 把芹菜,洋葱倒入锅内与虾一起翻炒一两分钟,再放少许盐###6. 最后,把炒完的食材倒去之前炸好的土豆条上!大功告成!', '水产,热菜,香辣,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/1/e/yuan_b120089cc4fb69c1ffab8ae3f2830bee.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 成品哦###2. 把土豆切成条(不要太细),锅内倒油,油温八成,把土豆条放去锅内炸至金黄捞出###3. 油锅烧热,放两勺白糖,融化以后放红干辣椒,花椒,炒出香味###4. 放入大虾,翻炒,虾略变红色倒去料酒,蚝油少许。###5. 把芹菜,洋葱倒入锅内与虾一起翻炒一两分钟,再放少许盐###6. 最后,把炒完的食材倒去之前炸好的土豆条上!大功告成!', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(24931, '宝炒腊味', 'meat', '芝麻:35克#玉米:460克#萝卜:460克#食用油:45毫升#食盐:7克#葱:35克#腊味:345克', '2名成年人总量+15%冗余', '1. 腊肠斜切片,胡萝卜切粒,大葱切4段。###2. 炒锅烧水,水开后把玉米粒和青豆下锅煮5分钟,然后捞起来沥干水,炒锅的水倒掉。###3. 炒锅烧热,待水分蒸发完后,放食用油,待油微热放大葱炒出香味后,把腊肠下锅一起炒,炒至变色。###4. 把胡萝卜粒、玉米粒和青豆一起倒炒锅翻炒5分钟,加盐炒匀,上菜。(上盘后可以在上面撒些熟的黑芝麻,更香,营养更丰富了。)', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/1/0/yuan_314dc7e18868f043d829d886612a7510.jpg', '简单', '15分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###腊味|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 腊肠斜切片,胡萝卜切粒,大葱切4段。###2. 炒锅烧水,水开后把玉米粒和青豆下锅煮5分钟,然后捞起来沥干水,炒锅的水倒掉。###3. 炒锅烧热,待水分蒸发完后,放食用油,待油微热放大葱炒出香味后,把腊肠下锅一起炒,炒至变色。###4. 把胡萝卜粒、玉米粒和青豆一起倒炒锅翻炒5分钟,加盐炒匀,上菜。(上盘后可以在上面撒些熟的黑芝麻,更香,营养更丰富了。)', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(25018, '粉蒸糟排骨新手也会的', 'meat', '芝麻:35克#排骨:575克#菜花:520克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 排骨洗净,葱姜料酒腌制30分钟去腥味。###2. 下生抽盐小半勺,糖一勺,生抽半勺,红糟一大勺腌20分钟。时间足够可以更久一点,排骨入味,口感更佳。###3. 倒掉多余的汁水,裹上蒸肉粉,搅拌均匀。###4. 放入高压锅,奇哩奇哩15分钟。###5. 西兰花洗净切小朵,锅内放一小碗水烧开下蒜末,橄榄油一小勺,入西兰花煮熟,围盘摆一圈备用。###6. 排骨熟入盘摆好,散葱花芝麻。上桌开吃!', '肉类,热菜,午餐,朋友聚餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/4/a/1/yuan_4ad9f15bb9023f8073a3fa0afd817401.jpg', '普通', '25分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###菜花|520|克|主料|掰小朵洗净|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 排骨洗净,葱姜料酒腌制30分钟去腥味。###2. 下生抽盐小半勺,糖一勺,生抽半勺,红糟一大勺腌20分钟。时间足够可以更久一点,排骨入味,口感更佳。###3. 倒掉多余的汁水,裹上蒸肉粉,搅拌均匀。###4. 放入高压锅,奇哩奇哩15分钟。###5. 西兰花洗净切小朵,锅内放一小碗水烧开下蒜末,橄榄油一小勺,入西兰花煮熟,围盘摆一圈备用。###6. 排骨熟入盘摆好,散葱花芝麻。上桌开吃!', '[]', '来源步骤数: 6', '蒸', 0, 0, NULL, NULL),
(25089, '鸡肉串', 'meat', '鸡肉:520克#料酒:30毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡胸肉切块,用烤肉酱 料酒 葱姜腌制两个小时。###2. 用竹签将腌制好的鸡胸肉串好,放入烤盘###3. 烤箱上下200度预热8分钟,放入烤盘,烤制20分钟!烤10分钟左右刷一次蜂蜜,也可以刷各种口味的酱料!', '禽类,肉类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/7/7/3/yuan_77555f5d685509105cdefc55961c7253.jpg', '普通', '20分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡胸肉切块,用烤肉酱 料酒 葱姜腌制两个小时。###2. 用竹签将腌制好的鸡胸肉串好,放入烤盘###3. 烤箱上下200度预热8分钟,放入烤盘,烤制20分钟!烤10分钟左右刷一次蜂蜜,也可以刷各种口味的酱料!', '[]', '来源步骤数: 3', '烤', 0, 0, NULL, NULL),
(25309, '红烧鸡翅', 'meat', '花生:170克#鸡翅:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 将买回的鸡翅洗净,水挤出去;切一些葱、姜片;###2. 将锅烧热至有烟,加油(很重要哟,阿姨说做东西热锅冷油最好,当然最好是花生油或者是调合油),将鸡翅放进去,翻炒两下,放入葱、姜、适量的糖、盐,再翻炒几下,然后加入料酒、酱油(最好是上海的淘大),再翻炒,再加水(凉水就可以啦)至没过鸡翅,盖上盖子,至水沸,将火调小。###3. 其间可尝尝汤的味道,依个人口味加些盐、酱油(不要太多', '禽类,热菜,朋友聚餐,下饭菜,下酒菜,二人世界,家常菜', 'https://cp1.douguo.net/upload/caiku/6/1/e/yuan_61f3a6dbc9120ea78ef75544826c814e.jpg', '普通', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 将买回的鸡翅洗净,水挤出去;切一些葱、姜片;###2. 将锅烧热至有烟,加油(很重要哟,阿姨说做东西热锅冷油最好,当然最好是花生油或者是调合油),将鸡翅放进去,翻炒两下,放入葱、姜、适量的糖、盐,再翻炒几下,然后加入料酒、酱油(最好是上海的淘大),再翻炒,再加水(凉水就可以啦)至没过鸡翅,盖上盖子,至水沸,将火调小。###3. 其间可尝尝汤的味道,依个人口味加些盐、酱油(不要太多', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(2531, '香麻鸡蛋干', 'meat', '花生:170克#鸡蛋:5个#食用油:45毫升#食盐:7克#生抽:35毫升#花椒:6克', '2名成年人总量+15%冗余', '1. 鸡蛋干切成细条状,装盘。###2. 取一个小碗,把盐,生抽,麻油鸡精放入。拌匀后淋在鸡蛋干上。###3. 起油锅,热油炒花椒,炒出香味后用漏勺把花椒捞出。###4. 再把花生米倒入油炸,需要不断的翻,炒出香味即可。如果有现成的花生米,此步可跳过。喜欢吃辣的,可以倒入少许红辣油。###5. 把热油和花生米浇在鸡蛋干上即可。吃前再拌一拌哦~', '川菜,蛋类,禽类,热菜,辣,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/7/4/f/yuan_74b0438877ace60309b12214f63ffc4f.jpg', '普通', '25分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 鸡蛋干切成细条状,装盘。###2. 取一个小碗,把盐,生抽,麻油鸡精放入。拌匀后淋在鸡蛋干上。###3. 起油锅,热油炒花椒,炒出香味后用漏勺把花椒捞出。###4. 再把花生米倒入油炸,需要不断的翻,炒出香味即可。如果有现成的花生米,此步可跳过。喜欢吃辣的,可以倒入少许红辣油。###5. 把热油和花生米浇在鸡蛋干上即可。吃前再拌一拌哦~', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(25318, '花肉炒猪肚菇', 'meat', '五花肉:345克#食用油:45毫升#食盐:7克#蒜:30克#花肉:345克#猪肚菇:345克', '2名成年人总量+15%冗余', '1. 猪肚菇洗净撕块;五花肉切成4mm厚的片。###2. 热锅下油把蒜蓉爆香,倒入五花内快速翻炒,放入盐,六成熟出锅上碟。###3. 热锅下油把蒜蓉爆香,倒入猪肚菇翻炒,洒入盐、鸡粉,边炒边洒少许水,菇身呈现少许透明后,全入少许水盖锅煮一分钟。###4. 把菇翻面,倒入五花肉半成品在上面(最好别粘到锅边),盖住煮一分钟。###5. 开盖翻炒把菇和肉拌匀出锅装盘。', '禽类,肉类,热菜,单身食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/c/e/c/yuan_cecf4ca4ee4e48d4511ab375b1f9049c.jpg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###猪肚菇|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 猪肚菇洗净撕块;五花肉切成4mm厚的片。###2. 热锅下油把蒜蓉爆香,倒入五花内快速翻炒,放入盐,六成熟出锅上碟。###3. 热锅下油把蒜蓉爆香,倒入猪肚菇翻炒,洒入盐、鸡粉,边炒边洒少许水,菇身呈现少许透明后,全入少许水盖锅煮一分钟。###4. 把菇翻面,倒入五花肉半成品在上面(最好别粘到锅边),盖住煮一分钟。###5. 开盖翻炒把菇和肉拌匀出锅装盘。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(25344, '香辣烤鸡翅配薯条', 'meat', '鸡翅:575克#土豆:460克#料酒:30毫升#淀粉:30克#姜:25克#干辣椒:15克#薯条:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 用料酒,干辣椒碎,姜末腌制鸡翅块,放冰箱腌制2个小时,越久越好啊###2. 把烧烤酱跟辣椒酱倒到小碗里混匀###3. 烤箱上下火预热200度,在烤盘上铺锡纸,把腌制好的鸡翅放上去,在上面刷一层酱,烤盘放入烤箱烤15分钟###4. 15分钟后拿出来翻面,刷酱烤5分钟,再拿出来翻面继续烤5分钟就可以出炉啦###5. 土豆去皮切条,放凉水里泡30分钟去淀粉,然后煮3分钟,再捞起控干水份', '禽类,热菜,香辣,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/3/8/8/yuan_3899d7012a6cbd408a48165d559045d8.jpg', '普通', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###薯条|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 用料酒,干辣椒碎,姜末腌制鸡翅块,放冰箱腌制2个小时,越久越好啊###2. 把烧烤酱跟辣椒酱倒到小碗里混匀###3. 烤箱上下火预热200度,在烤盘上铺锡纸,把腌制好的鸡翅放上去,在上面刷一层酱,烤盘放入烤箱烤15分钟###4. 15分钟后拿出来翻面,刷酱烤5分钟,再拿出来翻面继续烤5分钟就可以出炉啦###5. 土豆去皮切条,放凉水里泡30分钟去淀粉,然后煮3分钟,再捞起控干水份', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(25917, '土豆焖鸡翅', 'meat', '鸡翅:575克#土豆:460克#白糖:55克#食用油:45毫升#生抽:35毫升#淀粉:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 收到大喜大牛肉粉狠是开?......###2. 还有菜谱的呢,好贴心^o^.........###3. 鸡翅6个,土豆2个。。###4. 在鸡翅的双面各切三刀(让鸡翅在腌制过程中更容易入味)###5. 鸡翅放2茶匙大喜大牛肉粉;适量的酱油;白砂糖1茶匙;生粉1茶腌制待用。###6. 土豆削皮切小块待用。###7. 热锅下油,放鸡翅煎至金黄色。###8. 盛碟待用。###9. 不用洗锅,下土豆 、放适量的温水和腌', '禽类,肉类,热菜,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/7/4/8/yuan_74df585f286ce215a293eaff44240558.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 收到大喜大牛肉粉狠是开?......###2. 还有菜谱的呢,好贴心^o^.........###3. 鸡翅6个,土豆2个。。###4. 在鸡翅的双面各切三刀(让鸡翅在腌制过程中更容易入味)###5. 鸡翅放2茶匙大喜大牛肉粉;适量的酱油;白砂糖1茶匙;生粉1茶腌制待用。###6. 土豆削皮切小块待用。###7. 热锅下油,放鸡翅煎至金黄色。###8. 盛碟待用。###9. 不用洗锅,下土豆 、放适量的温水和腌', '[]', '来源步骤数: 9', '煎', 0, 0, NULL, NULL),
(25919, '胡萝卜牛肉丸', 'meat', '洋葱:290克#猪肉:345克#牛肉:400克#鸡蛋:5个#萝卜:460克#食用油:45毫升#生抽:35毫升#料酒:30毫升#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 牛肉馅用水浸泡一天去除血水,然后用料酒和生抽腌制过夜胡萝卜切丝焯水或者切小段(长不超过2厘米)备用###2. 洋葱切末备用###3. 肉馅中加入鸡蛋搅打上劲后加入调味料调味###4. 加入胡萝卜和洋葱搅匀###5. 放掌心中一个个挤出成丸子状###6. 宽锅热油高温炸至表面上色回锅低温复炸至熟透,即食', '肉类,禽类,蛋类,热菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/1/4/yuan_318443aaf2d2a66518925995a813ecd4.jpg', '困难', '45分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 牛肉馅用水浸泡一天去除血水,然后用料酒和生抽腌制过夜胡萝卜切丝焯水或者切小段(长不超过2厘米)备用###2. 洋葱切末备用###3. 肉馅中加入鸡蛋搅打上劲后加入调味料调味###4. 加入胡萝卜和洋葱搅匀###5. 放掌心中一个个挤出成丸子状###6. 宽锅热油高温炸至表面上色回锅低温复炸至熟透,即食', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(25973, '蒜苗炒肉', 'meat', '猪肉:345克#生菜:460克#食用油:45毫升#食盐:7克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 新鲜的蒜苗,洗净后用手将其分成合适的小段蒜苗###2. 将生姜,香菜,小葱,肉切好###3. 热锅放油,素炒蒜苗1分钟,不加配料,直接倒出###4. 热锅,放油,放入瘦肉###5. 放入生姜,剁辣椒,生菜梗,小葱梗,翻炒1分钟###6. 放入炒好的蒜苗###7. 翻炒1分钟,放入适量的盐###8. 放入小葱叶和香菜叶,翻炒几下出锅###9. 味道超级赞的蒜苗炒肉', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/6/4/d/yuan_64174b9d8bd926957e12b09f2ade4add.jpg', '困难', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###生菜|460|克|主料|洗净沥水|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 新鲜的蒜苗,洗净后用手将其分成合适的小段蒜苗###2. 将生姜,香菜,小葱,肉切好###3. 热锅放油,素炒蒜苗1分钟,不加配料,直接倒出###4. 热锅,放油,放入瘦肉###5. 放入生姜,剁辣椒,生菜梗,小葱梗,翻炒1分钟###6. 放入炒好的蒜苗###7. 翻炒1分钟,放入适量的盐###8. 放入小葱叶和香菜叶,翻炒几下出锅###9. 味道超级赞的蒜苗炒肉', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(26211, '香胡萝卜粒煮肉块', 'meat', '萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#干辣椒:15克#肉块:345克', '2名成年人总量+15%冗余', '1. 把胡萝卜和肉洗净,干辣椒三个,桂皮八角一同洗净###2. 热锅,放油盖到锅底,放肉块,大火炒一分钟###3. 放入胡萝卜,加水没过食材,放入辣椒,桂皮八角,酱油和适量的盐。盖上锅盖,来中火。###4. 等水差不多块干的时候,加调好的芡粉(生粉加一点水)。加一小勺白糖提味!快速收汁!美味的胡萝卜肉块就做好啦!', '肉类,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/7/5/1/yuan_75e1476844434c8922845fa7d0f6daa1.jpg', '简单', '15分钟', '萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###肉块|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 把胡萝卜和肉洗净,干辣椒三个,桂皮八角一同洗净###2. 热锅,放油盖到锅底,放肉块,大火炒一分钟###3. 放入胡萝卜,加水没过食材,放入辣椒,桂皮八角,酱油和适量的盐。盖上锅盖,来中火。###4. 等水差不多块干的时候,加调好的芡粉(生粉加一点水)。加一小勺白糖提味!快速收汁!美味的胡萝卜肉块就做好啦!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(26746, '鱼香肉丝', 'meat', '猪里脊:345克#青椒:205克#木耳:35克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#料酒:30毫升#香醋:30毫升#淀粉:30克#姜:25克#葱:35克#肉丝:345克', '2名成年人总量+15%冗余', '1. 里脊肉切丝,加入蛋清、淀粉、料酒拌匀,腌制。###2. 青椒切成细丝,尖椒剪成段,黑木耳泡发洗净切丝,备用。###3. 老抽、生抽、糖、醋加淀粉调成汁备用。###4. 锅中放油,油热放入肉丝翻炒,肉变色后放入葱姜、尖椒,炒出香味后放入调好汁子,片刻放木耳青椒,快出锅加盐调味。', '川菜,水产,肉类,热菜,鱼香,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/e/1/yuan_fe92e34ab9421dd8a81b6b57f0e83c71.jpg', '简单', '15分钟', '猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###肉丝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 里脊肉切丝,加入蛋清、淀粉、料酒拌匀,腌制。###2. 青椒切成细丝,尖椒剪成段,黑木耳泡发洗净切丝,备用。###3. 老抽、生抽、糖、醋加淀粉调成汁备用。###4. 锅中放油,油热放入肉丝翻炒,肉变色后放入葱姜、尖椒,炒出香味后放入调好汁子,片刻放木耳青椒,快出锅加盐调味。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(270, '川味宫保鸡丁', 'meat', '花生:170克#鸡腿:575克#鸡肉:520克#白糖:55克#食用油:45毫升#生抽:35毫升#香醋:30毫升#淀粉:30克#姜:25克#蒜:30克#干辣椒:15克#川味宫保:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡胸、鸡腿肉去骨,用刀背轻轻拍松,在肉面划十字刀,再切成一厘米见方的小丁,加酱油,米酒,水淀粉腌制二十分钟。###2. 花生放进微波碗,中高火叮5、6分钟。花生也可以用油锅炸熟,微波炉比较适合懒人,而且做出来的一样酥脆......###3. 叮熟的花生米放凉,去掉红衣。###4. 干辣椒去掉辣椒籽,剪成小段。###5. 酱油,醋,白糖,水淀粉混合,做成调味汁。###6. 生姜,大蒜切片,青蒜取蒜白部', '川菜,禽类,肉类,热菜,下饭菜,午餐,朋友聚餐,家常菜,懒人食谱,微波炉', 'https://cp1.douguo.net/upload/caiku/9/8/b/yuan_9896d02ab618f97899c13dfc5217612b.jpg', '普通', '25分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###川味宫保|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡胸、鸡腿肉去骨,用刀背轻轻拍松,在肉面划十字刀,再切成一厘米见方的小丁,加酱油,米酒,水淀粉腌制二十分钟。###2. 花生放进微波碗,中高火叮5、6分钟。花生也可以用油锅炸熟,微波炉比较适合懒人,而且做出来的一样酥脆......###3. 叮熟的花生米放凉,去掉红衣。###4. 干辣椒去掉辣椒籽,剪成小段。###5. 酱油,醋,白糖,水淀粉混合,做成调味汁。###6. 生姜,大蒜切片,青蒜取蒜白部', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(2706, '烧汁香菇面筋肉', 'meat', '猪肉:345克#鸡蛋:5个#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#淀粉:30克#蒜:30克', '2名成年人总量+15%冗余', '1. 剁馅###2. 装碗###3. 放老抽盐胡椒鸡蛋淀粉顺时针搅拌。###4. 面筋泡用筷子戳个洞在里面搅一圈,肉馅用裱花袋装好,把肉馅挤进面筋泡里(方法独创)不用麻烦的用筷子戳了###5. OK!###6. 锅中倒油烧热放辣椒蒜瓣爆香倒入蚝油酱油糖调的一碗汁熬开放面筋肉香菇炖十分钟左右,勾芡收汁即可###7. 装盘', '禽类,水产,蛋类,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/a/1/b/yuan_a18171fe9259085a2ecad9a27e73b3bb.jpeg', '困难', '60分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 剁馅###2. 装碗###3. 放老抽盐胡椒鸡蛋淀粉顺时针搅拌。###4. 面筋泡用筷子戳个洞在里面搅一圈,肉馅用裱花袋装好,把肉馅挤进面筋泡里(方法独创)不用麻烦的用筷子戳了###5. OK!###6. 锅中倒油烧热放辣椒蒜瓣爆香倒入蚝油酱油糖调的一碗汁熬开放面筋肉香菇炖十分钟左右,勾芡收汁即可###7. 装盘', '[]', '来源步骤数: 7', '炖', 0, 0, NULL, NULL),
(27062, '香辣手撕鸡', 'meat', '鸡腿:575克#鸡肉:520克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#葱:35克#花椒:6克#手撕鸡:345克', '2名成年人总量+15%冗余', '1. 锅中加冷水,加鸡腿,放入八角、花椒、葱段、生姜片、料酒等辅材大火煮10分钟左右,筷子能插烂即可###2. 把煮好的鸡腿放进凉水中,一分钟后捞起。###3. 冷凉鸡腿,戴上一次性手套,将鸡肉顺纹理撕成小细条,鸡皮撕成小块,放调菜盆中。###4. 加入辣油,也可以是老干妈油辣椒,###5. 加入生抽、醋、盐,拌匀。', '川菜,禽类,肉类,热菜,香辣,下饭菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/8/2/yuan_383a7dbf32fa71a84d679d5bf7b1dfb2.jpg', '简单', '15分钟', '鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###手撕鸡|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 锅中加冷水,加鸡腿,放入八角、花椒、葱段、生姜片、料酒等辅材大火煮10分钟左右,筷子能插烂即可###2. 把煮好的鸡腿放进凉水中,一分钟后捞起。###3. 冷凉鸡腿,戴上一次性手套,将鸡肉顺纹理撕成小细条,鸡皮撕成小块,放调菜盆中。###4. 加入辣油,也可以是老干妈油辣椒,###5. 加入生抽、醋、盐,拌匀。', '[]', '来源步骤数: 5', '煮', 0, 0, NULL, NULL),
(27070, '鲜百合炒猪扒粒', 'meat', '百合:90克#木耳:35克#食用油:45毫升#食盐:7克#淀粉:30克#蒜:30克#猪扒粒:345克', '2名成年人总量+15%冗余', '1. 鲜百合、木耳、虫草花洗净,沥干,草菇切开;###2. 沸水,放小许油、盐,倒下食材,至煮软;###3. 倒出,过冷水,沥干,待用;###4. 腌味猪扒;###5. 猪扒切粒,锅加热,放小许油,用中火煎猪扒粒,放下蒜片爆炒;###6. 放百合,翻炒;###7. 再把备用的木耳、虫草花、草菇放入,煸炒;###8. 淋上生粉芡水,煮至收汁;###9. 鲜百合炒猪扒粒,色彩增强了食欲!', '肉类,热菜,下饭菜,午餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/1/5/f/yuan_15b7c595c7755b087c98ffb1d764ff0f.jpeg', '普通', '20分钟', '百合|90|克|辅料|洗净备用|2名成年人总量+15%冗余|菜名+步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###猪扒粒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鲜百合、木耳、虫草花洗净,沥干,草菇切开;###2. 沸水,放小许油、盐,倒下食材,至煮软;###3. 倒出,过冷水,沥干,待用;###4. 腌味猪扒;###5. 猪扒切粒,锅加热,放小许油,用中火煎猪扒粒,放下蒜片爆炒;###6. 放百合,翻炒;###7. 再把备用的木耳、虫草花、草菇放入,煸炒;###8. 淋上生粉芡水,煮至收汁;###9. 鲜百合炒猪扒粒,色彩增强了食欲!', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(27129, '红烧肉', 'meat', '五花肉:345克#食用油:45毫升#料酒:30毫升#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好所有的食材。###2. 炒锅倒少许油爆香姜片。###3. 倒入切块的五花肉翻炒。###4. 炒至五花肉变色微发黄。###5. 加入料酒炒香。###6. 加入李锦记秘制红烧汁。###7. 加入适量的清水大火煮开,小火烧煮50分钟。###8. 最后用大火收汁即好。', '肉类,热菜,家常味,下饭菜,懒人食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/f/6/a/yuan_f6e3ad4ecd3e850b5207b4c1b7fc379a.jpg', '普通', '25分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好所有的食材。###2. 炒锅倒少许油爆香姜片。###3. 倒入切块的五花肉翻炒。###4. 炒至五花肉变色微发黄。###5. 加入料酒炒香。###6. 加入李锦记秘制红烧汁。###7. 加入适量的清水大火煮开,小火烧煮50分钟。###8. 最后用大火收汁即好。', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(27271, '香酥龙利鱼扒', 'meat', '黑胡椒:6克#鱼:690克#鸡蛋:5个#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 龙利鱼解冻洗净用厨房纸吸干水,切成等量大小块状###2. 放点盐抹匀###3. 放橄榄油和黑胡椒粉###4. 拌匀腌制20分钟###5. 沾上蛋液###6. 放碟里每块都均匀地滚上面包糠###7. 热锅冷油,下鱼块慢慢火煎至两面金黄即可###8. 吃时配点甜辣酱或蕃茄酱都非常美味', '水产,小吃,热菜,香酥,朋友聚餐,年夜饭,家常菜,电饼铛', 'https://cp1.douguo.net/upload/caiku/d/8/5/yuan_d87469a57da16cc26c1e0ce6c74aa075.jpg', '普通', '25分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 龙利鱼解冻洗净用厨房纸吸干水,切成等量大小块状###2. 放点盐抹匀###3. 放橄榄油和黑胡椒粉###4. 拌匀腌制20分钟###5. 沾上蛋液###6. 放碟里每块都均匀地滚上面包糠###7. 热锅冷油,下鱼块慢慢火煎至两面金黄即可###8. 吃时配点甜辣酱或蕃茄酱都非常美味', '[]', '来源步骤数: 8', '煎', 0, 0, NULL, NULL),
(27341, '茄子肉沫家常', 'meat', '猪肉:345克#茄子:460克#食用油:45毫升#食盐:7克#生抽:35毫升#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 茄子洗净切条,放入水里浸泡十五分钟。把瘦肉和蒜蓉剁碎,葱切成葱花备用。###2. 热锅放油,将肉沫和蒜蓉炒香后装盘。###3. 茄子入锅煎至7成熟时,再加入炒好的肉沫一同翻炒###4. 翻炒片刻加入适量的耗油,酱油,盐,葱花,翻炒均匀即可出锅。###5. 成品图', '肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/9/a/yuan_b9f2ae50fcd828e89f24e4bf0a06612a.jpg', '普通', '20分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###茄子|460|克|主料|切块或切条|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 茄子洗净切条,放入水里浸泡十五分钟。把瘦肉和蒜蓉剁碎,葱切成葱花备用。###2. 热锅放油,将肉沫和蒜蓉炒香后装盘。###3. 茄子入锅煎至7成熟时,再加入炒好的肉沫一同翻炒###4. 翻炒片刻加入适量的耗油,酱油,盐,葱花,翻炒均匀即可出锅。###5. 成品图', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(27454, '菜青椒肉片炒豆腐皮', 'meat', '猪肉:345克#豆腐:460克#青椒:205克#西红柿:460克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 首先准备豆腐皮,青椒,大蒜瓣,瘦肉,西红柿,豆腐皮超市都有的干豆腐皮,用热水泡几分钟即可。###2. 把辣椒斜切成小段,瘦肉切片,大蒜切片,西红柿切成小颗粒状###3. 锅里放适量油烧热以后先放入辣椒翻炒在放入肉片炒熟后放入大蒜和西红柿###4. 最后放入豆腐皮一起翻炒,然后放入适量盐和鸡精。###5. 炒熟入盘即可。', '禽类,肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/d/4/yuan_8d284bc500a0f314c3908d1f1c948074.jpg', '困难', '60分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 首先准备豆腐皮,青椒,大蒜瓣,瘦肉,西红柿,豆腐皮超市都有的干豆腐皮,用热水泡几分钟即可。###2. 把辣椒斜切成小段,瘦肉切片,大蒜切片,西红柿切成小颗粒状###3. 锅里放适量油烧热以后先放入辣椒翻炒在放入肉片炒熟后放入大蒜和西红柿###4. 最后放入豆腐皮一起翻炒,然后放入适量盐和鸡精。###5. 炒熟入盘即可。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(27486, '蜜汁鸡翅', 'meat', '洋葱:290克#鸡翅:575克#食用油:45毫升#葱:35克#蜜汁:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 把所有调料放入腌制20分钟。###2. 然后烤盘下刷层油摆上鸡翅,洋葱也放进去烤。###3. 入烤箱230度30分钟就OK额,要是喜欢吃焦一点的,可以在20分钟的时候把鸡翅反过来再考考。###4. 最后扳盘开吃,扳的不怎么好看,凑合看吧,好吃才是真道理,是不是很简单呢。好吃的不行。###5. 完美', '禽类,热菜,家常菜,懒人食谱,烤箱', 'https://cp1.douguo.net/upload/caiku/b/0/3/yuan_b0546614edcee7bb658703652fe0d663.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###蜜汁|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 把所有调料放入腌制20分钟。###2. 然后烤盘下刷层油摆上鸡翅,洋葱也放进去烤。###3. 入烤箱230度30分钟就OK额,要是喜欢吃焦一点的,可以在20分钟的时候把鸡翅反过来再考考。###4. 最后扳盘开吃,扳的不怎么好看,凑合看吧,好吃才是真道理,是不是很简单呢。好吃的不行。###5. 完美', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(27540, '花肉炒木耳', 'meat', '五花肉:345克#木耳:35克#小米:290克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#蒜:30克#花肉:345克', '2名成年人总量+15%冗余', '1. 1 五花肉切成薄片###2. 2 木耳用温水泡发###3. 3 大蒜子拍碎 小米椒根据个人口味决定量 不吃辣的也可不加###4. 4 锅中下一点油 把五花肉煸出猪油 微微焦黄即可 再加入生抽一点老抽煸炒 放入大蒜子小米椒###5. 5 放入木耳翻炒 不用加盐 前面生抽和老抽咸度够了 翻炒片刻后起锅', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/2/2/d/yuan_222a2e2a8228eb3a4ca17c07aa1b1e3d.jpg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|菜名+步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 1 五花肉切成薄片###2. 2 木耳用温水泡发###3. 3 大蒜子拍碎 小米椒根据个人口味决定量 不吃辣的也可不加###4. 4 锅中下一点油 把五花肉煸出猪油 微微焦黄即可 再加入生抽一点老抽煸炒 放入大蒜子小米椒###5. 5 放入木耳翻炒 不用加盐 前面生抽和老抽咸度够了 翻炒片刻后起锅', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(2755, '川味麻辣鱼', 'meat', '鱼:690克#芹菜:400克#食用油:45毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#川味:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 把调料香料姜蒜花椒适量放盘子里###2. 把豆芽煮熟 把手倒掉、待用###3. 鱼用料酒 芡粉 腌制###4. 把配菜切好 待用###5. 油烧开 把盘子里的料倒入 炒香###6. 加入大半锅水,把鱼头放进去###7. 煮大概5分钟放入鱼骨和凉粉、大葱###8. 煮沸腾放入鱼片,芹菜###9. 之前待用的豆芽放盆地###10. 把煮好的鱼倒入盆子 放上香菜 香喷喷的麻辣鱼好了', '川菜,水产,热菜,麻辣,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/8/b/8/yuan_8bc9377c9b040ab948b5b1abe7ff8ed8.jpg', '困难', '90分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###川味|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 把调料香料姜蒜花椒适量放盘子里###2. 把豆芽煮熟 把手倒掉、待用###3. 鱼用料酒 芡粉 腌制###4. 把配菜切好 待用###5. 油烧开 把盘子里的料倒入 炒香###6. 加入大半锅水,把鱼头放进去###7. 煮大概5分钟放入鱼骨和凉粉、大葱###8. 煮沸腾放入鱼片,芹菜###9. 之前待用的豆芽放盆地###10. 把煮好的鱼倒入盆子 放上香菜 香喷喷的麻辣鱼好了', '[]', '来源步骤数: 10', '炒', 0, 0, NULL, NULL),
(27555, '小煎鸭', 'meat', '鸭肉:575克#小米:290克#食用油:45毫升#食盐:7克#料酒:30毫升#豆瓣酱:30克#姜:25克', '2名成年人总量+15%冗余', '1. 鸭肉剁成块洗净后沥水,待用###2. 条椒斜切成丝、嫩姜也切丝,小米辣剁碎,待用###3. 油温7成热下鸭肉,大火翻炒,倒一点料酒,爆香,稍微爆久一点、干一点炒至合适下豆瓣酱,继续炒出豆瓣香炒出豆瓣香后放小米辣,翻炒几下,倒1/3小碗清水,让爆香后的鸭肉吸水回去(以免鸭肉咬不动)接着放条椒、嫩姜丝,翻炒均匀后放盐、鸡精或鸡粉出锅', '禽类,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/c/6/1/yuan_c66faeeac6dda672e4ce7194c5d97081.jpg', '困难', '60分钟', '鸭肉|575|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 鸭肉剁成块洗净后沥水,待用###2. 条椒斜切成丝、嫩姜也切丝,小米辣剁碎,待用###3. 油温7成热下鸭肉,大火翻炒,倒一点料酒,爆香,稍微爆久一点、干一点炒至合适下豆瓣酱,继续炒出豆瓣香炒出豆瓣香后放小米辣,翻炒几下,倒1/3小碗清水,让爆香后的鸭肉吸水回去(以免鸭肉咬不动)接着放条椒、嫩姜丝,翻炒均匀后放盐、鸡精或鸡粉出锅', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(28086, '番茄炒蛋', 'meat', '鸡蛋:5个#西红柿:460克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 材料准备好###2. 番茄切丁,大蒜切片###3. 把鸡蛋打散###4. 锅里放油把蛋煎熟放一边备用###5. 锅里放油烧热后把番茄放进去炒两分钟###6. 最后放蛋进去一起翻炒,放入适量盐和鸡精就可以出锅了###7. 好了,美味下饭的番茄炒鸡蛋。', '禽类,蛋类,热菜,番茄味,晚餐,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/7/3/yuan_9789efe7f3782a89ac0c78f63ecf8e23.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 材料准备好###2. 番茄切丁,大蒜切片###3. 把鸡蛋打散###4. 锅里放油把蛋煎熟放一边备用###5. 锅里放油烧热后把番茄放进去炒两分钟###6. 最后放蛋进去一起翻炒,放入适量盐和鸡精就可以出锅了###7. 好了,美味下饭的番茄炒鸡蛋。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(28174, '番茄炒蛋', 'meat', '鸡蛋:5个#西红柿:460克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 番茄洗净切小块。###2. 鸡蛋打到碗里调入少许盐芫荽末。###3. 蒜茸、芫荽切碎。###4. 起油锅,倒入蛋液摊成饼,用锅铲在锅里把蛋液饼凿成几大块捞起。###5. 把摊蛋液的余油放进蒜茸爆香,蒜茸捞起。###6. 锅里倒入番茄中火翻炒,调入盐,差不多了把蛋液饼,爆香的蒜茸一起倒进去再翻炒几下。###7. 快起锅前放入芫荽末即可。###8. 起锅装盘。', '禽类,蛋类,热菜,番茄味,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/a/a/yuan_3a93dcd92022d1ae956d48b78f969a6a.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 番茄洗净切小块。###2. 鸡蛋打到碗里调入少许盐芫荽末。###3. 蒜茸、芫荽切碎。###4. 起油锅,倒入蛋液摊成饼,用锅铲在锅里把蛋液饼凿成几大块捞起。###5. 把摊蛋液的余油放进蒜茸爆香,蒜茸捞起。###6. 锅里倒入番茄中火翻炒,调入盐,差不多了把蛋液饼,爆香的蒜茸一起倒进去再翻炒几下。###7. 快起锅前放入芫荽末即可。###8. 起锅装盘。', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(28190, '榛蘑炖排骨', 'meat', '排骨:575克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#榛蘑:345克', '2名成年人总量+15%冗余', '1. 干榛蘑用水泡上2小时,排骨冷水下锅煮沸后,再清洗一遍备用。###2. 锅加热放少许油先煸炒排骨1分钟左右。###3. 接下来放榛蘑一起炒,淋料酒,加点生抽。###4. 加水没过排骨开始炖上。###5. 煮到水份少了,加点盐,小火继续煮一会入味。###6. 喜欢干点还是汤汁留点,自己看着办,出锅了。香', '肉类,热菜,晚餐,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/e/0/yuan_5eb2a16543c3fd8ee0e900ccb7d7c770.jpg', '困难', '60分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###榛蘑|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 干榛蘑用水泡上2小时,排骨冷水下锅煮沸后,再清洗一遍备用。###2. 锅加热放少许油先煸炒排骨1分钟左右。###3. 接下来放榛蘑一起炒,淋料酒,加点生抽。###4. 加水没过排骨开始炖上。###5. 煮到水份少了,加点盐,小火继续煮一会入味。###6. 喜欢干点还是汤汁留点,自己看着办,出锅了。香', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(28415, '零厨艺也能轻松蒸出的', 'meat', '火腿:290克#鱼:690克#食盐:7克#料酒:30毫升#姜:25克#零厨艺也能轻松:345克#出的:345克', '2名成年人总量+15%冗余', '1. 黄花鱼洗净抹干水分,鱼身上斜划几刀,火腿切薄片,姜切丝备用;###2. 用少许盐和黄酒将黄花鱼抹匀,腌制30分钟;###3. 将姜片放于鱼肚子里和划刀处;###4. 每个划刀处铺上少许火腿片;###5. 锅中烧开水,水开后将鱼放入;###6. 隔水蒸8分钟左右即可。', '水产,肉类,热菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/5/2/yuan_259be5e67a0f557a23c9f78cee7cd8b2.jpg', '普通', '45分钟', '火腿|290|克|主料|切片|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###零厨艺也能轻松|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###出的|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 黄花鱼洗净抹干水分,鱼身上斜划几刀,火腿切薄片,姜切丝备用;###2. 用少许盐和黄酒将黄花鱼抹匀,腌制30分钟;###3. 将姜片放于鱼肚子里和划刀处;###4. 每个划刀处铺上少许火腿片;###5. 锅中烧开水,水开后将鱼放入;###6. 隔水蒸8分钟左右即可。', '[]', '来源步骤数: 6', '蒸', 0, 0, NULL, NULL),
(28456, '香卤素鸡', 'meat', '芝麻:35克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克#干辣椒:15克#素鸡:345克', '2名成年人总量+15%冗余', '1. 简简单单备起来;###2. 素鸡切成厚约5mm左右的薄片,生姜切片,备用;###3. 锅中入橄榄油,将素鸡片入锅,中火煎至两面起泡,成金黄色,起锅,沥油;###4. 锅中余油,放姜片爆香,放入煎好的素鸡,加入干辣椒、八角、香叶,放白糖、食盐、菁选酱油、黄酒;###5. 加入清水,没过素鸡的量,香葱打结放入,大火煮至汤汁过半,转小火收汁,洒上芝麻,即可。', '禽类,肉类,热菜,下饭菜,下酒菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/7/8/4/yuan_7803bba520a3b967d87859388466e904.jpg', '普通', '20分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###素鸡|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 简简单单备起来;###2. 素鸡切成厚约5mm左右的薄片,生姜切片,备用;###3. 锅中入橄榄油,将素鸡片入锅,中火煎至两面起泡,成金黄色,起锅,沥油;###4. 锅中余油,放姜片爆香,放入煎好的素鸡,加入干辣椒、八角、香叶,放白糖、食盐、菁选酱油、黄酒;###5. 加入清水,没过素鸡的量,香葱打结放入,大火煮至汤汁过半,转小火收汁,洒上芝麻,即可。', '[]', '来源步骤数: 5', '煎', 0, 0, NULL, NULL),
(28475, '湖南青椒炒肉', 'meat', '青椒:205克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#湖南:345克', '2名成年人总量+15%冗余', '1. 都切好###2. 锅烧干,放入青椒,中火炒干水,盛出备用###3. 有必要可以把锅洗一遍,放油烧热放入姜,放入肉中火翻炒,放入盐,酱油炒制七成熟倒入辣椒一起炒,大火炒五分钟,放入鸡精倒入少量的水,翻炒两分钟即可上锅', '湘菜,禽类,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/9/5/2/yuan_95ef011587254d24496f04a7e175c912.jpg', '普通', '20分钟', '青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###湖南|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 都切好###2. 锅烧干,放入青椒,中火炒干水,盛出备用###3. 有必要可以把锅洗一遍,放油烧热放入姜,放入肉中火翻炒,放入盐,酱油炒制七成熟倒入辣椒一起炒,大火炒五分钟,放入鸡精倒入少量的水,翻炒两分钟即可上锅', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(28521, '鲜虾口蘑香椿卷儿', 'meat', '黑胡椒:6克#虾:520克#鸡蛋:5个#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 将白虾去壳、去除虾线拍打后斩碎成泥###2. 口蘑切粒###3. 将蛋清、盐、蚝油、黑胡椒碎、糖,加入虾肉中搅拌均匀###4. 鸡蛋打散,加入少许食用油,摊成薄厚均匀的蛋皮###5. 香椿放入开水中汆烫变色后捞出备用###6. 将搅拌好的虾肉均匀的涂抹在蛋皮上,烫好的香椿卷放在中间,用蛋液封口###7. 在卷好的蛋卷上刷一层食用油,放入烤箱。180度预热5分钟、烤制10分钟即可。', '京菜,海鲜,禽类,水产,蛋类,肉类,小吃,热菜,午餐,创意菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/9/d/1/yuan_9d72ec292488074bfc3208ed3c2fc971.jpg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 将白虾去壳、去除虾线拍打后斩碎成泥###2. 口蘑切粒###3. 将蛋清、盐、蚝油、黑胡椒碎、糖,加入虾肉中搅拌均匀###4. 鸡蛋打散,加入少许食用油,摊成薄厚均匀的蛋皮###5. 香椿放入开水中汆烫变色后捞出备用###6. 将搅拌好的虾肉均匀的涂抹在蛋皮上,烫好的香椿卷放在中间,用蛋液封口###7. 在卷好的蛋卷上刷一层食用油,放入烤箱。180度预热5分钟、烤制10分钟即可。', '[]', '来源步骤数: 7', '汆', 0, 0, NULL, NULL),
(28581, '口味虾', 'meat', '虾:520克#食用油:45毫升#食盐:7克#香醋:30毫升#口味:345克', '2名成年人总量+15%冗余', '1. 用盐醋水清洗干净,去头,去腮帮,去肠线,背部剪开。沥干水备用。###2. 准备好配料###3. 热油,油温要八成热###4. 虾子沥干水,过大油,待虾体通红时捞起备用###5. 重新倒入一些油,放入配料,煸香。###6. 倒入过大油的虾,翻炒。###7. 翻炒三分钟后,倒入小瓶啤酒,差不多没过虾就好,盖上盖子焖15分钟###8. 再翻炒,收汤汁,起锅', '湘菜,海鲜,水产,热菜,朋友聚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/1/4/yuan_d1ff91c910bb661ae83757f3687ce734.jpg', '困难', '60分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###口味|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 用盐醋水清洗干净,去头,去腮帮,去肠线,背部剪开。沥干水备用。###2. 准备好配料###3. 热油,油温要八成热###4. 虾子沥干水,过大油,待虾体通红时捞起备用###5. 重新倒入一些油,放入配料,煸香。###6. 倒入过大油的虾,翻炒。###7. 翻炒三分钟后,倒入小瓶啤酒,差不多没过虾就好,盖上盖子焖15分钟###8. 再翻炒,收汤汁,起锅', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(28678, '李孃孃爱厨房之一一蒜蓉蒸虾', 'meat', '玉米:460克#虾:520克#红椒:170克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#蒜:30克', '2名成年人总量+15%冗余', '1. 先上两张成品图哦!###2. 制作蒜蓉蒸虾的材料:虾子、蒜蓉、盐、生抽、青、红椒。###3. 去虾头。###4. 从背部用剪刀剪开,再用刀从背部片开,挑出虾线洗净,用少许的盐、料酒码味待用。 在虾码味的时候,准备适量的蒜蓉,准备一口锅,等锅热后倒入少许的油(调合油、玉米油都可以)准备好的蒜蓉(蒜蓉倒一半哈)炒成金黄色后倒入剩下的一半后铲两下起锅铲入一个小碗里待用,在准备一点大的青、红椒', '海鲜,水产,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/3/5/yuan_03b9d418820f256f9d2f09c07f75f0e5.jpg', '困难', '60分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤', '1. 先上两张成品图哦!###2. 制作蒜蓉蒸虾的材料:虾子、蒜蓉、盐、生抽、青、红椒。###3. 去虾头。###4. 从背部用剪刀剪开,再用刀从背部片开,挑出虾线洗净,用少许的盐、料酒码味待用。 在虾码味的时候,准备适量的蒜蓉,准备一口锅,等锅热后倒入少许的油(调合油、玉米油都可以)准备好的蒜蓉(蒜蓉倒一半哈)炒成金黄色后倒入剩下的一半后铲两下起锅铲入一个小碗里待用,在准备一点大的青、红椒', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(28688, '虾球', 'meat', '虾:520克#西红柿:460克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 大虾去头去皮,后背切开至1/2处,剔除虾线,拿料酒混一点点淀粉腌制10分钟;###2. 热锅凉油,两面煎到变色,注意不需要太多油噢~###3. 油、蒜末,一勺番茄酱,一勺白糖,炒香放入大虾;料酒少许,蚝油一勺,食盐适量;###4. 放入葱段,稍微焖2分钟,出锅。', '海鲜,水产,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/0/c/d/yuan_0c0fc9638c4cde79b302a7d8b290bf3d.jpg', '普通', '25分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 大虾去头去皮,后背切开至1/2处,剔除虾线,拿料酒混一点点淀粉腌制10分钟;###2. 热锅凉油,两面煎到变色,注意不需要太多油噢~###3. 油、蒜末,一勺番茄酱,一勺白糖,炒香放入大虾;料酒少许,蚝油一勺,食盐适量;###4. 放入葱段,稍微焖2分钟,出锅。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(2875, '卤鸡翅', 'meat', '鸡翅:575克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#姜:25克#蒜:30克#干辣椒:15克', '2名成年人总量+15%冗余', '1. 首先将翅中洗净,然后放锅开水汆一下,捞起备用!###2. 姜蒜拍扁备用,我个人放的比较多,因为我觉得放多点去腥效果很好,而且又香!###3. 锅烧热,放入白糖,使其溶化。###4. 然后放入少许油搅拌###5. 加入翅中翻炒,使其上色!###6. 然后放入姜蒜,盐,老抽,料酒,味精,干辣椒,八角###7. 加入适量水,没过翅中为佳###8. 大火煮十分钟左右收汁,出锅便可享用啦', '禽类,热菜,下饭菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/e/e/yuan_6ef57d4f6afcbb1ac842207dba78690e.jpg', '普通', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤', '1. 首先将翅中洗净,然后放锅开水汆一下,捞起备用!###2. 姜蒜拍扁备用,我个人放的比较多,因为我觉得放多点去腥效果很好,而且又香!###3. 锅烧热,放入白糖,使其溶化。###4. 然后放入少许油搅拌###5. 加入翅中翻炒,使其上色!###6. 然后放入姜蒜,盐,老抽,料酒,味精,干辣椒,八角###7. 加入适量水,没过翅中为佳###8. 大火煮十分钟左右收汁,出锅便可享用啦', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(28786, '东北泡菜烤肉', 'meat', '五花肉:345克#猪肉:345克#食用油:45毫升#食盐:7克#老抽:15毫升#姜:25克#葱:35克#东北泡菜:345克', '2名成年人总量+15%冗余', '1. 将姜丝,大葱,老抽, 盐, 胡椒和辣椒粉等调味料放入五花肉片中;###2. 搅拌均匀后腌制一刻钟;###3. 将东北泡菜切成细丝备用;###4. 将电饼铛的下烤盘通电源打开;###5. 待下烤盘指示灯熄灭后, 将腌好的肉片平铺在烤盘上;###6. 注意翻动, 直至五花肉油脂烤出, 且微微金黄;###7. 下入准备好的酸菜丝;###8. 翻炒均匀即可;###9. 层入盘中。', '东北菜,肉类,热菜,下饭菜,朋友聚餐,家常菜,电饼铛', 'https://cp1.douguo.net/upload/caiku/1/8/f/yuan_18dae9677b57453cd0cd95500f8f88ff.jpg', '困难', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###东北泡菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将姜丝,大葱,老抽, 盐, 胡椒和辣椒粉等调味料放入五花肉片中;###2. 搅拌均匀后腌制一刻钟;###3. 将东北泡菜切成细丝备用;###4. 将电饼铛的下烤盘通电源打开;###5. 待下烤盘指示灯熄灭后, 将腌好的肉片平铺在烤盘上;###6. 注意翻动, 直至五花肉油脂烤出, 且微微金黄;###7. 下入准备好的酸菜丝;###8. 翻炒均匀即可;###9. 层入盘中。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(28800, '麻辣香锅', 'meat', '虾:520克#鸡蛋:5个#土豆:460克#香菇:230克#菜花:520克#莲藕:460克#食用油:45毫升#葱:35克#香锅:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 倒油入锅,把所有调料炒香,再转大火加入去背线的基围虾爆炒###2. 将藕、土豆切片,香菇、花菜切块,绰水,备用。鹌鹑蛋煮熟去壳,备用###3. 把焯好水的蔬菜和鹌鹑蛋倒入锅中和基围虾一起翻炒。加入鸡精和葱段起锅!###4. 绝对正宗哦!', '禽类,水产,蛋类,热菜,麻辣,下饭菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/2/7/yuan_324c974ff9fb4f2812d9770c6ef5bc77.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###菜花|520|克|主料|掰小朵洗净|2名成年人总量+15%冗余|步骤###莲藕|460|克|主料|去皮切片或切丁|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###香锅|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 倒油入锅,把所有调料炒香,再转大火加入去背线的基围虾爆炒###2. 将藕、土豆切片,香菇、花菜切块,绰水,备用。鹌鹑蛋煮熟去壳,备用###3. 把焯好水的蔬菜和鹌鹑蛋倒入锅中和基围虾一起翻炒。加入鸡精和葱段起锅!###4. 绝对正宗哦!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(2892, '孜然小炒鸡', 'meat', '孜然:9克#鸡肉:520克#土豆:460克#青椒:205克#红椒:170克#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 配底材料改刀备好###2. 清水带肉煮沸捞出血水倒掉###3. 沥干水份拌入白糖、生抽、姜粒、豆瓣,搅拌均匀腌制二十分钟###4. 锅中油烧热烹香花椒取出,放鸡肉入锅煸炒出香味###5. 加适量清水煨炖鸡肉十分钟左右###6. 放入蒜粒土豆炖约十分钟###7. 土豆变软汤汁浓时加入尖椒、葱段翻炒一、两分钟,撒入孜然粒###8. 盛盘点麻油、放红椒点缀西域风味—孜然小炒鸡', '禽类,肉类,热菜,孜然,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/2/e/f/yuan_2e3c8071c70292dd997d5658f8adc7ef.jpg', '困难', '60分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 配底材料改刀备好###2. 清水带肉煮沸捞出血水倒掉###3. 沥干水份拌入白糖、生抽、姜粒、豆瓣,搅拌均匀腌制二十分钟###4. 锅中油烧热烹香花椒取出,放鸡肉入锅煸炒出香味###5. 加适量清水煨炖鸡肉十分钟左右###6. 放入蒜粒土豆炖约十分钟###7. 土豆变软汤汁浓时加入尖椒、葱段翻炒一、两分钟,撒入孜然粒###8. 盛盘点麻油、放红椒点缀西域风味—孜然小炒鸡', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(29037, '爪鱼炒茭白', 'meat', '鱼:690克#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#葱:35克#茭白:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 食材:八爪鱼,茭白。###2. 八鱼爪洗净用热水快速烫下再洗净,茭白切丝。###3. 调料:蚝油、少量生抽、少量糖加少量水调匀待用。###4. 热锅热油倒入姜葱煸香八爪鱼倒入爆炒变色。###5. 加入调料。###6. 倒入茭白煸炒加少量水收汁就好。', '海鲜,水产,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/4/6/yuan_f4154e9d9988b7ed3227a00d12b65746.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###茭白|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 食材:八爪鱼,茭白。###2. 八鱼爪洗净用热水快速烫下再洗净,茭白切丝。###3. 调料:蚝油、少量生抽、少量糖加少量水调匀待用。###4. 热锅热油倒入姜葱煸香八爪鱼倒入爆炒变色。###5. 加入调料。###6. 倒入茭白煸炒加少量水收汁就好。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(29068, '沙姜凤爪', 'meat', '柠檬:170克#鸡肉:520克#鱼:690克#白糖:55克#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 凤爪洗净,放入电压力锅加水和柠檬片压10分钟。###2. 解压后用清水漂洗凤爪,然后将凤爪放入加有柠檬的冰水里浸泡降温。###3. 鱼露、花雕、水按1:2:3的比例调好,然后加入适量的九层塔、沙姜、柠檬汁、冰糖煮成卤水。###4. 将凤爪从冰水中捞出沥干水分,加入卤水然后放冰箱保鲜层腌半天即可食用。', '川菜,禽类,水产,热菜,下饭菜,朋友聚餐,家常菜,电压力锅,压力锅', 'https://cp1.douguo.net/upload/caiku/5/5/5/yuan_55603a5f239e435c642244be3e891b85.jpg', '普通', '45分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 凤爪洗净,放入电压力锅加水和柠檬片压10分钟。###2. 解压后用清水漂洗凤爪,然后将凤爪放入加有柠檬的冰水里浸泡降温。###3. 鱼露、花雕、水按1:2:3的比例调好,然后加入适量的九层塔、沙姜、柠檬汁、冰糖煮成卤水。###4. 将凤爪从冰水中捞出沥干水分,加入卤水然后放冰箱保鲜层腌半天即可食用。', '[]', '来源步骤数: 4', '煮', 0, 0, NULL, NULL),
(29417, '洋葱烤鱼', 'meat', '洋葱:290克#鱼:690克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 将处理好的鳊鱼洗净,再将鱼身表面两边划上适量的刀口。###2. 用奥尔良腌料分别将鱼身两边涂满,鱼肚中也涂上腌料。###3. 再将切好的洋葱条用腌料腌好,撒在鱼上面,放入冰箱冷藏两个小时。###4. 在烤盘上铺上锡纸,腌好的洋葱铺在锡纸上,上面放上鱼再用锡纸将它们包好。###5. 放入烤箱中层,230度15分钟,装盘打开锡纸,美味的洋葱烤鱼就做好了。', '川菜,水产,热菜,午餐,一家三口,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/1/d/9/yuan_1df350f9a1ccf92ad5b3b2e1a3026539.jpg', '简单', '15分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将处理好的鳊鱼洗净,再将鱼身表面两边划上适量的刀口。###2. 用奥尔良腌料分别将鱼身两边涂满,鱼肚中也涂上腌料。###3. 再将切好的洋葱条用腌料腌好,撒在鱼上面,放入冰箱冷藏两个小时。###4. 在烤盘上铺上锡纸,腌好的洋葱铺在锡纸上,上面放上鱼再用锡纸将它们包好。###5. 放入烤箱中层,230度15分钟,装盘打开锡纸,美味的洋葱烤鱼就做好了。', '[]', '来源步骤数: 5', '烤', 0, 0, NULL, NULL),
(29433, '鲍鱼汁排骨煲', 'meat', '花生:170克#排骨:575克#鱼:690克#食用油:45毫升#淀粉:30克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 排骨洗净并用一小勺生粉及花生油腌制。###2. 倒油热锅将蒜头爆香,当蒜头变金黄将蒜头放到砂锅中。###3. 将排骨倒在锅里稍煎至两面金黄,并倒在砂锅中继续煮。###4. 在砂锅中倒入鲍鱼汁用中小火慢慢煮。###5. 排骨上色后加适量葱段。###6. 我喜欢把排骨上碟过滤锅中的油。', '肉类,水产,热菜,鲜,下酒菜,朋友聚餐,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/4/b/5/yuan_4b7b04126bd812790f49f0f46bddf025.jpg', '简单', '15分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 排骨洗净并用一小勺生粉及花生油腌制。###2. 倒油热锅将蒜头爆香,当蒜头变金黄将蒜头放到砂锅中。###3. 将排骨倒在锅里稍煎至两面金黄,并倒在砂锅中继续煮。###4. 在砂锅中倒入鲍鱼汁用中小火慢慢煮。###5. 排骨上色后加适量葱段。###6. 我喜欢把排骨上碟过滤锅中的油。', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(2947, '农家小炒牛肉', 'meat', '牛肉:400克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#豆瓣酱:30克#蒜:30克#葱:35克#农家小:345克', '2名成年人总量+15%冗余', '1. 将牛肉切片(牛肉切要选对肉的纹理有网纹方向切)、备料切段、蒜也最好切片味道不流失可以很好入味,备用。###2. 锅预热后倒入油,油热后将八角爆香放入蒜炒香,在放入牛肉翻炒微变色后放入豆瓣酱炒香加入少许白糖炒炒放入适量白酒(或料酒),入味后加入辣椒及葱,翻炒数下加入少许盐。准备出锅!###3. 如果有干锅迹象可以加一点水一起翻炒。最后装盘出锅!吃饭吧:)', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/e/8/a/yuan_e83a7634d128489a63c5a1097ef7a5ca.jpeg', '困难', '60分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###农家小|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 将牛肉切片(牛肉切要选对肉的纹理有网纹方向切)、备料切段、蒜也最好切片味道不流失可以很好入味,备用。###2. 锅预热后倒入油,油热后将八角爆香放入蒜炒香,在放入牛肉翻炒微变色后放入豆瓣酱炒香加入少许白糖炒炒放入适量白酒(或料酒),入味后加入辣椒及葱,翻炒数下加入少许盐。准备出锅!###3. 如果有干锅迹象可以加一点水一起翻炒。最后装盘出锅!吃饭吧:)', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(29483, '酱油与白糖就很', 'meat', '鸡翅:575克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡翅砍成琵琶腿与鸡中翅。###2. 将琵琶腿与鸡中翅放入料理碗,加入生抽、料酒与白糖腌制,最少腌制3个小时以上。###3. 取出腌制好的鸡翅,放在铺好锡纸的烤盘上。###4. 烤箱预热220°C放入,将烤盘放入烤箱中上层,上下火烤30分钟。###5. 中间取出翻面。###6. 取出烤好的鸡翅,装盘即可食用。', '禽类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/2/1/6/yuan_219a9d4813e59b7e03a784a338314936.jpg', '简单', '15分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡翅砍成琵琶腿与鸡中翅。###2. 将琵琶腿与鸡中翅放入料理碗,加入生抽、料酒与白糖腌制,最少腌制3个小时以上。###3. 取出腌制好的鸡翅,放在铺好锡纸的烤盘上。###4. 烤箱预热220°C放入,将烤盘放入烤箱中上层,上下火烤30分钟。###5. 中间取出翻面。###6. 取出烤好的鸡翅,装盘即可食用。', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(29497, '花肉烧白菜梗', 'meat', '毛豆:345克#五花肉:345克#猪肉:345克#香菇:230克#白菜:575克#萝卜:460克#食用油:45毫升#生抽:35毫升#老抽:15毫升#料酒:30毫升#豆瓣酱:30克#姜:25克#葱:35克#花肉:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 五花肉切片加料酒生抽姜片葱段腌渍。###2. 白菜梗洗净切段。###3. 蘑菇胡萝卜切片毛豆白果剥去壳。###4. 取二勺豆瓣酱。###5. 豆瓣酱加二勺凉水,加少量老抽调匀。###6. 坐锅热油,油比平常烧菜多放点。###7. 炉子开大火倒入肉片煸炒五分钟。###8. 再倒入其它食材煸炒三分钟加佐料翻炒五分钟入味就好了', '肉类,热菜,朋友聚餐,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/7/8/3/yuan_783598c25427eaccfe44522530963ac3.png', '普通', '20分钟', '毛豆|345|克|主料|剥壳洗净|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###白菜|575|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 五花肉切片加料酒生抽姜片葱段腌渍。###2. 白菜梗洗净切段。###3. 蘑菇胡萝卜切片毛豆白果剥去壳。###4. 取二勺豆瓣酱。###5. 豆瓣酱加二勺凉水,加少量老抽调匀。###6. 坐锅热油,油比平常烧菜多放点。###7. 炉子开大火倒入肉片煸炒五分钟。###8. 再倒入其它食材煸炒三分钟加佐料翻炒五分钟入味就好了', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(29578, '清淡爽口又的小炒', 'meat', '枸杞:25克#虾:520克#食用油:45毫升#食盐:7克#清淡爽口又的小:345克', '2名成年人总量+15%冗余', '1. 卷心菜手撕成片;虾米提前泡一下。###2. 锅中放少许油,油热后放入卷心菜翻炒至变软;###3. 放入虾米继续翻炒,加入适量水(根据个人喜好,我喜欢汤多的,就多加一些水),盖锅盖小火焖几分钟。###4. 开盖放入鸡精、少许盐,枸杞,即可出锅装盘。', '禽类,水产,热菜,清淡,爽口,家常菜', 'https://cp1.douguo.net/upload/caiku/e/8/b/yuan_e83ada54bb917374535b636b563149ab.jpg', '简单', '15分钟', '枸杞|25|克|辅料|洗净备用|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###清淡爽口又的小|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 卷心菜手撕成片;虾米提前泡一下。###2. 锅中放少许油,油热后放入卷心菜翻炒至变软;###3. 放入虾米继续翻炒,加入适量水(根据个人喜好,我喜欢汤多的,就多加一些水),盖锅盖小火焖几分钟。###4. 开盖放入鸡精、少许盐,枸杞,即可出锅装盘。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(29697, '香辣虾', 'meat', '虾:520克#土豆:460克#食用油:45毫升#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 鲜虾剪须,背部剖一刀便于入味###2. 准备时蔬,切片###3. 土豆切片泡水,去淀粉,保持脆度###4. 锅煮开水,将虾倒入,同时放二片姜,两勺黄酒,煮沸2分钟后捞起###5. 锅内倒油,姜切丝蒜切未爆炒出香味###6. 加入豆豉爆香###7. 倒入时蔬翻炒六成熟###8. 倒入煮好虾子,同时加入调料,翻炒入味后盛出装盘', '海鲜,水产,热菜,香辣,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/2/6/yuan_820f0739fb4ebcf8f0127428936ad956.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鲜虾剪须,背部剖一刀便于入味###2. 准备时蔬,切片###3. 土豆切片泡水,去淀粉,保持脆度###4. 锅煮开水,将虾倒入,同时放二片姜,两勺黄酒,煮沸2分钟后捞起###5. 锅内倒油,姜切丝蒜切未爆炒出香味###6. 加入豆豉爆香###7. 倒入时蔬翻炒六成熟###8. 倒入煮好虾子,同时加入调料,翻炒入味后盛出装盘', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL);
INSERT INTO eatwhat_food_import (id, name, type, cl, fl, step, tags, image, difficulty, cook_time, ingredients_amounts, steps, step_images, tips, methods, kcal, is_custom, user_id, create_time) VALUES
(29889, '花肉炒笋', 'meat', '洋葱:290克#五花肉:345克#竹笋:460克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#蒜:30克#葱:35克#花肉:345克', '2名成年人总量+15%冗余', '1. 笋切片后在滚水里焯5-10分钟,可适量加点盐入味,然后捞出锅沥干水分。###2. 将油锅烧热,倒入蒜头、五花肉煸油,待五花肉略有些焦黄时,倒入笋片翻炒。###3. 而后加入适量盐、生抽、料酒、白糖、水、胡萝卜、洋葱,继续爆炒至水微干后,加蒜苗、青红辣椒炒几下即可出锅。', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/0/d/1/yuan_0d200d04f01b5551e06a398f014d1b01.jpg', '困难', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 笋切片后在滚水里焯5-10分钟,可适量加点盐入味,然后捞出锅沥干水分。###2. 将油锅烧热,倒入蒜头、五花肉煸油,待五花肉略有些焦黄时,倒入笋片翻炒。###3. 而后加入适量盐、生抽、料酒、白糖、水、胡萝卜、洋葱,继续爆炒至水微干后,加蒜苗、青红辣椒炒几下即可出锅。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(29989, '香辣红烧带鱼不放一滴水的醇香', 'meat', '鱼:690克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. 带鱼洗净。用剪刀帮忙拆去鱼鳃后用手拉出来###2. 切成小块后放在碗里备用###3. 尖椒切圈。姜切厚片。蒜拍扁###4. 起油锅。放入带鱼块和1茶匙盐。放入之后不要立即翻动###5. 一面煎透了再翻面。煎至两面金黄###6. 放入青椒圈和姜蒜翻炒一下###7. 烹入酱油,料酒和糖翻炒一会儿至汤汁收浓即可其实反正汤汁里面不含水。可以不用收很浓。汤汁拌饭真的是超超超超超好吃QAQ', '鲁菜,海鲜,肉类,水产,热菜,香辣,朋友聚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/b/6/yuan_2b5d93a6d1c058155ee5b58bdbf69fe6.jpg', '困难', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 带鱼洗净。用剪刀帮忙拆去鱼鳃后用手拉出来###2. 切成小块后放在碗里备用###3. 尖椒切圈。姜切厚片。蒜拍扁###4. 起油锅。放入带鱼块和1茶匙盐。放入之后不要立即翻动###5. 一面煎透了再翻面。煎至两面金黄###6. 放入青椒圈和姜蒜翻炒一下###7. 烹入酱油,料酒和糖翻炒一会儿至汤汁收浓即可其实反正汤汁里面不含水。可以不用收很浓。汤汁拌饭真的是超超超超超好吃QAQ', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(30167, '香酥鸡柳', 'meat', '鸡肉:520克#虾:520克#鸡蛋:5个#食用油:45毫升#料酒:30毫升#淀粉:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡胸肉切条,加鸡蛋,淀粉,料酒抓捏腌制10分钟。###2. 面包糠和炸鸡粉混合###3. 鸡柳沾上混合粉###4. 完全裹均匀###5. 下油锅小火慢炸###6. 大火炸至金黄色捞出即可###7. 还炸了点虾片一起,嘿嘿沾千岛酱不但能解腻更有一番滋味哦!###8. 趁热开吃吧,怕胖的可以裹好粉烤箱上下火180度烤20分钟哦,一样美味!(每家烤箱不同,请大家酌情调试)', '禽类,水产,蛋类,肉类,小吃,热菜,香酥,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/d/c/3/yuan_dca3c6b5ce4f4fc57b22d4b983eef833.jpeg', '普通', '20分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡胸肉切条,加鸡蛋,淀粉,料酒抓捏腌制10分钟。###2. 面包糠和炸鸡粉混合###3. 鸡柳沾上混合粉###4. 完全裹均匀###5. 下油锅小火慢炸###6. 大火炸至金黄色捞出即可###7. 还炸了点虾片一起,嘿嘿沾千岛酱不但能解腻更有一番滋味哦!###8. 趁热开吃吧,怕胖的可以裹好粉烤箱上下火180度烤20分钟哦,一样美味!(每家烤箱不同,请大家酌情调试)', '[]', '来源步骤数: 8', '炸', 0, 0, NULL, NULL),
(3032, '沙锅版五香红烧肉', 'meat', '五香粉:6克#五花肉:345克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#老抽:15毫升#姜:25克', '2名成年人总量+15%冗余', '1. 五花肉,切约2-3厘米宽四方形的块。###2. 锅热,加少许油,加两勺糖,用铲划开,待糖化后,将肉倒入。中火翻炒,待肉变成金黄色。###3. 锅中加两小碗水,能把肉淹住即可。水开后,全部倒入砂锅。如无砂锅,可以就直接在铁锅中做。用砂锅更香些。###4. 水开后,倒入所有香料,姜,加盐,生抽,老抽,少许五香粉和胡椒粉。转小火煮半小时,大功告成!', '肉类,热菜,五香,朋友聚餐,下饭菜,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/d/d/a/yuan_dd5346eed781b95ccd796ae71d0271aa.jpg', '简单', '15分钟', '五香粉|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 五花肉,切约2-3厘米宽四方形的块。###2. 锅热,加少许油,加两勺糖,用铲划开,待糖化后,将肉倒入。中火翻炒,待肉变成金黄色。###3. 锅中加两小碗水,能把肉淹住即可。水开后,全部倒入砂锅。如无砂锅,可以就直接在铁锅中做。用砂锅更香些。###4. 水开后,倒入所有香料,姜,加盐,生抽,老抽,少许五香粉和胡椒粉。转小火煮半小时,大功告成!', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(30423, '空气炸锅之辣子鸡块', 'meat', '鸡腿:575克#鸡肉:520克#小米:290克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克#干辣椒:15克#花椒:6克#空气:345克#锅之辣子:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将鸡腿肉剁成小块。放小米椒姜,料酒,白酒腌制一下。###2. 炸锅先180度预热后放入鸡块,炸5分钟,再200度炸5分钟。###3. 准备好葱姜花椒###4. 干红辣椒掰成段###5. 热锅凉油先将葱姜花椒炒香,要始终大火。###6. 加入干辣椒炒###7. 放入煸好的鸡块大火炒,最后放点酱油翻炒几下即可', '川菜,禽类,肉类,热菜,晚餐,朋友聚餐,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/3/d/f/yuan_3d74972df1c6ad6a56ed29fc87bace0f.jpg', '普通', '20分钟', '鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###空气|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###锅之辣子|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将鸡腿肉剁成小块。放小米椒姜,料酒,白酒腌制一下。###2. 炸锅先180度预热后放入鸡块,炸5分钟,再200度炸5分钟。###3. 准备好葱姜花椒###4. 干红辣椒掰成段###5. 热锅凉油先将葱姜花椒炒香,要始终大火。###6. 加入干辣椒炒###7. 放入煸好的鸡块大火炒,最后放点酱油翻炒几下即可', '[]', '来源步骤数: 7', '炸', 0, 0, NULL, NULL),
(30488, '火腿肠', 'meat', '火腿:290克#猪肉:345克#鸡蛋:5个#土豆:460克#食用油:45毫升#生抽:35毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 1、猪肉和土豆洗净,切块,放入搅拌器,加入一个生鸡蛋,打成肉泥。(越细越好)###2. 2、将打好的肉泥倒入容器,容器在桌上掂几下,使肉泥变实。上火蒸熟。###3. 3、将蒸好的肉泥倒扣在盆子里,切片就能给宝宝吃啦!###4. 4、如果要加味道的话此时也能加,淋上麻油和生抽即可。也可将肉块切条炒菜或与其他菜凉拌。', '肉类,禽类,蛋类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/7/1/yuan_17bcca169ee84f80df9bb40eb796a2d1.jpg', '普通', '20分钟', '火腿|290|克|主料|切片|2名成年人总量+15%冗余|菜名###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 1、猪肉和土豆洗净,切块,放入搅拌器,加入一个生鸡蛋,打成肉泥。(越细越好)###2. 2、将打好的肉泥倒入容器,容器在桌上掂几下,使肉泥变实。上火蒸熟。###3. 3、将蒸好的肉泥倒扣在盆子里,切片就能给宝宝吃啦!###4. 4、如果要加味道的话此时也能加,淋上麻油和生抽即可。也可将肉块切条炒菜或与其他菜凉拌。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(30600, '香辣烤猪手', 'meat', '芝麻:35克#白糖:55克#生抽:35毫升#老抽:15毫升#猪手:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 猪手斩平块洗干净,放入锅中,加水没过猪手,加入卤味包,老抽,生抽,糖,大火煮开小火炖一个小时,到筷子轻轻可以戳穿即可。###2. 煮好的猪手不要捞出来,放在卤味汁里浸泡隔夜。###3. 隔夜后取出猪手,猪皮朝上一个个摆好在铺了锡纸的烤盘中。###4. 表面撒上辣椒粉、白芝麻。也可以做原味的表面刷蜂蜜然后撒上白芝麻。###5. 风干一个小时,烤箱预热180度烘烤20分钟取出。', '肉类,热菜,香辣,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/f/d/5/yuan_fdc08e8d9175381cc3debad5e76e9f05.jpg', '困难', '60分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###猪手|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 猪手斩平块洗干净,放入锅中,加水没过猪手,加入卤味包,老抽,生抽,糖,大火煮开小火炖一个小时,到筷子轻轻可以戳穿即可。###2. 煮好的猪手不要捞出来,放在卤味汁里浸泡隔夜。###3. 隔夜后取出猪手,猪皮朝上一个个摆好在铺了锡纸的烤盘中。###4. 表面撒上辣椒粉、白芝麻。也可以做原味的表面刷蜂蜜然后撒上白芝麻。###5. 风干一个小时,烤箱预热180度烘烤20分钟取出。', '[]', '来源步骤数: 5', '炖', 0, 0, NULL, NULL),
(30682, '手工香菇肉丸', 'meat', '花生:170克#玉米:460克#猪肉:345克#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克#淀粉:30克', '2名成年人总量+15%冗余', '1. 新鲜猪肉二肥八瘦,剁碎,(肉机绞不好吃)自己剁口感好,剁好后用杆面棍捶肉末,不断捶,肉沾手就基本行了。###2. 肉末捶好下香菇,下适量盐,适量白糖,适量玉米淀粉,花生油适量拌匀做成丸子。###3. 锅注入清水燒沸,将肉丸遂一下锅,中小火煮至熟。肉丸如果做多吃不完可放速冻,配蔬菜,瓜之类煮汤很鲜美。###4. 香菇肉丸煮汤配上杂蔬很美味###5. 自己动手做的丸了吃的放心,易做!', '肉类,热菜,午餐,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/f/1/a/yuan_f18df26eb1cb3d7a9f9c426e5f576f0a.jpg', '困难', '20分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 新鲜猪肉二肥八瘦,剁碎,(肉机绞不好吃)自己剁口感好,剁好后用杆面棍捶肉末,不断捶,肉沾手就基本行了。###2. 肉末捶好下香菇,下适量盐,适量白糖,适量玉米淀粉,花生油适量拌匀做成丸子。###3. 锅注入清水燒沸,将肉丸遂一下锅,中小火煮至熟。肉丸如果做多吃不完可放速冻,配蔬菜,瓜之类煮汤很鲜美。###4. 香菇肉丸煮汤配上杂蔬很美味###5. 自己动手做的丸了吃的放心,易做!', '[]', '来源步骤数: 5', '煮', 0, 0, NULL, NULL),
(30696, '鲜香鲈鱼', 'meat', '枸杞:25克#鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#姜:25克#葱:35克#鲜香:345克', '2名成年人总量+15%冗余', '1. 鲈鱼去鳞从背部开一刀把整鱼切成平面,不要洗,把内脏取出,抹少量盐,腌制15分钟。###2. 15分钟后,把鱼洗干净,趴在盘子里。###3. 放几片生姜###4. 菁选酱油少许###5. 白糖6g醋是酱油的2倍 搅拌均匀###6. 水半锅烧开后放鱼蒸10分钟###7. 10分钟后,倒掉鱼水,放葱花 枸杞,淋上刚才配置的菁选酱油汁。美味极了!', '海鲜,水产,热菜,晚餐,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/d/3/8/yuan_d39b4dc109a1265d7d47608f13b81b98.jpg', '普通', '25分钟', '枸杞|25|克|辅料|洗净备用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###鲜香|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鲈鱼去鳞从背部开一刀把整鱼切成平面,不要洗,把内脏取出,抹少量盐,腌制15分钟。###2. 15分钟后,把鱼洗干净,趴在盘子里。###3. 放几片生姜###4. 菁选酱油少许###5. 白糖6g醋是酱油的2倍 搅拌均匀###6. 水半锅烧开后放鱼蒸10分钟###7. 10分钟后,倒掉鱼水,放葱花 枸杞,淋上刚才配置的菁选酱油汁。美味极了!', '[]', '来源步骤数: 7', '蒸', 0, 0, NULL, NULL),
(30709, '焖汁荷包蛋香汁荷包蛋', 'meat', '鸡蛋:5个#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#葱:35克', '2名成年人总量+15%冗余', '1. 把葱切末、用适量的糖、盐、鸡精与酱油调成汁备用。###2. 将油锅烧热,打入鸡蛋炸至金黄即可。###3. 将鸡蛋翻个把另一面煎至金黄色(如图程度)、鸡蛋就煎好了出锅备用。###4. 锅中留少许油,把葱末爆香这时将鸡蛋下锅加入调好香汁和少量的凉开水焖煮收汁。###5. 最后点缀点香菜出锅淋上少许香油更佳。###6. 如果是用早餐,再配合1碗香喷喷的粥和一个小咸菜那将是绝配,超级美味!', '蛋类,禽类,热菜,早餐食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/0/5/7/yuan_05f251cabfef83737c07292ed079a577.jpg', '普通', '20分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 把葱切末、用适量的糖、盐、鸡精与酱油调成汁备用。###2. 将油锅烧热,打入鸡蛋炸至金黄即可。###3. 将鸡蛋翻个把另一面煎至金黄色(如图程度)、鸡蛋就煎好了出锅备用。###4. 锅中留少许油,把葱末爆香这时将鸡蛋下锅加入调好香汁和少量的凉开水焖煮收汁。###5. 最后点缀点香菜出锅淋上少许香油更佳。###6. 如果是用早餐,再配合1碗香喷喷的粥和一个小咸菜那将是绝配,超级美味!', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(30764, '文鱼新吃', 'meat', '芝麻:35克#黑胡椒:6克#鱼:690克#白糖:55克#食盐:7克', '2名成年人总量+15%冗余', '1. 三文鱼洗净控干水分,放在盆里撒上盐和糖充分抹匀腌制;荸荠削皮切成碎末###2. 五分钟后,在盆里倒入白葡萄酒,撒入小茴香和黑胡椒碎,研制一小时,最好放进冰箱冷藏###3. 一小时后,腌制好的三文鱼从冰箱取出,用刀呈45度斜切。切好的鱼片并排叠放,第二片要叠放在第一片的三分之二处。以此类推,四片并排好往中心卷,卷好的花儿中间撒上荸荠末和黑芝麻即可。', '海鲜,水产,凉菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/8/b/yuan_c8334d23ed52c35eed2a19d59529e73b.jpg', '普通', '25分钟', '芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 三文鱼洗净控干水分,放在盆里撒上盐和糖充分抹匀腌制;荸荠削皮切成碎末###2. 五分钟后,在盆里倒入白葡萄酒,撒入小茴香和黑胡椒碎,研制一小时,最好放进冰箱冷藏###3. 一小时后,腌制好的三文鱼从冰箱取出,用刀呈45度斜切。切好的鱼片并排叠放,第二片要叠放在第一片的三分之二处。以此类推,四片并排好往中心卷,卷好的花儿中间撒上荸荠末和黑芝麻即可。', '[]', '来源步骤数: 3', '腌', 0, 0, NULL, NULL),
(31040, '辅食肉末胡萝卜笋丝', 'meat', '莴笋:460克#猪肉:345克#鸡肉:520克#竹笋:460克#萝卜:460克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 莴笋去皮,我削的比较厚,这样不会有嚼不烂的地方###2. 切成宝宝能接受的大小###3. 鸡胸肉打碎###4. 加油放锅中翻炒###5. 放入切好的胡萝卜###6. 笋丝,加适量的水稍微焖一会儿,软一点好消化###7. 我没有加盐,妈妈们可以根据宝宝情况加少许盐,不加也可以的,胡萝卜和莴笋都有点甜甜的。', '禽类,肉类,热菜,午餐,幼儿食谱,家常菜', 'https://cp1.douguo.net/upload/caiku/5/1/4/yuan_51e4e0f8c95b7c99902682610284b7d4.jpg', '普通', '20分钟', '莴笋|460|克|主料|去皮切片|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 莴笋去皮,我削的比较厚,这样不会有嚼不烂的地方###2. 切成宝宝能接受的大小###3. 鸡胸肉打碎###4. 加油放锅中翻炒###5. 放入切好的胡萝卜###6. 笋丝,加适量的水稍微焖一会儿,软一点好消化###7. 我没有加盐,妈妈们可以根据宝宝情况加少许盐,不加也可以的,胡萝卜和莴笋都有点甜甜的。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(31108, '番茄控之番茄牛肉', 'meat', '牛肉:400克#西红柿:460克#葱:35克#控之:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 各种主材,辅材大集合 番茄切的很碎,这样炒起来更好出汁。一边高压锅炖清水牛肉,炖到差不多另一边起锅炒番茄浓汤mix###2. 将牛肉倒入番茄锅中,加点儿炖牛肉的汤,盖盖闷煮,让番茄mix充分渗入牛肉,半个多小时的样子###3. finally, 小葱飘落~再来点儿小酒,康忙!康忙!', '肉类,热菜,番茄味,一家三口,午餐,朋友聚餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/2/4/b/yuan_2437bc5279a4b6216117946c0eb7805b.jpg', '普通', '25分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###控之|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 各种主材,辅材大集合 番茄切的很碎,这样炒起来更好出汁。一边高压锅炖清水牛肉,炖到差不多另一边起锅炒番茄浓汤mix###2. 将牛肉倒入番茄锅中,加点儿炖牛肉的汤,盖盖闷煮,让番茄mix充分渗入牛肉,半个多小时的样子###3. finally, 小葱飘落~再来点儿小酒,康忙!康忙!', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(31340, '花肉烧土豆丁', 'meat', '五花肉:345克#土豆:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#花肉:345克', '2名成年人总量+15%冗余', '1. 土豆洗净切丁,五花肉切条状;###2. 热锅热油后将五花肉和姜片下锅,待五花肉至金黄色时将土豆丁倒入一起翻炒小会儿,倒入盐,料酒,酱油;###3. 倒入清水与菜量相等后大火煮(可以放入八角,味道更好哦!),待快熟时小火收汁即可;', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/4/0/yuan_f420777cda9dcc9334b51c1ecc4b5150.jpg', '简单', '15分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###花肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 土豆洗净切丁,五花肉切条状;###2. 热锅热油后将五花肉和姜片下锅,待五花肉至金黄色时将土豆丁倒入一起翻炒小会儿,倒入盐,料酒,酱油;###3. 倒入清水与菜量相等后大火煮(可以放入八角,味道更好哦!),待快熟时小火收汁即可;', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(31471, '西红柿牛腩', 'meat', '洋葱:290克#牛肉:400克#鱼:690克#西红柿:460克#白菜:575克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 牛肉入水飞血沫后''把姜''八角''白酒''生抽和蒸鱼豉油倒去高压锅''放入开水''开水没过肉即可!此处不宜放盐''因为需要二次加工!###2. 热锅倒入橄榄油''炒番茄''洋葱''胡萝卜''放入番茄酱''韩式辣酱''糖''然后把刚才煮的肉连同汤直接倒入锅内''最后将菠萝切成沫放入''放入适量盐~###3. 待汤汁将收尽时''放入圆白菜''出锅即可!', '肉类,水产,热菜,午餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/3/5/a/yuan_3565c256bb10d0c58146b24030e3771a.jpg', '困难', '60分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###白菜|575|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 牛肉入水飞血沫后''把姜''八角''白酒''生抽和蒸鱼豉油倒去高压锅''放入开水''开水没过肉即可!此处不宜放盐''因为需要二次加工!###2. 热锅倒入橄榄油''炒番茄''洋葱''胡萝卜''放入番茄酱''韩式辣酱''糖''然后把刚才煮的肉连同汤直接倒入锅内''最后将菠萝切成沫放入''放入适量盐~###3. 待汤汁将收尽时''放入圆白菜''出锅即可!', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(31480, '花肉爆炒茶树菇', 'meat', '五花肉:345克#青椒:205克#香菇:230克#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#花肉爆:345克#食用油:45毫升', '2名成年人总量+15%冗余', '1. 五花肉切薄片,青椒切丝,茶树菇泡发洗净,葱姜蒜切碎备用###2. 小火下五花肉煸至肥肉部分透明,然后放入花椒,姜蒜爆香,放入青椒丝翻炒,放入茶树菇翻炒均匀,放入少许生抽,料酒调味,中间可以加点泡茶树菇的水,待汁收干,起锅时放盐和葱花即可###3. 装盘出锅,肉香菌香四溢~', '肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/9/9/f/yuan_99a3668df51881b5a21dbf5c0147192f.jpg', '普通', '20分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###花肉爆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全', '1. 五花肉切薄片,青椒切丝,茶树菇泡发洗净,葱姜蒜切碎备用###2. 小火下五花肉煸至肥肉部分透明,然后放入花椒,姜蒜爆香,放入青椒丝翻炒,放入茶树菇翻炒均匀,放入少许生抽,料酒调味,中间可以加点泡茶树菇的水,待汁收干,起锅时放盐和葱花即可###3. 装盘出锅,肉香菌香四溢~', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(31493, '砂锅排骨煲酸菜', 'meat', '排骨:575克#豆腐:460克#香菇:230克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克#花椒:6克#砂锅:345克#酸菜:345克', '2名成年人总量+15%冗余', '1. 把排骨抄水去掉血沫,加姜葱、大料、花椒粉、香叶、料酒、小茴香、酱油腌制十分钟左右###2. 砂锅加水,大火煮开,加入腌制好的排骨和调料,煮开后转小火煲半小时左右。###3. 在砂锅里加入少量冰糖或白糖,切好的香菇,腐乳汤和酸菜、豆腐、小火半小时左右###4. 出锅前根据喜好加盐,撒点葱花,出锅', '肉类,热菜,鲜,下酒菜,朋友聚餐,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/a/b/5/yuan_ab3766934bc622b0a7228dd42eab1065.jpg', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###砂锅|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###酸菜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 把排骨抄水去掉血沫,加姜葱、大料、花椒粉、香叶、料酒、小茴香、酱油腌制十分钟左右###2. 砂锅加水,大火煮开,加入腌制好的排骨和调料,煮开后转小火煲半小时左右。###3. 在砂锅里加入少量冰糖或白糖,切好的香菇,腐乳汤和酸菜、豆腐、小火半小时左右###4. 出锅前根据喜好加盐,撒点葱花,出锅', '[]', '来源步骤数: 4', '煲', 0, 0, NULL, NULL),
(31671, '分钟自制新鲜虾皮', 'meat', '虾:520克#食盐:7克#料酒:30毫升#姜:25克', '2名成年人总量+15%冗余', '1. 用料酒一勺,胡椒粉,姜粉、盐适量把虾皮腌一下;###2. 因为买来的虾是活的,进微波炉怕他们乱蹦,所以先放个碗里,罩上保鲜膜,高火一分钟热熟了;###3. 再找个平底的盘子,尽可能把虾摊开,撒上细盐,拌匀;###4. 进微波炉,设置2分钟中高火,好了就拿出来,再翻匀下,重复四次,虾皮就好了,一共所需8分钟。###5. 装入密封的罐子,保存。', '海鲜,水产,热菜,朋友聚餐,幼儿食谱,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/8/8/b/yuan_88dccab0d669178eecc091799d6de82b.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 用料酒一勺,胡椒粉,姜粉、盐适量把虾皮腌一下;###2. 因为买来的虾是活的,进微波炉怕他们乱蹦,所以先放个碗里,罩上保鲜膜,高火一分钟热熟了;###3. 再找个平底的盘子,尽可能把虾摊开,撒上细盐,拌匀;###4. 进微波炉,设置2分钟中高火,好了就拿出来,再翻匀下,重复四次,虾皮就好了,一共所需8分钟。###5. 装入密封的罐子,保存。', '[]', '来源步骤数: 5', '微波', 0, 0, NULL, NULL),
(31724, '烧烤味孜然盐煎肉', 'meat', '洋葱:290克#孜然:9克#黑胡椒:6克#猪肉:345克#食用油:45毫升#食盐:7克#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 瘦肉切薄厚适中的片,洋葱切丝(洋葱可以不要或者换成葱姜丝)。###2. 加入盐,黑胡椒粉,孜然粉等所有辅料。###3. 抓匀,放入保鲜盒冰箱冷藏腌制一晚。###4. 平底锅不放油,直接将肉片平铺中小火慢慢煎。###5. 中途翻一下面,煎至两面焦黄即可,出锅前再撒点孜然粉和胡椒粉。###6. 吃辣的话再撒点辣椒面。肉煎好后把洋葱煎煎也很好吃,我这里就不拍了。', '川菜,肉类,热菜,孜然,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/b/8/d/yuan_b8dcef2b7a196cafa71760488d4e675d.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名+步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 瘦肉切薄厚适中的片,洋葱切丝(洋葱可以不要或者换成葱姜丝)。###2. 加入盐,黑胡椒粉,孜然粉等所有辅料。###3. 抓匀,放入保鲜盒冰箱冷藏腌制一晚。###4. 平底锅不放油,直接将肉片平铺中小火慢慢煎。###5. 中途翻一下面,煎至两面焦黄即可,出锅前再撒点孜然粉和胡椒粉。###6. 吃辣的话再撒点辣椒面。肉煎好后把洋葱煎煎也很好吃,我这里就不拍了。', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(31744, '辣炒猪油渣', 'meat', '韭菜:400克#食用油:45毫升#生抽:35毫升#老抽:15毫升#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 蒜切片,韭菜切短,辣椒切丁备用。###2. 这是炼猪油剩下的油渣。###3. 切成小丁备用。###4. 锅里适量的油,爆香蒜皮。###5. 放入辣椒断生。###6. 再加入韭菜,韭菜比较容易出水,所以晚放。###7. 倒入切碎的猪油渣。###8. 加少许老抽,蚝油和生抽调味,拌匀即可出锅。###9. 成品。下饭或者拌个面啥的那是妥妥的。', '肉类,水产,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/1/9/c/yuan_192beb1bb460fc351624c89712ce173c.jpg', '困难', '20分钟', '韭菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 蒜切片,韭菜切短,辣椒切丁备用。###2. 这是炼猪油剩下的油渣。###3. 切成小丁备用。###4. 锅里适量的油,爆香蒜皮。###5. 放入辣椒断生。###6. 再加入韭菜,韭菜比较容易出水,所以晚放。###7. 倒入切碎的猪油渣。###8. 加少许老抽,蚝油和生抽调味,拌匀即可出锅。###9. 成品。下饭或者拌个面啥的那是妥妥的。', '[]', '来源步骤数: 9', '炒', 0, 0, NULL, NULL),
(31768, '洋葱肉末', 'meat', '洋葱:290克#猪肉:345克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#葱:35克', '2名成年人总量+15%冗余', '1. 洋葱洗净切小粒,肉末备好。###2. 锅底下少许油加热,先煸炒洋葱。###3. 洋葱出香味,加入肉末翻炒。###4. 接下来放料酒,盐、生抽,炒一会,加水煮。(喜欢拌饭吃,水可以多放一些)###5. 水开转小水再炖上5分钟,汤汁更浓郁,撒上葱花出锅。###6. 出来了。###7. 拌饭了。', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/6/e/yuan_d6c84ee98ccff6e3ed322852180e168e.jpg', '普通', '20分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|菜名+步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|菜名+步骤', '1. 洋葱洗净切小粒,肉末备好。###2. 锅底下少许油加热,先煸炒洋葱。###3. 洋葱出香味,加入肉末翻炒。###4. 接下来放料酒,盐、生抽,炒一会,加水煮。(喜欢拌饭吃,水可以多放一些)###5. 水开转小水再炖上5分钟,汤汁更浓郁,撒上葱花出锅。###6. 出来了。###7. 拌饭了。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(31864, '蜂蜜烤鸡翅', 'meat', '鸡翅:575克#姜:25克#蒜:30克#蜂蜜:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 之所以选择8只,是因为正好够一家三口的量。头天晚上鸡翅洗净,化冻###2. 生姜、大蒜切小块,把除蜂蜜以外的材料全部到鸡翅里,拌匀。盖上保鲜膜,冰箱保鲜层腌渍过夜,或者至少4—6小时。###3. 第二天,取出鸡翅,抹去腌料,表面均匀涂抹蜂蜜,放在已铺好锡纸的烤盘上###4. 烤箱中层,上下火,220度,烤20分钟。大约十五分钟时,取出翻面一次。于是,金黄诱人的烤鸡翅出炉啦!', '肉类,禽类,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/9/3/e/yuan_932d06eac162d61bf3bd8a4f74cf6b9e.jpg', '普通', '25分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###蜂蜜|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 之所以选择8只,是因为正好够一家三口的量。头天晚上鸡翅洗净,化冻###2. 生姜、大蒜切小块,把除蜂蜜以外的材料全部到鸡翅里,拌匀。盖上保鲜膜,冰箱保鲜层腌渍过夜,或者至少4—6小时。###3. 第二天,取出鸡翅,抹去腌料,表面均匀涂抹蜂蜜,放在已铺好锡纸的烤盘上###4. 烤箱中层,上下火,220度,烤20分钟。大约十五分钟时,取出翻面一次。于是,金黄诱人的烤鸡翅出炉啦!', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(31872, '辅食之韭菜鸡蛋虾仁碎', 'meat', '虾:520克#鸡蛋:5个#韭菜:400克#大米:345克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好所用材料###2. 韭菜在盐水里浸泡5分钟后冲水备用###3. 韭菜和吓人切碎###4. 将切碎的韭菜、虾仁与鸡蛋放在碗里,由于北极虾比较咸,不需要放盐###5. 将所有材料充分打散###6. 锅内添少许油###7. 小火快速翻炒,待鸡蛋凝固后盛出###8. 加少许软米饭,OK', '禽类,水产,蛋类,热菜,午餐,婴儿(10-12个月),家常菜', 'https://cp1.douguo.net/upload/caiku/1/5/6/yuan_159c8a0fb1724bfa6fe3da95bbdf7776.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###韭菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###大米|345|克|主料|淘洗|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 准备好所用材料###2. 韭菜在盐水里浸泡5分钟后冲水备用###3. 韭菜和吓人切碎###4. 将切碎的韭菜、虾仁与鸡蛋放在碗里,由于北极虾比较咸,不需要放盐###5. 将所有材料充分打散###6. 锅内添少许油###7. 小火快速翻炒,待鸡蛋凝固后盛出###8. 加少许软米饭,OK', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(31913, '莴笋炒肉', 'meat', '莴笋:460克#竹笋:460克#食用油:45毫升#食盐:7克#生抽:35毫升', '2名成年人总量+15%冗余', '1. 莴笋切片,前腿肉切片并且加盐,蚝油,酱油腌制半小时。###2. 把前腿肉爆香###3. 前腿肉爆香到去生以后盛起,放油,爆香莴笋,边炒边加适量的盐###4. 莴笋翻炒一分钟后加入肉,继续翻炒一分钟###5. 盖锅盖,焖个三分钟到五分钟###6. 出锅!', '水产,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/6/3/7/yuan_633ec5610da8f5eb9db792baed2dbeb7.jpg', '普通', '20分钟', '莴笋|460|克|主料|去皮切片|2名成年人总量+15%冗余|菜名+步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤', '1. 莴笋切片,前腿肉切片并且加盐,蚝油,酱油腌制半小时。###2. 把前腿肉爆香###3. 前腿肉爆香到去生以后盛起,放油,爆香莴笋,边炒边加适量的盐###4. 莴笋翻炒一分钟后加入肉,继续翻炒一分钟###5. 盖锅盖,焖个三分钟到五分钟###6. 出锅!', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(31925, '红烧排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 排骨切小块 中排好吃###2. 下锅将血水去掉 捞起排骨###3. 50克白糖,下油锅###4. 金黄色就可以下排骨了###5. 加上生姜和酱油###6. 酱油用这个 我不是打广告!不是!###7. 放入高压锅因为饿了...加水没过排骨!还有料酒 5分钟哦###8. 我不是广告!不是!###9. 收汁起锅!', '肉类,热菜,午餐,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/7/e/f/yuan_7ec009818dad6e44cd725f75bf1ffa9f.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 排骨切小块 中排好吃###2. 下锅将血水去掉 捞起排骨###3. 50克白糖,下油锅###4. 金黄色就可以下排骨了###5. 加上生姜和酱油###6. 酱油用这个 我不是打广告!不是!###7. 放入高压锅因为饿了...加水没过排骨!还有料酒 5分钟哦###8. 我不是广告!不是!###9. 收汁起锅!', '[]', '来源步骤数: 9', '红烧', 0, 0, NULL, NULL),
(31995, '香辣焦香猪脚脚', 'meat', '生抽:35毫升#姜:25克#葱:35克#花椒:6克#焦香猪脚脚:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 解冻,剁小块###2. 冷水下锅,撇去血沫###3. 准备好调料。那个卤水汁超市有卖的,如果没有味道也不会差哪儿去。没有的话就多放点生抽和下面的香料也行。###4. 各种香料###5. 大火烧开,撇去血沫后,放入以上香料和调料,加入葱姜。###6. 大火烧开后,中火炖1小时。关火,不用开锅盖,浸泡2小时以上,直至自然冷却就好。捞出备用###7. 四川的花椒粉......来自老妈人工空运###8. 四', '肉类,热菜,香辣,午餐,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/0/7/1/yuan_07c0d211be233038e1046e8666a607b1.jpg', '简单', '15分钟', '生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###焦香猪脚脚|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 解冻,剁小块###2. 冷水下锅,撇去血沫###3. 准备好调料。那个卤水汁超市有卖的,如果没有味道也不会差哪儿去。没有的话就多放点生抽和下面的香料也行。###4. 各种香料###5. 大火烧开,撇去血沫后,放入以上香料和调料,加入葱姜。###6. 大火烧开后,中火炖1小时。关火,不用开锅盖,浸泡2小时以上,直至自然冷却就好。捞出备用###7. 四川的花椒粉......来自老妈人工空运###8. 四', '[]', '来源步骤数: 8', '炖', 0, 0, NULL, NULL),
(32059, '京酱肉丝', 'meat', '猪肉:345克#鸡蛋:5个#黄瓜:400克#萝卜:460克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 铺底的素菜可以随意,此次用的是卷心菜和黄瓜,还可选择豆芽,萝卜丝等等,开水中过一下,什么都不用放,因为上层的蛋饼和肉丝的酱汁及油会层层渗下来。###2. 蛋液里放了少许盐###3. 肉丝腌制,热油翻炒,变色即可起锅,开火炒甜面酱(用的是李锦记),下肉丝挂酱。', '京菜,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/8/5/1/yuan_85f66cb6fd1e77895d0f79b94c0d5f81.jpg', '普通', '45分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###黄瓜|400|克|主料|洗净切片或拍碎|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 铺底的素菜可以随意,此次用的是卷心菜和黄瓜,还可选择豆芽,萝卜丝等等,开水中过一下,什么都不用放,因为上层的蛋饼和肉丝的酱汁及油会层层渗下来。###2. 蛋液里放了少许盐###3. 肉丝腌制,热油翻炒,变色即可起锅,开火炒甜面酱(用的是李锦记),下肉丝挂酱。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(32148, '西瓜皮炒腊肉', 'meat', '西瓜:575克#猪肉:345克#青椒:205克#木耳:35克#食用油:45毫升#食盐:7克#姜:25克#蒜:30克#腊肉:345克', '2名成年人总量+15%冗余', '1. 西瓜皮去掉外面硬皮和里瓤,洗净。###2. 西瓜皮切丝加少许盐腌制片刻。###3. 木耳泡发、青椒切丝、姜蒜切片、干红辣椒切段备用。###4. 熟腊肉切丝(我腊肉煮得有点烂,切丝时容易切碎)###5. 锅中放油,稍热加姜蒜,依次加辣椒、木耳、西瓜皮丝、腊肉丝翻炒热起锅盛盘,大功告成!(因为腊肉比较咸,我就没放盐了)', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/6/9/1/yuan_69a28fb030f1ada77ca226ed1f3b39a1.jpg', '普通', '20分钟', '西瓜|575|克|主料|去皮去籽切块|2名成年人总量+15%冗余|菜名+步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###木耳|35|克|配菜|干品提前泡发|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###腊肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 西瓜皮去掉外面硬皮和里瓤,洗净。###2. 西瓜皮切丝加少许盐腌制片刻。###3. 木耳泡发、青椒切丝、姜蒜切片、干红辣椒切段备用。###4. 熟腊肉切丝(我腊肉煮得有点烂,切丝时容易切碎)###5. 锅中放油,稍热加姜蒜,依次加辣椒、木耳、西瓜皮丝、腊肉丝翻炒热起锅盛盘,大功告成!(因为腊肉比较咸,我就没放盐了)', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(32154, '番茄牛腩', 'meat', '牛肉:400克#西红柿:460克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克#老抽:15毫升#料酒:30毫升#香醋:30毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 番茄去皮 切块。用油翻炒出汁加水煮片刻。胡萝卜焯水。葱姜蒜切段###2. 牛肉煮5分钟。待颜色全变之后捞出。汤去沫留用###3. 葱蒜入锅翻炒。加入牛肉###4. 后加入备好的番茄(切小一点...我的番茄切大了 失误失误)###5. 之后倒入牛肉的汤。加料酒。老抽。白醋 冰糖慢慢炖###6. 出锅前放盐。用淀粉勾芡。', '肉类,热菜,番茄味,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/9/b/yuan_49af725b89013a2b6feca3fe20f250fb.jpeg', '普通', '25分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###老抽|15|毫升|调味料|调色|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 番茄去皮 切块。用油翻炒出汁加水煮片刻。胡萝卜焯水。葱姜蒜切段###2. 牛肉煮5分钟。待颜色全变之后捞出。汤去沫留用###3. 葱蒜入锅翻炒。加入牛肉###4. 后加入备好的番茄(切小一点...我的番茄切大了 失误失误)###5. 之后倒入牛肉的汤。加料酒。老抽。白醋 冰糖慢慢炖###6. 出锅前放盐。用淀粉勾芡。', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(32214, '彩虾仁', 'meat', '玉米:460克#虾:520克#萝卜:460克#食用油:45毫升#食盐:7克#淀粉:30克', '2名成年人总量+15%冗余', '1. 新鲜河虾洗浄剥壳成虾仁,红辣椒和胡萝卜切成小丁与玉米粒、青豆一起装盘待用。###2. 虾仁里加入打散的蛋白,淀粉和料洒上浆待用。###3. 干净炒锅烧热倒入适量橄露橄榄油。###4. 放入上浆的虾仁滑炒起锅。###5. 炒锅洗净再倒入适量橄露橄榄油,放入胡萝卜丁煸炒至软。###6. 加入其余的三色丁继续翻炒,加少许盐调味。###7. 最后加入滑炒过的虾仁翻炒装盘即食。', '水产,蛋类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/9/3/5/yuan_9333ae856ad3776fdcde7ee32c5bb215.png', '普通', '20分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 新鲜河虾洗浄剥壳成虾仁,红辣椒和胡萝卜切成小丁与玉米粒、青豆一起装盘待用。###2. 虾仁里加入打散的蛋白,淀粉和料洒上浆待用。###3. 干净炒锅烧热倒入适量橄露橄榄油。###4. 放入上浆的虾仁滑炒起锅。###5. 炒锅洗净再倒入适量橄露橄榄油,放入胡萝卜丁煸炒至软。###6. 加入其余的三色丁继续翻炒,加少许盐调味。###7. 最后加入滑炒过的虾仁翻炒装盘即食。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(32309, '糖醋排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#香醋:30毫升#姜:25克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 排骨改刀切成小块儿,冷水下锅,烧开之后,去除血沫,控干水分备用###2. 锅中放入1小匙油,放入葱,姜片,八角炒出香味###3. 放入处理好的排骨,翻炒均匀###4. 放入红糖翻炒均匀###5. 排骨炒到如图这样,没一块儿都裹上红糖色了就可以了###6. 放入米酒,酱油和水,水的量和排骨持平就可以了,大火烧开之后,转小火炖20分钟###7. 等20分钟之后,就打开大火,准备收汤汁', '肉类,热菜,酸甜,晚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/7/6/yuan_274526fddd687cbf97fe732ea96082c6.jpg', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 排骨改刀切成小块儿,冷水下锅,烧开之后,去除血沫,控干水分备用###2. 锅中放入1小匙油,放入葱,姜片,八角炒出香味###3. 放入处理好的排骨,翻炒均匀###4. 放入红糖翻炒均匀###5. 排骨炒到如图这样,没一块儿都裹上红糖色了就可以了###6. 放入米酒,酱油和水,水的量和排骨持平就可以了,大火烧开之后,转小火炖20分钟###7. 等20分钟之后,就打开大火,准备收汤汁', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(3231, '豆豉陈皮仔排', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#淀粉:30克#蒜:30克#葱:35克#豆豉陈皮:345克', '2名成年人总量+15%冗余', '1. 仔排剁成小块,陈皮、蒜头、豆豉剁成末。###2. 将剁成末的陈皮、豆豉、蒜头加一勺海鲜酱、一勺柱候酱放油锅里煸炒至出香味。###3. 在仔排里加一大汤匙炒制的酱料、再依次加黄酒、蚝油、香油、食用油、生抽、盐糖、生粉,充分拌至均匀,腌半小时。###4. 大火急蒸十分钟,出锅撒葱丝即可(喜欢酥烂的可延长蒸制时间)', '肉类,水产,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/e/0/3/yuan_e09da34ecd8f816856ba62939e55be03.jpg', '简单', '15分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###豆豉陈皮|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 仔排剁成小块,陈皮、蒜头、豆豉剁成末。###2. 将剁成末的陈皮、豆豉、蒜头加一勺海鲜酱、一勺柱候酱放油锅里煸炒至出香味。###3. 在仔排里加一大汤匙炒制的酱料、再依次加黄酒、蚝油、香油、食用油、生抽、盐糖、生粉,充分拌至均匀,腌半小时。###4. 大火急蒸十分钟,出锅撒葱丝即可(喜欢酥烂的可延长蒸制时间)', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(32491, '色猪肝', 'meat', '猪肝:345克#青椒:205克#香菇:230克#西红柿:460克#萝卜:460克#白糖:55克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 将食材切成形状大小相似的片待用。###2. 猪肝用以上调料腌15分钟后放入热锅中划炒至变色乘起。重新放油待6成热时依次放入香菇、胡萝卜、青椒、西红柿翻炒。###3. 重新放入猪肝,再加适量盐糖,然后加1-2汤勺热水,待汁收得差不多即可起锅。', '肉类,热菜,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/d/f/6/yuan_dfd0cf102684427bb9a582e20f065306.jpg', '普通', '20分钟', '猪肝|345|克|主料|浸泡洗净切片|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 将食材切成形状大小相似的片待用。###2. 猪肝用以上调料腌15分钟后放入热锅中划炒至变色乘起。重新放油待6成热时依次放入香菇、胡萝卜、青椒、西红柿翻炒。###3. 重新放入猪肝,再加适量盐糖,然后加1-2汤勺热水,待汁收得差不多即可起锅。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(3277, '凤尾虾', 'meat', '虾:520克#鸡蛋:5个#食用油:45毫升#料酒:30毫升#淀粉:30克#姜:25克#葱:35克#凤尾:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 虾若干剥壳去虾线,再用刀把虾拍扁备用###2. 葱姜料酒腌制20分钟###3. 腌好的虾依次占淀粉,鸡蛋液,面包渣成型拍实备用###4. 最后电饼撑放少许油就可以煎虾了,两面来回煎至熟透就可以出锅了,摆盘之后在虾上挤上喜欢口味的沙拉酱即可。', '海鲜,禽类,水产,蛋类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/9/a/d/yuan_9aeb9bbbbb125c1c8ab130729387d6cd.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###凤尾|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 虾若干剥壳去虾线,再用刀把虾拍扁备用###2. 葱姜料酒腌制20分钟###3. 腌好的虾依次占淀粉,鸡蛋液,面包渣成型拍实备用###4. 最后电饼撑放少许油就可以煎虾了,两面来回煎至熟透就可以出锅了,摆盘之后在虾上挤上喜欢口味的沙拉酱即可。', '[]', '来源步骤数: 4', '煎', 0, 0, NULL, NULL),
(32982, '香辣馋嘴鸭', 'meat', '鸭肉:575克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#蒜:30克#葱:35克#馋嘴鸭:345克', '2名成年人总量+15%冗余', '1. 鸭块、姜片冷水下锅,水开后煮5分钟捞出备用。###2. 把准备好的八角、桂皮、干红辣椒放入高压锅内,倒入鸭块,加入盐、鸡精、十三香调味,搅拌均匀后往锅中倒水,刚好覆盖鸭块即可。###3. 焖熟后捞出鸭块,汤汁备用,炒锅倒油,爆香蒜与葱白,倒入鸭块翻炒,把汤汁倒入锅中,加入生抽,大火焖煮。###4. 最后放入香菜杆,葱段,大火收汁,装盘后在表面撒上香菜叶,用锅中余汁浇盖。', '禽类,热菜,香辣,朋友聚餐,下饭菜,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/d/d/5/yuan_ddb7eb3f6468cf9412f30cc621aaa4a5.jpg', '简单', '15分钟', '鸭肉|575|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###馋嘴鸭|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸭块、姜片冷水下锅,水开后煮5分钟捞出备用。###2. 把准备好的八角、桂皮、干红辣椒放入高压锅内,倒入鸭块,加入盐、鸡精、十三香调味,搅拌均匀后往锅中倒水,刚好覆盖鸭块即可。###3. 焖熟后捞出鸭块,汤汁备用,炒锅倒油,爆香蒜与葱白,倒入鸭块翻炒,把汤汁倒入锅中,加入生抽,大火焖煮。###4. 最后放入香菜杆,葱段,大火收汁,装盘后在表面撒上香菜叶,用锅中余汁浇盖。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(33052, '糯米蒸排骨', 'meat', '排骨:575克#糯米:345克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#食盐:7克', '2名成年人总量+15%冗余', '1. 将适量的糯米,以及棕叶浸泡2小时。生姜切片。###2. 排骨切成小段,去血水后,倒入适量的料酒、菁选酱油和生姜,以及少许白砂糖一起腌制2小时左右。###3. 将排骨放入浸泡好的糯米上,薄薄滴裹上一层即可###4. 将棕叶摆放在盘子里,将蘸了糯米的排骨平铺摆好,放入蒸锅中,盖上锅盖。###5. 用大火蒸开后,随即转为小火,继续蒸约40min,即可食用。', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/3/d/9/yuan_3d0ecdb3f78198cfc67e0e2eeca35109.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###糯米|345|克|主料|提前浸泡|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将适量的糯米,以及棕叶浸泡2小时。生姜切片。###2. 排骨切成小段,去血水后,倒入适量的料酒、菁选酱油和生姜,以及少许白砂糖一起腌制2小时左右。###3. 将排骨放入浸泡好的糯米上,薄薄滴裹上一层即可###4. 将棕叶摆放在盘子里,将蘸了糯米的排骨平铺摆好,放入蒸锅中,盖上锅盖。###5. 用大火蒸开后,随即转为小火,继续蒸约40min,即可食用。', '[]', '来源步骤数: 5', '蒸', 0, 0, NULL, NULL),
(3328, '香醉排骨', 'meat', '排骨:575克#食用油:45毫升#食盐:7克#淀粉:30克#葱:35克#香醉:345克', '2名成年人总量+15%冗余', '1. 把排骨斩成块,下盐、味精腌制;接着要打入一个全蛋,当然这个可以酌量加减;###2. 加入生粉或地瓜粉搅拌,然后下油锅炸,约7-8成油温,中途要注意保持油温不要炸回油了;###3. 把炸好的排骨倒进调味汁中,撒上葱珠,翻颠均匀。', '闽菜,肉类,热菜,朋友聚餐,下饭菜,家常菜', 'https://cp1.douguo.net/upload/recipe/8/c/f/yuan_8c53d30ad023ce50140181f713059ddf.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###香醉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 把排骨斩成块,下盐、味精腌制;接着要打入一个全蛋,当然这个可以酌量加减;###2. 加入生粉或地瓜粉搅拌,然后下油锅炸,约7-8成油温,中途要注意保持油温不要炸回油了;###3. 把炸好的排骨倒进调味汁中,撒上葱珠,翻颠均匀。', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(33584, '香辣蟹', 'meat', '蟹:690克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#花椒:6克', '2名成年人总量+15%冗余', '1. 把蟹刷洗干净,加入白酒腌制一会儿###2. 去掉鳃等不能食用的地方,把脏的地方洗净,用刀把蟹切成四块;###3. 把尖椒,红辣椒,姜洗干净后切成片待用。###4. 在锅内放入适量油,烧到约三成热,放入花椒、辣椒以慢火爆香###5. 放入蟹煸炒一会儿,再加入尖椒片继续翻炒。###6. 加入适量盐、糖、酱油翻炒两三分钟, 勾芡出锅即可', '海鲜,水产,热菜,香辣,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/6/a/yuan_164d48541a40a404713d4ade199086fa.jpg', '普通', '45分钟', '蟹|690|克|主料|刷洗干净|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 把蟹刷洗干净,加入白酒腌制一会儿###2. 去掉鳃等不能食用的地方,把脏的地方洗净,用刀把蟹切成四块;###3. 把尖椒,红辣椒,姜洗干净后切成片待用。###4. 在锅内放入适量油,烧到约三成热,放入花椒、辣椒以慢火爆香###5. 放入蟹煸炒一会儿,再加入尖椒片继续翻炒。###6. 加入适量盐、糖、酱油翻炒两三分钟, 勾芡出锅即可', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(33859, '土豆炖排骨', 'meat', '排骨:575克#土豆:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#葱:35克', '2名成年人总量+15%冗余', '1. 土豆切块###2. 排骨洗净###3. 葱姜切段###4. 排骨入锅焯水捞出###5. 倒油放葱姜大料翻炒出香,放排骨,翻炒片刻后加入料酒酱油。稍后加水炖十分钟左右。###6. 放土豆,锅里如果烧没水了可以再放点,十分钟左右。###7. 加盐鸡精调味出锅', '肉类,禽类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/d/d/0/yuan_dd4ee4b3988fff9a53b6de7f3f3d5810.jpg', '普通', '25分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 土豆切块###2. 排骨洗净###3. 葱姜切段###4. 排骨入锅焯水捞出###5. 倒油放葱姜大料翻炒出香,放排骨,翻炒片刻后加入料酒酱油。稍后加水炖十分钟左右。###6. 放土豆,锅里如果烧没水了可以再放点,十分钟左右。###7. 加盐鸡精调味出锅', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(33906, '炸酥肉', 'meat', '五花肉:345克#鸡蛋:5个#食用油:45毫升#食盐:7克#淀粉:30克#酥肉:345克', '2名成年人总量+15%冗余', '1. 五花肉切片,放盐,鸡蛋,淀粉拌上。就像炸茄盒那样,让五花肉每片都裹上鸡蛋液和淀粉,尽量裹厚些,这样吃起来更酥松。###2. 油烧至七成热,用筷子一块一块下油锅炸,炸至两面金黄色,沥油捞出。香喷喷的酥肉就炸好了。吃起来狠香。###3. 可以存放进冰箱,每次取出几块切成小块,加水煮汤,在放点青菜,香而不腻~', '禽类,蛋类,肉类,热菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/f/4/yuan_4f04f606e91fbe9af807e6cee4fcf424.jpg', '简单', '15分钟', '五花肉|345|克|主料|切块或切片|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###酥肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 五花肉切片,放盐,鸡蛋,淀粉拌上。就像炸茄盒那样,让五花肉每片都裹上鸡蛋液和淀粉,尽量裹厚些,这样吃起来更酥松。###2. 油烧至七成热,用筷子一块一块下油锅炸,炸至两面金黄色,沥油捞出。香喷喷的酥肉就炸好了。吃起来狠香。###3. 可以存放进冰箱,每次取出几块切成小块,加水煮汤,在放点青菜,香而不腻~', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(34036, '潮汕传统牛腩不用焯', 'meat', '牛肉:400克#芹菜:400克#白糖:55克#食用油:45毫升#生抽:35毫升#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 洗干净牛腩,用刀背来回拍打两分钟。然后加入沙茶酱、耗油、酱油(三者均一勺)腌制10分钟。###2. 把腌制好的牛腩放入锅中(用的是砂锅),加入辣椒、一勺花椒、半勺冰糖、八角3个、桂皮一片、三勺生抽,锅中加水,水量平过牛腩可以开始煮了。我这里水少了还可以再加些###3. 大火熬煮10分钟,转小火熬制2个小时。然后就可以出锅啦!切块装盘,撒上西芹,淋上锅里剩下的汤汁就可以啦!', '粤菜,肉类,热菜,一家三口,午餐,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/a/b/c/yuan_ab104676250d9f84db717aaf37ab04bc.jpg', '困难', '60分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 洗干净牛腩,用刀背来回拍打两分钟。然后加入沙茶酱、耗油、酱油(三者均一勺)腌制10分钟。###2. 把腌制好的牛腩放入锅中(用的是砂锅),加入辣椒、一勺花椒、半勺冰糖、八角3个、桂皮一片、三勺生抽,锅中加水,水量平过牛腩可以开始煮了。我这里水少了还可以再加些###3. 大火熬煮10分钟,转小火熬制2个小时。然后就可以出锅啦!切块装盘,撒上西芹,淋上锅里剩下的汤汁就可以啦!', '[]', '来源步骤数: 3', '煮', 0, 0, NULL, NULL),
(34129, '红烧排骨', 'meat', '排骨:575克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#香醋:30毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 排骨放凉水锅中烧开,去除血沫,沥干水分###2. 另取一锅,锅内放少量油烧制6成热,倒入排骨翻炒至表皮发干###3. 先后加入1勺料酒,2勺酱油,3勺糖,4勺醋翻炒一会###4. 加入热水没过排骨大火烧开,小火慢炖,最后再大火收干汤汁,简单美味的糖醋排骨就好了', '肉类,热菜,晚餐,下饭菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/1/c/d/yuan_1c2ccc0df0d8ff7f0359503ad0b331cd.jpg', '普通', '20分钟', '排骨|575|克|主料|剁块并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 排骨放凉水锅中烧开,去除血沫,沥干水分###2. 另取一锅,锅内放少量油烧制6成热,倒入排骨翻炒至表皮发干###3. 先后加入1勺料酒,2勺酱油,3勺糖,4勺醋翻炒一会###4. 加入热水没过排骨大火烧开,小火慢炖,最后再大火收干汤汁,简单美味的糖醋排骨就好了', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(34248, '蒜香糯米鸡肉肠', 'meat', '洋葱:290克#椒盐:9克#鸡肉:520克#鸡蛋:5个#大米:345克#糯米:345克#食盐:7克#蒜:30克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 讲盐渍肠衣泡好洗净,糯米饭蒸好,洗净配料###2. 肉搅成肉泥,米饭捣成末,洋葱、蒜、辣椒都切成末备用###3. 将各种末混合加上花椒胡椒盐鸡蛋再搅匀,然后用自制的工具灌肠如图所示###4. 烤箱预热5分钟后,将肠放进去烤10分钟时,用叉子在肠身 均匀插几个孔,放出里面水分,再继续烤15分钟###5. 好了,可以吃了,吃不了可以冻上', '肉类,禽类,蛋类,热菜,蒜香,晚餐,午餐,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/5/f/d/yuan_5f44ae9d08aca648fbebc8f192e5707d.jpg', '困难', '60分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###椒盐|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###大米|345|克|主料|淘洗|2名成年人总量+15%冗余|步骤###糯米|345|克|主料|提前浸泡|2名成年人总量+15%冗余|菜名+步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 讲盐渍肠衣泡好洗净,糯米饭蒸好,洗净配料###2. 肉搅成肉泥,米饭捣成末,洋葱、蒜、辣椒都切成末备用###3. 将各种末混合加上花椒胡椒盐鸡蛋再搅匀,然后用自制的工具灌肠如图所示###4. 烤箱预热5分钟后,将肠放进去烤10分钟时,用叉子在肠身 均匀插几个孔,放出里面水分,再继续烤15分钟###5. 好了,可以吃了,吃不了可以冻上', '[]', '来源步骤数: 5', '蒸', 0, 0, NULL, NULL),
(344, '酸豆角炒肉丝', 'meat', '猪肉:345克#豆角:460克#食用油:45毫升#食盐:7克#香醋:30毫升', '2名成年人总量+15%冗余', '1. 首先将买回来的豆角洗净,拿到阳台晾干水份后,去头去尾备用。###2. 准备1个带盖的无油无水的玻璃瓶,倒入适量的凉白开,放适量的盐搅拌均匀后,用手指沾少许舔一舔,感觉到咸味即可,再倒入适量的醋,然后放入晾干水份的豆角,盐水一定要没过豆角,(喜欢吃辣的童鞋可以放些辣椒下去^o^)腌制3天左右即成。(期间可以拿出来尝尝,感觉OK就可以了,天数由自己掌握)###3. 这是腌制好的豆角。', '苏菜,肉类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/9/6/yuan_3951912decf7b7e510ebb2f6a9068db6.jpg', '简单', '15分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名###豆角|460|克|主料|去筋切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤', '1. 首先将买回来的豆角洗净,拿到阳台晾干水份后,去头去尾备用。###2. 准备1个带盖的无油无水的玻璃瓶,倒入适量的凉白开,放适量的盐搅拌均匀后,用手指沾少许舔一舔,感觉到咸味即可,再倒入适量的醋,然后放入晾干水份的豆角,盐水一定要没过豆角,(喜欢吃辣的童鞋可以放些辣椒下去^o^)腌制3天左右即成。(期间可以拿出来尝尝,感觉OK就可以了,天数由自己掌握)###3. 这是腌制好的豆角。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(34404, '沙茶肉酱', 'meat', '花生:170克#芝麻:35克#猪肉:345克#虾:520克#白糖:55克#食用油:45毫升#姜:25克#蒜:30克#沙茶肉:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 油烧热,下糖炒出糖色。###2. 关小火,下蒜末、姜末微炒一下,再下甜面酱、沙茶酱、黄豆酱、花生酱微炒香。###3. 还是小火,下肉末、虾皮稍炒制一下。###4. 下适量水,把上述材料搅拌均匀,开中火慢慢熬制。###5. 熬制成肉酱后,最后下已炒好的芝麻增香即可。', '水产,肉类,热菜,鲜,家常菜', 'https://cp1.douguo.net/upload/caiku/d/4/9/yuan_d46f223929c79d9e13764340445f5779.jpg', '困难', '45分钟', '花生|170|克|辅料|洗净浸泡|2名成年人总量+15%冗余|步骤###芝麻|35|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###沙茶肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 油烧热,下糖炒出糖色。###2. 关小火,下蒜末、姜末微炒一下,再下甜面酱、沙茶酱、黄豆酱、花生酱微炒香。###3. 还是小火,下肉末、虾皮稍炒制一下。###4. 下适量水,把上述材料搅拌均匀,开中火慢慢熬制。###5. 熬制成肉酱后,最后下已炒好的芝麻增香即可。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(34494, '香烤春鸡', 'meat', '玉米:460克#鸡肉:520克#菠菜:460克#牛奶:575毫升#淡奶油:290毫升#食用油:45毫升#食盐:7克#春鸡:345克', '2名成年人总量+15%冗余', '1. 用黄油和橄榄油、盐、胡椒、百里香提前腌制鸡肉10分钟,放进烤箱160°烤制15-20分钟左右,烤制过程中不断地给鸡肉淋上黄油和橄榄油,烤至鸡肉外脆里嫩,表皮呈现金黄色即可。###2. 鸡汤牛奶烧开加入玉米粉搅拌均匀,加少许盐调味,等水分蒸发后成玉米糊状,加入帕玛森芝士粉,再加少许鲜奶油,继续加热成膏状即可。###3. 最后装盘,配上朝鲜蓟、菠菜,以及鸡肉汁。', '京菜,禽类,肉类,热菜,朋友聚餐,年夜饭,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/3/a/4/yuan_3ae909d97aab72b9a41cfc34a39761f4.jpg', '困难', '90分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###菠菜|460|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###牛奶|575|毫升|主料|直接使用|2名成年人总量+15%冗余|步骤###淡奶油|290|毫升|主料|冷藏备用|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###春鸡|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 用黄油和橄榄油、盐、胡椒、百里香提前腌制鸡肉10分钟,放进烤箱160°烤制15-20分钟左右,烤制过程中不断地给鸡肉淋上黄油和橄榄油,烤至鸡肉外脆里嫩,表皮呈现金黄色即可。###2. 鸡汤牛奶烧开加入玉米粉搅拌均匀,加少许盐调味,等水分蒸发后成玉米糊状,加入帕玛森芝士粉,再加少许鲜奶油,继续加热成膏状即可。###3. 最后装盘,配上朝鲜蓟、菠菜,以及鸡肉汁。', '[]', '来源步骤数: 3', '蒸', 0, 0, NULL, NULL),
(34604, '椒盐秋刀鱼', 'meat', '柠檬:170克#椒盐:9克#鱼:690克#食用油:45毫升#食盐:7克#秋刀:345克', '2名成年人总量+15%冗余', '1. 柠檬:将柠檬切成两半,用力将柠檬汁挤入碗中待用。###2. 切配:将秋刀鱼去头和内脏后,用流水洗净,用盐和柠檬汁均匀涂抹全身,并将胡椒粉均匀抹在鱼腹中,静置10分钟后用厨房用纸将鱼身多余的水分抹干。###3. 预热:取出方太烤箱中的烤盘,再关门、通电、开机,选择“上下”模式,设置190°C,定时14分钟,按确认键,烤箱开始预热。###4. 烤盘:在烤盘上铺一层锡纸,锡纸上刷一层色拉油,再在秋刀', '海鲜,水产,热菜,椒盐,晚餐,午餐,朋友聚餐,一家三口,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/2/b/4/yuan_2bc67fe814046c7aa3ac274fb37741e4.png', '困难', '20分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###椒盐|9|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|菜名+步骤###秋刀|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 柠檬:将柠檬切成两半,用力将柠檬汁挤入碗中待用。###2. 切配:将秋刀鱼去头和内脏后,用流水洗净,用盐和柠檬汁均匀涂抹全身,并将胡椒粉均匀抹在鱼腹中,静置10分钟后用厨房用纸将鱼身多余的水分抹干。###3. 预热:取出方太烤箱中的烤盘,再关门、通电、开机,选择“上下”模式,设置190°C,定时14分钟,按确认键,烤箱开始预热。###4. 烤盘:在烤盘上铺一层锡纸,锡纸上刷一层色拉油,再在秋刀', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(34877, '香龙虾', 'meat', '虾:520克#青椒:205克#红椒:170克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 将大蒜头剥好切碎,各种食材准备好,龙虾洗净沥干水。###2. 起油锅,下姜、蒜、胡葱、干红椒(剪碎),炒香后加入小龙虾,翻炒片刻后加入十三香、花椒粉或香辣粉,加入一铲子生抽、白砂糖3茶碮,加少许水,加入青椒后盖锅盖烧5分钟。###3. 喷上料酒起锅。可加香菜点缀。', '海鲜,水产,热菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/f/4/3/yuan_f48608998f02cbf7abb97383d8c685e3.jpg', '简单', '15分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将大蒜头剥好切碎,各种食材准备好,龙虾洗净沥干水。###2. 起油锅,下姜、蒜、胡葱、干红椒(剪碎),炒香后加入小龙虾,翻炒片刻后加入十三香、花椒粉或香辣粉,加入一铲子生抽、白砂糖3茶碮,加少许水,加入青椒后盖锅盖烧5分钟。###3. 喷上料酒起锅。可加香菜点缀。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(35011, '青椒毛豆肉丝', 'meat', '毛豆:345克#猪肉:345克#青椒:205克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克', '2名成年人总量+15%冗余', '1. 热锅凉油,先将肉丝加姜丝爆炒,略变金色时倒入料酒,生抽,少许糖提味,不停翻炒上色。###2. 下入毛豆籽翻炒。###3. 待稍稍断生后加入开水,开水量刚刚平食材。###4. 略煮三五分钟后下入切成丝的青椒,加盐调味,稍稍翻炒至青椒成熟即可装盘。', '贵州菜,肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/4/4/yuan_84fd96014291bc94557e77f74415e724.jpeg', '普通', '20分钟', '毛豆|345|克|主料|剥壳洗净|2名成年人总量+15%冗余|菜名+步骤###猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###青椒|205|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤', '1. 热锅凉油,先将肉丝加姜丝爆炒,略变金色时倒入料酒,生抽,少许糖提味,不停翻炒上色。###2. 下入毛豆籽翻炒。###3. 待稍稍断生后加入开水,开水量刚刚平食材。###4. 略煮三五分钟后下入切成丝的青椒,加盐调味,稍稍翻炒至青椒成熟即可装盘。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(35091, '春韭银鳕鱼', 'meat', '鱼:690克#韭菜:400克#白糖:55克#食盐:7克#淀粉:30克#春韭银:345克', '2名成年人总量+15%冗余', '1. 银鳕鱼去皮后切块,加入少许盐腌制,用生粉上浆后备用。###2. 烧一锅水,将银鳕鱼轻轻放入,烫熟捞出摆盘。中间不要翻动以免脱浆。###3. 水不要倒掉,将韭菜在热水里焯水以后切成末。###4. 锅里加一点水烧热,倒入韭菜末,然后撒盐,少许糖和味精调味。###5. 勾芡以后将韭菜汁淋在鳕鱼上。', '水产,凉菜,午餐,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/2/2/1/yuan_229aa451672984588f48800b6cddce11.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###韭菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###春韭银|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 银鳕鱼去皮后切块,加入少许盐腌制,用生粉上浆后备用。###2. 烧一锅水,将银鳕鱼轻轻放入,烫熟捞出摆盘。中间不要翻动以免脱浆。###3. 水不要倒掉,将韭菜在热水里焯水以后切成末。###4. 锅里加一点水烧热,倒入韭菜末,然后撒盐,少许糖和味精调味。###5. 勾芡以后将韭菜汁淋在鳕鱼上。', '[]', '来源步骤数: 5', '腌', 0, 0, NULL, NULL),
(35101, '荷兰豆炒培根', 'meat', '萝卜:460克#食盐:7克#蒜:30克#荷兰豆:345克#培根:345克#食用油:45毫升', '2名成年人总量+15%冗余', '1. 荷兰豆摘洗干净,胡萝卜切片(很闲~将其搞成花片儿状了(^_-))培根切段,蒜剁成末。###2. 蒜末爆香,放入荷兰豆大火爆炒。###3. 荷兰豆炒至变色后加入培根及胡萝卜片,继续爆炒。###4. 放入少量食盐,加入大喜大牛肉粉,继续快速翻炒。###5. OK,清脆爽口,好吃极了!', '肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/7/5/yuan_4721f7ea82a83cd7216d220734854775.jpg', '普通', '20分钟', '萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###荷兰豆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###培根|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全', '1. 荷兰豆摘洗干净,胡萝卜切片(很闲~将其搞成花片儿状了(^_-))培根切段,蒜剁成末。###2. 蒜末爆香,放入荷兰豆大火爆炒。###3. 荷兰豆炒至变色后加入培根及胡萝卜片,继续爆炒。###4. 放入少量食盐,加入大喜大牛肉粉,继续快速翻炒。###5. OK,清脆爽口,好吃极了!', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(35115, '汁财鱼焖锅', 'meat', '鱼:690克#小米:290克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#姜:25克#汁财:345克', '2名成年人总量+15%冗余', '1. 财鱼整理好,切成小块,放入姜片、料酒、盐、胡椒腌制###2. 蔬菜切成滚刀块###3. 锅里放油少许,蔬菜放入,加入少许盐。盖盖子中火闷十分钟左右。###4. 在蔬菜闷的时候制作酱汁,锅里放油少许,放入姜丝小米椒炒一会加入三种酱汁和糖炒匀,最后加入生粉勾芡。###5. 放入鱼块,鱼块上淋入酱汁,再闷十分钟左右###6. 闻到香味,鱼肉变白就差不多了,把锅内的菜搅拌均匀', '水产,肉类,热菜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/c/f/yuan_1cdafd6755ab1a03f4181b6c0e2c135f.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###汁财|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 财鱼整理好,切成小块,放入姜片、料酒、盐、胡椒腌制###2. 蔬菜切成滚刀块###3. 锅里放油少许,蔬菜放入,加入少许盐。盖盖子中火闷十分钟左右。###4. 在蔬菜闷的时候制作酱汁,锅里放油少许,放入姜丝小米椒炒一会加入三种酱汁和糖炒匀,最后加入生粉勾芡。###5. 放入鱼块,鱼块上淋入酱汁,再闷十分钟左右###6. 闻到香味,鱼肉变白就差不多了,把锅内的菜搅拌均匀', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(35233, '烤串', 'meat', '玉米:460克#羊肉:460克#土豆:460克#红椒:170克#食用油:45毫升#蒜:30克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好食材###2. 所有调料放在一起加食用油拌匀###3. 羊肉切小块,用兑好的调料抓匀###4. 黄红椒也切小块###5. 串起来###6. 烤箱按照自家“习性”烤,烤到有肉串香就差不多了哈哈哈(我家没有烤网,我是在签子下面垫个锡盒子用来接烤串流下来油)###7. 我还烤了玉米串和土豆片(涂蒜蓉甜辣酱),面包片(涂蜂蜜),小烤肠串,都很好吃###8. 今晚吃串!', '新疆菜,肉类,热菜,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/6/c/5/yuan_6c5d90940faaf9aa82a0ed444f8bcb75.jpg', '困难', '60分钟', '玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###羊肉|460|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好食材###2. 所有调料放在一起加食用油拌匀###3. 羊肉切小块,用兑好的调料抓匀###4. 黄红椒也切小块###5. 串起来###6. 烤箱按照自家“习性”烤,烤到有肉串香就差不多了哈哈哈(我家没有烤网,我是在签子下面垫个锡盒子用来接烤串流下来油)###7. 我还烤了玉米串和土豆片(涂蒜蓉甜辣酱),面包片(涂蜂蜜),小烤肠串,都很好吃###8. 今晚吃串!', '[]', '来源步骤数: 8', '烤', 0, 0, NULL, NULL),
(35293, '红焖羊腿肉', 'meat', '萝卜:460克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#羊腿肉:345克', '2名成年人总量+15%冗余', '1. 一整块羊腿肉 放锅 凉水煮开 这样飞水里面肉嫩不柴###2. 沥干水 切成小块 纵向纹理###3. 切好就这样 里面的肉有弹性###4. 腌制 加入酱油 盐 鸡精 胡椒粉 十三香或者南街村调料 料酒 红酒 胡椒粉 姜 搅拌 静置30分钟###5. 红萝卜去皮滚刀切###6. 入高压锅 20分钟 水要没过一半食材###7. 成功 出锅尝甜咸 成了', '肉类,禽类,热菜,家常菜,高压锅', 'https://cp1.douguo.net/upload/caiku/d/b/6/yuan_db90a6ddc0fefcb45e089104e0e708f6.jpeg', '困难', '60分钟', '萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###羊腿肉|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 一整块羊腿肉 放锅 凉水煮开 这样飞水里面肉嫩不柴###2. 沥干水 切成小块 纵向纹理###3. 切好就这样 里面的肉有弹性###4. 腌制 加入酱油 盐 鸡精 胡椒粉 十三香或者南街村调料 料酒 红酒 胡椒粉 姜 搅拌 静置30分钟###5. 红萝卜去皮滚刀切###6. 入高压锅 20分钟 水要没过一半食材###7. 成功 出锅尝甜咸 成了', '[]', '来源步骤数: 7', '焖', 0, 0, NULL, NULL),
(35322, '品鲜醋鸡', 'meat', '鸡翅:575克#鸡肉:520克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#淀粉:30克#姜:25克#葱:35克#干辣椒:15克', '2名成年人总量+15%冗余', '1. 将鸡中翅 剁成块倒入锅中加适量的广东米酒 (可用可不用)煮熟 盛好备用###2. 大葱切成段 姜切成片 盛好备用 生粉加水 做芡###3. 锅中加少许油 将葱姜 泡椒 倒入锅中 爆香 加水 再把 鸡块倒入家干辣椒 加盐味 鸡粉 ,酱油上色 (加适量)加醋 ,等鸡肉入味了用生粉 勾芡###4. 。 加盐味 鸡粉 ,酱油上色 (加适量)加醋 ,等鸡肉入味了用生粉 勾芡', '禽类,肉类,热菜,酸,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/c/e/4/yuan_ce0cdab6d254dcb16eecad4961d5b254.jpg', '困难', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|菜名+步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤', '1. 将鸡中翅 剁成块倒入锅中加适量的广东米酒 (可用可不用)煮熟 盛好备用###2. 大葱切成段 姜切成片 盛好备用 生粉加水 做芡###3. 锅中加少许油 将葱姜 泡椒 倒入锅中 爆香 加水 再把 鸡块倒入家干辣椒 加盐味 鸡粉 ,酱油上色 (加适量)加醋 ,等鸡肉入味了用生粉 勾芡###4. 。 加盐味 鸡粉 ,酱油上色 (加适量)加醋 ,等鸡肉入味了用生粉 勾芡', '[]', '来源步骤数: 4', '煮', 0, 0, NULL, NULL),
(35337, '老卤状元豆', 'meat', '孜然:9克#牛肉:400克#竹笋:460克#食用油:45毫升#食盐:7克#生抽:35毫升#姜:25克#状元豆:345克', '2名成年人总量+15%冗余', '1. 黄豆/黑豆、笋衣/笋丝提前泡发好,倒入锅中,加姜丝、洗净切好的牛肉粒,加入适量清水,大火煮开后转小火煮1个小时###2. 开盖后加入盐、酱油,秘制老卤汤、胡椒粉、孜然粉,大火煮至汤汁完全收干后关火###3. 将煮好冷却的状元豆倒在竹筛上均匀摊开,在取暖器上烘烤一夜即可装入密封罐保存##4.', '肉类,热菜,晚餐,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/2/0/c/yuan_20481a29f68699537dc1eaa5a950aaec.jpg', '普通', '25分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###竹笋|460|克|主料|去壳切段|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###状元豆|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 黄豆/黑豆、笋衣/笋丝提前泡发好,倒入锅中,加姜丝、洗净切好的牛肉粒,加入适量清水,大火煮开后转小火煮1个小时###2. 开盖后加入盐、酱油,秘制老卤汤、胡椒粉、孜然粉,大火煮至汤汁完全收干后关火###3. 将煮好冷却的状元豆倒在竹筛上均匀摊开,在取暖器上烘烤一夜即可装入密封罐保存##4.', '[]', '来源步骤数: 3', '煮', 0, 0, NULL, NULL),
(35575, '鲜嫩无敌的创新果味三杯鸡', 'meat', '草莓:345克#柠檬:170克#鸡肉:520克#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 鸡切块焯水、草莓洗净备用。###2. 草莓去蒂切小块放锅里,倒入冰糖一起煮。###3. 挤入几滴柠檬汁,小火煮至软烂,大火收至汁液浓稠即可。###4. 将葱姜蒜切好备用,锅里倒入一杯橄榄油。###5. 爆香葱姜蒜,放入鸡块爆炒。###6. 倒入一杯米酒 ,再倒入一杯酱油。###7. 倒入草莓酱,小火炖15-20分钟,大火收汁即可。', '禽类,热菜,下饭菜,朋友聚餐,年夜饭,家常菜', 'https://cp1.douguo.net/upload/caiku/9/2/a/yuan_9229485d66f258b9b047f0bb207f290a.jpg', '简单', '15分钟', '草莓|345|克|主料|去蒂洗净|2名成年人总量+15%冗余|步骤###柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鸡切块焯水、草莓洗净备用。###2. 草莓去蒂切小块放锅里,倒入冰糖一起煮。###3. 挤入几滴柠檬汁,小火煮至软烂,大火收至汁液浓稠即可。###4. 将葱姜蒜切好备用,锅里倒入一杯橄榄油。###5. 爆香葱姜蒜,放入鸡块爆炒。###6. 倒入一杯米酒 ,再倒入一杯酱油。###7. 倒入草莓酱,小火炖15-20分钟,大火收汁即可。', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(35659, '胡萝卜炒鸡丝', 'meat', '鸡肉:520克#萝卜:460克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#姜:25克#蒜:30克#葱:35克#鸡丝:345克', '2名成年人总量+15%冗余', '1. 鸡肉洗净 切成细丝###2. 将鸡肉放入碗里加入适量盐 料酒 生粉 白胡椒粉抓匀###3. 然后将胡萝卜切细丝 姜和大蒜切末 葱切好###4. 锅内放少许油 油热后倒入姜末 蒜末 葱末煸炒出香味###5. 倒入鸡丝炒至变色捞出备用###6. 锅内再放少许油放入胡萝卜丝炒软###7. 再倒入鸡丝翻遍片刻 加入适量盐 撒上葱花即可', '鲁菜,禽类,肉类,热菜,下饭菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/1/a/yuan_11ad38c50f8ece6f4733d4384500fcca.jpg', '普通', '20分钟', '鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###萝卜|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###鸡丝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鸡肉洗净 切成细丝###2. 将鸡肉放入碗里加入适量盐 料酒 生粉 白胡椒粉抓匀###3. 然后将胡萝卜切细丝 姜和大蒜切末 葱切好###4. 锅内放少许油 油热后倒入姜末 蒜末 葱末煸炒出香味###5. 倒入鸡丝炒至变色捞出备用###6. 锅内再放少许油放入胡萝卜丝炒软###7. 再倒入鸡丝翻遍片刻 加入适量盐 撒上葱花即可', '[]', '来源步骤数: 7', '炒', 0, 0, NULL, NULL),
(35830, '香辣红酒鸡腿', 'meat', '孜然:9克#黑胡椒:6克#鸡腿:575克#生抽:35毫升#红酒:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备好鸡腿、调味料,生抽倒入鸡腿中,拌匀。###2. 孜然粉、烤肉粉、黑胡椒粉放入碗中,加入红酒调匀。###3. 调好的腌料倒入碗中,充分将鸡腿揉,装入保鲜袋,入冰箱腌制24小时入味。###4. 腌好的鸡腿放入微波烤盘。###5. 烤盘送入微波炉;调至微波烘烤档,烤5分钟,取出翻面;再烤5分钟,刷上一层调料,再烤5分钟即熟。###6. 开吃。', '禽类,肉类,烧烤,热菜,香辣,朋友聚餐,一家三口,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/f/3/1/yuan_f39bcbfa94bcbd741be252f6e5ecf9a1.jpg', '普通', '20分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡腿|575|克|主料|洗净并切块|2名成年人总量+15%冗余|菜名+步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###红酒|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备好鸡腿、调味料,生抽倒入鸡腿中,拌匀。###2. 孜然粉、烤肉粉、黑胡椒粉放入碗中,加入红酒调匀。###3. 调好的腌料倒入碗中,充分将鸡腿揉,装入保鲜袋,入冰箱腌制24小时入味。###4. 腌好的鸡腿放入微波烤盘。###5. 烤盘送入微波炉;调至微波烘烤档,烤5分钟,取出翻面;再烤5分钟,刷上一层调料,再烤5分钟即熟。###6. 开吃。', '[]', '来源步骤数: 6', '烤', 0, 0, NULL, NULL),
(363, '麻辣小龙虾', 'meat', '虾:520克#小米:290克#白糖:55克#食用油:45毫升#食盐:7克#豆瓣酱:30克#葱:35克#干辣椒:15克', '2名成年人总量+15%冗余', '1. 买回来去除虾线,虾尾中间那个,用牙刷刷干净###2. 刷干净洗干净备用###3. yu锅内放油,放入郫县豆瓣酱,炒出红油,放入麻椒,干辣椒,香叶,放入洗干净小龙虾,翻炒几下,看龙虾变色,倒入啤酒,加入盐,###4. 大火炖至烫收干净,放入小米辣,加入糖,香葱,###5. 烫收干,出锅', '海鲜,水产,热菜,麻辣,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/c/e/4/yuan_cec7e94fbe085579b29f8886333d3094.jpg', '困难', '90分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###小米|290|克|主料|淘洗|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤', '1. 买回来去除虾线,虾尾中间那个,用牙刷刷干净###2. 刷干净洗干净备用###3. yu锅内放油,放入郫县豆瓣酱,炒出红油,放入麻椒,干辣椒,香叶,放入洗干净小龙虾,翻炒几下,看龙虾变色,倒入啤酒,加入盐,###4. 大火炖至烫收干净,放入小米辣,加入糖,香葱,###5. 烫收干,出锅', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(36356, '蜜汁鸡翅', 'meat', '鸡翅:575克#食用油:45毫升#生抽:35毫升#姜:25克#蜜汁:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 材料图###2. 鸡翅双面都各切2刀(方便入味,快熟)。###3. 姜片切丝。###4. 锅中放少许油,下姜丝炒片刻。###5. 放下鸡翅2面都煎炸。###6. 至鸡翅微黄肉熟。###7. 调下蜂蜜,蚝油,黑酱油加少许清水拌匀,盖锅盖焖到汁收干即可。(黑酱油少许即可,用来调色的)###8. 蜜汁鸡翅完成了!', '禽类,水产,肉类,小吃,热菜,朋友聚餐,下酒菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/2/a/yuan_12e247ac41e6b233abf85137309995aa.jpg', '普通', '20分钟', '鸡翅|575|克|主料|洗净并划刀|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蜜汁|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 材料图###2. 鸡翅双面都各切2刀(方便入味,快熟)。###3. 姜片切丝。###4. 锅中放少许油,下姜丝炒片刻。###5. 放下鸡翅2面都煎炸。###6. 至鸡翅微黄肉熟。###7. 调下蜂蜜,蚝油,黑酱油加少许清水拌匀,盖锅盖焖到汁收干即可。(黑酱油少许即可,用来调色的)###8. 蜜汁鸡翅完成了!', '[]', '来源步骤数: 8', '炸', 0, 0, NULL, NULL),
(36442, '香辣羊排', 'meat', '羊肉:460克#芹菜:400克#料酒:30毫升#淀粉:30克#豆瓣酱:30克#姜:25克#葱:35克#花椒:6克#食盐:7克', '2名成年人总量+15%冗余', '1. 羊排清水洗两遍后,用清水浸泡4小时以上,中间换换水哈,然后加少许料酒,几片大姜焯水,我加了点儿淀粉,觉得这样肉质嫩些,而且好清洗###2. 将焯水的羊排,清洗好后放入砂锅里,加入少许料酒,几粒儿花椒大料,加入姜片,葱段,再加入足量的清水,大火烧开小火慢炖一小时左右吧###3. 将炖熟的羊排捞出待用,汤可以留着做其他的###4. 将圆葱,芹菜洗净切丁待用,葱姜切末,郫县豆瓣酱也剁碎', '肉类,热菜,香辣,下酒菜,午餐,朋友聚餐,家常菜,砂锅', 'https://cp1.douguo.net/upload/caiku/8/5/d/yuan_85afcd1b2c1c9d56886dacea9a502fed.jpg', '普通', '25分钟', '羊肉|460|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 羊排清水洗两遍后,用清水浸泡4小时以上,中间换换水哈,然后加少许料酒,几片大姜焯水,我加了点儿淀粉,觉得这样肉质嫩些,而且好清洗###2. 将焯水的羊排,清洗好后放入砂锅里,加入少许料酒,几粒儿花椒大料,加入姜片,葱段,再加入足量的清水,大火烧开小火慢炖一小时左右吧###3. 将炖熟的羊排捞出待用,汤可以留着做其他的###4. 将圆葱,芹菜洗净切丁待用,葱姜切末,郫县豆瓣酱也剁碎', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(36668, '杯鱿鱼简化版三步搞定', 'meat', '鱼:690克#鱿鱼:520克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#姜:25克#蒜:30克', '2名成年人总量+15%冗余', '1. (鱿鱼买来前可以让卖家杀好)用刀在鱿鱼身上轻轻的划出网纹,用料酒盐酱油腌制20分钟###2. 热油爆香姜蒜后倒入酱汁(料酒、酱油、糖、香油)到煮沸###3. 倒入鱿鱼翻炒到发白,再加入罗勒碎或者香菜末拌炒就可以起锅装盘了', '海鲜,水产,热菜,下酒菜,家常菜', 'https://cp1.douguo.net/upload/caiku/c/8/7/yuan_c8f3420a9913d608ba24953523e04727.jpg', '简单', '15分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###鱿鱼|520|克|主料|清洗并切花或切圈|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. (鱿鱼买来前可以让卖家杀好)用刀在鱿鱼身上轻轻的划出网纹,用料酒盐酱油腌制20分钟###2. 热油爆香姜蒜后倒入酱汁(料酒、酱油、糖、香油)到煮沸###3. 倒入鱿鱼翻炒到发白,再加入罗勒碎或者香菜末拌炒就可以起锅装盘了', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(36714, '黄金虾', 'meat', '虾:520克#鸡蛋:5个#西红柿:460克#食用油:45毫升#生抽:35毫升#淀粉:30克#黄金:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 大虾去壳去肠衣,背部剪开不要断,轻轻拍扁用少许海鲜酱油淹一会儿,做其它准备工作。###2. 淀粉,面包糠准备好,蛋液忘记拍了。###3. 淹好的大虾先沾上淀粉,再放入蛋液中浸饱,最后在面包糠中打个滚儿,就这样了。不粘锅里放少量油,小火两面煎黄,是煎不是炸哦。###4. 是不是很有食欲呢~###5. 如果蘸番茄酱吃,应该更好,家里没有了,下回喽。', '海鲜,水产,热菜,午餐,朋友聚餐,一家三口,家常菜', 'https://cp1.douguo.net/upload/caiku/2/a/0/yuan_2a3bf59f62495c87e4a1b13f5280db90.jpeg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###黄金|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 大虾去壳去肠衣,背部剪开不要断,轻轻拍扁用少许海鲜酱油淹一会儿,做其它准备工作。###2. 淀粉,面包糠准备好,蛋液忘记拍了。###3. 淹好的大虾先沾上淀粉,再放入蛋液中浸饱,最后在面包糠中打个滚儿,就这样了。不粘锅里放少量油,小火两面煎黄,是煎不是炸哦。###4. 是不是很有食欲呢~###5. 如果蘸番茄酱吃,应该更好,家里没有了,下回喽。', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(36749, '烤箱烤扇贝', 'meat', '白糖:55克#食用油:45毫升#食盐:7克#蒜:30克#扇贝:345克', '2名成年人总量+15%冗余', '1. 1、大蒜剁碎!###2. 2、红、绿辣椒剁碎!###3. 3、锅热后放入菜油,把大蒜、红、绿辣椒下油锅!(小火)放入盐、糖、蚝油搅拌!###4. 4、烤箱预热,放入扇贝烤5分钟,拿出来倒出扇贝烤出的汁!###5. 5、放入熬好的酱!放入烤箱!大火220--230烤15分钟!###6. 6、拿出来,刷酱料,再放入烤箱5分钟!###7. 7、OK啦!', '海鲜,水产,热菜,蒜香,午餐,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/4/e/5/yuan_4e01065364a67b6a5ad5db1372682e65.jpg', '困难', '60分钟', '白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###扇贝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 1、大蒜剁碎!###2. 2、红、绿辣椒剁碎!###3. 3、锅热后放入菜油,把大蒜、红、绿辣椒下油锅!(小火)放入盐、糖、蚝油搅拌!###4. 4、烤箱预热,放入扇贝烤5分钟,拿出来倒出扇贝烤出的汁!###5. 5、放入熬好的酱!放入烤箱!大火220--230烤15分钟!###6. 6、拿出来,刷酱料,再放入烤箱5分钟!###7. 7、OK啦!', '[]', '来源步骤数: 7', '烤', 0, 0, NULL, NULL),
(36751, '红烧塔嘛鱼', 'meat', '鱼:690克#鸡蛋:5个#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#干辣椒:15克#塔嘛:345克', '2名成年人总量+15%冗余', '1. 2条塔嘛鱼收拾干净,洗净。###2. 1个鸡蛋打散成蛋液,塔嘛鱼两面都均匀的沾满鸡蛋液。###3. 热锅凉油,放入 塔嘛鱼,中火煎成两面金黄色,盛出备用。###4. 锅里留少许底油,放入香叶、八角、姜片、蒜瓣、干辣椒煸香。###5. 将鱼放回锅中,加入少许生抽、醋、白糖、盐,再加入一罐啤酒,刚好没过鱼肉的量。###6. 烧至汤汁浓稠,鱼肉入味,可出锅,捡去葱、八角、香叶等,摆盘。', '海鲜,水产,禽类,蛋类,肉类,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/4/2/2/yuan_42cc8dca0fba57c423a1ac042e540a72.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###干辣椒|15|克|辅料|剪段|2名成年人总量+15%冗余|步骤###塔嘛|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 2条塔嘛鱼收拾干净,洗净。###2. 1个鸡蛋打散成蛋液,塔嘛鱼两面都均匀的沾满鸡蛋液。###3. 热锅凉油,放入 塔嘛鱼,中火煎成两面金黄色,盛出备用。###4. 锅里留少许底油,放入香叶、八角、姜片、蒜瓣、干辣椒煸香。###5. 将鱼放回锅中,加入少许生抽、醋、白糖、盐,再加入一罐啤酒,刚好没过鱼肉的量。###6. 烧至汤汁浓稠,鱼肉入味,可出锅,捡去葱、八角、香叶等,摆盘。', '[]', '来源步骤数: 6', '煎', 0, 0, NULL, NULL),
(36887, '香酥烤鱼柳排', 'meat', '柠檬:170克#黑胡椒:6克#鱼:690克#鸡蛋:5个#面粉:400克#食用油:45毫升#食盐:7克#柳排:345克', '2名成年人总量+15%冗余', '1. 鱼柳两面倒入盐抹匀###2. 黑胡椒粉倒入鱼柳两面抹匀###3. 倒入柠檬汁腌半小时###4. 罗勒洗干净切碎###5. 罗勒碎倒进面包糠里拌匀###6. 加入色拉油拌匀###7. 将面粉倒入腌好的鱼柳里拌匀###8. 打入一只鸡蛋拌匀###9. 将鱼柳放进面包糠里沾满面包糠###10. 将鱼柳放进烤盘里###11. 烤箱200度提前预热,烤盘放进烤箱中层,上下火烤20分钟', '海鲜,禽类,水产,蛋类,热菜,香酥,朋友聚餐,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/0/5/d/yuan_052a09baa61b727b8fcfa6b4bca2b20d.jpg', '普通', '25分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###柳排|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 鱼柳两面倒入盐抹匀###2. 黑胡椒粉倒入鱼柳两面抹匀###3. 倒入柠檬汁腌半小时###4. 罗勒洗干净切碎###5. 罗勒碎倒进面包糠里拌匀###6. 加入色拉油拌匀###7. 将面粉倒入腌好的鱼柳里拌匀###8. 打入一只鸡蛋拌匀###9. 将鱼柳放进面包糠里沾满面包糠###10. 将鱼柳放进烤盘里###11. 烤箱200度提前预热,烤盘放进烤箱中层,上下火烤20分钟', '[]', '来源步骤数: 11', '烤', 0, 0, NULL, NULL),
(36907, '蒜蓉烤大虾', 'meat', '黑胡椒:6克#虾:520克#食用油:45毫升#食盐:7克#蒜:30克', '2名成年人总量+15%冗余', '1. 大虾用剪刀剪去虾枪和虾须,再用刀从背部剖开,去除泥肠并用水清洗干净(注意不要切断)。###2. 蒜切成末装碗中,加入准备好的盐、黑胡椒粉、香草粉、橄榄油等拌均匀###3. 用筷子将调好味的蒜末放在虾背上,再放入垫锡纸的烤盘上###4. 烤箱180度预热,上下火烤10分钟左右,装盘', '海鲜,水产,热菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/6/0/d/yuan_60c8a9c426bf05c2b41560efa5fa7a5d.jpg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤', '1. 大虾用剪刀剪去虾枪和虾须,再用刀从背部剖开,去除泥肠并用水清洗干净(注意不要切断)。###2. 蒜切成末装碗中,加入准备好的盐、黑胡椒粉、香草粉、橄榄油等拌均匀###3. 用筷子将调好味的蒜末放在虾背上,再放入垫锡纸的烤盘上###4. 烤箱180度预热,上下火烤10分钟左右,装盘', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(36912, '快手芹菜肉丝', 'meat', '猪里脊:345克#芹菜:400克#食用油:45毫升#食盐:7克#生抽:35毫升#淀粉:30克#蒜:30克', '2名成年人总量+15%冗余', '1. 这道菜非常简单,所有原材料的全家福。芹菜+里脊+蒜末###2. 芹菜斜着切###3. 里脊肉切丝,放少许淀粉抓,可以让里脊肉嫩。###4. 热锅热油,下肉丝煸炒。###5. 肉丝煸白后,下芹菜。放盐。。可以让芹菜塌下去。###6. 菜塌下去后,放入生抽。###7. 出锅前放蒜末提香。###8. 完成~', '肉类,热菜,下饭菜,家常菜,懒人食谱', 'https://cp1.douguo.net/upload/caiku/f/f/f/yuan_ff5a0ef95d1219cf27a79628c6ddf77f.jpg', '普通', '20分钟', '猪里脊|345|克|主料|切丝或切片|2名成年人总量+15%冗余|步骤###芹菜|400|克|主料|洗净切段|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤', '1. 这道菜非常简单,所有原材料的全家福。芹菜+里脊+蒜末###2. 芹菜斜着切###3. 里脊肉切丝,放少许淀粉抓,可以让里脊肉嫩。###4. 热锅热油,下肉丝煸炒。###5. 肉丝煸白后,下芹菜。放盐。。可以让芹菜塌下去。###6. 菜塌下去后,放入生抽。###7. 出锅前放蒜末提香。###8. 完成~', '[]', '来源步骤数: 8', '炒', 0, 0, NULL, NULL),
(37002, '喜丸子非油炸版', 'meat', '猪肉:345克#白糖:55克#食用油:45毫升#生抽:35毫升#姜:25克#葱:35克#花椒:6克#喜丸子非:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 肉成小块然后剁成肉末,加入所有调料,顺时针用筷子搅到有粘稠性###2. 锅里倒入适量油加入少量花椒炸至变色捞出,放少许白糖炒至变色加入葱姜八角生抽加水烧开,然后用勺子将肉馅弄成圆形放到开水的锅里煮至熟剩一些汤然后勾芡!###3. 丸子摆盘将芡汁淋上', '肉类,热菜,晚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/8/e/6/yuan_8e43019fc19878e3b4ea86a09ec05856.jpg', '困难', '60分钟', '猪肉|345|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名+步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###喜丸子非|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 肉成小块然后剁成肉末,加入所有调料,顺时针用筷子搅到有粘稠性###2. 锅里倒入适量油加入少量花椒炸至变色捞出,放少许白糖炒至变色加入葱姜八角生抽加水烧开,然后用勺子将肉馅弄成圆形放到开水的锅里煮至熟剩一些汤然后勾芡!###3. 丸子摆盘将芡汁淋上', '[]', '来源步骤数: 3', '炸', 0, 0, NULL, NULL),
(37128, '凤尾虾球', 'meat', '虾:520克#鸡蛋:5个#土豆:460克#面粉:400克#食用油:45毫升#食盐:7克', '2名成年人总量+15%冗余', '1. 土豆去皮切片煮熟###2. 煮熟的土豆片家少许盐、胡椒粉、亚麻籽油压泥拌匀。###3. 鲜虾去头微挑去虾肠留尾巴,用盐和胡椒粉腌制10分钟。取适量的土豆泥,放在中间一个只虾,再盖上一点土豆泥,用手团成圆球###4. 然后准备好面粉、鸡蛋液、面包糠,把最好的虾球分别沾上面粉、蛋液、面包糠###5. 摆在铺好油纸的烤盘上###6. 烤箱无需预热上下火150°烤20分钟,表面金黄即可。', '粤菜,禽类,水产,蛋类,热菜,创意菜,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/6/1/a/yuan_61d59d00ed7897f9106f901e69af001a.jpeg', '困难', '60分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###土豆|460|克|主料|去皮切块或切片|2名成年人总量+15%冗余|步骤###面粉|400|克|主料|过筛或和面|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤', '1. 土豆去皮切片煮熟###2. 煮熟的土豆片家少许盐、胡椒粉、亚麻籽油压泥拌匀。###3. 鲜虾去头微挑去虾肠留尾巴,用盐和胡椒粉腌制10分钟。取适量的土豆泥,放在中间一个只虾,再盖上一点土豆泥,用手团成圆球###4. 然后准备好面粉、鸡蛋液、面包糠,把最好的虾球分别沾上面粉、蛋液、面包糠###5. 摆在铺好油纸的烤盘上###6. 烤箱无需预热上下火150°烤20分钟,表面金黄即可。', '[]', '来源步骤数: 6', '煮', 0, 0, NULL, NULL),
(37147, '无油鸡米花', 'meat', '黑胡椒:6克#鸡肉:520克#鸡蛋:5个#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克', '2名成年人总量+15%冗余', '1. 鸡胸肉切丁加料酒、盐、黑椒粉,少量淀粉(喜辣的可以加点辣椒粉),抓匀腌制二十分钟,鸡蛋打散备用。###2. 腌制好的鸡丁裹上淀粉,再沾上蛋液,然后再裹上面包糠,装盘。###3. 入烤箱中层,上下火190度20分钟。###4. 出炉装盘,趁热吃。', '肉类,禽类,蛋类,热菜,咸,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/5/2/3/yuan_52324533dd684c7ade3bd232e7089f43.jpeg', '普通', '20分钟', '黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤', '1. 鸡胸肉切丁加料酒、盐、黑椒粉,少量淀粉(喜辣的可以加点辣椒粉),抓匀腌制二十分钟,鸡蛋打散备用。###2. 腌制好的鸡丁裹上淀粉,再沾上蛋液,然后再裹上面包糠,装盘。###3. 入烤箱中层,上下火190度20分钟。###4. 出炉装盘,趁热吃。', '[]', '来源步骤数: 4', '烤', 0, 0, NULL, NULL),
(37172, '层塔鲍菇炒花蛤', 'meat', '蛤蜊:690克#香菇:230克#食用油:45毫升#料酒:30毫升#姜:25克#蒜:30克#葱:35克#层塔鲍菇:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 准备生姜、葱、蒜头###2. 杏鲍菇洗净切成薄片备用###3. 九层塔洗净###4. 油锅烧热暴香部分生姜、香葱、蒜头###5. 放入杏鲍菇片将其暴炒出水分,倒入小碗备用###6. 锅中暴香生姜、香葱、蒜头###7. 倒入洗净的花蛤暴炒,然后放入料酒去腥###8. 倒入炒好的杏鲍菇翻炒###9. 加入一些蚝油调味###10. 加些水盖锅盖,让花蛤煮开至张口###11. 放入九层塔,焖两分钟调味即可装盘开吃', '海鲜,水产,热菜,下酒菜,单身食谱,私家菜,家常菜', 'https://cp1.douguo.net/upload/caiku/5/1/9/yuan_51033612c9c6f04c461f83ce85c7cc79.jpg', '困难', '20分钟', '蛤蜊|690|克|主料|吐沙并清洗|2名成年人总量+15%冗余|菜名+步骤###香菇|230|克|配菜|洗净切片|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###层塔鲍菇|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备生姜、葱、蒜头###2. 杏鲍菇洗净切成薄片备用###3. 九层塔洗净###4. 油锅烧热暴香部分生姜、香葱、蒜头###5. 放入杏鲍菇片将其暴炒出水分,倒入小碗备用###6. 锅中暴香生姜、香葱、蒜头###7. 倒入洗净的花蛤暴炒,然后放入料酒去腥###8. 倒入炒好的杏鲍菇翻炒###9. 加入一些蚝油调味###10. 加些水盖锅盖,让花蛤煮开至张口###11. 放入九层塔,焖两分钟调味即可装盘开吃', '[]', '来源步骤数: 11', '炒', 0, 0, NULL, NULL),
(37231, '蒜焗小黄花鱼', 'meat', '孜然:9克#鱼:690克#白糖:55克#食用油:45毫升#食盐:7克#料酒:30毫升#姜:25克#蒜:30克#小黄花:345克', '2名成年人总量+15%冗余', '1. 小黄鱼画刀,料酒,姜,烧烤汁,盐,糖~腌制半小时入味~###2. 油锅入油~油温六成热,小黄鱼入锅煎制两面微焦~出锅~###3. 蒜切碎末,到入之前腌制的汁,加少量油一同与蒜末混合。小黄鱼放烤盘~铺上蒜末,撒辣椒面,孜然粉,烤箱预热。###4. 烤箱上下火200度,五分钟~蒜末微焦即可出炉~', '海鲜,水产,热菜,蒜香,朋友聚餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/0/c/7/yuan_0cc5b7e17a154982ea8f81f15b152337.jpg', '简单', '15分钟', '孜然|9|克|调味料|直接使用|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###小黄花|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 小黄鱼画刀,料酒,姜,烧烤汁,盐,糖~腌制半小时入味~###2. 油锅入油~油温六成热,小黄鱼入锅煎制两面微焦~出锅~###3. 蒜切碎末,到入之前腌制的汁,加少量油一同与蒜末混合。小黄鱼放烤盘~铺上蒜末,撒辣椒面,孜然粉,烤箱预热。###4. 烤箱上下火200度,五分钟~蒜末微焦即可出炉~', '[]', '来源步骤数: 4', '煎', 0, 0, NULL, NULL),
(37384, '麻辣啤酒濑尿虾', 'meat', '虾:520克#食用油:45毫升#生抽:35毫升#姜:25克#蒜:30克#葱:35克#花椒:6克#啤酒濑尿:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 将每个红辣椒从中间截断,目的是让里面的籽出来增强辣味,半根左右的大葱切段,姜和蒜切成小片;###2. 将锅里的油烧热,倒入辣椒,花椒粒及切好的葱姜蒜,大火爆炒出香味,然后倒入整听啤酒和适量酱油;###3. 锅里的料汁烧开后放入洗净的濑尿虾,烹至虾壳变色即可盛盘。', '川菜,海鲜,水产,热菜,麻辣,下酒菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/recipe/c/2/d/yuan_c2c2a04512b35d13102459f8784f1a2d.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###啤酒濑尿|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 将每个红辣椒从中间截断,目的是让里面的籽出来增强辣味,半根左右的大葱切段,姜和蒜切成小片;###2. 将锅里的油烧热,倒入辣椒,花椒粒及切好的葱姜蒜,大火爆炒出香味,然后倒入整听啤酒和适量酱油;###3. 锅里的料汁烧开后放入洗净的濑尿虾,烹至虾壳变色即可盛盘。', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(37431, '彩腰果虾仁', 'meat', '虾:520克#食用油:45毫升#食盐:7克#料酒:30毫升#姜:25克#彩腰果:345克', '2名成年人总量+15%冗余', '1. 我用的是白虾仁,非常大,所以炒这样一盘菜几个就够了###2. 蔬菜和虾仁都提前焯水,水中加盐###3. 生腰果小火炒制金黄备用###4. 锅内留底油爆炒姜片并把蔬菜倒入一起翻炒,再放入虾仁加少许料酒,放盐翻炒一下###5. 准备出锅的时候放入腰果翻炒片刻就好。腰果切记不能提前放,那样就不脆了。', '水产,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/3/d/f/yuan_3d331fcdfeea6c3bce4cab045ade43ff.jpeg', '困难', '60分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###彩腰果|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 我用的是白虾仁,非常大,所以炒这样一盘菜几个就够了###2. 蔬菜和虾仁都提前焯水,水中加盐###3. 生腰果小火炒制金黄备用###4. 锅内留底油爆炒姜片并把蔬菜倒入一起翻炒,再放入虾仁加少许料酒,放盐翻炒一下###5. 准备出锅的时候放入腰果翻炒片刻就好。腰果切记不能提前放,那样就不脆了。', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(37591, '不开火不加一滴油做番茄炒蛋', 'meat', '鸡蛋:5个#西红柿:460克#食用油:45毫升#食盐:7克#葱:35克', '2名成年人总量+15%冗余', '1. 鸡蛋打入微波碗里。###2. 加入食盐和2汤匙水、葱花,搅拌均匀。*秘诀就是:鸡蛋液要适当加点水,这样用微波炉叮出来的鸡蛋才不会老,口感才最好!###3. 放进微波炉,加盖,中高火三分钟。###4. 取出微波碗,用筷子将鸡蛋块划散。###5. 番茄切成小块,放进微波碗。###6. 加盖,微波炉中高火两分钟,健康美味的番茄炒蛋就做好啦!', '蛋类,禽类,热菜,番茄味,午餐,家常菜,微波炉', 'https://cp1.douguo.net/upload/caiku/b/7/8/yuan_b70672f14c20e253abacc8c632661d38.jpg', '简单', '15分钟', '鸡蛋|5|个|主料|打散|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 鸡蛋打入微波碗里。###2. 加入食盐和2汤匙水、葱花,搅拌均匀。*秘诀就是:鸡蛋液要适当加点水,这样用微波炉叮出来的鸡蛋才不会老,口感才最好!###3. 放进微波炉,加盖,中高火三分钟。###4. 取出微波碗,用筷子将鸡蛋块划散。###5. 番茄切成小块,放进微波碗。###6. 加盖,微波炉中高火两分钟,健康美味的番茄炒蛋就做好啦!', '[]', '来源步骤数: 6', '炒', 0, 0, NULL, NULL),
(37627, '文鱼头炖豆腐', 'meat', '洋葱:290克#鱼:690克#豆腐:460克#红椒:170克#白糖:55克#食用油:45毫升#食盐:7克#生抽:35毫升#料酒:30毫升#香醋:30毫升#姜:25克#蒜:30克#葱:35克#花椒:6克', '2名成年人总量+15%冗余', '1. 油适量,放入鱼头,煎至金黄。###2. 煎好的豆腐###3. 洋葱、姜、蒜、红椒。###4. 锅内留少许油,放入葱、姜、蒜、红椒,炒香再放入鱼和豆腐,依次放酱油、料酒、白糖、醋、加适量的水,盐,花椒、八角、香叶。###5. 开锅小火,炖20~30分钟,装盘。色香味俱全!我的豆果小伙伴们!快尝试为家人做一次吧!不吃不知道!吃了忘不掉!嘿嘿!', '水产,热菜,晚餐,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/1/f/0/yuan_1fe665b6a22dc1c6f615a7ce12255d60.jpg', '普通', '25分钟', '洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###豆腐|460|克|主料|切块或切片|2名成年人总量+15%冗余|菜名+步骤###红椒|170|克|配菜|去籽切丝或切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###香醋|30|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤', '1. 油适量,放入鱼头,煎至金黄。###2. 煎好的豆腐###3. 洋葱、姜、蒜、红椒。###4. 锅内留少许油,放入葱、姜、蒜、红椒,炒香再放入鱼和豆腐,依次放酱油、料酒、白糖、醋、加适量的水,盐,花椒、八角、香叶。###5. 开锅小火,炖20~30分钟,装盘。色香味俱全!我的豆果小伙伴们!快尝试为家人做一次吧!不吃不知道!吃了忘不掉!嘿嘿!', '[]', '来源步骤数: 5', '炒', 0, 0, NULL, NULL),
(37784, '蒜香黑虎虾铸铁锅版', 'meat', '虾:520克#食用油:45毫升#食盐:7克#蒜:30克#葱:35克', '2名成年人总量+15%冗余', '1. 黑虎虾洗净剪去黑线,大蒜切蒜泥,小葱葱白切长段,葱叶切葱花备用。铸铁锅热锅后倒入橄榄油和黄油,油热后倒入蒜泥爆香,再倒入黑虎虾,微炒一下,虾变色即可。烤箱180度预热。###2. 虾变色即可关火,表面撒入葱白段。###3. 连锅一起放入烤箱中层,180度烤15分钟左右。###4. 从烤箱取出后把表面烤焦的葱白去掉,撒入食盐,稍微搅拌一下,撒入葱末,即可上桌。', '水产,热菜,蒜香,晚餐,午餐,家常菜,烤箱', 'https://cp1.douguo.net/upload/caiku/8/4/f/yuan_84b611da862fdf904795d341a307a47f.jpg', '普通', '20分钟', '虾|520|克|主料|去虾线并清洗|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|菜名+步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤', '1. 黑虎虾洗净剪去黑线,大蒜切蒜泥,小葱葱白切长段,葱叶切葱花备用。铸铁锅热锅后倒入橄榄油和黄油,油热后倒入蒜泥爆香,再倒入黑虎虾,微炒一下,虾变色即可。烤箱180度预热。###2. 虾变色即可关火,表面撒入葱白段。###3. 连锅一起放入烤箱中层,180度烤15分钟左右。###4. 从烤箱取出后把表面烤焦的葱白去掉,撒入食盐,稍微搅拌一下,撒入葱末,即可上桌。', '[]', '来源步骤数: 4', '炒', 0, 0, NULL, NULL),
(37797, '条椒牛肉丝', 'meat', '牛肉:400克#食用油:45毫升#食盐:7克#料酒:30毫升#淀粉:30克#豆瓣酱:30克#姜:25克#花椒:6克#条椒丝:345克', '2名成年人总量+15%冗余', '1. 牛肉、嫩姜、条椒切丝,泡椒、老姜剁碎,待用###2. 牛肉丝放盆里,放淀粉、豆瓣酱、泡椒、老姜末、花椒、料酒,搅拌匀,待用###3. 油温8成熟放腌好的牛肉,快速翻炒均匀,放嫩姜、条椒丝、鸡精或鸡粉,炒到条椒稍变软,关小火,尝味道,不够加盐,起锅', '肉类,禽类,热菜,下饭菜,家常菜', 'https://cp1.douguo.net/upload/caiku/e/1/1/yuan_e177ce9706b5c67409f09da2f3545a61.jpg', '困难', '60分钟', '牛肉|400|克|主料|按步骤切配|2名成年人总量+15%冗余|菜名+步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###淀粉|30|克|调味料|腌制或勾芡|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###花椒|6|克|辅料|直接使用|2名成年人总量+15%冗余|步骤###条椒丝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名', '1. 牛肉、嫩姜、条椒切丝,泡椒、老姜剁碎,待用###2. 牛肉丝放盆里,放淀粉、豆瓣酱、泡椒、老姜末、花椒、料酒,搅拌匀,待用###3. 油温8成熟放腌好的牛肉,快速翻炒均匀,放嫩姜、条椒丝、鸡精或鸡粉,炒到条椒稍变软,关小火,尝味道,不够加盐,起锅', '[]', '来源步骤数: 3', '炒', 0, 0, NULL, NULL),
(37829, '彩开屏鱼戏珠', 'meat', '枸杞:25克#玉米:460克#鱼:690克#西红柿:460克#白糖:55克#食用油:45毫升#生抽:35毫升#料酒:30毫升#豆瓣酱:30克#姜:25克#蒜:30克#葱:35克#食盐:7克', '2名成年人总量+15%冗余', '1. 鱼一条,去头尾###2. 备葱姜蒜###3. 鱼切片,用姜蒜、料酒腌制十分钟###4. 将鱼头摆上,码上鱼肉,弃尾。水烧开气,放鱼开蒸10分钟。然后坐锅烧油炸姜蒜,加少许豆瓣酱继续炒香,锅里加点生抽和白糖,关火起锅作为淋酱汁。###5. 将刚才的炸姜蒜的酱汁浇在蒸好的鱼身上###6. 再浇一点蒸鱼豉油,点缀点枸杞和玉米粒,鱼嘴塞一颗番茄。哈哈哈... 戏珠开始', '水产,肉类,热菜,鲜,朋友聚餐,家常菜', 'https://cp1.douguo.net/upload/caiku/5/e/6/yuan_5e12e28e320494cc2a26793ad4385786.jpg', '普通', '25分钟', '枸杞|25|克|辅料|洗净备用|2名成年人总量+15%冗余|步骤###玉米|460|克|主料|剥粒洗净|2名成年人总量+15%冗余|步骤###鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名+步骤###西红柿|460|克|主料|切块|2名成年人总量+15%冗余|步骤###白糖|55|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###料酒|30|毫升|调味料|去腥|2名成年人总量+15%冗余|步骤###豆瓣酱|30|克|调味料|炒香|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 鱼一条,去头尾###2. 备葱姜蒜###3. 鱼切片,用姜蒜、料酒腌制十分钟###4. 将鱼头摆上,码上鱼肉,弃尾。水烧开气,放鱼开蒸10分钟。然后坐锅烧油炸姜蒜,加少许豆瓣酱继续炒香,锅里加点生抽和白糖,关火起锅作为淋酱汁。###5. 将刚才的炸姜蒜的酱汁浇在蒸好的鱼身上###6. 再浇一点蒸鱼豉油,点缀点枸杞和玉米粒,鱼嘴塞一颗番茄。哈哈哈... 戏珠开始', '[]', '来源步骤数: 6', '炸', 0, 0, NULL, NULL),
(38055, '黑椒烤鸡串', 'meat', '柠檬:170克#洋葱:290克#黑胡椒:6克#鸡肉:520克#食盐:7克#葱:35克#鸡串:345克#食用油:45毫升', '2名成年人总量+15%冗余', '1. 准备食材:食材B全部洗净后,切丁,用开水焯一下,洋葱切丁,放入沙拉酱搅拌均匀,待用。###2. 鸡胸放入几片柠檬,用水泡1个小时###3. 泡好后的鸡胸切成大小适中的块状,放入所有调料A,用手充分抓匀,腌制2-3小时###4. 竹签用盐开水浸泡后,用蒸锅蒸一下(平时蒸东西就可以一起蒸了),鸡胸串好后###5. 放入空气炸锅180度15分钟,就可以和家人一起享受美味了。', '禽类,热菜,黑椒,朋友聚餐,家常菜,空气炸锅', 'https://cp1.douguo.net/upload/caiku/6/9/1/yuan_69a6de46cececbfd7e877a19c5ad4a91.jpg', '普通', '25分钟', '柠檬|170|克|主料|洗净切片|2名成年人总量+15%冗余|步骤###洋葱|290|克|配菜|去皮切丝|2名成年人总量+15%冗余|步骤###黑胡椒|6|克|调味料|直接使用|2名成年人总量+15%冗余|菜名###鸡肉|520|克|主料|按步骤切配|2名成年人总量+15%冗余|步骤###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###鸡串|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|烹饪常规补全', '1. 准备食材:食材B全部洗净后,切丁,用开水焯一下,洋葱切丁,放入沙拉酱搅拌均匀,待用。###2. 鸡胸放入几片柠檬,用水泡1个小时###3. 泡好后的鸡胸切成大小适中的块状,放入所有调料A,用手充分抓匀,腌制2-3小时###4. 竹签用盐开水浸泡后,用蒸锅蒸一下(平时蒸东西就可以一起蒸了),鸡胸串好后###5. 放入空气炸锅180度15分钟,就可以和家人一起享受美味了。', '[]', '来源步骤数: 5', '炸', 0, 0, NULL, NULL),
(38057, '清蒸皇帝鱼', 'meat', '鱼:690克#食用油:45毫升#生抽:35毫升#姜:25克#蒜:30克#葱:35克#皇帝:345克#食盐:7克', '2名成年人总量+15%冗余', '1. 【菁选酱油】 美丽 美味 实用 健康 做菜的首选 你值得拥有###2. 用剪刀剪去尾 和旁边的翅 刮去麟 挖去鳃和内脏洗洗###3. 对切放盘上蒸 放姜 葱 辣椒丝 少许味精 大火15 分钟OK###4. 蒸好洒上蒜碎 和少许葱 用热油一淋 倒上酱油 特写一个###5. 味道棒极了 再来一碗粥吧', '水产,热菜,午餐,家常菜', 'https://cp1.douguo.net/upload/caiku/e/d/4/yuan_ed74c04f513c6c9b031d94cfb1e34de4.jpg', '普通', '20分钟', '鱼|690|克|主料|去鳞去内脏并清洗|2名成年人总量+15%冗余|菜名###食用油|45|毫升|调味料|炒制或拌制|2名成年人总量+15%冗余|步骤###生抽|35|毫升|调味料|调味|2名成年人总量+15%冗余|步骤###姜|25|克|辅料|切片或切末|2名成年人总量+15%冗余|步骤###蒜|30|克|辅料|切末|2名成年人总量+15%冗余|步骤###葱|35|克|辅料|切段或切花|2名成年人总量+15%冗余|步骤###皇帝|345|克|主料|按步骤处理|2名成年人总量+15%冗余|菜名###食盐|7|克|调味料|按口味调整|2名成年人总量+15%冗余|烹饪常规补全', '1. 【菁选酱油】 美丽 美味 实用 健康 做菜的首选 你值得拥有###2. 用剪刀剪去尾 和旁边的翅 刮去麟 挖去鳃和内脏洗洗###3. 对切放盘上蒸 放姜 葱 辣椒丝 少许味精 大火15 分钟OK###4. 蒸好洒上蒜碎 和少许葱 用热油一淋 倒上酱油 特写一个###5. 味道棒极了 再来一碗粥吧', '[]', '来源步骤数: 5', '蒸', 0, 0, NULL, NULL),
